__modules["src/arteria/chest_esp"] = function()
-- Arteria Chest ESP: Neon corner brackets and distance labels.
-- Bounded, pre-allocated screen-space line and text pools. Zero per-frame allocations.
local theme = require("@src/arteria/theme")
local C = theme.color
local feature = { id = "chest_esp", pool = {} }
local players = game:GetService("Players")

local function create(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props) do object[key] = value end
    object.Parent = parent
    return object
end

local MAX_CHESTS = 40

function feature:render(dt)
    local camera = workspace.CurrentCamera
    if not camera or camera.ViewportSize.X < 16 or camera.ViewportSize.Y < 48 then return end

    local own_character = players.LocalPlayer.Character
    local own_root = own_character and own_character:FindFirstChild("HumanoidRootPart")
    local origin = own_root and own_root.Position or camera.CFrame.Position

    local max_dist = aztup.flags.arteria_chest_range or 3000
    local show_opened = aztup_options.arteria_chest_opened.Value == "Show"
    local text_size = aztup.flags.arteria_chest_text or 13

    local candidates = {}

    local function check_container(container)
        if not container or not container.GetChildren then return end
        local ok, children = pcall(function() return container:GetChildren() end)
        if not ok or type(children) ~= "table" then return end
        for _, entity in ipairs(children) do
            if entity.Name == "Chest" or entity:FindFirstChild("Lid") then
                local lid = entity:FindFirstChild("Lid")
                local part = lid or entity:FindFirstChildWhichIsA("BasePart")
                if part and part:IsA("BasePart") then
                    local is_opened = entity:GetAttribute("Opened") == true
                    if show_opened or not is_opened then
                        local dist = (part.Position - origin).Magnitude
                        if dist <= max_dist then
                            table.insert(candidates, { entity = entity, part = part, dist = dist, opened = is_opened })
                        end
                    end
                end
            end
        end
    end

    check_container(workspace:FindFirstChild("Thrown"))
    check_container(workspace:FindFirstChild("Chests"))
    check_container(workspace)

    table.sort(candidates, function(a, b) return a.dist < b.dist end)

    local active_count = math.min(#candidates, MAX_CHESTS)

    for i = 1, MAX_CHESTS do
        local slot = self.pool[i]
        if i <= active_count then
            local item = candidates[i]
            local part, dist, opened = item.part, item.dist, item.opened
            local point, on_screen = camera:WorldToViewportPoint(part.Position)

            if on_screen and point.Z > 0 then
                -- Project corner box around chest size
                local size = part.Size
                local sy = size and size.Y or 2
                local p_top, v_top = camera:WorldToViewportPoint(part.Position + Vector3.new(0, sy / 2 + 0.5, 0))
                local p_bot, v_bot = camera:WorldToViewportPoint(part.Position - Vector3.new(0, sy / 2 + 0.5, 0))

                local h = math.clamp(math.abs(p_bot.Y - p_top.Y), 16, 120)
                local w = h * 1.3
                local cx, cy = point.X, point.Y

                local left, right = cx - w / 2, cx + w / 2
                local top, bottom = cy - h / 2, cy + h / 2
                local arm_w, arm_h = w * 0.28, h * 0.28

                -- 8 corner bracket segments
                local segments = {
                    { left + arm_w / 2, top, arm_w, 1 },
                    { left, top + arm_h / 2, 1, arm_h },
                    { right - arm_w / 2, top, arm_w, 1 },
                    { right, top + arm_h / 2, 1, arm_h },
                    { left + arm_w / 2, bottom, arm_w, 1 },
                    { left, bottom - arm_h / 2, 1, arm_h },
                    { right - arm_w / 2, bottom, arm_w, 1 },
                    { right, bottom - arm_h / 2, 1, arm_h },
                }

                for s_idx, seg in ipairs(segments) do
                    local line = slot.lines[s_idx]
                    line.Position = UDim2.fromOffset(seg[1], seg[2])
                    line.Size = UDim2.fromOffset(seg[3], seg[4])
                    line.BackgroundColor3 = opened and C.muted or C.neon
                    line.Visible = true
                end

                local label_text = string.format("CHEST  ·  %d studs", math.floor(dist))
                if opened then
                    label_text = label_text .. "  (OPEN)"
                end

                slot.label.Text = label_text
                slot.label.TextSize = text_size
                slot.label.TextColor3 = opened and C.muted or C.text
                slot.label.Position = UDim2.fromOffset(cx, top - 14)
                slot.label.Visible = true
            else
                slot:hide()
            end
        else
            slot:hide()
        end
    end
end

function feature:enable()
    self:disable()
    self.pool = {}

    self.gui = create("ScreenGui", {
        Name = "ArteriaChestESP",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 95,
    }, players.LocalPlayer:WaitForChild("PlayerGui"))

    for i = 1, MAX_CHESTS do
        local slot = { lines = {} }

        for b = 1, 8 do
            local line = create("Frame", {
                Name = "Bracket",
                BorderSizePixel = 0,
                BackgroundColor3 = C.neon,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Visible = false,
            }, self.gui)
            table.insert(slot.lines, line)
        end

        slot.label = create("TextLabel", {
            Name = "ChestLabel",
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Font = theme.font.mono,
            TextColor3 = C.text,
            TextStrokeColor3 = C.ink,
            TextStrokeTransparency = 0.15,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Text = "",
            Visible = false,
        }, self.gui)

        function slot:hide()
            for _, line in ipairs(self.lines) do line.Visible = false end
            self.label.Visible = false
        end

        table.insert(self.pool, slot)
    end

    self.conn = game:GetService("RunService").RenderStepped:Connect(function(dt)
        local ok, err = pcall(self.render, self, dt)
        if not ok then
            aztup_toggles.chest_esp:SetValue(false)
            local runtime = getgenv().arteria
            if runtime then runtime.errors.chest_esp = tostring(err); runtime.refresh() end
            warn("[arteria] chest ESP: " .. tostring(err))
        end
    end)
end

function feature:disable()
    if self.conn then self.conn:Disconnect(); self.conn = nil end
    if self.gui then self.gui:Destroy(); self.gui = nil end
    self.pool = {}
end

return feature

end;

__modules["src/arteria/compat"] = function()
-- Only the dependency contracts used by the allowlisted legacy modules.
local Compat = {}
local function set(values)
    local result = {}
    for _, value in ipairs(values) do result[value] = true end
    return result
end
function Compat.configure(runtime)
    local env = getgenv()
    env.is_depths = game.PlaceId == 5735553160
    env.is_eastern = game.PlaceId == 6473861193
    env.is_etrean = game.PlaceId == 6032399813
    env.is_chime = game.PlaceId == 6832944305
    env.debug_print = function(...) if runtime.flags.debug then print("[arteria]", ...) end end
    local defaults = {
        dont_process_players_over_studs = 500, dont_process_mobs_over_studs = 2000,
        task_concurrency = 20, anti_ap_breaker_max_speed = 5, anti_ap_breaker_minimum_wt = 10,
        anti_ap_breaker_length_ms = 50, parry_to_fallback_chance = 0, bluff_feint_chance = 0,
        bi_punishable_time = 650, extra_bi_punishable_time = 0, max_boxes = 5, hb_trans = 100,
        info_logger_range = 1, feint_chance = 100,
    }
    for _, prefix in ipairs({ "pve_", "pvp_" }) do
        defaults[prefix .. "parry_chance"] = 100
        defaults[prefix .. "max_roll_cancel_delay"] = 150
        defaults[prefix .. "min_roll_cancel_delay"] = 70
        defaults[prefix .. "roll_cancel_chance"] = 90
    end
    for _, suffix in ipairs({ "undefined", "spells", "critical", "m1" }) do defaults["parry_to_dodge_chance_" .. suffix] = 0 end
    for key, value in pairs(defaults) do runtime.flags[key] = value end
    local options = {
        allowed_targets = set({ "Unknown", "PVE", "PVP", "All" }),
        filters = set({ "Dont Parry If Typing", "Dont Parry If Knocked" }),
        fallbacks = set({ "Curse of the Unbidden" }),
        validation_filters = set({ "WT <= X (WT = WeightTarget)", "Core Priority", "Idle Priority", "Priority Hiding", "S >= X (S = Speed)", "Fadetime" }),
        validation_log_filters = {}, blocked_auto_feint_moves = {},
        auto_feint_own_tags = set({ "M1", "Spell" }), blocked_safe_input_moves = {},
        blocked_safe_input_user_moves = {}, allowed_bi_targets = {}, blocked_timings = {},
        bi_punishable_type = "Static", m1_timing_hitbox_type = "Block",
        aggressive_3_break_on = set({ "Spells", "M1s" }),
        anim_speed_changer_types = set({ "Criticals", "Untagged", "Spells", "Bells", "M1s" }),
        no_stun_items = set({ "LightningStun", "PreventAction", "OffhandAttack", "UsingCritical", "MobileAction", "MediumAttack", "CarryObject", "PreventRoll", "LightAttack", "HeavyAttack", "InDialogue", "UsingSpell", "NoParkour", "NoJumpAlt", "Blocking", "NoAttack", "Carried", "Falling", "Chilled", "Pinned", "Action", "Dodged", "NoJump", "NoRoll", "NoMove", "Stun" }),
        ally_settings = {}, ally_guilds_input = "", ally_players_input = "",
    }
    for key, value in pairs(options) do env.aztup_options[key] = { Value = value } end
    Compat.animation_speed(runtime, 1)
end

function Compat.animation_speed(runtime, value)
    for _, id in ipairs({ "anim_critical_speed", "anim_untagged_speed", "anim_spell_speed", "anim_bell_speed", "anim_m1_speed" }) do
        runtime.flags[id] = { min = value, max = value }
    end
end

function Compat.restore_point(id)
    local lighting = game:GetService("Lighting")
    local env = getgenv()
    if id == "no_shadows" then
        local value = lighting.GlobalShadows
        return function() lighting.GlobalShadows = value end
    elseif id == "no_fog" then
        local distance = lighting.FogEnd
        local atmosphere = lighting:FindFirstChildOfClass("Atmosphere")
        local density = atmosphere and atmosphere.Density
        return function()
            lighting.FogEnd = distance
            if atmosphere and atmosphere.Parent then atmosphere.Density = density end
        end
    elseif id == "no_blur" then
        local values = {}
        for _, object in ipairs(lighting:GetChildren()) do
            if object:IsA("BlurEffect") then values[object] = object.Size end
        end
        return function()
            for object, value in pairs(values) do if object.Parent then object.Size = value end end
        end
    elseif id == "no_blind" or id == "no_one_bit" then
        local passives = env.EffectReplicator.Passives
        if not passives then return end
        local keys = id == "no_blind" and { "Blind", "Blinded" } or { "OneBit" }
        local values = {}
        for _, key in ipairs(keys) do values[key] = passives[key] end
        return function() for _, key in ipairs(keys) do passives[key] = values[key] end end
    elseif id == "no_sanity_vfx" then
        local gui = env.local_player.instance:FindFirstChild("PlayerGui")
        local overlay = gui and gui:FindFirstChild("OverlayGui")
        local enabled = overlay and overlay.Enabled
        return function() if overlay and overlay.Parent then overlay.Enabled = enabled end end
    elseif id == "void_mobs" then
        local value = workspace.FallenPartsDestroyHeight
        local attribute = workspace:GetAttribute("OriginalFPDH")
        return function()
            workspace.FallenPartsDestroyHeight = value
            workspace:SetAttribute("OriginalFPDH", attribute)
        end
    end
end

function Compat.prepare(runtime)
    if runtime.prepared then return end
    local env = getgenv()
    env.Latency = require("@src/utility/latency")
    env.scheduler = require("@src/utility/scheduler")
    env.general = require("@src/utility/deepwoken/general_utilitys")
    env.fflags = require("@src/utility/fflags")
    env.InstanceWatcher = require("@src/utility/instancewatcher")
    local data = env.local_player
    data.character_added = require("@src/utility/signal").new()
    runtime.maid:give_task(function() data.character_added:destroy() end)
    data.tracker = require("@src/utility/deepwoken/action_tracker").new(data)
    runtime.maid:give_task(data.tracker.on_mantra_request)
    env.chance_store = require("@src/features/auto-parry/data/chance_store")
    env.TargetFilter = require("@src/features/auto-parry/util/target-filter")
    require("@src/features/auto-parry/block-input-manager")

    -- Stable hook handles: the old handler used mutable array indices, so
    -- disabling one feature could leave another feature's hook registered.
    local hooks = {}
    local handler = {}
    function handler:hook(kind, callback)
        local token = { kind = kind, callback = callback, owner = runtime.enabling, threads = {} }
        hooks[token] = true
        function token:remove()
            hooks[self] = nil
            for thread in pairs(self.threads) do pcall(task.cancel, thread) end
            table.clear(self.threads)
        end
        return token
    end
    env.EffectReplicatorHandler = handler
    runtime.maid:give_task(function()
        for token in pairs(hooks) do token:remove() end
    end)
    for _, pair in ipairs({ { "added", env.EffectReplicator.EffectAdded }, { "removed", env.EffectReplicator.EffectRemoved } }) do
        runtime.maid:give_task(pair[2]:Connect(function(effect)
            if not runtime.alive or not data.root_part or not data.humanoid then return end
            for token in pairs(hooks) do
                if token.kind == pair[1] and (not token.owner or runtime.flags[token.owner]) then
                    local thread
                    thread = task.defer(function()
                        if not runtime.alive or not hooks[token] then return end
                        local ok, err = pcall(token.callback, effect)
                        if not ok then
                            if token.owner then runtime:set(token.owner, false) end
                            warn("[arteria] effect hook: " .. tostring(err))
                        end
                        token.threads[thread] = nil
                    end)
                    token.threads[thread] = true
                end
            end
        end))
    end
    runtime.prepared = true
end

function Compat.observers(runtime)
    Compat.prepare(runtime)
    if runtime.observers_loaded then return end
    -- These modules install observers; execution remains flag-driven.
    require("@src/features/auto-parry/auto-parry")
    require("@src/features/auto-parry/handlers/animator-handler")
    runtime.observers_loaded = true
end
return Compat

end;

__modules["src/arteria/config"] = function()
-- Named local profiles: JSON data only, never executable code or farm consent.
local Config = {}
Config.__index = Config
local ROOT = "Arteria/Configs"
local AUTOLOAD_PATH = ROOT .. "/autoload.json"
local RESERVED = { Unknown = true, V = true, Escape = true, Tab = true, Return = true, Backspace = true }

local function key(name)
    if type(name) ~= "string" or RESERVED[name] then return nil end
    local ok, value = pcall(function() return Enum.KeyCode[name] end)
    return ok and value or nil
end

local function valid_name(name)
    assert(type(name) == "string", "Enter a profile name")
    name = name:match("^%s*(.-)%s*$")
    assert(#name >= 1 and #name <= 48 and name:match("^[%w][%w _%-]*$"), "Use 1–48 letters, numbers, spaces, underscores or hyphens")
    return name
end

function Config.new(runtime)
    return setmetatable({
        runtime = runtime,
        message = "Profiles are local. Echo-farm consent is never saved in a config.",
        profiles = {},
    }, Config)
end

function Config:path(name) return ROOT .. "/profile-" .. valid_name(name) .. ".json" end

function Config:list()
    local result = {}
    if isfolder(ROOT) then
        for _, path in ipairs(listfiles(ROOT)) do
            local basename = path:gsub("\\", "/"):match("([^/]+)$")
            local name = basename and basename:match("^profile%-(.+)%.json$")
            if name and pcall(valid_name, name) then table.insert(result, name) end
        end
    end
    table.sort(result)
    self.profiles = result
    return result
end

function Config:snapshot()
    local runtime = self.runtime
    local data = {
        version = 1,
        flags = {},
        options = {},
        bindings = {},
        ui_key = (runtime.ui_key or Enum.KeyCode.RightShift).Name,
        reduce_motion = runtime.reduce_motion == true,
    }
    for _, entry in ipairs(runtime.catalog.entries) do
        data.flags[entry.id] = runtime.flags[entry.id] == true
        local binding = runtime.bindings and runtime.bindings[entry.id]
        data.bindings[entry.id] = binding and binding.Name or false
        for _, option in ipairs(entry.settings) do data.options[option.id] = runtime.flags[option.id] end
    end
    return data
end

function Config:validate(data)
    assert(type(data) == "table" and data.version == 1, "Unsupported or invalid profile format")
    assert(type(data.flags) == "table" and type(data.options) == "table" and type(data.bindings) == "table", "Incomplete profile")
    local result = { flags = {}, options = {}, bindings = {}, ui_key = key(data.ui_key), reduce_motion = data.reduce_motion == true }
    assert(result.ui_key, "Invalid UI key")
    local used = { [result.ui_key.Name] = true }
    for _, entry in ipairs(self.runtime.catalog.entries) do
        local enabled = data.flags[entry.id]
        assert(enabled == nil or type(enabled) == "boolean", "Invalid feature state: " .. entry.id)
        result.flags[entry.id] = enabled == true
        local value = data.bindings[entry.id]
        if value ~= nil and value ~= false then
            local binding = key(value)
            assert(binding and not used[binding.Name], "Invalid or duplicate keybind: " .. entry.id)
            result.bindings[entry.id], used[binding.Name] = binding, true
        end
        for _, option in ipairs(entry.settings) do
            local value = data.options[option.id]
            if value == nil then value = option.value end
            if option.values then
                assert(table.find(option.values, value), "Invalid option: " .. option.id)
            else
                assert(type(value) == "number" and value == value and math.abs(value) < math.huge, "Invalid number: " .. option.id)
                value = math.clamp(value, option.low, option.high)
                if option.id == "min_speed_mult" or option.id == "max_speed_mult" then value = math.floor(value) end
            end
            result.options[option.id] = value
        end
    end
    return result
end

function Config:save(name)
    local vname = valid_name(name)
    local path = self:path(vname)
    local data = self:snapshot()
    self:validate(data)
    local encoded = game:GetService("HttpService"):JSONEncode(data)
    if not isfolder("Arteria") then makefolder("Arteria") end
    if not isfolder(ROOT) then makefolder(ROOT) end
    writefile(path, encoded)
    self:list()
    self.message = "Saved / " .. vname
end

function Config:load(name, restore_flags)
    local raw = readfile(self:path(name))
    assert(#raw <= 1024 * 1024, "Profile exceeds the size limit")
    self:apply(game:GetService("HttpService"):JSONDecode(raw), restore_flags, valid_name(name))
end

function Config:apply(payload, restore_flags, label)
    assert(not (self.runtime.echo and self.runtime.echo.running), "Stop the echo cycle before loading a profile")
    local data = self:validate(payload)
    local runtime = self.runtime
    runtime.bindings = runtime.bindings or {}
    table.clear(runtime.bindings)
    for id, value in pairs(data.bindings) do runtime.bindings[id] = value end
    runtime.ui_key, runtime.reduce_motion = data.ui_key, data.reduce_motion
    for _, entry in ipairs(runtime.catalog.entries) do
        for _, option in ipairs(entry.settings) do runtime:option(option, data.options[option.id]) end
    end
    local failed = 0
    if restore_flags == true then
        for _, entry in ipairs(runtime.catalog.entries) do runtime:set(entry.id, false) end
        for _, entry in ipairs(runtime.catalog.entries) do
            if data.flags[entry.id] then runtime:set(entry.id, true); if not runtime.flags[entry.id] then failed += 1 end end
        end
    end
    self.message = "Loaded / " .. (label or "session") .. (restore_flags and " · saved toggles applied" or " · settings and binds only")
        .. (failed > 0 and (" · " .. failed .. " unavailable feature(s)") or "")
    if runtime.refresh then runtime.refresh() end
end

function Config:delete(name)
    local vname = valid_name(name)
    local path = self:path(vname)
    assert(isfile(path), "Profile does not exist")
    delfile(path)
    local auto_name = self:get_autoload()
    if auto_name == vname then self:clear_autoload() end
    self:list()
    self.message = "Deleted / " .. vname
end

function Config:get_autoload()
    if not isfile(AUTOLOAD_PATH) then return nil, false end
    local ok, result = pcall(function()
        return game:GetService("HttpService"):JSONDecode(readfile(AUTOLOAD_PATH))
    end)
    if ok and type(result) == "table" and type(result.name) == "string" and pcall(valid_name, result.name) then
        return result.name, result.restore_flags == true
    end
    return nil, false
end

function Config:set_autoload(name, restore_flags)
    local vname = valid_name(name)
    assert(isfile(self:path(vname)), "Save the profile first before setting it as autoload")
    if not isfolder("Arteria") then makefolder("Arteria") end
    if not isfolder(ROOT) then makefolder(ROOT) end
    local data = { name = vname, restore_flags = restore_flags == true }
    writefile(AUTOLOAD_PATH, game:GetService("HttpService"):JSONEncode(data))
    self.message = "Autoload set / " .. vname .. (restore_flags and " (with toggles)" or " (settings only)")
    if self.runtime.refresh then self.runtime.refresh() end
end

function Config:clear_autoload()
    if isfile(AUTOLOAD_PATH) then delfile(AUTOLOAD_PATH) end
    self.message = "Autoload cleared."
    if self.runtime.refresh then self.runtime.refresh() end
end

function Config:autoload()
    local name, restore_flags = self:get_autoload()
    if not name or not isfile(self:path(name)) then return false end
    local ok, err = pcall(function()
        self:load(name, restore_flags)
    end)
    if ok then
        self.message = "Autoloaded / " .. name .. (restore_flags and " (with toggles)" or " (settings only)")
        return true
    else
        self.message = "Autoload failed / " .. tostring(err)
        return false
    end
end

return Config

end;

__modules["src/arteria/echo"] = function()
-- Soup echo cycle, with explicit slot consent and locally guarded continuation.
local Scope = require("@src/arteria/scope")
local Transfer = require("@src/arteria/echo_transfer")
local Echo = {}
Echo.__index = Echo
local STATE = "Arteria/echo-session.json"
local BOOTSTRAP = "Arteria/bootstrap.lua"
local function read_state()
    local ok, result = pcall(function()
        if not isfile(STATE) then return {} end
        return game:GetService("HttpService"):JSONDecode(readfile(STATE))
    end)
    return ok and type(result) == "table" and result or {}
end
local function save(state)
    if not isfolder("Arteria") then makefolder("Arteria") end
    writefile(STATE, game:GetService("HttpService"):JSONEncode(state))
end
local function decode(payload)
    local encoding = game:GetService("EncodingService")
    return buffer.tostring(encoding:DecompressBuffer(encoding:Base64Decode(buffer.fromstring(payload)), Enum.CompressionAlgorithm.Zstd))
end
function Echo.new(runtime, prepare)
    local self = setmetatable({ runtime = runtime, prepare = prepare, session = read_state(),
        running = false, state = "idle", owned = {}, resume_authorized = getgenv().Arteria_resume_requested == true }, Echo)
    getgenv().Arteria_resume_requested = nil
    -- Never honor another farm's flags or a malformed saved session.
    local s = self.session
    if s.mode ~= "soup" or type(s.token) ~= "string" or type(s.slot) ~= "string" then self.session = {} end
    if type(self.session.transfer_error) == "string" then self.error = self.session.transfer_error; self.state = "transfer failed" end
    return self
end
function Echo:refresh()
    if self.runtime.alive and self.runtime.refresh then self.runtime.refresh() end
end
function Echo:guard(source)
    return string.format([[
local ok, session = pcall(function()
    return game:GetService("HttpService"):JSONDecode(readfile(%q))
end)
if not ok or not session.enabled or session.token ~= %q then return end
]], STATE, self.session.token) .. source
end
function Echo:queue(source)
    assert(self.running and self.scope.active, "Echo farm stopped")
    local queue = queue_on_teleport or queueonteleport
    assert(type(queue) == "function", "Executor does not support teleport continuation")
    queue(self:guard(source))
end
function Echo:queue_bootstrap()
    local queue = queue_on_teleport or queueonteleport
    assert(type(queue) == "function", "Executor does not support teleport continuation")
    assert(isfile(BOOTSTRAP), "Local Arteria bootstrap is missing; inject the rebuilt bundle")
    queue(self:guard(string.format('getgenv().Arteria_resume_requested = true; assert(loadstring(readfile(%q), "=arteria-resume"))()', BOOTSTRAP)))
end
function Echo:stop(reason, preserve)
    if not preserve then
        self.resume_authorized = false
        self.session.enabled = false
        local ok, err = pcall(save, self.session)
        if not ok then self.error = "Could not invalidate queued continuation: " .. tostring(err) end
    end
    self.running = false
    if self.scope then
        self.scope:stop()
        if getgenv().persistent_data == self.scope.store then getgenv().persistent_data = self.previous_store end
        self.scope = nil
    end
    for id, value in pairs(self.owned) do self.runtime:set(id, value) end
    table.clear(self.owned)
    self.state = reason or "stopped"
    self:refresh()
end
function Echo:start(slot_confirmation, resuming)
    if self.running then return false end
    local runtime, env = self.runtime, getgenv()
    if runtime.status ~= "ready" or runtime.busy or not env.local_player.root_part then
        self.error = "Wait for the character and AC initialization."
        self:refresh()
        return false
    end
    local slot = tostring(env.local_player.instance:GetAttribute("DataSlot") or "")
    if slot == "" or slot_confirmation ~= slot or (resuming and self.session.slot ~= slot) then
        self.error = "Slot confirmation does not match the selected character."
        self:refresh()
        return false
    end
    local allowed = env.is_etrean or env.is_eastern or env.is_depths
    if not allowed then self.error = "Soup cycles require Etrean, Eastern, or the Depths."; self:refresh(); return false end
    self.error = nil
    runtime.busy = true
    self.state = "preparing"
    self:refresh()
    local ok, err = pcall(function()
        self.prepare(runtime)
        assert(runtime.alive, "Arteria was unloaded during farm preparation")
        env.StateMachine = require("@src/utility/statemachine")
        if env.Arteria_bootstrap_b64 then
            if not isfolder("Arteria") then makefolder("Arteria") end
            writefile(BOOTSTRAP, decode(env.Arteria_bootstrap_b64))
        end
        assert(isfile(BOOTSTRAP), "Inject the latest Arteria bundle before starting a farm")
        assert(type(queue_on_teleport or queueonteleport) == "function", "Teleport continuation is unavailable")
        if not resuming then
            self.session = { mode = "soup", slot = slot, token = game:GetService("HttpService"):GenerateGUID(false),
                enabled = true, started = os.time(), cycles = 0, echoes = 0 }
        end
        save(self.session)
        self.resume_authorized = true
        local scope = Scope.new()
        self.scope, self.running = scope, true
        scope.on_error = function(message)
            self.error = tostring(message)
            warn("[arteria] echo farm: " .. self.error)
            self:stop("error")
        end
        scope.queue = function(_, source) return self:queue(source) end
        scope.store = {
            get = function(_, key, fallback)
                if key == "soup_echo_farm_origin" then return "Etris" end
                local map = { cycle_count = "cycles", echoes_gained = "echoes", started_farm_at = "started", wiped_at = "wiped_at" }
                local value = self.session[map[key] or key]
                if value == nil then return fallback end
                return value
            end,
            set = function(_, key, value)
                local map = { cycle_count = "cycles", echoes_gained = "echoes", wiped_at = "wiped_at" }
                self.session[map[key] or key] = value
                save(self.session)
                self:refresh()
            end,
        }
        scope.Tween = { new = function(...)
            local tween = env.Tween.new(...)
            scope:track(function() tween.stop() end)
            return tween
        end }
        local function transition(slot_id, small, sound, wipe)
            assert(scope.active, "Echo farm stopped")
            scope:queue(Transfer.source(slot_id or slot, wipe, self.session.token, game.JobId))
            self.state = wipe and "wiping confirmed slot" or "changing server"
            self:refresh()
            scope.task.spawn(function()
                env.local_player.instance:Kick("arteria / echo cycle transfer")
                while scope.active do
                    game:GetService("TeleportService"):Teleport(4111023553)
                    scope.task.wait(1)
                end
            end)
        end
        scope.servers = {
            hop = function(_, slot_id, small, sound) transition(slot_id, small, sound, false) end,
            obliteration = function(_, slot_id) transition(slot_id, false, false, true) end,
        }
        self.previous_store = env.persistent_data
        env.persistent_data = scope.store
        local farm = require("@src/automation/persistent_tasks/soup_echofarm")
        assert(runtime.alive and scope.active, "Echo farm stopped during module initialization")
        farm:bind_scope(scope)
        self.farm = farm
        self:queue_bootstrap()
        runtime.busy = false
        -- Use the controller, not legacy struct:run(), to avoid duplicate
        -- connections and the old farm HUD. Restore prior values on Stop.
        for _, id in ipairs(farm.features) do
            self.owned[id] = runtime.flags[id] == true
            runtime:set(id, true)
            assert(runtime.alive and scope.active, "Echo farm stopped during dependency initialization")
            assert(runtime.flags[id], "Farm dependency unavailable: " .. id)
        end
        self.state = "running"
        scope.task.spawn(function() farm.state_machine:start() end)
        scope.task.spawn(function()
            while scope.active do self:refresh(); scope.task.wait(0.5) end
        end)
    end)
    runtime.busy = false
    if not ok then self.error = tostring(err); self:stop("error"); warn("[arteria] echo farm: " .. self.error) end
    self:refresh()
    return ok
end
function Echo:resume()
    if self.running or not self.session.enabled then return end
    if not self.resume_authorized then self.state = "confirmation required"; self:refresh(); return end
    if game.PlaceId == 4111023553 then
        local ok, err = pcall(function() self:queue_bootstrap() end)
        self.state = "waiting for world"
        if not ok then self.error = tostring(err) end
        self:refresh()
    elseif self.runtime.status == "ready" and getgenv().local_player.root_part then
        self:start(self.session.slot, true)
    end
end
return Echo

end;

__modules["src/arteria/echo_transfer"] = function()
-- A bounded menu continuation using the same StartMenu/Servers interfaces as
-- the legacy hopper, without its missing IP-data file or endless click loop.
local Transfer = {}
function Transfer.source(slot, wipe, token, previous_server)
    local source = [[
if not game:IsLoaded() then game.Loaded:Wait() end
if game.PlaceId ~= 4111023553 then return end
local slot, wipe, token, previous = __SLOT__, __WIPE__, __TOKEN__, __PREVIOUS__
local http = game:GetService("HttpService")
local function active()
    local ok, value = pcall(function() return http:JSONDecode(readfile("Arteria/echo-session.json")) end)
    return ok and type(value) == "table" and value.enabled and value.token == token
end
if not active() then return end
local connections = {}
local ok, err = pcall(function()
    local rs = game:GetService("ReplicatedStorage")
    local player = game:GetService("Players").LocalPlayer
    local requests = assert(rs:WaitForChild("Requests", 30), "Requests unavailable")
    local menu = assert(requests:WaitForChild("StartMenu", 30), "StartMenu unavailable")
    local show = assert(requests:WaitForChild("ShowServers", 15), "Server list unavailable")
    local pick_slot = assert(menu:WaitForChild("PickSlot", 15), "Slot selection unavailable")
    local pick_server = assert(menu:WaitForChild("PickServer", 15), "Server selection unavailable")
    local servers = assert(rs:WaitForChild("Servers", 15), "Servers unavailable")
    local joining
    table.insert(connections, show.OnClientEvent:Connect(function(luminant)
        if not active() or joining then return end
        local group = servers:FindFirstChild(tostring(luminant))
        if not group then return end
        local candidates = {}
        for _, server in ipairs(group:GetChildren()) do
            local count, capacity = server:FindFirstChild("NumPlayers"), server:FindFirstChild("MaxPlayers")
            local id = server:GetAttribute("JobId")
            if count and capacity and id and id ~= previous and count.Value < capacity.Value then
                table.insert(candidates, { id = id, count = count.Value })
            end
        end
        table.sort(candidates, function(a,b) return a.count < b.count end)
        local choice = candidates[1]
        if choice and active() then joining = choice.id; pick_server:FireServer(choice.id) end
    end))
    table.insert(connections, game:GetService("TeleportService").TeleportInitFailed:Connect(function()
        joining = nil
    end))
    local deadline = os.clock() + 120
    while active() and (not workspace:GetAttribute("ServerReady") or not player:GetAttribute("GameLoaded")) do
        assert(os.clock() < deadline, "Menu initialization timed out")
        task.wait(0.25)
    end
    if not active() then return end
    if wipe then
        local remote = assert(requests:WaitForChild("WipeSlot", 15), "WipeSlot unavailable")
        if not active() then return end
        remote:InvokeServer(slot)
    end
    local deadline = os.clock() + 90
    while active() and os.clock() < deadline do
        if not joining then pick_slot:FireServer(slot, { PrivateTest = false }) end
        task.wait(5)
    end
    if active() then error("Echo transfer timed out; check the selected slot and available servers") end
end)
for _, connection in ipairs(connections) do connection:Disconnect() end
if not ok then
    warn("[arteria] echo transfer: " .. tostring(err))
    local loaded, state = pcall(function() return http:JSONDecode(readfile("Arteria/echo-session.json")) end)
    if loaded and state.token == token then
        state.enabled, state.transfer_error = false, tostring(err)
        writefile("Arteria/echo-session.json", http:JSONEncode(state))
    end
end
]]
    local values = { __SLOT__ = string.format("%q", slot), __WIPE__ = tostring(wipe == true),
        __TOKEN__ = string.format("%q", token), __PREVIOUS__ = string.format("%q", previous_server or "") }
    return (source:gsub("__[A-Z]+__", function(key) return assert(values[key], key) end))
end
return Transfer

end;

__modules["src/arteria/init"] = function()
-- Arteria has its own entry point. The complete legacy tree remains available.
if not game:IsLoaded() then game.Loaded:Wait() end
local env = getgenv()
if env.arteria then env.arteria:destroy() end
if env.aztup and env.aztup.detach then env.aztup:detach() end

require("@src/luarmor_init_script")
env.env = env
if not isfolder("Frutiger") then makefolder("Frutiger") end
local Maid = require("@src/utility/maid")
local catalog = require("@src/arteria/catalog")
local compat = require("@src/arteria/compat")
local runtime = {
    maid = Maid.new(), features = {}, flags = {
        fly = false, speed = false, infinite_jump = false,
        fly_speed = 60, walk_speed = 32, jump_power = 50,
    },
    farms = {}, silent_mode = true, alive = true, status = "loading", catalog = catalog,
    entries = {}, errors = {}, restorers = {}, brand = "arteria",
}
env.arteria = runtime
env.aztup = runtime -- Compatibility contract used by the retained modules.
runtime.automation = {
    has_any = function() return runtime.echo and runtime.echo.running or false end,
    should_auto_start = function() return runtime.echo and runtime.echo.session.enabled == true or false end,
}
env.Logger = require("@src/utility/logger")
env.Library = {
    AccentColor = Color3.fromRGB(222, 219, 210),
    AddTextToInfoLogger = function(_, message) print("[arteria]", message) end,
    Notify = function(_, message) warn("[arteria]", message) end,
    NotifyWithSound = function(_, message) warn("[arteria]", message) end,
}
env.Logger.notify_sound = function(_, message) warn("[arteria]", message) end
env.Logger.long_notify_sound = env.Logger.notify_sound
env.Feature = require("@src/features/generic_feature")
env.Tween = require("@src/utility/deepwoken/safe_tween")
env.aztup_toggles = {}
env.aztup_options = {}
compat.configure(runtime)
for _, entry in ipairs(catalog.entries) do
    runtime.entries[entry.id] = entry
    runtime.flags[entry.id] = false
    for _, option in ipairs(entry.settings) do
        runtime.flags[option.id] = option.value
        env.aztup_options[option.id] = { Value = option.value }
    end
    env.aztup_toggles[entry.id] = { SetValue = function(_, value) runtime:set(entry.id, value) end }
end
-- Fake void's original implementation requires this internal dependency.
runtime.entries.no_kill_bricks = { id = "no_kill_bricks", path = "@src/features/removals/no_kill_bricks", settings = {} }
env.aztup_toggles.no_kill_bricks = { SetValue = function(_, value) runtime:set("no_kill_bricks", value) end }
runtime.flags.no_kill_bricks = false
local farm_dependencies = {
    mod_detector = "@src/features/misc/mod_detector/mod_detector",
    jesus = "@src/features/qol/jesus",
    auto_equip_weapon = "@src/features/automation/auto_equip_weapon",
}
for id, path in pairs(farm_dependencies) do
    runtime.entries[id] = { id = id, path = path, settings = {} }
    runtime.flags[id] = false
    env.aztup_toggles[id] = { SetValue = function(_, value) runtime:set(id, value) end }
end

local player = services.Players.LocalPlayer
env.local_player = { instance = player }
local character_maid = Maid.new()
runtime.maid:give_task(character_maid)

function runtime:set(id, enabled)
    local entry = self.entries[id]
    if not self.alive or not entry or self.flags[id] == enabled then return end
    if enabled and (self.status ~= "ready" or self.busy) then return end
    if enabled and not env.local_player.root_part then return end
    if enabled and ((id == "fake_void" or id == "no_castle_light_gate" or id == "no_yun_shul_gate") and not env.is_depths
        or id == "no_hive_gate" and not env.is_eastern) then
        self.errors[id] = entry.note
        self.refresh()
        return
    end
    if entry.kind == "action" then
        self.busy = true
        self.refresh()
        local ok, err = pcall(function()
            compat.prepare(self)
            local action_fn = require(entry.path)
            if type(action_fn) == "function" then
                action_fn()
            elseif type(action_fn) == "table" and type(action_fn.run) == "function" then
                action_fn:run()
            end
        end)
        self.busy = false
        if not ok then
            self.errors[id] = tostring(err)
            warn("[arteria] " .. id .. ": " .. tostring(err))
        end
        self.flags[id] = false
        self.refresh()
        return
    end
    local needs_observers = entry.kind == "parry" or entry.kind == "parry-flag" or entry.kind == "observer"
    if enabled and entry.kind ~= "flag" and (not self.features[id] or needs_observers and not self.observers_loaded) then
        self.busy = true
        self.refresh()
        local loaded, load_err = pcall(function()
            if entry.kind ~= "visual" and entry.kind ~= "visual-init" then compat.prepare(self) end
            self.restorers[id] = compat.restore_point(id)
            if entry.path and not self.features[id] then
                local module = require(entry.path)
                if entry.kind == "visual-init" then module = module() end
                self.features[id] = module
            end
            if needs_observers then
                compat.observers(self)
            end
        end)
        self.busy = false
        if not self.alive then
            local late_feature = self.features[id]
            if late_feature then pcall(late_feature.disable, late_feature) end
            if self.restorers[id] then pcall(self.restorers[id]); self.restorers[id] = nil end
            self.maid:do_cleaning()
            return
        end
        if not loaded then
            if self.restorers[id] then pcall(self.restorers[id]); self.restorers[id] = nil end
            self.errors[id] = tostring(load_err)
            warn("[arteria] " .. id .. ": " .. tostring(load_err))
            self.refresh()
            return
        end
    end
    local feature = self.features[id]
    self.errors[id] = nil
    if not feature then
        self.flags[id] = enabled
        if id == "auto_parry" and not enabled and env.DefendActionManager then
            table.clear(env.DefendActionManager.actions_to_play_through)
        end
        self.refresh()
        return
    end
    local was_enabled = self.flags[id]
    self.flags[id] = enabled
    local ok, err = pcall(function()
        if feature.current_connection then
            feature.current_connection:Disconnect()
            feature.current_connection = nil
        end
        if enabled then
            if not self.restorers[id] then self.restorers[id] = compat.restore_point(id) end
            self.enabling = id
            if id == "auto_builder" then
                local mode = env.aztup_options.auto_builder_mode and env.aztup_options.auto_builder_mode.Value or "Talents & Points"
                feature.shrined = (env.aztup_options.auto_builder_shrined and env.aztup_options.auto_builder_shrined.Value == "On")
                if mode == "Talents & Points" or mode == "Talents only" then pcall(function() feature:build() end) end
                if mode == "Talents & Points" or mode == "Points only" then pcall(function() feature:put_points() end) end
            else
                feature:enable()
            end
            self.enabling = nil
            if not self.alive then feature:disable(); return end
            if not self.flags[id] then return end
            -- Auto-fight owns an RBXScriptConnection rather than a signal.
            if typeof(feature.conn) ~= "RBXScriptSignal" then return end
            feature.current_connection = feature.conn:Connect(function(dt)
                local data = env.local_player
                if not self.alive or not self.flags[id] then return end
                if not data.character or not data.root_part or not data.humanoid then return end
                if data.humanoid.Health <= 0 or services.UserInputService:GetFocusedTextBox() then return end
                local updated, update_err = pcall(feature.update, dt)
                if not updated then
                    self:set(id, false)
                    self.errors[id] = tostring(update_err)
                    warn("[arteria] " .. id .. ": " .. tostring(update_err))
                    if self.refresh then self.refresh() end
                end
            end)
        else
            if id == "auto_builder" then
                pcall(function() feature:killswitch() end)
                pcall(function() feature:points_killswitch() end)
            else
                feature:disable()
            end
            if self.restorers[id] then self.restorers[id](); self.restorers[id] = nil end
        end
    end)
    self.enabling = nil
    if not ok then
        self.flags[id] = false
        if feature.current_connection then feature.current_connection:Disconnect() end
        feature.current_connection = nil
        pcall(feature.disable, feature)
        if self.restorers[id] then pcall(self.restorers[id]); self.restorers[id] = nil end
        self.errors[id] = tostring(err)
        warn("[arteria] " .. id .. ": " .. tostring(err))
    end
    -- The legacy modules schedule the shared cap override for deletion. Wait
    -- until that deletion has passed before renewing it for a remaining user.
    if was_enabled and not enabled and (id == "fly" or id == "speed") and (self.flags.fly or self.flags.speed) and env.EffectReplicator then
        local renewal = task.delay(1.1, function()
            if self.alive and (self.flags.fly or self.flags.speed) then
                env.EffectReplicator:CreateEffect("OverrideSpeedCap")
            end
        end)
        self.maid:give_task(function() pcall(task.cancel, renewal) end)
    end
    if self.refresh then self.refresh() end
end

function runtime:option(option, value)
    self.flags[option.id] = value
    if env.aztup_options[option.id] then env.aztup_options[option.id].Value = value end
    if option.id == "arteria_anim_speed" then compat.animation_speed(self, value) end
    if option.id == "auto_feint" then self.flags.auto_feint = (value == "On") end
    if option.id == "basic_validation" then self.flags.basic_validation = (value == "On") end
    if option.id == "view_hitboxes" then self.flags.view_hitboxes = (value == "On") end
    if option.id == "auto_parry_fallback" and env.aztup_options.fallbacks then
        env.aztup_options.fallbacks.Value = { [value] = true }
    end
end

function runtime:destroy()
    if not self.alive then return end
    if self.echo then self.echo:stop("stopped") end
    -- Disable dependants before the internal dependency they own.
    self:set("fake_void", false)
    for id in pairs(self.entries) do self:set(id, false) end
    self.alive = false
    self.maid:do_cleaning()
    if self.gui then self.gui:Destroy() end
    -- Existing security hooks are not reversible through the legacy API.
    -- Keep the disabled compatibility state alive for their closures.
end
runtime.detach = runtime.destroy

local function bind_character(character)
    for id in pairs(runtime.entries) do runtime:set(id, false) end
    character_maid:do_cleaning()
    env.local_player.character = character
    env.local_player.root_part = character:FindFirstChild("HumanoidRootPart")
    env.local_player.humanoid = character:FindFirstChildOfClass("Humanoid")
    if env.local_player.character_added then env.local_player.character_added:fire(character) end
    character_maid:give_task(character.ChildAdded:Connect(function(child)
        if child.Name == "HumanoidRootPart" then env.local_player.root_part = child end
        if child:IsA("Humanoid") then env.local_player.humanoid = child end
        if runtime.echo and runtime.status == "ready" and env.local_player.root_part and env.local_player.humanoid then runtime.echo:resume() end
    end))
    character_maid:give_task(character.ChildRemoved:Connect(function(child)
        if child == env.local_player.root_part then env.local_player.root_part = nil end
        if child == env.local_player.humanoid then env.local_player.humanoid = nil end
    end))
end
runtime.maid:give_task(player.CharacterAdded:Connect(bind_character))
runtime.maid:give_task(player.CharacterRemoving:Connect(function()
    if runtime.echo and runtime.echo.running then runtime.echo:stop("waiting for character", true) end
    for id in pairs(runtime.entries) do runtime:set(id, false) end
    character_maid:do_cleaning()
    env.local_player.character = nil
    env.local_player.root_part = nil
    env.local_player.humanoid = nil
end))
runtime.echo = require("@src/arteria/echo").new(runtime, compat.prepare)
runtime.config = require("@src/arteria/config").new(runtime)
runtime.ui_key = Enum.KeyCode.RightShift
if player.Character then bind_character(player.Character) end

require("@src/arteria/ui").mount(runtime)
if game.PlaceId == 4111023553 then
    runtime.status = "join a game first"
    runtime.refresh()
    runtime.echo:resume()
    return runtime
end

-- Load the existing AC path unchanged. Requiring it does not prove that its
-- asynchronous hooks succeed; the UI deliberately never claims protection.
task.spawn(function()
    local ok, err = pcall(function()
        assert(require("@src/features/hooking"), "existing AC layer failed to load")
        if not runtime.alive then return end
        runtime.ac_loaded = true
        local raw_effects = services.ReplicatedStorage:WaitForChild("EffectReplicator", 15)
        assert(raw_effects, "EffectReplicator unavailable")
        env.EffectReplicator = base_require(raw_effects)
        -- Feature factories are now loaded on first enable, never at startup.
        if runtime.alive then
            runtime.status = "ready"
            pcall(function() runtime.config:autoload() end)
            runtime.echo:resume()
        end
    end)
    if not runtime.alive then return end
    if not ok then
        runtime.status = "initialization failed"
        warn("[arteria] " .. tostring(err))
    end
    runtime.refresh()
end)
return runtime

end;

__modules["src/arteria/mob_esp"] = function()
-- Arteria Mob ESP: Skeletons (Motor6D + R6/R15 fallback), Health bars & values, Distance labels.
-- Bounded, pre-allocated screen-space line and text pools. Zero per-frame allocations.
local theme = require("@src/arteria/theme")
local C = theme.color
local feature = { id = "mob_esp", targets = {}, bones_cache = {} }
local players = game:GetService("Players")

local function create(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props) do object[key] = value end
    object.Parent = parent
    return object
end

local function clean_name(raw)
    local name = tostring(raw):gsub("<[^>]*>", ""):gsub("^%.", ""):gsub("%d+$", ""):gsub("_", " ")
    name = name:match("^%s*(.-)%s*$")
    if name == "" then name = "Mob" end
    return name
end

local function get_mob_bones(model)
    local bones = {}
    -- 1. Query active Motor6D joints connecting body parts
    local ok_desc, all_parts = pcall(function() return model:GetDescendants() end)
    if ok_desc and type(all_parts) == "table" then
        for _, motor in ipairs(all_parts) do
            if motor.IsA and motor:IsA("Motor6D") and motor.Part0 and motor.Part1 and motor.Part0.IsA and motor.Part0:IsA("BasePart") and motor.Part1.IsA and motor.Part1:IsA("BasePart") then
                table.insert(bones, { motor.Part0, motor.Part1 })
                if #bones >= 24 then break end
            end
        end
    end
    if #bones > 0 then
        return bones
    end
    -- 2. Fallback to standard named rig parts if no Motor6D joints exist
    local head = model:FindFirstChild("Head")
    local torso = model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso")
    if head and torso and head:IsA("BasePart") and torso:IsA("BasePart") then
        table.insert(bones, { head, torso })
    end
    if torso and torso:IsA("BasePart") then
        local names = { "Left Arm", "Right Arm", "Left Leg", "Right Leg", "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg" }
        for _, name in ipairs(names) do
            local limb = model:FindFirstChild(name)
            if limb and limb:IsA("BasePart") then
                table.insert(bones, { torso, limb })
            end
        end
    end
    return bones
end

local MAX_MOBS = 50
local BONES_PER_MOB = 20

function feature:render(dt)
    local camera = workspace.CurrentCamera
    if not camera or camera.ViewportSize.X < 16 or camera.ViewportSize.Y < 48 then return end

    local own_character = players.LocalPlayer.Character
    local own_root = own_character and own_character:FindFirstChild("HumanoidRootPart")
    local origin = own_root and own_root.Position or camera.CFrame.Position

    local live = workspace:FindFirstChild("Live")
    if not live then return end

    local max_dist = aztup.flags.arteria_mob_range or 2000
    local show_skeleton = aztup_options.arteria_mob_skeleton.Value == "Enabled"
    local health_mode = aztup_options.arteria_mob_health.Value
    local show_dist = aztup_options.arteria_mob_distance.Value == "Shown"
    local thickness = aztup.flags.arteria_mob_thickness or 1
    local text_size = aztup.flags.arteria_mob_text or 13
    local limit = math.min(MAX_MOBS, aztup.flags.arteria_mob_limit or 40)

    -- Collect living mob candidates
    local candidates = {}
    for _, mob in ipairs(live:GetChildren()) do
        if mob:IsA("Model") and mob.Name:sub(1, 1) == "." and not mob.Name:match("watcher") and mob ~= own_character then
            local root = mob:FindFirstChild("HumanoidRootPart") or mob:FindFirstChild("Torso") or mob:FindFirstChildWhichIsA("BasePart")
            local humanoid = mob:FindFirstChildOfClass("Humanoid")
            if root and root:IsA("BasePart") and humanoid and humanoid.Health > 0 then
                local dist = (root.Position - origin).Magnitude
                if dist <= max_dist then
                    table.insert(candidates, { mob = mob, root = root, humanoid = humanoid, dist = dist })
                end
            end
        end
    end

    table.sort(candidates, function(a, b) return a.dist < b.dist end)

    local active_count = math.min(#candidates, limit)
    local now = os.clock()

    for i = 1, MAX_MOBS do
        local slot = self.pool[i]
        if i <= active_count then
            local item = candidates[i]
            local mob, root, humanoid, dist = item.mob, item.root, item.humanoid, item.dist
            local point, on_screen = camera:WorldToViewportPoint(root.Position)

            if on_screen and point.Z > 0 then
                -- 1. Render Skeleton Bones
                local bone_pairs = self.bones_cache[mob]
                if not bone_pairs or (now - (slot.cache_time or 0) > 3) then
                    bone_pairs = get_mob_bones(mob)
                    self.bones_cache[mob] = bone_pairs
                    slot.cache_time = now
                end

                local bone_idx = 0
                if show_skeleton and bone_pairs then
                    for _, pair in ipairs(bone_pairs) do
                        if pair[1].Parent and pair[2].Parent then
                            local p0, v0 = camera:WorldToViewportPoint(pair[1].Position)
                            local p1, v1 = camera:WorldToViewportPoint(pair[2].Position)
                            if (v0 or v1) and p0.Z > 0 and p1.Z > 0 then
                                bone_idx = bone_idx + 1
                                if bone_idx <= BONES_PER_MOB then
                                    local line = slot.bones[bone_idx]
                                    local dx, dy = p1.X - p0.X, p1.Y - p0.Y
                                    local length = math.sqrt(dx * dx + dy * dy)
                                    if length > 0.5 then
                                        line.Position = UDim2.fromOffset((p0.X + p1.X) / 2, (p0.Y + p1.Y) / 2)
                                        line.Size = UDim2.fromOffset(length, thickness)
                                        line.Rotation = math.deg(math.atan2(dy, dx))
                                        line.Visible = true
                                    else
                                        line.Visible = false
                                    end
                                end
                            end
                        end
                    end
                end
                for b = bone_idx + 1, BONES_PER_MOB do
                    slot.bones[b].Visible = false
                end

                -- 2. Render Name, Health, and Distance Label
                local name = clean_name(mob:GetAttribute("MOB_rich_name") or mob.Name)
                local hp = math.floor(humanoid.Health)
                local max_hp = math.floor(math.max(1, humanoid.MaxHealth))
                local ratio = math.clamp(hp / max_hp, 0, 1)

                local lines = { name }
                if show_dist then
                    table.insert(lines, string.format("%d studs", math.floor(dist)))
                end
                if health_mode == "Value" or health_mode == "Bar and value" then
                    table.insert(lines, string.format("%d / %d HP", hp, max_hp))
                end

                slot.label.Text = table.concat(lines, "  ·  ")
                slot.label.TextSize = text_size
                slot.label.Position = UDim2.fromOffset(point.X, point.Y - 26)
                slot.label.Visible = true

                -- 3. Render Health Bar
                if health_mode == "Bar" or health_mode == "Bar and value" then
                    local bounds = slot.label.TextBounds
                    local bar_w = (bounds and bounds.X > 0) and math.clamp(bounds.X + 8, 48, 120) or 64
                    slot.bar_track.Size = UDim2.fromOffset(bar_w, 3)
                    slot.bar_track.Position = UDim2.fromOffset(point.X, point.Y - 14)
                    slot.bar_track.Visible = true

                    slot.bar_fill.Size = UDim2.fromOffset(math.max(1, math.floor(bar_w * ratio)), 3)
                    slot.bar_fill.Position = UDim2.fromOffset(point.X - bar_w / 2 + (bar_w * ratio) / 2, point.Y - 14)
                    slot.bar_fill.BackgroundColor3 = ratio < 0.25 and C.alert or C.neon
                    slot.bar_fill.Visible = true
                else
                    slot.bar_track.Visible = false
                    slot.bar_fill.Visible = false
                end
            else
                slot:hide()
            end
        else
            slot:hide()
        end
    end
end

function feature:enable()
    self:disable()
    self.pool = {}
    self.bones_cache = {}

    self.gui = create("ScreenGui", {
        Name = "ArteriaMobESP",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 96,
    }, players.LocalPlayer:WaitForChild("PlayerGui"))

    for i = 1, MAX_MOBS do
        local slot = { bones = {} }

        for b = 1, BONES_PER_MOB do
            local line = create("Frame", {
                Name = "MobBone",
                BorderSizePixel = 0,
                BackgroundColor3 = C.neon,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Visible = false,
            }, self.gui)
            table.insert(slot.bones, line)
        end

        slot.label = create("TextLabel", {
            Name = "MobLabel",
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Font = theme.font.mono,
            TextColor3 = C.text,
            TextStrokeColor3 = C.ink,
            TextStrokeTransparency = 0.15,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Text = "",
            Visible = false,
        }, self.gui)

        slot.bar_track = create("Frame", {
            Name = "HealthTrack",
            BorderSizePixel = 0,
            BackgroundColor3 = C.ink,
            BackgroundTransparency = 0.3,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Visible = false,
        }, self.gui)

        slot.bar_fill = create("Frame", {
            Name = "HealthFill",
            BorderSizePixel = 0,
            BackgroundColor3 = C.neon,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Visible = false,
        }, self.gui)

        function slot:hide()
            for _, b in ipairs(self.bones) do b.Visible = false end
            self.label.Visible = false
            self.bar_track.Visible = false
            self.bar_fill.Visible = false
        end

        table.insert(self.pool, slot)
    end

    self.conn = game:GetService("RunService").RenderStepped:Connect(function(dt)
        local ok, err = pcall(self.render, self, dt)
        if not ok then
            local runtime = getgenv().arteria
            if runtime then runtime.errors.mob_esp = tostring(err); runtime.refresh() end
            aztup_toggles.mob_esp:SetValue(false)
            warn("[arteria] mob ESP: " .. tostring(err))
        end
    end)
end

function feature:disable()
    if self.conn then self.conn:Disconnect(); self.conn = nil end
    if self.gui then self.gui:Destroy(); self.gui = nil end
    self.pool = {}
    self.bones_cache = {}
end

return feature

end;

__modules["src/arteria/mod_detector"] = function()
-- Arteria Mod Notification: Real-time Deepwoken staff and moderator detection.
-- Displays a prominent neon alert banner on screen and updates Arteria status.
local theme = require("@src/arteria/theme")
local C = theme.color
local feature = { id = "mod_detector", detected_mods = {}, active_alerts = {} }
local players = game:GetService("Players")
local raw_task = task or { spawn = function(f) coroutine.resume(coroutine.create(f)) end, wait = function() end }

local moderator_map = require("@src/features/misc/mod_detector/group_members")

local function create(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props) do object[key] = value end
    object.Parent = parent
    return object
end

function feature:show_banner(player_name, role)
    if not self.gui then return end

    local text_content = string.format("STAFF DETECTED  //  %s  (%s)", string.upper(player_name), string.upper(role))

    local banner = create("Frame", {
        Name = "ModAlert_" .. player_name,
        BackgroundColor3 = C.ink,
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(480, 50),
        Position = UDim2.new(0.5, -240, 0, 18),
        ZIndex = 10,
    }, self.gui)

    local stroke = create("UIStroke", {
        Color = C.alert,
        Thickness = 1.5,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, banner)

    local outer_glow = create("UIStroke", {
        Color = C.alert_glow,
        Thickness = 5,
        Transparency = 0.85,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    }, banner)

    local icon = create("TextLabel", {
        Text = "[ ! ]",
        Font = theme.font.heading,
        TextSize = 18,
        TextColor3 = C.alert,
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(14, 0),
        Size = UDim2.fromOffset(40, 50),
        TextXAlignment = Enum.TextXAlignment.Center,
        ZIndex = 11,
    }, banner)

    local msg = create("TextLabel", {
        Text = text_content,
        Font = theme.font.mono,
        TextSize = 13,
        TextColor3 = C.text,
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(60, 0),
        Size = UDim2.new(1, -110, 1, 0),
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 11,
    }, banner)

    local dismiss = create("TextButton", {
        Text = "DISMISS",
        Font = theme.font.mono,
        TextSize = 10,
        TextColor3 = C.muted,
        BackgroundColor3 = C.surface,
        BorderSizePixel = 0,
        Position = UDim2.new(1, -80, 0.5, -13),
        Size = UDim2.fromOffset(70, 26),
        ZIndex = 12,
    }, banner)

    dismiss.Activated:Connect(function()
        banner:Destroy()
    end)

    -- Play alert sound
    if aztup_options.arteria_mod_sound.Value == "On" then
        pcall(function()
            local sound = Instance.new("Sound", game:GetService("CoreGui"))
            sound.SoundId = "rbxassetid://9069609200"
            sound.Volume = 1.5
            sound:Play()
            game:GetService("Debris"):AddItem(sound, 3)
        end)
    end
end

function feature:check_player(player)
    if player == players.LocalPlayer then return end
    local uid = tostring(player.UserId)
    local role = moderator_map[uid]

    if not role then
        local success, in_group = pcall(function()
            return player:GetRankInGroup(5212858) > 0
        end)
        if success and in_group then
            role = "Staff Group Member"
        end
    end

    if role and not self.detected_mods[player] then
        self.detected_mods[player] = role
        self:show_banner(player.Name, role)

        local runtime = getgenv().arteria
        if runtime then
            runtime.errors.mod_detector = string.format("STAFF: %s (%s)", player.Name, role)
            if runtime.refresh then runtime.refresh() end
        end

        warn(string.format("[arteria] MODERATOR DETECTED: %s (%s)", player.Name, role))

        -- Optional auto-serverhop
        if aztup_options.arteria_mod_serverhop.Value == "On" then
            pcall(function()
                local slot = players.LocalPlayer:GetAttribute("DataSlot")
                server_utility:hop(slot, "any", true)
            end)
        end
    end
end

function feature:enable()
    self:disable()
    self.detected_mods = {}

    self.gui = create("ScreenGui", {
        Name = "ArteriaModAlerts",
        ResetOnSpawn = false,
        DisplayOrder = 999,
    }, players.LocalPlayer:WaitForChild("PlayerGui"))

    self.conn_added = players.PlayerAdded:Connect(function(player)
        raw_task.wait(1)
        self:check_player(player)
    end)

    self.conn_removed = players.PlayerRemoving:Connect(function(player)
        if self.detected_mods[player] then
            self.detected_mods[player] = nil
        end
    end)

    -- Scan current players in server
    raw_task.spawn(function()
        for _, player in ipairs(players:GetPlayers()) do
            self:check_player(player)
        end
    end)
end

function feature:disable()
    if self.conn_added then self.conn_added:Disconnect(); self.conn_added = nil end
    if self.conn_removed then self.conn_removed:Disconnect(); self.conn_removed = nil end
    if self.gui then self.gui:Destroy(); self.gui = nil end
    self.detected_mods = {}
end

return feature

end;

__modules["src/arteria/npc_esp"] = function()
-- Arteria NPC ESP: Neon text labels and distance markers.
-- Bounded, pre-allocated text pool. Zero per-frame allocations.
local theme = require("@src/arteria/theme")
local C = theme.color
local feature = { id = "npc_esp", pool = {} }
local players = game:GetService("Players")

local function create(class, props, parent)
    local object = Instance.new(class)
    for key, value in pairs(props) do object[key] = value end
    object.Parent = parent
    return object
end

local function clean_name(raw)
    local name = tostring(raw):gsub("<[^>]*>", ""):gsub("^%.", ""):gsub("%d+$", ""):gsub("_", " ")
    name = name:match("^%s*(.-)%s*$")
    if name == "" then name = "NPC" end
    return name
end

local MAX_NPCS = 50

function feature:render(dt)
    local camera = workspace.CurrentCamera
    if not camera or camera.ViewportSize.X < 16 or camera.ViewportSize.Y < 48 then return end

    local own_character = players.LocalPlayer.Character
    local own_root = own_character and own_character:FindFirstChild("HumanoidRootPart")
    local origin = own_root and own_root.Position or camera.CFrame.Position

    local max_dist = aztup.flags.arteria_npc_range or 2000
    local text_size = aztup.flags.arteria_npc_text or 13

    local npcs_folder = workspace:FindFirstChild("NPCs")
    if not npcs_folder then return end

    local candidates = {}
    for _, npc in ipairs(npcs_folder:GetChildren()) do
        local root = npc:FindFirstChild("HumanoidRootPart") or npc:FindFirstChild("Torso") or npc:FindFirstChildWhichIsA("BasePart")
        if root and root:IsA("BasePart") then
            local dist = (root.Position - origin).Magnitude
            if dist <= max_dist then
                table.insert(candidates, { npc = npc, root = root, dist = dist })
            end
        end
    end

    table.sort(candidates, function(a, b) return a.dist < b.dist end)

    local active_count = math.min(#candidates, MAX_NPCS)

    for i = 1, MAX_NPCS do
        local slot = self.pool[i]
        if i <= active_count then
            local item = candidates[i]
            local npc, root, dist = item.npc, item.root, item.dist
            local point, on_screen = camera:WorldToViewportPoint(root.Position + Vector3.new(0, 2, 0))

            if on_screen and point.Z > 0 then
                local name = clean_name(npc:GetAttribute("NPC_rich_name") or npc:GetAttribute("Name") or npc.Name)
                slot.label.Text = string.format("[NPC] %s  ·  %d studs", name, math.floor(dist))
                slot.label.TextSize = text_size
                slot.label.Position = UDim2.fromOffset(point.X, point.Y - 10)
                slot.label.Visible = true

                slot.dot.Position = UDim2.fromOffset(point.X, point.Y)
                slot.dot.Visible = true
            else
                slot.label.Visible = false
                slot.dot.Visible = false
            end
        else
            slot.label.Visible = false
            slot.dot.Visible = false
        end
    end
end

function feature:enable()
    self:disable()
    self.pool = {}

    self.gui = create("ScreenGui", {
        Name = "ArteriaNPCESP",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 94,
    }, players.LocalPlayer:WaitForChild("PlayerGui"))

    for i = 1, MAX_NPCS do
        local slot = {}

        slot.dot = create("Frame", {
            Name = "Dot",
            BorderSizePixel = 0,
            BackgroundColor3 = C.neon,
            Size = UDim2.fromOffset(3, 3),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Visible = false,
        }, self.gui)

        slot.label = create("TextLabel", {
            Name = "NPCLabel",
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Font = theme.font.mono,
            TextColor3 = C.text,
            TextStrokeColor3 = C.ink,
            TextStrokeTransparency = 0.15,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Text = "",
            Visible = false,
        }, self.gui)

        table.insert(self.pool, slot)
    end

    self.conn = game:GetService("RunService").RenderStepped:Connect(function(dt)
        local ok, err = pcall(self.render, self, dt)
        if not ok then
            aztup_toggles.npc_esp:SetValue(false)
            local runtime = getgenv().arteria
            if runtime then runtime.errors.npc_esp = tostring(err); runtime.refresh() end
            warn("[arteria] NPC ESP: " .. tostring(err))
        end
    end)
end

function feature:disable()
    if self.conn then self.conn:Disconnect(); self.conn = nil end
    if self.gui then self.gui:Destroy(); self.gui = nil end
    self.pool = {}
end

return feature

end;

