                game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("Craft"):InvokeServer(unpack(args))
            end)
            task.wait(1)
        elseif has_iron and has_coal then
            task.spawn(function()
                local args = {
                    {
                        Coal = true,
                        Iron = true
                    }
                }
                game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("Craft"):InvokeServer(unpack(args))
            end)
            task.wait(1)
        elseif has_rock and has_coal then
            task.spawn(function()
                local args = {
                    {
