                        end
                        task.wait();
                    end
                end

                task.wait(5)
                
                --Mine coal
                if not has_coal then
                    self.temp_tween(nearest_coal.CFrame, 170)
                    for i = 0, 60 do
                        pcall(function(...)  
                            fireproximityprompt(nearest_coal.InteractPrompt)
                        end)
                        
                        if self.player_near() then
                            self.server_hop()
