        --                    game:GetService("Players").LocalPlayer.PlayerGui.ChoicePrompt.Choice:InvokeServer(4)
        --                end)
        --            end)
        --            task.wait(1)
        --        until (local_player.instance.Backpack:FindFirstChild('Campfire Pit') and local_player.instance.Backpack['Campfire Pit'].Quantity.Value >= 4) or tick() - start >= 30
        --    end, print)
        --end
    end
    
    pcall(function() task.cancel(playercheck) end)
end

function autoferryman:create_instance()
    --autoferryman:bypass_ac()
    local function firestarter()
        local flint = local_player.instance.Backpack:FindFirstChild('Flint')
        local umbral_flint = local_player.instance.Backpack:FindFirstChild('Umbral Flint')
        
        if flint then
            return flint.ActivateRt
        elseif umbral_flint then
            return umbral_flint.ActivateRt
        end
        
        return nil
    end
    
    local area_location = services.ReplicatedStorage.MarkerWorkspace.AreaMarkers["Boatman's Watch"].AreaMarker.CFrame
    
    local dist = (local_player.root_part.Position - area_location.Position).Magnitude
    if dist >= 700 then
        task.spawn(train_math_textbook);
        self.player_safe_tween(self, area_location, bypassed and 999 or 250, false, boatmans_watch_path)
        local_player.root_part.CFrame = CFrame.new(area_location.X, 0, area_location.Z);
    end

    task.wait(1);

    local playercheck = task.spawn(function()
        while task.wait() do
            if self.player_near() then
                self.server_hop()
            end
        end
    end)

    if not workspace:FindFirstChild('MakeFires') then
        Tween.new(area_location, true, bypassed and 999 or 250).wait()
        repeat task.wait() until  workspace:FindFirstChild('MakeFires')
    end
    
    local campfire_locations = workspace:FindFirstChild('MakeFires'):GetChildren()

    repeat task.wait() until local_player.character
    
    services.RunService.Heartbeat:Connect(function() 
        aztup.features.m1_hold.held = hold_m1
    end)

    for _, campfire in workspace.Destructibles:GetChildren() do
        if not campfire.Name:match('Campfire') then continue end
        
        for _, location in campfire_locations do
            local dist = ((campfire:IsA("Model") and campfire:GetPivot() or campfire).Position - location.Position).Magnitude
            if dist <= 200 then 
                self.ready_weapon()
                local t;
                while campfire.Parent do
                    if t then
                        t.stop();
                    end;
                    
                    if not campfire:IsA("Model") and not campfire.Anchored then
                        break;
                    end;

                    if campfire:IsA("Model") and campfire:FindFirstChild("Campfire") and not campfire:FindFirstChild("Campfire").Anchored then
                        break;
                    end;

                    t = Tween.new(CFrame.new((campfire:IsA("Model") and campfire:GetPivot() or campfire).Position), true, bypassed and 999 or 250);
                    self.m1_hold(true)
                    task.wait();
                end;
                self.m1_hold(false)
            end
        end
    end

    local character_handler = local_player.character:FindFirstChild("CharacterHandler");
    character_handler.Requests.DrawWeapon:FireServer(false);
    
    local spoofing = false;
    local spoof_at;

    task.spawn(function() 
        aztup.flags.silent_aim = true;
        while task.wait(1 / 30) do
            if not spoofing then continue end;

            local v809 = buffer.create(24);
            buffer.writef64(v809, 0, spoof_at.X);
            buffer.writef64(v809, 8, spoof_at.Y);
            buffer.writef64(v809, 16, spoof_at.Z);
            local requests = services.ReplicatedStorage:FindFirstChild("Requests");
            local update_mouse = requests and requests:FindFirstChild("UpdateMouse");

            if update_mouse then
                update_mouse:FireServer(v809);
            end;
        end;
    end);

    task.wait(1.5) -- so we dont lagspike and place incorrectly

    local function campfire_count()
        local destructibles = workspace:FindFirstChild('Destructibles')
        if not destructibles then return 0 end

        local count = 0
        for _, campfire in destructibles:GetChildren() do
            if not campfire.Name:match('Campfire') then continue end

            local pivot = (campfire:IsA("Model") and campfire:GetPivot() or campfire).Position
            for _, location in campfire_locations do
                if (pivot - location.Position).Magnitude <= 200 then
                    count += 1
                    break
                end
            end
        end

        return count
    end

    local function campfire_exists_near(position, radius)
        local destructibles = workspace:FindFirstChild('Destructibles')
        if not destructibles then return false end

        for _, campfire in destructibles:GetChildren() do
            if not campfire.Name:match('Campfire') then continue end

            local pivot = (campfire:IsA("Model") and campfire:GetPivot() or campfire).Position
            if (pivot - position).Magnitude <= radius then
                return true
            end
        end

        return false
    end

    local function equip_campfire()
        local equipped = local_player.character and local_player.character:FindFirstChild('Campfire Pit')
        if equipped then return equipped end

        local stored = local_player.instance.Backpack:FindFirstChild('Campfire Pit')
        if not stored or not local_player.character then return nil end

        stored.Parent = local_player.character

        local start = tick()
        repeat task.wait() until (local_player.character and local_player.character:FindFirstChild('Campfire Pit')) or tick() - start >= 3

        return local_player.character and local_player.character:FindFirstChild('Campfire Pit')
    end

    local function place_campfire(location)
        local before = campfire_count()

        for attempt = 1, 16 do
            spoofing = true;
            spoof_at = location.MouseCF;

            self.temp_tween(location.CFrame, 250)
            if local_player.root_part then
                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
            end
            task.wait(0.5);

            local pit = equip_campfire()
            if not pit then
                if not local_player.instance.Backpack:FindFirstChild('Campfire Pit') then
                    return false
                end

                continue
            end

            pcall(function()
                pit:Activate()
            end)

            local start = tick()
            repeat task.wait() until campfire_count() > before or tick() - start >= 4

            if campfire_count() > before then return true end
        end

        return false
    end

    for _, location in {
        {
            MouseCF = CFrame.new(-4092.21118, 62.9762077, 9410.96094),
            CFrame =  CFrame.new(-4091.36743, 65.8562164, 9406.87793)
        },
        {
            MouseCF =  CFrame.new(-4108.79053, 62.763382, 9421.04004),
            CFrame = CFrame.new(-4109.85938, 65.8506699, 9417.92773)
        },
        {
            MouseCF = CFrame.new(-4096.95654, 62.7243958, 9440.11621),
            CFrame =  CFrame.new(-4098.92334, 65.8594055, 9440.22363),
        },
        {
            MouseCF = CFrame.new(-4080.64844, 62.9762077, 9428.41309),
            CFrame =  CFrame.new(-4078.77832, 65.7046738, 9424.35156),
        }
    } do
        if not campfire_exists_near(location.CFrame.Position, 12) then
            place_campfire(location)
        end
    end
    --aztup.flags.silent_aim = false;

    self.temp_tween(CFrame.new(-4103.17822, 65.7434998, 9413.24609), false, 200);
    task.wait(.5);
    pcall(function(...)  
        firestarter():FireServer()
    end)
    task.wait(3);
    self.temp_tween(CFrame.new(-4086.92041, 65.7434998, 9437.04395), false, 200);
    task.wait(.5);
    pcall(function(...)  
        firestarter():FireServer()
    end)
    task.wait(3);

    --pcall(function() task.cancel(playercheck) end)

    local time_wait = tick()
    repeat task.wait() until ((tick() - time_wait) >= 20)
    self.server_hop()
end

function autoferryman:kill_ferryman()
    if #services.Players:GetPlayers() ~= 1 then
        task.delay(5, function()
            server_utility:hop(local_player.instance:GetAttribute("DataSlot") or "A", true);
        end);

        return local_player.instance:Kick("AAAA WTF GUY IN OUR GAME !!!");
    end;

    services.Players.PlayerAdded:Connect(function() 
        task.delay(5, function()
            server_utility:hop(local_player.instance:GetAttribute("DataSlot") or "A", true);
        end);
        return local_player.instance:Kick("AAAA WTF GUY IN OUR GAME !!!");
    end);

    local function get_closest_tree()
        local closest = nil
        
        for _, tree in workspace.Destructibles:GetChildren() do
            if not tree.Name:match('Tree') then continue end
            if not tree:GetAttribute('StructureHealth') then continue end
            if tree:GetAttribute('StructureHealth') <= 0 then continue end
            
            if closest == nil then
                closest = tree
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                local treeDist = (local_player.root_part.Position - tree:GetPivot().Position).Magnitude
                
                if closestDist > treeDist then
                    closest = tree
                end
            end
        end
        
        return closest
    end

    
    -- temp until i add anti_afk
    task.spawn(function()
        local vim = Instance.new('VirtualInputManager')
        
        while task.wait(120) do
            vim:SendKeyEvent(true, Enum.KeyCode.Unknown, false, game)
            task.wait(0.1)
            vim:SendKeyEvent(false, Enum.KeyCode.Unknown, false, game)
            task.wait(0.1)
        end
    end)
    
    
    services.RunService.Heartbeat:Connect(function() 
        aztup.features.m1_hold.held = hold_m1
    end)
    
    local initcf = CFrame.new(-4094, 66, 9421)
    local heal_cf = CFrame.new(-3799, -1, 7788)

    aztup.automation.requesting_mob_ai_breaker_stop = true;

    train_math_textbook();

    pcall(function(...)
        self.temp_tween(workspace.NPCs['The Ferryman'].HumanoidRootPart.CFrame, 125)
        
        repeat
            pcall(function(...)  
                fireproximityprompt(workspace.NPCs['The Ferryman'].InteractPrompt)
            end)
            task.wait(.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        local args = {
            {
                choice = "Who are you?"
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
        
        task.wait(0.5)
        
        local args = {
            {
                choice = "[Tell him your name]"
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
        
        task.wait(0.5)
        
        local args = {
            {
                choice = "A wager?"
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
        
        task.wait(0.5)
        
        local args = {
            {
                choice = "Deal."
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
        
    end)
    
    local ferryman = nil
    
    repeat 
        for _, target in workspace.Live:GetChildren() do
            if target == local_player.character then continue end
            if not target.Name:lower():find('ferryman') then continue end
            
            ferryman = target
            break
        end
        task.wait()
    until ferryman


    -- Add anim detections
    local tripleattack = false
    local lastassualt = tick()
    local assualtlistener = nil
    
    local javelinattack = false
    local lastjavelin = tick()
    local javelinlistener = nil
    
    ferryman.Humanoid.Animator.AnimationPlayed:Connect(function(anim)
        if anim.Animation.AnimationId:match('rbxassetid://5968282214') then
            tripleattack = true
            lastassualt = tick()
            self.m1_hold(false)
            
            if assualtlistener == nil then
                assualtlistener = task.spawn(function()
                    repeat task.wait() until (tick() - lastassualt >= 1.5)
                    self.m1_hold(true)
                    tripleattack = false
                    assualtlistener = nil
                end)
            end
            
            return
        end
        
        if anim.Animation.AnimationId:match('rbxassetid://5968288116') then
            tripleattack = true
            lastassualt = tick()
            self.m1_hold(false)
            
            if assualtlistener == nil then
                assualtlistener = task.spawn(function()
                    repeat task.wait() until (tick() - lastassualt >= 1.5)
                    self.m1_hold(true)
                    tripleattack = false
                    assualtlistener = nil
                end)
            end
            
            return
        end
        
        if anim.Animation.AnimationId:match('rbxassetid://8183996606') then
            javelinattack = true
            lastjavelin = tick()
            
            if javelinlistener == nil then
                javelinlistener = task.spawn(function()
                    repeat task.wait() until (tick() - lastjavelin >= 1)
                    javelinattack = false
                    javelinlistener = nil
                end)
            end
            
            return
        end
    end)
    
    self.ready_weapon()
    self.m1_hold(true)
    
    local atb = nil
    local tween;
    local last = 0;
    local last_attunement = 0;
    local started_tweening = false;
    xpcall(function()
        repeat
                if (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * .35)) then
                    self.m1_hold(false)

                    repeat
                        self.m1_hold(false)
                        self.temp_tween(heal_cf, 125)
                        task.wait()
                    until (local_player.humanoid.Health >= (local_player.humanoid.MaxHealth * .85))

                    if not tripleattack then
                        self.m1_hold(true)
                    end
            elseif javelinattack then
                self.temp_tween(CFrame.new(local_player.root_part.CFrame.X, 0, local_player.root_part.CFrame.Z), 125)
                task.wait()
            elseif tripleattack then
                task.wait()
            else
                local start = 0;
                atb = task.spawn(function()
                    while task.wait() do
                        if not aztup.automation:has_any() then break; end
                        if ferryman.Parent == nil then break; end
                        if not ferryman:FindFirstChild('HumanoidRootPart') then break; end
                        if EffectReplicator:FindEffect("Knocked") or EffectReplicator:FindEffect("Ragdoll") then continue; end

                        --* CFrame.Angles(math.rad(-90), 0, 0) 
                        local cf = ferryman.HumanoidRootPart.CFrame * CFrame.new(0, -7, 4) 
                        local target_position = cf.Position
                        local target_cframe = CFrame.lookAt(target_position, ferryman.HumanoidRootPart.Position)
                        local got = false;
                        local_player.root_part.AssemblyLinearVelocity = Vector3.zero; 
                        local_player.root_part.Velocity = Vector3.zero; 

                        if (local_player.root_part.Position - target_position).Magnitude > 30  then
                            start = 0;
                            if not (ferryman.Torso.Transparency >= 1) then
                                --services.TweenService:Create(local_player.root_part, TweenInfo.new((local_player.root_part.Position - target_position).Magnitude / 125, Enum.EasingStyle.Linear), {
                                --    CFrame = target_cframe
                                --}):Play();
                                if not tween then
                                    tween = Tween.new(cf, true, 200)
                                    task.delay(0, function()
                                        if tween then
                                            tween.stop();
                                        end;
                                        
                                        tween = nil;
                                    end);
                                end;
                            end
                            
                            continue;
                        else
                            if not (ferryman.Torso.Transparency >= 1) then
                                local_player.root_part.CFrame = target_cframe;
                                got = true;

                                if start == 0 then
                                    start = tick();
                                end;
                            else
                                start = 0;
                            end;
                        end;
 
                        if not got then
                            last = tick();
                        end

                        if got or (ferryman.HumanoidRootPart.Position - Vector3.new(-4095.33, 68.5, 9425.35)).Magnitude > 13.5 then
                            started_tweening = true;
                        end;

                        aztup.automation.requesting_mob_ai_breaker_stop = not started_tweening or (not got and tick() - last >= 0.2);

                        if aztup.flags.allow_automation_use_solar and EffectReplicator.Passives and EffectReplicator.Passives.Solar and got and start > 0 and tick() - start > 0.5 and tick() - start < 2 then
                            local_player.character.CharacterHandler.Requests.Vent:FireServer()
                        end;

                        if aztup.flags.allow_automation_use_attunements and got and tick() - last_attunement >= 4 then
                            if self.use_attunement(self) then
                                last_attunement = tick();
                            end
                        end;
                    end
                end)
                --table.insert(automation_struct.threads, atb);
                
                repeat task.wait() until tripleattack or javelinattack or ferryman.Parent == nil or (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * .25))
                
                pcall(function(...) task.cancel(atb) end)
                if tween then
                    tween.stop();
                    tween = nil;
                end;
                aztup.automation.requesting_mob_ai_breaker_stop = true; 
            end
            task.wait()
        until ferryman.Parent == nil
    end, Logger.log)
    aztup.automation.requesting_mob_ai_breaker_stop = true;

    self.m1_hold(false)
    
    repeat task.wait() until workspace.Thrown:FindFirstChild('Model')
    
    task.wait(1)
    
    -- Loot chests nigga
    if aztup.flags.auto_loot then
        self.grab_chests(self)
    end;
    
    -- Talk to ferryman
    self.temp_tween(workspace.NPCs['The Ferryman, Defeated'].HumanoidRootPart.CFrame, 125)
    
    repeat
        pcall(function(...)     
            fireproximityprompt(workspace.NPCs['The Ferryman, Defeated'].InteractPrompt)
        end)
        task.wait(0.5)
    until local_player.instance.PlayerGui.DialogueGui.Enabled
    
    local args = {
        {
            choice = "Who are you?"
        }
    }
    game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
    
    task.wait(0.5)
    
    local args = {
        {
            exit = true
        }
    }
    game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
    
    task.wait(0.5)

    persistent_data:set('ferryman_rounds_completed', (persistent_data:get('ferryman_rounds_completed', 0) or 0) + 1);

    -- Leave instance
    while task.wait() do
        self.temp_tween(workspace.Ferryman.FerrymanExit.CFrame, 125)
        firetouchinterest(local_player.root_part, workspace.Ferryman.FerrymanExit, 0);
        firetouchinterest(local_player.root_part, workspace.Ferryman.FerrymanExit, 1);
        firetouchinterest(local_player.root_part, workspace.Ferryman.FerrymanExit, 0);
        firetouchinterest(local_player.root_part, workspace.Ferryman.FerrymanExit, 1);
    end;
end

local struct;
struct = automation_struct:construct({
    persistent_data_store = 'auto_ferryman_store',
    persistent_data_flag = 'auto_ferryman',
    id = 'auto_ferryman',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start',    from = 'idle', to = '_check_area'},
            {name = 'refill',   from = '_check_area', to = '_refill'},
            {name = 'initiate', from = '_check_area', to = '_initiate'},
            {name = 'initiate', from = '_refill', to = '_initiate'},
            {name = 'kill',     from = '_check_area', to ='_kill'}         
        },
        callbacks = {
            onenter_check_area = function(self)
                aztup.automation.requesting_mob_ai_breaker_stop = true;
                aztup.automation.requesting_aa_bypass_stop = true;
                aztup_options.breaker_type.Value = "Aggressive"
                if is_eastern then  
                    self:refill()
                    self:initiate()
                    return
                end
                
                if is_etrean then
                    -- Teleport to eastern
                    require("@src/features/buttons/teleports/eastern")()
                    return
                end
                
                pcall(function(...)  
                    local is_dungeon = local_player.instance:GetAttribute('Dungeon'):match('Ferryman')
                    if is_dungeon then
                        aztup.automation.requesting_aa_bypass_stop = true;
                        if #services.Players:GetPlayers() > 1 then
                            local_player.instance:Kick('Somehow ended up in another players instance.')
                        end
                        
                        services.Players.PlayerAdded:Connect(function() 
                            local_player.instance:Kick('Somehow ended up in another players instance.')
                        end)
                        self:kill()
                        return
                    end
                end)
                
                if is_depths then
                    aztup.automation:set('auto_ferryman', not persistent_data:get('auto_ferryman', false))
                    local_player.instance:Kick('Somehow ended up in depths.')
                    return
                end
            end,
            onenter_refill = function(self)
                autoferryman:refill()
                self:initiate()
            end,
            onenter_initiate = function(self)
                aztup.automation.requesting_aa_bypass_stop = true;
                autoferryman:create_instance()
            end,
            onenter_kill = function(self)
                autoferryman:kill_ferryman()
            end
        }
    }),
    features = {
        "no_fall",
        "noclip",
        'no_kill_bricks',
        "mod_detector",
        "fly",
        "aa_bypass",
        "m1_hold",
        "anti_fire",
        'auto_wisp',
        "mob_ai_breaker",
        "jesus",
        "auto_decline_guild_invites",
        "auto_decline_squad_invites",
        "auto_train_agility",
        "auto_parry",
        "block_input"
    },
    not_allowed = function()
        return is_depths and persistent_data:get("auto_progress")
    end,
    character_creator_handler_used = false,
    character_creator_handler_opts = {},

    on_run = function()
        aztup.flags.block_input = true;
        aztup_options.blocked_safe_input_user_moves.Value.M1s = true;
        aztup_options.bi_punishable_type.Value = "Always";
    end
})

return struct;

end;

__modules["src/automation/persistent_tasks/auto_layer2"] = function()
--!nocheck
if is_regular then
    return {
        run = function()
            local_player.instance:Kick("Attempted to start a beta-only automation whilst not on beta.");
            persistent_data:wipe();
        end
    }
end;
local autofarm_util = require('@src/utility/deepwoken/autofarm_utilitys')
local safety = require('@src/utility/safety')
local automation_struct = require("@src/automation/struct");
local layertwo = {
    temp_tween = function(cf, speed)
        Tween.new(cf, true, speed).wait();
    end,
    m1_hold = function(toggle)
        if not toggle then
            aztup.features.m1_hold.held = false;
            return
        end
        
        aztup.features.m1_hold.held = true
    end,
    player_near = function()
        for _, player in services.Players:GetPlayers() do
            if local_player.instance == player then continue end
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            
            local dist = (local_player.root_part.Position - player.Character:GetPivot().Position).Magnitude
            if dist <= 400 then return true end
        end
        
        return false
    end,
    get_blood_jar = function(target)
        local hrp = target:FindFirstChild("HumanoidRootPart")
        if hrp then
            local bloodJar = hrp:FindFirstChild("BloodJar")
            if bloodJar and bloodJar.Value then
                return bloodJar.Value
            end
        end
        
        return nil
    end,
    get_position = function(self, instance)
        if instance:IsA("BasePart") then
            return instance.Position
        end
        
        if instance:IsA("Model") then
            if instance.GetPivot then
                return instance:GetPivot().Position
            elseif instance.PrimaryPart then
                return instance.PrimaryPart.Position
            else
                warn("model or pivot not available")
                return nil
            end
        end
        if instance:IsA("ObjectValue") and instance.Value then
            return self.get_position(self, instance.Value)
        end
        return nil
    end,
    get_nearest = function(self, list, filter)
        local closestObject = nil
        local closest = 9e9;
        for i, v in pairs(list) do
            if filter(v) and (self.get_position(self, v) - local_player.root_part.Position).Magnitude < closest then
                closest = (self.get_position(self, v) - local_player.root_part.Position).Magnitude
                closestObject = v
            end
        end
        return closestObject
    end,

    server_hop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, true, true)
    end,
    ready_weapon = function()
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        character_handler.Requests.DrawWeapon:FireServer(true);
    end,
    grab_target_chest = function(self, targetchest)
        local time = 3
        local secondsWaited = 0
        
        if targetchest == nil then
            for _, chest in pairs(workspace.Thrown:GetChildren()) do
                if not chest:FindFirstChild("Lid") then continue; end
                
                self.temp_tween(chest.Lid.CFrame, 170)
                local moreTime = 3
                local moreSecondsWaited = 0
                
                repeat 
                    task.wait(.1) 
                    pcall(function()
                        fireproximityprompt(chest:FindFirstChildWhichIsA("ProximityPrompt"));
                    end);
                    pcall(function(...) 
                        self.temp_tween(chest.Lid.CFrame, 170)
                    end)
                    moreSecondsWaited += .1
                until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or moreSecondsWaited >= moreTime
                
                repeat task.wait(.1); secondsWaited += .1; until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or secondsWaited >= time
                
                break;
            end
        else
            self.temp_tween(targetchest.Lid.CFrame, 170)
            local moreTime = 3
            local moreSecondsWaited = 0
            
            repeat 
                task.wait(.1) 
                pcall(function()
                    fireproximityprompt(targetchest:FindFirstChildWhichIsA("ProximityPrompt"));
                end);
                pcall(function(...) 
                    self.temp_tween(targetchest.Lid.CFrame, 170)
                end)
                moreSecondsWaited += .1
            until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt')  or moreSecondsWaited >= moreTime
            
            repeat task.wait(.1); secondsWaited += .1; until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or secondsWaited >= time
        end
    end,
    grab_nearest_chest = function(self)
        local closest = nil
        
        for _, chest in workspace.Thrown:GetChildren() do
            if not chest:FindFirstChild('Lid') then continue end
            
            if not closest then
                closest = chest
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest.Lid.Position).Magnitude
                local chestDist = (local_player.root_part.Position - chest.Lid.Position).Magnitude
                
                if closestDist > chestDist then
                    closest = chest
                end
            end
        end
        
        if closest then
            self.grab_target_chest(self, closest)
        end
    end,
    avatar_exists = function()
        for _, avatar in workspace.Live:GetChildren() do
            if not avatar.Name:match('.avatar') then continue end
            return true
        end
        
        return false
    end,
    detect_bomb_fully_charged = function()
        while task.wait() do
            local specsCount = 0
            
            for _, projectiles in workspace.Thrown:GetChildren() do
                if not projectiles.Name:lower():find('bombspec') then continue end
                specsCount += 1
            end
            
            if specsCount > 7 then
                return
            end
        end
    end,
    detect_bomb_fired = function()
        while task.wait() do
            local specsCount = 0
            
            for _, projectiles in workspace.Thrown:GetChildren() do
                if projectiles.Name:lower():find('bombspec') then
                    specsCount += 1
                end
            end
            
            if specsCount <= 5 then
                return
            end
        end
    end,
    get_highest_point = function()
        local params = RaycastParams.new()
        params.FilterDescendantsInstances = { workspace.Live, workspace.NPCs }
        params.FilterType = Enum.RaycastFilterType.Blacklist
        
        
        local floor = workspace:Raycast(Vector3.new(local_player.root_part.Position.X, 5000, local_player.root_part.Position.Z), Vector3.new(0, -10000, 0), params)
        if not floor or not floor.Instance then
            return 50000
        end
        
        return floor.Position.Y + 1.3;
    end,
    get_nearest_bonespear = function()
        local closest = nil
        
        for _, object in workspace.Thrown:GetChildren() do
            if not object.Name:match('BoneSpear') then continue end
            if not object:FindFirstChild('InteractPrompt') then continue end
            
            if closest == nil then
                closest = object
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest.Position).Magnitude
                local objectDist = (local_player.root_part.Position - object.Position).Magnitude
                
                if closestDist > objectDist then
                    closest = object
                end
            end
        end 
        
        return closest
    end,
    found_flying_bonespear = function()
        local flyingbonespear = false
        
        for _, spear in workspace.Thrown:GetChildren() do
            if not spear.Name:match('BoneSpear') then continue end
            if not spear:FindFirstChild('InteractPrompt') then
                flyingbonespear = true
                break
            end
        end
        
        return flyingbonespear
    end,
    get_nearest_altar = function()
        local floor_one_done   = true
        local floor_two_done   = true
        
        local closest = nil
        
        for _, altar in workspace.TrueAvatarBossRoom.Floor1Stuff:GetChildren() do
            if not altar.Name:match('Altar') then continue end
            if altar:FindFirstChild('BoneSpear') then continue end
            
            floor_one_done = false
            
            if closest == nil then
                closest = altar
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                local altarDist = (local_player.root_part.Position - altar:GetPivot().Position).Magnitude
                
                if closestDist > altarDist then
                    closest = altar
                end
            end
        end
        
        if floor_one_done then
            for _, altar in workspace.TrueAvatarBossRoom.Floor2Stuff:GetChildren() do
                if not altar.Name:match('Altar') then continue end
                if altar:FindFirstChild('BoneSpear') then continue end
                
                floor_two_done = false
                
                if closest == nil then
                    closest = altar
                    continue
                end
                
                if closest then
                    local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                    local altarDist = (local_player.root_part.Position - altar:GetPivot().Position).Magnitude
                    
                    if closestDist > altarDist then
                        closest = altar
                    end
                end
            end
        end
        
        if floor_two_done then
            for _, altar in workspace.TrueAvatarBossRoom.Floor3Stuff:GetChildren() do
                if not altar.Name:match('Altar') then continue end
                if altar:FindFirstChild('BoneSpear') then continue end
                
                floor_three_done = false
                
                if closest == nil then
                    closest = altar
                    continue
                end
                
                if closest then
                    local closestDist = (local_player.root_part.Position - closest:GetPivot().Position).Magnitude
                    local altarDist = (local_player.root_part.Position - altar:GetPivot().Position).Magnitude
                    
                    if closestDist > altarDist then
                        closest = altar
                    end
                end
            end
        end
        
        return closest
    end,
    send_dialogue = function(text, exit)
        if exit then
            local args = {
                {
                    exit = true
                }
            }
            game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
            
            return
        end
        
        local args = {
            {
                choice = text
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
        task.wait(0.5)
    end,
}

local struct;
function layertwo:handle_medallions()
    local function initiate_dialogue(character)
        repeat
            pcall(function(...)  
                fireproximityprompt(character.InteractPrompt)
            end)
            task.wait(0.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
    end
    
    local medallions = local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame:FindFirstChild('KyrsanMedallions')
    local amount = medallions and medallions.Amount
    
    if not amount or amount and tonumber(amount.Text) < 5 then return end
    repeat task.wait() until local_player.character

    -- Safe player tween behind klaris
    safety:PlayerSafeTween(CFrame.new(5211.48926, -1889.79028, -498.766296, -0.0895125493, 0.000309288444, 0.995985627, 1.03505154e-05, 0.99999994, -0.000309604802, -0.995985687, -1.74045508e-05, -0.0895125493), 250, math.random(3000, 4000))

    local player_check = task.spawn(function()
        while task.wait() do
            if safety:PlayerNear(300) then
                autofarm_util:ServerHop()
            end
        end
    end)
    
    task.wait(1)

    local klaris = workspace.NPCs:FindFirstChild('Klaris')
    
    repeat
        Tween.new(CFrame.new(5211.48926, -1889.79028, -498.766296, -0.0895125493, 0.000309288444, 0.995985627, 1.03505154e-05, 0.99999994, -0.000309604802, -0.995985687, -1.74045508e-05, -0.0895125493), true, 175).wait()
        klaris = workspace.NPCs:FindFirstChild('Klaris')
        task.wait()
    until klaris
    
    initiate_dialogue(klaris)
    
    self.send_dialogue('Why do you need competent people?', nil)
    self.send_dialogue('So where does that leave me?', nil)
    self.send_dialogue("Light Hook? What's that?", nil)
    self.send_dialogue(nil, true)
        
    task.wait(0.5)
        
    initiate_dialogue(klaris)
        
    self.send_dialogue('What do you have to offer?', nil)
    self.send_dialogue('What can you offer for Medallions?')
            
    -- Wait for shop ui to be enabled
    repeat 
        task.wait()
    until local_player.instance.PlayerGui.DialogueGui.DialogueExtents.ShopFrame.Visible and local_player.instance.PlayerGui.DialogueGui.DialogueExtents.ShopFrame:FindFirstChild("Category_Medallion Exchange")
    
    repeat
        local knowledge = local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame.ShrinePoints.Amount.Text
        local maximum_knowledge = tonumber(knowledge) >= 999
        
        if not maximum_knowledge then
            -- Trade medallions for knowledge
            self.send_dialogue('Knowledge [1 Medallion]')
            self.send_dialogue(100)
            self.send_dialogue(nil, true)
            task.wait(0.5)
            initiate_dialogue(klaris)
            
            self.send_dialogue('What do you have to offer?')
            self.send_dialogue('What can you offer for Medallions?')
                
            -- Wait for shop ui to be enabled
            repeat 
                task.wait()
            until local_player.instance.PlayerGui.DialogueGui.DialogueExtents.ShopFrame.Visible and local_player.instance.PlayerGui.DialogueGui.DialogueExtents.ShopFrame:FindFirstChild("Category_Medallion Exchange") or not medallions.Parent or tonumber(amount.Text) < 5
        elseif maximum_knowledge then
            -- Trade medallions for enchant stones / grease
            local choices = {
                '.EnchantStone',
                '.EnchantGrease'
            }
                
            local random_choice = choices[math.random(1, 2)]
                
            local args = {
                {
                    shopchoice = random_choice
                }
            }
            game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
            task.wait(.5)
        end 
        task.wait()
    until not medallions.Parent or tonumber(amount.Text) < 5
        
    task.wait(0.5)
    self.send_dialogue(nil, true)
    pcall(function(...) task.cancel(player_check) end)
end

function layertwo:floorone()
    local function handle_door()
        autofarm_util:ReadyWeapon(true)
        
        repeat
            pcall(function(...)  
                Tween.new(workspace.NPCs:FindFirstChild('TheKey'):GetPivot(), true, 250).wait()
            end)
            
            pcall(function(...)  
                fireproximityprompt(workspace.NPCs.TheKey.InteractPrompt)
            end)
            task.wait(.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        self.send_dialogue(nil, true)
        
        Tween.new(workspace.NPCs:FindFirstChild('TheDoor'):GetPivot(), true, 250).wait()
        
        repeat
            pcall(function(...)  
                fireproximityprompt(workspace.NPCs:FindFirstChild('TheDoor').InteractPrompt)
            end)
            task.wait(.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        self.send_dialogue(nil, true)
    end
    
    local function handle_bonekeeper()
        local bonekeeper_location = CFrame.new(-5747, 459, -6357);
        self.temp_tween(bonekeeper_location, 250);
        aztup_toggles.void_mobs:SetValue(true);

        local bonekeeper = nil;
        local real_bonekeeper = nil;

        repeat
            if not bonekeeper then
                self.temp_tween(CFrame.new(-5889, 459, -6308));
            end

            if real_bonekeeper and real_bonekeeper.Parent == nil and not bonekeeper then
                bonekeeper = nil;
                real_bonekeeper = nil;
                break;
            end

            for _, v in workspace.Live:GetChildren() do
                if v == local_player.character then continue end
                if not v.Name:find(".boneboy") then continue end
                real_bonekeeper = v;
                --if not v:FindFirstChild("Target") or not v.Target.Value then continue end
                bonekeeper = v;
            end

            if not bonekeeper then
                self.temp_tween(bonekeeper_location);
            end

            task.wait();
        until bonekeeper;

        self.temp_tween(CFrame.new(-5788, 563, -6351), 250);

        repeat
            task.wait();
        until not workspace.EncounterTriggers:FindFirstChild('BonekeeperBridge')
            or (workspace.EncounterTriggers:FindFirstChild('BoneKeeperBridge') and not workspace.EncounterTriggers.BoneKeeperBridge:FindFirstChild('Barrier'));
    end
    
    local function handle_generator()
        Tween.new(CFrame.new(-5555, 529, -6475), true, 175).wait()
        
        repeat
            task.wait(.5)
            pcall(function(...)  
                fireproximityprompt(workspace.NPCs.TheGenerator.InteractPrompt)
            end)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        self.send_dialogue('[Restart it]')
        self.send_dialogue(nil, true)
    end
    
    local function handle_spawn_chaser(): Model
        self.temp_tween(CFrame.new(-5361, 5000, -4801), 250); -- so we dont get ragdolled and hit our head (ow) or get snow
        local foundchaser = nil;
        repeat
            self.temp_tween(CFrame.new(-5361, 285, -4801), 250);
            task.wait();

            for _, v in workspace.Live:GetChildren() do
                if v == local_player.character then continue end
                if v.Name:find('chaser') then
                    foundchaser = v;
                    break;
                end
            end

            self.temp_tween(CFrame.new(-5224.36523, 194.26561, -4633.03223, -0.803056717, -9.8259835e-20, -0.595902622, -3.56286109e-20, 1, -1.16878229e-19, 0.595902622, -7.26286614e-20, -0.803056717), 250);
            task.wait();
        until foundchaser;

        return foundchaser
    end
    
    local function init_chaser_fight(foundchaser: Model)
        Tween.new(foundchaser:GetPivot(), true, 250).wait()
        
        repeat
            pcall(function(...) 
                fireproximityprompt(foundchaser.InteractPrompt)
            end)
            task.wait(.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        self.send_dialogue('Ethiron\'s Wake?')
        self.send_dialogue('What happened here?')
        self.send_dialogue('They mutinied?')
        self.send_dialogue('The City?')
    end
    
    local function handle_chaser_fight(foundchaser: Model): CFrame
        local initchaserlocation = foundchaser.HumanoidRootPart.CFrame
        
        local atb;
        local time = tick()
        local last_frost_grab_use = 0;
            local tween;


        pcall(function(...)         
            repeat
                local bloodjar = self.get_blood_jar(foundchaser)
                local foundDroppables = false
                local chaserdown = foundchaser.HumanoidRootPart:FindFirstChild('REP_SOUND_10463439228')
                local waves = foundchaser.HumanoidRootPart:FindFirstChild('TelegraphAttach') and foundchaser.HumanoidRootPart.TelegraphAttach:FindFirstChild('Ring')
                
                if tick() - time >= 250 and local_player.character.Torso:FindFirstChild('NewSnowClump') then 
                    autofarm_util:Auto_M1(false)
                    repeat
                        Tween.new(CFrame.new(-5898, 479, -5921), true, 190).wait()
                        
                        local closest = nil
                        
                        for _, v in workspace.Layer2Floor1:GetChildren() do
                            if not v:IsA('Model') then continue end
                            if not v:FindFirstChild('BurnOff') then continue end
                            if not v.BurnOff:FindFirstChild('InteractPrompt') then continue end
                            
                            if closest == nil then
                                closest = v.BurnOff
                                continue
                            end
                            
                            if closest then
                                local closestDist = (local_player.root_part.Position - closest.Position).Magnitude
                                local vDist = (local_player.root_part.Position - v.BurnOff.Position).Magnitude
                                
                                if closestDist > vDist then
                                    closest = v.BurnOff
                                end
                            end
                        end
                        
                        pcall(function(...)  
                            fireproximityprompt(closest.InteractPrompt)
                        end)
                        
                        task.wait(1)
                    until not local_player.character.Torso:FindFirstChild('NewSnowClump')
                    
                    time = tick()
                end
                
                for _, v in workspace.SpecialSpikeTrap:GetChildren() do
                    if not v.Name:match('SpikeMod') then continue end
                    if not v:FindFirstChild('Stalagmite') then continue end
                    if not (#v.Stalagmite:GetChildren() > 0) then continue end
                    
                    foundDroppables = true
                end
                
                aztup.features.void_mobs.let_me_void_chaser = true;
                if not (foundchaser.Parent == nil) then
                    local voiding_mode = persistent_data:get("auto_layertwo_void_chaser", false);
                    aztup_toggles.void_mobs:SetValue(voiding_mode and chaserdown);
                    --[[if (foundDroppables or waves) and not foundchaser.HumanoidRootPart:FindFirstChild('REP_SOUND_10463439228') then
                        autofarm_util:Auto_M1(false)
                        Tween.new(CFrame.new(-4708, 633, -5199), true, 115).wait()
                        if not foundchaser.HumanoidRootPart:FindFirstChild('REP_SOUND_10463439228') then
                            task.wait(0.8)
                        end;
                    else]]if bloodjar and not waves and not foundDroppables then
                        Tween.new(CFrame.new(self.get_position(self, bloodjar)), true, 250).wait()
                        if not workspace:FindFirstChild("SpikeStabEff", true) or workspace:FindFirstChild("HitTendril", true) then
                            autofarm_util:Auto_M1(true)
                            task.wait(.1);
                            autofarm_util:Auto_M1(false)
                            task.wait(.1);
                        end;
                    elseif chaserdown then
                        if voiding_mode then
                            autofarm_util:Auto_M1(tick() - last_frost_grab_use > 2 and tick() - last_frost_grab_use < 3)    
                        else
                            autofarm_util:Auto_M1(true)
                        end;

                        -- Attach to head
                        atb = task.spawn(function()
                            while foundchaser.Parent ~= nil and task.wait() do
                                if foundchaser.Parent == nil then break; end
                                if not foundchaser:FindFirstChild('HumanoidRootPart') then break; end
                                
                                local cf = foundchaser.HumanoidRootPart.CFrame * CFrame.new(0, -5, 0) * CFrame.Angles(math.rad(90), 0, 0)
                                
                                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;

                                if cf.Y < 20 then
                                    continue;
                                end;    
                                
                                if (local_player.root_part.Position - cf.Position).Magnitude > 30  then
                                    if not tween then
                                        tween = Tween.new(cf, true, 240)
                                        task.delay(0, function()
                                            tween.stop();
                                            tween = nil;
                                        end);
                                    end;
                                    continue;
                                else
                                    if voiding_mode and tick() - last_frost_grab_use > 5 then
                                        local Event = local_player.character.CharacterHandler.Requests.ActivateMantra
                                        Event:FireServer(
                                            game:GetService("Players").LocalPlayer.Backpack:FindFirstChild("Mantra:ChokeIce{{Frost Grab}}")
                                        )
                                        last_frost_grab_use = tick();
                                    end;
                                    local_player.root_part.CFrame = cf;
                                end;
                            end
                        end)
                        
                        table.insert(struct.threads, atb);
                        repeat task.wait() until not foundchaser.HumanoidRootPart:FindFirstChild('REP_SOUND_10463439228') or (foundchaser.Parent == nil)
                        task.wait(0.25);
                        pcall(function() task.cancel(atb) end)
                    --[[elseif (foundchaser.Humanoid.Health <= (foundchaser.Humanoid.MaxHealth * 0.20)) then
                        autofarm_util:Auto_M1(false)
                        Tween.new(CFrame.new(-4523, 745, -5069), true, 125).wait()
                    ]]else
                        autofarm_util:Auto_M1(false)
                        Tween.new(CFrame.new(-4523, 745, -5069), true, 125).wait()
                    end
                end
                task.wait()
            until foundchaser.Parent == nil
        end)
        
        pcall(function() task.cancel(atb) end)
        if tween then
            tween.stop();
            tween = nil;
        end;

        autofarm_util:Auto_M1(false)
        
        return initchaserlocation
    end
    
    local function handle_chest(initchaserlocation: CFrame)
        local chaserchest = nil 
        
        repeat
            Tween.new(initchaserlocation * CFrame.new(0, 40, 0), true, 175).wait()
            
            for _, chest in workspace.Thrown:GetChildren() do
                if not chest:FindFirstChild('Lid') then continue end
                
                local dist = (local_player.root_part.Position - chest.Lid.Position).Magnitude
                
                if dist > 400 then continue end
                chaserchest = chest
                break
            end
            
            task.wait()
        until chaserchest
        
        -- Grab chest
        self.grab_target_chest(self, chaserchest)
    end
    
    local function puzzle_skip()
        Tween.new(CFrame.new(-5538.2334, 43.929615, -5194.18164, 0.383664161, 9.29316303e-14, -0.923472703, -8.4064537e-14, 1, 6.57074967e-14, 0.923472703, 5.242169e-14, 0.383664161), true, 175).wait()
        
        local one   = nil
        local two   = nil
        local three = nil
        local four  = nil
        
        for _, puzzlepart in workspace.Layer2Floor1:GetChildren() do
            if not puzzlepart.Name:match('PuzzlePart') then continue end
            if not puzzlepart:FindFirstChild('Requires') then continue end
            
            local req = puzzlepart:FindFirstChild("Requires").Value
            
            if req:match('AShape') then one = puzzlepart; continue; end
            if req:match('DShape') then two = puzzlepart; continue; end
            if req:match('CShape') then three = puzzlepart; continue; end
            if req:match('BShape') then four = puzzlepart; continue; end
            
            if one and two and three and four then break; end
        end
        
        -- Tween to both areas until you find interactprompts in the puzzleparts
        repeat
            Tween.new(CFrame.new(-5579.28174, 6.74480486, -5203.97754, 0.490061522, 4.77236426e-19, 0.871687829, -2.21196962e-19, 1, -4.23128888e-19, -0.871687829, 1.4544488e-20, 0.490061522), true, 175).wait()
            firetouchinterest(local_player.root_part, workspace.EncounterTriggers.TrapDoorPuzzle.Spawner, 0)
            firetouchinterest(local_player.root_part, workspace.EncounterTriggers.TrapDoorPuzzle.Spawner, 1)
            task.wait(1)

            Tween.new(CFrame.new(-5510.97363, 5.74480391, -5181.09619, -0.191880465, -1.82673041e-19, -0.981418312, -1.15571244e-20, 1, -1.83872104e-19, 0.981418312, -2.39390916e-20, -0.191880465), true, 175).wait()
            firetouchinterest(local_player.root_part, workspace.EncounterTriggers.TrapDoorPuzzle.Spawner, 0)
            firetouchinterest(local_player.root_part, workspace.EncounterTriggers.TrapDoorPuzzle.Spawner, 1)
            task.wait(1)
        until one:FindFirstChild('InteractPrompt', true)
        
        Tween.new(one:GetPivot() * CFrame.new(0, 4, 0), true, 175).wait()
        for i = 1, 2 do
            repeat
                pcall(function(...)  
                    fireproximityprompt(one:FindFirstChild('InteractPrompt', true))
                end) 
                task.wait() 
            until one:FindFirstChild('Shifting', true)
            repeat task.wait() until not one:FindFirstChild('Shifting', true)
        end
        
        Tween.new(two:GetPivot() * CFrame.new(0, 4, 0), true, 175).wait()
        repeat
            pcall(function(...)  
                fireproximityprompt(two:FindFirstChild('InteractPrompt', true))
            end) 
            task.wait() 
        until two:FindFirstChild('Shifting', true)
        repeat task.wait() until not two:FindFirstChild('Shifting', true)
        
        Tween.new(three:GetPivot() * CFrame.new(0, 4, 0), true, 175).wait()
        for i = 1, 3 do
            repeat
                pcall(function(...)  
                    fireproximityprompt(three:FindFirstChild('InteractPrompt', true))
                end)
                task.wait() 
            until three:FindFirstChild('Shifting', true)
            repeat task.wait() until not three:FindFirstChild('Shifting', true)
        end
        
        Tween.new(four:GetPivot() * CFrame.new(0, 4, 0), true, 175).wait()
        for i = 1, 4 do
            repeat
                pcall(function(...)  
                    fireproximityprompt(four:FindFirstChild('InteractPrompt', true))
                end) 
                task.wait() 
            until four:FindFirstChild('Shifting', true)
            repeat task.wait() until not four:FindFirstChild('Shifting', true)
        end
        
        Tween.new(workspace.Layer2Floor1.WindPortal.CFrame, true, 175).wait()
        firetouchinterest(local_player.root_part, workspace.Layer2Floor1.WindPortal, 0);
        firetouchinterest(local_player.root_part, workspace.Layer2Floor1.WindPortal, 1);
        firetouchinterest(local_player.root_part, workspace.Layer2Floor1.WindPortal, 0);
        firetouchinterest(local_player.root_part, workspace.Layer2Floor1.WindPortal, 1);
    end
    
    -- Main
    if not persistent_data:get('auto_layertwo_kill_chaser', false) and persistent_data:get('auto_layertwo_killed_chaser', false) then
        puzzle_skip()
        while task.wait() do end
    end
    
    handle_door()
    handle_bonekeeper()
    handle_generator()
    aztup_toggles.void_mobs:SetValue(false);

    local foundchaser = handle_spawn_chaser()
    init_chaser_fight(foundchaser)
    local initchaserlocation = handle_chaser_fight(foundchaser)
    handle_chest(initchaserlocation)
    
    if persistent_data:get('auto_layertwo_kill_ethiron', false) then
        Tween.new(workspace.SecondStage, true, 175).wait()
        return
    end
    
    Tween.new(workspace.InGameLightHook.CFrame, true, 175).wait()
    while task.wait() do end
end

function layertwo:floortwo()
    local function handle_obelisks()
        repeat
            local obelisk = self.get_nearest(self, game.CollectionService:GetTagged('BuzzObelisk'), function(self)
                return self.Name:match('Buzz')
            end)
            if obelisk then
                Tween.new(obelisk.CFrame, true, 175).wait()
                pcall(function(...) 
                    fireproximityprompt(obelisk.InteractPrompt)
                end)
            end
            task.wait()
        until not (#game.CollectionService:GetTagged('BuzzObelisk') > 0)
    end
    
    local function handle_krysan_chests()
        local medallions = local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame:FindFirstChild('KyrsanMedallions')
        local amount = medallions and medallions.Amount
        
        if not amount or amount and not (amount.Text == '250') then
            local chests = {}
            
            for _, chest in workspace.Thrown:GetChildren() do
                if not chest:FindFirstChild('Lid') then continue end
                table.insert(chests, chest)
            end
            
            repeat
                
                local closest = nil
                local currentindex = nil
                
                for index, chest in chests do
                    if not closest then
                        closest = chest
                        currentindex = index
                        continue
                    end
                    
                    if closest then
                        local closestDist = (local_player.root_part.Position - closest.Lid.Position).Magnitude
                        local chestDist = (local_player.root_part.Position - chest.Lid.Position).Magnitude
                        
                        if closestDist > chestDist then
                            closest = chest
                            currentindex = index
                        end
                    end
                end
                
                if closest then
                    Tween.new(closest.Lid.CFrame, true, 175).wait()
                    self.grab_target_chest(self, closest)
                    table.remove(chests, currentindex)
                end
                
                task.wait()
            until #chests == nil or #chests <= 0
        end
    end
    
    local function handle_miserables()
        local miserablesToggled = true
        if miserablesToggled or persistent_data:get('auto_layertwo_kill_champion', false) then
            Tween.new(CFrame.new(263.157104, 1013.80902, 5536.84668, 0.984595954, 2.55551505e-20, 0.174845025, -5.52093428e-20, 1, 1.64738719e-19, -0.174845025, -1.71854152e-19, 0.984595954), true, 175).wait()
            
            local miserables = workspace.NPCs:FindFirstChild('Miserables')
            
            repeat
                miserables = workspace.NPCs:FindFirstChild('Miserables')
                task.wait()
            until miserables
            
            repeat
                pcall(function(...)  
                    fireproximityprompt(miserables.InteractPrompt)
                end)
                task.wait(0.5)
            until local_player.instance.PlayerGui.DialogueGui.Enabled
            
            self.send_dialogue('Rose')
            self.send_dialogue('Relax')
            self.send_dialogue('Peace of mind, friend.')
            self.send_dialogue('I seek power in my upcoming battles.')
            self.send_dialogue("I'm interested.")
            self.send_dialogue('Here are the coins.')
            self.send_dialogue(nil, true)
            
            if persistent_data:get('auto_layertwo_kill_champion', false) then
                Tween.new(CFrame.new(1259.44861, 1189.7738, 5303.23584, 0.0604383796, 0.000191673607, 0.998171926, -0.000752008054, 0.999999702, -0.000146491191, -0.998171628, -0.00074177963, 0.0604385063), true, 175).wait()
                
                local purge_shrine = workspace.NPCs:FindFirstChild('Purge Shrine')
                repeat
                    purge_shrine = workspace.NPCs:FindFirstChild('Purge Shrine')
                    task.wait()
                until purge_shrine
                
                repeat
                    pcall(function(...)  
                        fireproximityprompt(purge_shrine.InteractPrompt)
                    end)
                    task.wait(0.5)
                until local_player.instance.PlayerGui.DialogueGui.Enabled
                
                self.send_dialogue('[Call out]')
                self.send_dialogue(nil, true)
            end
        end
    end
     
    local function handle_ethiron_spawn()
        Tween.new(CFrame.new(787.787598, 1311.22559, 7324.95801), true, 175).wait()
        Tween.new(workspace.NPCs.EthironSummonPodium:GetPivot(), true, 175).wait()
        
        repeat
            pcall(function(...) 
                fireproximityprompt(workspace.NPCs.EthironSummonPodium.InteractPrompt)
            end)
            task.wait(.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        self.send_dialogue('[Resist it]')
        self.send_dialogue('[Resist further]')
        self.send_dialogue('[Resist with all that you are]')
        self.send_dialogue('[Breathe out]')
    end
    
    local function handle_ethiron_fight()
        local ultimatedetected = false
        local bonetweenactive = false
        local ethironstunned = false
        
        workspace.DescendantAdded:Connect(function(descendant)
            if descendant.Name:lower():find('bombcharge') then
                if not self.avatar_exists() then return end
                ultimatedetected = true
                
                if bonetweenactive then
                    repeat
                        task.wait()
                    until not bonetweenactive
                end
                
                Tween.new(CFrame.new(787.787598, 1380, 7324.95801), true, 175).wait()
                self.detect_bomb_fully_charged()
                self.detect_bomb_fired()
                Tween.new(CFrame.new(774.600281, 2000, 7465.85791), true, 175).wait()
                ultimatedetected = false
            end
        end)
        
        local avatar = nil
        
        repeat
            for i, v in workspace.Live:GetChildren() do
                if v.Name:find('.avatar') then
                    avatar = v
                    break
                end
            end
            task.wait()
        until avatar
        
        local initavatarheadcf = nil
        
        repeat
            pcall(function(...) 
                initavatarheadcf = avatar:FindFirstChild('Head').CFrame
            end)
            task.wait()
        until initavatarheadcf
        
        avatar.Humanoid.Animator.AnimationPlayed:Connect(function(anim)
            --print(anim.Animation.AnimationId)
            if anim.Animation.AnimationId:match('rbxassetid://10880826811') then
                ethironstunned = true
            end 
            
            if anim.Animation.AnimationId:match('rbxassetid://10978735338') then
                ethironstunned = false
            end
        end)
        
        repeat
            xpcall(function()
                repeat
                    local bonespear = self.get_nearest_bonespear()
                    local bonealtar = self.get_nearest_altar()
                    
                    if (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * 0.25)) then
                        repeat
                            if not ultimatedetected then
                                Tween.new(CFrame.new(774.600281, 1380, 7465.85791), true, 175).wait()
                            end
                            task.wait()
                        until (local_player.humanoid.Health >= (local_player.humanoid.MaxHealth * 0.25))
                    elseif ultimatedetected then
                        task.wait()
                    elseif bonespear and bonealtar and not self.found_flying_bonespear() or (bonealtar and local_player.character:FindFirstChild('BoneSpear')) then
                        if not ultimatedetected and not local_player.character:FindFirstChild('BoneSpear') and not (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * 0.40)) then
                            bonetweenactive = true
                            repeat
                                pcall(function(...)  
                                    Tween.new(bonespear.CFrame, true, 175).wait()
                                end)
                                pcall(function(...) 
                                    fireproximityprompt(bonespear.InteractPrompt)
                                end)
                                task.wait()
                            until bonespear == nil or bonespear.Parent == nil or (local_player.character:FindFirstChild('BoneSpear')) or ultimatedetected or (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * 0.40))
                        end
                        
                        if not ultimatedetected and local_player.character:FindFirstChild('BoneSpear') and not (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * 0.40)) then
                            bonetweenactive = true
                            repeat
                                pcall(function(...)  
                                    Tween.new(bonealtar:GetPivot(), true, 175).wait()
                                end)
                                pcall(function(...)  
                                    fireproximityprompt(bonealtar.InteractPrompt)
                                end)
                                task.wait()
                            until not (local_player.character:FindFirstChild('BoneSpear')) or ultimatedetected or (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * 0.40))
                        end
                        
                        bonetweenactive = false
                    elseif ethironstunned and not self.found_flying_bonespear() then
                        repeat
                            bonetweenactive = true
                            Tween.new(avatar.Head.CFrame * CFrame.new(0, -5, 0), true, 175).wait()
                            bonetweenactive = false
                            autofarm_util:Auto_M1(true)
                            task.wait()
                        until not ethironstunned or (local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * 0.40))
                        
                        autofarm_util:Auto_M1(false)
                    else
                        bonetweenactive = true
                        Tween.new(initavatarheadcf * CFrame.new(0, 150, 0), true, 175).wait()
                        bonetweenactive = false
                    end
                    
                    task.wait()
                until (avatar.Parent == nil)
                
            end, Logger.log)
            task.wait()
        until avatar.Parent == nil
        
        autofarm_util:Auto_M1(false)
    end
    
    local function handle_ethiron_chest()
        Tween.new(CFrame.new(791.660889, 563.343811, 7120.29248), true, 175).wait()
        self.grab_nearest_chest(self)
    end
    
    local function handle_champion_fight()
        if not persistent_data:get('auto_layertwo_kill_champion', false) then return end
        while task.wait() do end
    end
    
    local function handle_champion_chest()
    end
    
    -- Main
    
    autofarm_util:ReadyWeapon(true)
    handle_obelisks()
    handle_krysan_chests()
    handle_miserables()
    handle_ethiron_spawn()
    handle_ethiron_fight()
    handle_ethiron_chest()
    handle_champion_fight()
    handle_champion_chest()
    
    Tween.new(CFrame.new(944.20166, 850.517029, 4173.19775), true, 175).wait()
    firetouchinterest(local_player.root_part, workspace.InGameLightHook, 0);
    firetouchinterest(local_player.root_part, workspace.InGameLightHook, 1);
    firetouchinterest(local_player.root_part, workspace.InGameLightHook, 0);
    firetouchinterest(local_player.root_part, workspace.InGameLightHook, 1);
end

function layertwo:go_to_layer_two()
    local function get_closest_kill_plane()
        local part;
        local dist = 9e9;

        for _, item in workspace:QueryDescendants("#KillPlane") do
            print(item)
            local current_dist = (item.Position - local_player.root_part.Position).Magnitude;

            if current_dist < dist then
                dist = current_dist;
                part = item;
            end;
        end;

        return part;
    end;

    if aztup.flags.no_kill_bricks then
        aztup_toggles.no_kill_bricks:SetValue(false);
    end;

    if local_player.humanoid.Health <= local_player.humanoid.MaxHealth / 2 then
        return local_player.instance:Kick("Too low of health.");
    end;

    local start = tick();
    local plane = get_closest_kill_plane();
    repeat plane = get_closest_kill_plane(); task.wait(); until plane or tick() - start > 15;


    local is_fragments = local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):match('Fragments of Self')
    if is_fragments then
        getgenv().dont_auto_hop_pls = true;
        persistent_data:wipe();
        return local_player.instance:Kick("Auto L2 wiped your slot....");
    end

    local playercheck = task.spawn(function()
        while task.wait() do
            if self.player_near() then
                self.server_hop()
            end
        end
    end)
    
    aztup_toggles.fly:SetValue(false);

    local tween;
    while tick() - start < 60 do
        if not plane then break; end
        if tween then tween.stop(); end;
        tween = Tween.new(plane.CFrame, false, 200);
        local_player.root_part.Velocity = Vector3.new(0, -999, 0);
        task.wait();
    end;    

    return local_player.instance:Kick("Failed to enter plane somehow.");
end;

struct = automation_struct:construct({
    persistent_data_store = 'auto_layertwo_store',
    persistent_data_flag = 'auto_layertwo',
    id = 'auto_layertwo',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start', from = 'idle', to = '_check_area'}, 
            {name = 'todepths', from = '_check_area', to = '_to_layer_two_floor_one'},
            {name = 'depths', from = '_check_area', to = '_to_layer_two_floor_one'},
            {name = 'floorone', from = '_check_area', to = '_floor_one'},
            {name = 'floortwo', from = '_check_area', to = '_floor_two'}
        },
        callbacks = {
            onenter_check_area = function(self)
                if is_eastern or is_etrean then
                    self:todepths()
                    return
                end
                
                pcall(function(...) 
                    local is_floor_one = local_player.instance:GetAttribute('Dungeon'):match('Layer2Floor1')
                    if is_floor_one then
                        self:floorone()
                        return
                    end
                end)
                
                pcall(function(...)  
                    local is_floor_two = local_player.instance:GetAttribute('Dungeon'):match('Layer2Floor2')
                    if is_floor_two then
                        self:floortwo()
                        return
                    end
                end)
                
                if is_depths then
                    self:depths()
                    return
                end
                
                pcall(function(...)  
                    local is_fragments = local_player.instance:GetAttribute('CurrentArea'):match('Fragments of Self')
                    if is_fragments then
                        return
                    end
                end)
            end,
            onenter_to_layer_two_floor_one = function(self)

                if persistent_data:get("auto_layertwo_allow_loops") then return layertwo:go_to_layer_two(); end
                aztup.automation:set("auto_layertwo", false)
                persistent_data:wipe();
                getgenv().dont_auto_hop_pls = true;
                local_player.instance:Kick("Escaped layer 2 successfully - You are in scyphozia/l1f1/depths.");
            end,
            onenter_floor_one = function(self)
                layertwo:floorone()
            end,
            onenter_floor_two = function(self)
                layertwo:floortwo()
            end
        }
    }),
    features = {
        "no_fall",
        "noclip",
        'no_kill_bricks',
        "mod_detector",
        "fly",
        "anti_afk",
        "no_wind",
        "m1_hold",
        "auto_equip_weapon"
    },
    not_allowed = function()
        if not aztup.flags.auto_parry then
            task.delay(1, function() 
                Logger:notify_sound("Skipped running Auto L2 because Auto Parry is not on, Please setup auto parry on your auto load configuration.")
            end)
        end
        return not aztup.flags.auto_parry;
    end,
    character_creator_handler_used = false,
    character_creator_handler_opts = {},

    on_run = function()
        aztup.flags.block_input = true;
        aztup_options.blocked_safe_input_user_moves.Value.M1s = true;
        aztup_options.bi_punishable_type.Value = "Always";
    end
})

return struct; 

end;

__modules["src/automation/persistent_tasks/auto_mooneyrie"] = function()
--!nocheck
if is_regular then
    return {
        run = function()
            local_player.instance:Kick("Attempted to start a beta-only automation whilst not on beta.");
            persistent_data:wipe();
        end
    }
end;

local automation_struct = require("@src/automation/struct");
local moonseyrie = {
    player_near = function()
        for _, player in services.Players:GetPlayers() do
            if local_player.instance == player then continue end
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            
            local dist = (local_player.root_part.Position - player.Character:GetPivot().Position).Magnitude
            if dist <= 200 then return true end
        end
        
        return false
    end,
    players_near = function(target, mag)
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            if player == local_player.instance then continue end
            
            local hmrp = player.Character.HumanoidRootPart
            
            local dist = (target - player.Character:GetPivot().Position).Magnitude
            
            if (dist <= mag) then
                return true
            end
        end
        
        return false
    end,
    player_safe_tween = function(self, cf, speed)
        if self.player_near() then
            -- Serverhop to small server, will kick for now
            self.server_hop()
            while task.wait() do end
        end
        
        local ylevel = math.random(8000, 10000)
        
        -- Tween up
        local_player.root_part.CFrame = local_player.root_part.CFrame + Vector3.new(0, ylevel, 0)
        --self.tempTween(local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0), speed)
        
        -- Tween to target location
        self.temp_tween(self, cf + Vector3.new(0, ylevel, 0), speed)
        
        -- Check for players
        if self.players_near(Vector3.new(cf.X, cf.Y, cf.Z), 200) then
            -- Serverhop to small server, will kick for now
            self.server_hop()
            while task.wait() do end
        end
        
        -- Tween down
        local_player.root_part.CFrame = cf
        task.wait(1)
    end,
    server_hop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, 'any', true)
    end,
    temp_tween = function(self, cf, speed)
        Tween.new(cf, true, speed).wait();
    end,
    ready_weapon = function()
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        character_handler.Requests.DrawWeapon:FireServer(true);
    end,
    hold_m1 = false,
    auto_m1 = function(self, toggle)
        self.hold_m1 = toggle
    end,
    health_check = function(percent)
        return local_player.humanoid and local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * percent)
    end,
    get_closest_mob = function(name, mag)
        local closest = nil
        
        for _, mob in workspace.Live:GetChildren() do
            if not mob:IsA('Model') then continue end
            if not mob.Name:find(name) then continue end
            
            if not closest then
                
                if mag then 
                    local dist = (local_player.root_part.Position - mob.HumanoidRootPart.Position).Magnitude
                    if dist < mag then
                        closest = mob
                    end
                    
                    continue
                end
                
                closest = mob
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest.HumanoidRootPart.Position).Magnitude
                local mobDist = (local_player.root_part.Position - mob.HumanoidRootPart.Position).Magnitude
                
                if closestDist > mobDist then
                    closest = mob
                end
            end
        end 
        
        return closest
    end,
    grab_chest = function(self)
        local time = 3
        local secondsWaited = 0
        
        for _, chest in pairs(workspace.Thrown:GetChildren()) do
            if not chest:FindFirstChild("Lid") then continue; end
            
            self.temp_tween(self, chest.Lid.CFrame, 170)
            local moreTime = 3
            local moreSecondsWaited = 0
            
            repeat 
                task.wait(.5) 
                pcall(function()
                    fireproximityprompt(chest:FindFirstChildWhichIsA("ProximityPrompt"));
                end);
                pcall(function(...) 
                    self.temp_tween(self, chest.Lid.CFrame, 170)
                end)
                moreSecondsWaited += .5
            until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or not aztup.automation:has_any() or moreSecondsWaited >= moreTime or self.player_near()
            
            if self.player_near() then break end
            
            if not self.player_near() then
                repeat task.wait(1); secondsWaited += 1; until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or not aztup.automation:has_any() or secondsWaited >= time or self.player_near()
            end
            
            break;
        end
    end,
    get_closest_campfire = function()
        local closest = nil 
        
        for _, campfire in workspace.Thrown:GetChildren() do
            if not campfire.Name:match('Campfire') then continue end
            if not campfire:IsA('Model') then continue end
            
            local campfirePart = campfire:FindFirstChildOfClass('Part')
            
            if closest == nil then
                closest = campfirePart
                continue
            end
            
            if closest then
                local closestDist = (local_player.root_part.Position - closest.Position).Magnitude
                local campfireDist = (local_player.root_part.Position - campfirePart.Position).Magnitude
                
                if closestDist > campfireDist then
                    closest = campfirePart
                end
            end
        end
        
        return closest
    end
}

function moonseyrie:kill(target)
    if self.player_near() then return end
    if not target then return end
    if not target:IsA('Model') then return; end
    
    if target.Name:match(local_player.instance.Name) then return; end
    
    self.ready_weapon()
    self.temp_tween(self, target.HumanoidRootPart.CFrame, 170)
    
    if self.player_near() then return end
    
    local foundKickAnim = false
    local targetAnimator = target:FindFirstChild('Animator', true)
    local kick_anim_listener = targetAnimator.AnimationPlayed:Connect(function(track)
        if track.Animation.AnimationId:match("106711913879378") or track.Animation.AnimationId:match("111024000122473") and not foundKickAnim then
            foundKickAnim = true
            task.delay(2, function()
                foundKickAnim = false
            end)
        end
    end)
    
    -- Attach to back
    local atb = task.spawn(function()
        while task.wait() and not self.player_near() do
            if target.Parent == nil then break; end
            if not target:FindFirstChild('HumanoidRootPart') then break; end
            
            local cf = target.HumanoidRootPart.CFrame * CFrame.new(0, foundKickAnim and 60 or 10, 0) * CFrame.Angles(math.rad(-90), 0, 0)
            
            
            local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
            
            -- If you detect the knight kicking animation then tween away
            local_player.root_part.CFrame = cf;
        end
    end)
    
    local healthTick = tick()
    local healthLastChecked = nil
    
    -- Status Check
    local status = task.spawn(function()
        while task.wait() do
            pcall(function(...)  
                if healthLastChecked == nil then
                    healthTick = tick()
                    healthLastChecked = target.Humanoid.Health
                end
                
                if healthLastChecked then
                    if healthLastChecked ~= target.Humanoid.Health then
                        healthTick = tick()
                        healthLastChecked = target.Humanoid.Health
                    end
                end
            end)
        end
    end)
    
    self:auto_m1(true)
    repeat task.wait(); until not target or target.Parent == nil or not aztup.automation:has_any() or self.player_near() or self.health_check(0.35) or ((tick() - healthTick) >= 20)
    pcall(function(...)  
        kick_anim_listener:Disconnect()
    end)
    xpcall(function() task.cancel(atb); end, Logger.error)
    pcall(function() task.cancel(status); end)
    self:auto_m1(false)
    
    if not self.player_near() then
        task.wait(2)
        local timewaited = tick()
        for _, lootdrop in workspace.Thrown:GetChildren() do
            if not lootdrop:IsA('Model') then continue end
            if not lootdrop:FindFirstChild('LootDrop') then continue end
            
            local dist = (local_player.root_part.Position - lootdrop.LootDrop.Position).Magnitude
            if dist > 100 then continue end
            
            if self.players_near(lootdrop.LootDrop.Position, 200) then continue end
            self.temp_tween(self, lootdrop.LootDrop.CFrame, 120)
            repeat
                pcall(function(...)  
                    firetouchinterest(lootdrop.LootDrop, local_player.root_part, 0)
                    firetouchinterest(lootdrop.LootDrop, local_player.root_part, 1)
                end)
                task.wait()
            until lootdrop.Parent == nil or self.player_near() or not aztup.automation:has_any() or tick() - timewaited >= 3
            if lootdrop.Parent ~= nil then
                lootdrop:Destroy()
            end
        end
        task.wait(.2)
    end
    
    if self.health_check(.35) then return end
    if self.player_near() then return true end
    if not aztup.automation:has_any() then return true end
    
    return false
end

function moonseyrie:handle()
    if self.health_check(.35) then
        self.player_safe_tween(self, CFrame.new(-7632.27881, 980.369873, 421.907501, -0.95457083, 1.47911251e-20, 0.297984123, -4.46200836e-20, 1, -1.92574548e-19, -0.297984123, -1.97122129e-19, -0.95457083), 170)
        task.wait(1)
        
        local campfire = self.get_closest_campfire()
        
        repeat
            local_player.root_part.CFrame = campfire.CFrame * CFrame.new(0, 1, 0)
            
            task.wait(1)
            
            fireproximityprompt(campfire.Parent.InteractPrompt)
            
            task.wait(1)
        until EffectReplicator:FindEffect("Resting") or not aztup.automation:has_any()
        
        repeat task.wait() until local_player.humanoid.Health >= (local_player.humanoid.MaxHealth * 0.5);
        
        local VIM = Instance.new('VirtualInputManager')
        
        VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game);
        task.wait(0.1);
        VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game);
        
        task.wait(1)
        
        VIM:Destroy()
    end
    
    local location = services.ReplicatedStorage.MarkerWorkspace.AreaMarkers["Moon's Eyrie"].AreaMarker.CFrame
    
    self.player_safe_tween(self, location, 170)
    
    local moons_eye_door = nil
    
    repeat task.wait(); moons_eye_door = workspace:FindFirstChild('MoonseyeDoor') until moons_eye_door
    
    self.ready_weapon()
    self.player_safe_tween(self, moons_eye_door.CFrame * CFrame.new(0, -5, 0), 170)
    
    repeat
        pcall(function(...)  
            fireproximityprompt(workspace.NPCs:FindFirstChild('MoonDoor'):FindFirstChild('InteractPrompt'))
        end)
        task.wait(.5)
    until local_player.instance.PlayerGui.DialogueGui.Enabled or not aztup.automation:has_any()
    
    local args = {
        {
            choice = "[Interact]"
        }
    }
    services.ReplicatedStorage:WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
    
    self.temp_tween(self, moons_eye_door.CFrame * CFrame.new(0, 0, -100), 170)
    
    local timeWaited = 0
    
    repeat
        task.wait(0.1)
        timeWaited += 0.1
    until timeWaited > 3 or self.player_near() or self.get_closest_mob('moonknight', 60)
    
    if self.player_near() then return end
    
    local knight = self.get_closest_mob('moonknight', 60)
    local knightNil = knight == nil
    
    services.RunService.Heartbeat:Connect(function()
        if self.hold_m1 then
            aztup.features.m1_hold.held = true;
            aztup.flags.no_aerials = true;
        else
            aztup.features.m1_hold.held = false;
            aztup.flags.no_aerials = false;
        end
    end)
    
    self:kill(knight)
    
    -- Look for chest and loot that shit
    if not self.player_near() and not self.health_check(.35) and not knightNil then
        task.wait(0.5)
        self.grab_chest(self)
    end
    
    local knight = self.get_closest_mob('moonknight', 3000)
    local knightNil = knight == nil
    
    if not knightNil then
        self:kill(knight)
    end
end

function moonseyrie:tosafety()
    repeat
        local_player.root_part.CFrame = local_player.root_part.CFrame * CFrame.new(0, math.random(8000, 10000), 0) 
        task.wait() 
    until not self:indanger()
end

function moonseyrie:indanger()
    return local_player.humanoid:GetAttribute("DangerExpiration") and local_player.humanoid:GetAttribute("DangerExpiration") > 0
end

return automation_struct:construct({
    persistent_data_store = 'auto_moonseyrie_store',
    persistent_data_flag = 'auto_moonseyrie',
    id = 'auto_moonseyrie',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start', from = 'idle', to = '_check_area'},
            {name = 'continuation', from = '_hide', to = '_mooonseyrie'},
            
            {name = 'moons', from = '_check_area', to = '_moonseyrie'},
            
            {name = 'hide', from = '_check_area', to = '_hide'},
            {name = 'hide', from = '_moonseyrie', to = '_hide'},
            
            {name = 'hop', from = '_moonseyrie', to = '_hop'},
            {name = 'hop', from = '_hide', to = '_hop'}
        },
        callbacks = {
            onenter_check_area = function(self)
                if is_depths then
                    aztup.automation:set('auto_moonseyrie', not persistent_data:get('auto_moonseyrie', false))
                    local_player.instance:Kick('Somehow ended up in depths?')
                    getgenv().dont_auto_hop_pls = true;
                    return
                end
                
                if is_eastern then
                    self:moons()
                    return
                end
            end,
            
            onenter_moonseyrie = function(self)
                moonseyrie:handle()
                
                if moonseyrie.player_near() or moonseyrie:indanger() then
                    self:hide()
                    return
                end
                
                self:hop()
            end,
            
            onenter_hide = function(self)
                moonseyrie:tosafety()
                self:hop()
            end,
            
            onenter_hop = function(self)
                moonseyrie.server_hop()
                while task.wait() do end
            end,
        },
    }),
    features = {
        "no_fall",
        "noclip",
        "fly",
        "no_fire",
        "m1_hold",
        "no_stun",
        "fast_swing",
        "auto_equip_weapon"
    },
    
    not_allowed = function()
        return false; --todo
    end,
    
    character_creator_handler_used = false,
    character_creator_handler_opts = {
    }
})

end;

__modules["src/automation/persistent_tasks/auto_progress"] = function()
if is_regular then
    return {
        run = function()
            local_player.instance:Kick("Attempted to start a beta-only automation whilst not on beta.");
            persistent_data:wipe();
        end
    }
end;

local webhook = require("@src/utility/webhook");
local AutoProgression = {};
AutoProgression.__index = AutoProgression;
AutoProgression.internal_state = persistent_data:get("auto_progression_internal", {
    state = "JUST_STARTED",
    data = {}
});
AutoProgression.internal_struct = {};
AutoProgression.current = setmetatable({}, {
    __index = function(_, key)
        return AutoProgression.internal_state[key];
    end,
    __newindex = function(_, key, value)
        AutoProgression.internal_state[key] = value;
    end,
    __call = function(type)
        if type == "wipe" then
            AutoProgression.internal_state = { 
                state = "NULL",
                data = {}
            };
        end
    end
})

AutoProgression.player_near = function()
    for _, player in services.Players:GetPlayers() do
        if local_player.instance == player then continue end
        if not player.Character then continue end
        if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
        
        local dist = (local_player.root_part.Position - player.Character:GetPivot().Position).Magnitude
        if dist <= 400 then return true end
    end
    
    return false
end;

AutoProgression.server_hop = function()
    local axe = local_player.character and local_player.character:FindFirstChild('Lumber Axe');
    if axe then
        axe.Parent = local_player.instance.Backpack;
        task.wait(0.4);
    end
    local slot = local_player.instance:GetAttribute("DataSlot");
    server_utility:hop(slot, true, true)
end

function AutoProgression:set_state(state)
    local curr = AutoProgression.internal_state;
    curr.state = state;
    AutoProgression.internal_state = curr;
        
    persistent_data:set("auto_progression_internal", AutoProgression.internal_state);
end

function AutoProgression:set_data(data)
    local curr = AutoProgression.internal_state;
    curr.data = data;
    AutoProgression.internal_state = curr; 

    persistent_data:set("auto_progression_internal", AutoProgression.internal_state);
end

function AutoProgression:read_state()
    return AutoProgression.current.state;
end

function AutoProgression:read_data()
    return AutoProgression.current.data;
end

function AutoProgression:farm_tag()
    if not ab_builder.build_config then
        local wait_start = tick();
        repeat task.wait(0.5) until ab_builder.build_config or tick() - wait_start >= 15;
    end;

    local data = self:read_data();
    local method = data and data.farm_method;

    if not method then
        method = aztup_options.auto_progress_method and aztup_options.auto_progress_method.Value;
    end;

    return method == "Ferryman" and "auto_ferryman" or "auto_saramed";
end

function AutoProgression:other_farm_tag()
    return self:farm_tag() == "auto_ferryman" and "auto_saramed" or "auto_ferryman";
end

function AutoProgression:set_farm(active)
    local flag = self:farm_tag();

    if active then
        aztup.automation:set(self:other_farm_tag(), false);
    end;

    aztup.automation:set(flag, active);
end

function AutoProgression:persist_farm(active)
    local flag = self:farm_tag();

    if active then
        persistent_data:set(self:other_farm_tag(), false);
    end;

    persistent_data:set(flag, active);
end

function AutoProgression:heal_at_campfire()
    local function equip_campfire()
        local equipped = local_player.character and local_player.character:FindFirstChild('Campfire Pit');
        if equipped then return equipped end;

        local stored = local_player.instance.Backpack:FindFirstChild('Campfire Pit');
        if not stored or not local_player.character then return nil end;

        stored.Parent = local_player.character;

        local start = tick();
        repeat task.wait() until (local_player.character and local_player.character:FindFirstChild('Campfire Pit')) or tick() - start >= 3;

        return local_player.character and local_player.character:FindFirstChild('Campfire Pit');
    end;

    local tool = equip_campfire();
    if tool then
        pcall(function() tool:Activate(); end);
        task.wait(1);
    end;

    local start = tick();
    repeat
        task.wait(0.3);

        local destructibles = workspace:FindFirstChild('Destructibles');
        local campfire, closest_dist = nil, math.huge;

        if destructibles then
            for _, c in destructibles:GetChildren() do
                if not c.Name:match('Campfire') then continue; end;

                local pivot = (c:IsA("Model") and c:GetPivot() or c).Position;
                local dist = (pivot - local_player.root_part.Position).Magnitude;

                if dist < closest_dist then
                    closest_dist = dist;
                    campfire = c;
                end;
            end;
        end;

        if campfire then
            local prompt = campfire:IsA("Model") and campfire:FindFirstChildWhichIsA("ProximityPrompt", true) or campfire:FindFirstChildWhichIsA("ProximityPrompt");
            if prompt then
                pcall(function() fireproximityprompt(prompt); end);
            end;
        end;
    until (local_player.humanoid and local_player.humanoid.Health >= local_player.humanoid.MaxHealth * 0.89)
        or tick() - start >= 60
        or not persistent_data:get('auto_progress', false);
end

function AutoProgression:has_ankle_weights_equipped()
    local character = local_player.character;
    if not character then return false end;

    local leg = character:FindFirstChild("Left Leg");
    if not leg then return false end;

    return leg:FindFirstChild("AnkleWeight") ~= nil;
end

function AutoProgression:equip_ankle_weights()
    if self:has_ankle_weights_equipped() then return end;
    if ab_builder:missing_for("Agility") <= 0 then return end;

    local character = local_player.character;
    if not character then return end;

    local backpack = local_player.instance:FindFirstChild('Backpack');
    local weights = (backpack and backpack:FindFirstChild('Ankle Weights')) or character:FindFirstChild('Ankle Weights');
    if not weights then return end;

    pcall(function()
        local_player.humanoid:EquipTool(weights);
        weights:Activate();

        task.wait(0.2);
        local_player.humanoid:UnequipTools();
    end);
end

function AutoProgression:points_awaiting()
    local ok, data = pcall(function()
        return require(services.ReplicatedStorage.Info.DataReplication).GetData();
    end);

    if not ok or not data then return 0 end;

    return tonumber(data.AttributePoints) or 0;
end

function AutoProgression:hit_nearest_mob_once()
    local live = workspace:FindFirstChild("Live");
    if not live then return end;
    if not local_player.character or not local_player.root_part then return end;

    local brutus_position = Vector3.new(-6985, 336, 3060);

    if (local_player.root_part.Position - brutus_position).Magnitude > 150 then return end;

    local players = {};
    for _, player in services.Players:GetPlayers() do
        if player.Character then
            players[player.Character] = true;
        end;
    end;

    local closest, closest_dist = nil, math.huge;
    for _, model in live:GetChildren() do
        if not model:IsA("Model") then continue end;
        if model == local_player.character then continue end;
        if players[model] then continue end;
        if services.Players:GetPlayerFromCharacter(model) then continue end;
        if model.Name:find("Brutus") then continue end;

        local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart;
        if not root then continue end;

        local humanoid = model:FindFirstChildOfClass("Humanoid");
        if not humanoid or humanoid.Health <= 0 then continue end;

        local dist = (root.Position - local_player.root_part.Position).Magnitude;
        if dist < closest_dist then
            closest_dist = dist;
            closest = model;
        end;
    end;

    if not closest then return end;

    local root = closest:FindFirstChild("HumanoidRootPart") or closest.PrimaryPart;

    pcall(function()
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        if character_handler then
            character_handler.Requests.DrawWeapon:FireServer(true);
        end;
    end);

    Tween.new(root.CFrame, true, 200).wait();
    local_player.root_part.CFrame = root.CFrame;

    -- we gotta hit the mob because exp gets desynced lol - try twice since we just teleported in and the first swing can whiff
    for i = 1, 2 do
        local_player.root_part.CFrame = root.CFrame;

        aztup.features.m1_hold.held = true;
        task.wait(0.3);
        aztup.features.m1_hold.held = false;

        task.wait(0.3);
    end;

    -- we moved to the mob to hit it, so head back to brutus before continuing
    Tween.new(CFrame.new(brutus_position), true, 200).wait();
    local_player.root_part.CFrame = CFrame.new(brutus_position);
end

function AutoProgression:train_fortitude()
    aztup_toggles.noclip:SetValue(true);
    aztup_toggles.knocked_ownership:SetValue(true);
    aztup_toggles.jesus:SetValue(true);

    local playercheck = task.spawn(function()
        while task.wait() do
            if self.player_near() then
                self.server_hop()
            end
        end
    end)
    
    self:equip_ankle_weights();
        
    Tween.new(CFrame.new(-6985, 336, 3060), true, 200).wait();

    self:hit_nearest_mob_once();

    if self:points_awaiting() <= 0 then return end;

    aztup_toggles.auto_brutus:SetValue(true);

    local start = tick();
    repeat
        self:equip_ankle_weights(); 
        task.wait(1);
    until self:points_awaiting() <= 0
        or ab_builder:missing_for("Fortitude") <= 0
        or tick() - start >= 120
        or not persistent_data:get('auto_progress', false);

    aztup_toggles.auto_brutus:SetValue(false);

    if not persistent_data:get('auto_progress', false) then return; end;

    self:equip_ankle_weights();
    Tween.new(CFrame.new(-6698, 914, 3576), true, 200).wait();

    self:heal_at_campfire();

    return playercheck;
end

function AutoProgression:maybe_train_fortitude(force)
    local flag = self:farm_tag();
    if flag ~= "auto_ferryman" then return false end;
    if is_dungeon then return false end;

    local missing = ab_builder:missing_for("Fortitude");
    if not force and missing <= 0 then return false end;
    if self:points_awaiting() <= 0 then return false end;

    self:persist_farm(false);
    self:set_state("DOING_AUTO_BRUTUS");

    server_utility:rejoin(local_player.instance:GetAttribute("DataSlot") or "A");

    return true;
end

function AutoProgression:resume_from_depths()
    local data = self:read_data();
    local return_to = data.escape_depths_return_to;

    if not return_to or return_to == "JUST_STARTED" or return_to == "ESCAPING_DEPTHS" then
        return_to = "DOING_AUTO_FERRYMAN";
    end;

    data.escape_depths_return_to = nil;
    self:set_data(data);
    self:set_state(return_to);

    return return_to;
end

function AutoProgression:power()
    local character = local_player.character;
    if not character then return nil end

    local points = 0;
    for name, value in character:GetAttributes() do
        if typeof(value) == "number" and name:match("Stat") then
            points += value;
        end;
    end;

    local power = 0;
    for _ = 1, 20 do
        if points <= 15 then break end;

        points -= 15;
        power += 1;
    end;

    return math.min(20, math.max(1, power));
end

function AutoProgression:should_do_trial()
    if is_eastern then return false end;

    local origin;
    pcall(function()
        origin = game:GetService("ReplicatedStorage").Requests.Get:InvokeServer().Origin;
    end);

    if origin == "Deepbound" then return false end;

    local power = self:power();
    if not power then return false end;

    return power <= 1;
end

function AutoProgression:import_build()
    local url = persistent_data:get("auto_progress_url", "");
    if url == "" then
        return false;
    end

    local requests = services.ReplicatedStorage:FindFirstChild("Requests");
    local build_maker = requests and requests:FindFirstChild("BuildMaker");
    local import_build = build_maker and build_maker:FindFirstChild("ImportBuild");

    if not import_build then
        return false;
    end

    local ok, result = pcall(function()
        return import_build:InvokeServer(url);
    end);

    if ok then
        self:unlock_attributes();
    end;

    return ok;
end

function AutoProgression:unlock_attributes()
    local requests = services.ReplicatedStorage:FindFirstChild("Requests");
    if not requests then return false end;

    local lock_attribute = requests:FindFirstChild("LockAttribute");
    local limit_attribute = requests:FindFirstChild("LimitAttribute");

    if not lock_attribute and not limit_attribute then return false end;

    local data;
    pcall(function()
        data = base_require(services.ReplicatedStorage.Info.DataReplication).GetData();
    end);

    local locked = (data and data.LockedAttributes) or {};
    local limits = (data and data.AttributeLimits) or {};

    for _, attribute in {
        "Strength",
        "Fortitude",
        "Agility",
        "Intelligence",
        "Willpower",
        "Charisma",
        "WeaponHeavy",
        "WeaponMedium",
        "WeaponLight",
        "ElementFire",
        "ElementIce",
        "ElementLightning",
        "ElementWind",
        "ElementShadow",
        "ElementMetal",
        "ElementBlood",
    } do
        if lock_attribute and locked[attribute] then
            pcall(function()
                lock_attribute:InvokeServer(attribute, false);
            end);

            task.wait(0.05);
        end;

        if limit_attribute and limits[attribute] then
            pcall(function()
                limit_attribute:InvokeServer(attribute, true);
            end);

            task.wait(0.05);
        end;
    end;

    return true;
end

function AutoProgression:manual_shrine()
    Library:Notify("Please click this button when you have shrined and finished up.", 9e9)
    local button = Instance.new("TextButton", services.CoreGui.RobloxGui);
    button.Size = UDim2.fromOffset(200, 50)
    button.Position = UDim2.fromScale(0.1, 0.5)
    button.AnchorPoint = Vector2.new(0.5, 0.5)
            
    button.BackgroundTransparency = 0.5
    button.BackgroundColor3 = Color3.fromRGB(50, 50, 50)
            
    button.TextColor3 = Color3.fromRGB(255, 255, 255)
    button.Text = "I have shrined."
    button.Activated:Wait();

    local data = self:read_data();
    data.shrined = true;
    self:set_data(data)
    self:set_state("DOING_AUTO_FERRYMAN");
    local stored = persistent_data:get("auto_progression_internal", {});
    Logger.log(string.format("[auto progression] shrined saved as %s", tostring(stored.data and stored.data.shrined)));
    print(string.format("[auto progression] shrined saved as %s", tostring(stored.data and stored.data.shrined)));
    
    self:set_farm(true);

    server_utility:rejoin(local_player.instance:GetAttribute("DataSlot") or "A");
end;

function AutoProgression:start()
    local state = self:read_state();
    local data = self:read_data();
    Logger.log("[auto progression] starting with state: " .. state);

    if aztup.flags.auto_progress_shrined and not data.shrined then
        data.shrined = true;
        self:set_data(data);
    end;

    ab_builder.shrined = data.shrined == true;
    print(string.format("[auto progression] state %s | shrined %s", state, tostring(ab_builder.shrined)));

    self:unlock_attributes();

    task.spawn(function()
        if state == 'JUST_STARTED' then return; end

        if state == 'WAITING_MANUAL_SHRINE' then return; end

        ab_builder.url_override = persistent_data:get("auto_progress_url", "");

        ab_builder:build();
        ab_builder:put_points();
    end);

    if is_depths then
        aztup.automation:set('auto_escape_depths', true)
        if state ~= "ESCAPING_DEPTHS" then
            data.escape_depths_return_to = state;
            self:set_data(data)
            self:set_state("ESCAPING_DEPTHS")
        end;

        return;
    elseif state == "ESCAPING_DEPTHS" then
        state = self:resume_from_depths();
    end;
    if is_etrean and state == "DOING_AUTO_FERRYMAN" then
        self:persist_farm(true);
        require("@src/features/buttons/teleports/eastern")();
        return true;
    end;

    if state == "JUST_STARTED" then
        --check if the user is in character creation, if not we will be stuck in the JUST_STARTED state and not progress at all, therefor cancelling
        local character_creator = workspace:FindFirstChild('CharacterCreator');
        local character_parent = local_player.character and local_player.character.Parent;
        local game_loaded = local_player.instance:GetAttribute("GameLoaded");

        local in_character_creation = character_creator and character_parent == character_creator or game_loaded == "CharacterCreation";

        if not in_character_creation then
            self:import_build();
            if is_dungeon then
                self:set_state("DOING_TRIAL_OF_ONE");
                require("@src/features/buttons/auto_trial")();
                return true;
            end;

            --started on a character thats already made and power 1, then we can still do trial (its worth it) checks if they're deepbound ofc
            if self:should_do_trial() then
                self:set_state("WAITING_ON_TRIAL_OF_ONE");
                require("@src/features/buttons/teleports/trial")();
                return true;
            end;

            self:set_state("DOING_AUTO_FERRYMAN");

            if is_etrean then
                self:persist_farm(true);
                require("@src/features/buttons/teleports/eastern")();
                return true;
            end;

            self:set_farm(true);
            return true;
        end;

        self:set_state("WAITING_ON_TRIAL_OF_ONE");
        --AutoProgression.internal_struct:create_character();
        Logger:long_notify_sound("Please create your character.");

        local waited = 0;
        repeat
            task.wait(1)
            waited += 1;

            if waited % 10 == 0 then
                print(string.format("[auto progression] waiting on character | parent %s | GameLoaded %s",
                    tostring(local_player.character and local_player.character.Parent and local_player.character.Parent.Name),
                    tostring(local_player.instance:GetAttribute("GameLoaded"))));
            end
        until (local_player.character
            and local_player.character.Parent
            and local_player.character.Parent.Name == "Live")
            or not persistent_data:get('auto_progress', false);

        if not persistent_data:get('auto_progress', false) then return true; end
        task.spawn(pcall, function() --note: SOMETIMES WE GET STUCK HERE, MAYBE THE USER DIDNT SELECT TRIAL OF ONE?
            repeat
                task.wait(1)
            until (local_player.character
                and local_player.character.Parent
                and local_player.character.Parent.Name == "Live")
                or not persistent_data:get('auto_progress', false);

            if not persistent_data:get('auto_progress', false) then return; end

            self:import_build();
            if self:should_do_trial() then
                require("@src/features/buttons/teleports/trial")()
            else
                self:set_state("DOING_AUTO_FERRYMAN");
                self:set_farm(true);
            end;
        end)
    elseif state == "WAITING_ON_TRIAL_OF_ONE" and is_dungeon then
        self:set_state("DOING_TRIAL_OF_ONE");
        require("@src/features/buttons/auto_trial")();
    elseif state == "WAITING_ON_TRIAL_OF_ONE" then
        require("@src/features/buttons/teleports/trial")();

        local waiting_since = tick();
        repeat
            task.wait(1)
        until tick() - waiting_since >= 30 or not persistent_data:get('auto_progress', false);

        if persistent_data:get('auto_progress', false) then
            print("[auto progression] couldnt reach the trial, doing the ferryman instead");

            self:set_state("DOING_AUTO_FERRYMAN");
            self:persist_farm(true);
            server_utility:rejoin(local_player.instance:GetAttribute("DataSlot") or "A");
        end;
    elseif state == "DOING_TRIAL_OF_ONE" and is_etrean then
        self:set_state("DOING_AUTO_FERRYMAN");
        self:set_farm(true);
    elseif state == "DOING_AUTO_BRUTUS" then
        data.brutus_attempts = (data.brutus_attempts or 0) + 1;
        self:set_data(data);

        if data.brutus_attempts <= 3 then
            self:train_fortitude();
        end;

        data.brutus_attempts = 0;
        self:set_data(data);

        self:set_state("DOING_AUTO_FERRYMAN");
        self:set_farm(true);
    elseif state == "DOING_AUTO_FERRYMAN" then
        if not persistent_data:get(self:farm_tag(), false) then
            self:set_farm(true);
        end;

        --boilerplate
        task.wait(2);
        local waiting_since = tick();
        repeat task.wait(0.5) until ab_builder.build_config or tick() - waiting_since >= 15;

        if self:farm_tag() == "auto_ferryman" and not self.ferryman_watch_started then
            self.ferryman_watch_started = true;

            if not data.ferryman_baseline then
                data.ferryman_baseline = persistent_data:get('ferryman_rounds_completed', 0);
                self:set_data(data);
            end;

            task.spawn(function()
        
                while persistent_data:get('auto_progress', false) and self:read_state() == "DOING_AUTO_FERRYMAN" do
                    task.wait(3);
--
                    if self:farm_tag() ~= "auto_ferryman" then break; end;
--
                    local baseline = self:read_data().ferryman_baseline or 0;
                    local completed = persistent_data:get('ferryman_rounds_completed', 0) - baseline;
--
                    if completed >= 2 then
                        local d = self:read_data();
                        d.ferryman_baseline = persistent_data:get('ferryman_rounds_completed', 0);
                        self:set_data(d);
--
                        self:maybe_train_fortitude(false);
                    end;
                end;
--
                self.ferryman_watch_started = false;
            end);
        end;--

        if ab_builder:shrine_ready() and not ab_builder.shrined then
            self:set_farm(false);
            
            webhook:send_webhook("Auto Progression", "Ready for shrine. Please manually use your shrines & grab what you need.", "@everyone");
            local_player.instance:Kick("Ready for shrine. Please manually use your shrines & grab what you need.");
            getgenv().dont_auto_hop_pls = true;
            self:set_state("WAITING_MANUAL_SHRINE")
        elseif not ab_builder.shrined and not self.shrine_watch_started then
            self.shrine_watch_started = true;

            task.spawn(function()
                while persistent_data:get('auto_progress', false) and self:read_state() == "DOING_AUTO_FERRYMAN" do
                    task.wait(3);

                    if ab_builder.shrined then break; end;

                    if ab_builder:shrine_ready() then
                        self:set_farm(false);
                        local_player.instance:Kick("Ready for shrine. Please manually use your shrines & grab what you need.");
                        self:set_state("WAITING_MANUAL_SHRINE");
                        break;
                    end;
                end;

                self.shrine_watch_started = false;
            end);
        end;

        local finished, missing = ab_builder:finished();
        if finished then
            self:set_farm(false);
            self:set_state("DONE");
            persistent_data:wipe();

            webhook:send_webhook("Auto Progression", "@everyone Auto progression has finished up. :), Clean up using shrines.");
            local_player.instance:Kick("Auto progression has finished up. :), Clean up using shrines.");
            getgenv().dont_auto_hop_pls = true;
        elseif missing > 0 then
            print(string.format("[auto progression] %i stat points left on the build", missing));
        end;
    elseif state == "WAITING_MANUAL_SHRINE" then
        ab_builder:points_killswitch();

        self:manual_shrine();
    else
        local edge_case_warn = string.format("Reached possible edge-case @ %i | %s (do not restart the auto progression this way...)", game.PlaceId, state);
        Logger.warn(edge_case_warn);
        Logger:long_notify(edge_case_warn);
    end

    return true;
end

local started = false;
AutoProgression.internal_struct = require("@src/automation/struct"):construct({
    persistent_data_flag = 'auto_progress',
    id = 'auto_progress',
    
    state_machine = {
        start = function()
            if started then return; end

            started = true;
            AutoProgression:start();
        end
    },
    features = {
        "no_fall",
        "noclip",
        "fly",
        "no_fire",
        "m1_hold",
        "no_stun",
        "fast_swing",
        "auto_decline_guild_invites",
        "auto_decline_squad_invites",
        "auto_train_agility",
        "knocked_ownership",
        "auto_equip_weapon"
    },
    
    not_allowed = function()
        local state = AutoProgression:read_state();
        local data = AutoProgression:read_data();

        if state == "WAITING_MANUAL_SHRINE" then
            task.spawn(function() 
                AutoProgression:manual_shrine();
            end);

            return true;
        end;

        return started;
    end,
    
    character_creator_handler_used = true,
    character_creator_handler_opts = {
        gamemode = "Pathfinder"
        -- We shouldn't decide on the origin.
    },

    on_run = function()
        aztup.flags.block_input = true;
        aztup_options.blocked_safe_input_user_moves.Value.M1s = true;
        aztup_options.bi_punishable_type.Value = "Always";
    end
})

AutoProgression.internal_struct.resume_from_depths = function()
    if AutoProgression:read_state() ~= "ESCAPING_DEPTHS" then
        return;
    end;

    return AutoProgression:resume_from_depths();
end;

AutoProgression.internal_struct.initialize = function(state, data)
    AutoProgression:set_data(data);
    AutoProgression:set_state(state);
end;

return AutoProgression.internal_struct;

end;

__modules["src/automation/persistent_tasks/auto_saramed"] = function()
--!nocheck
if is_regular then
    return {
        run = function()
            local_player.instance:Kick("Attempted to start a beta-only automation whilst not on beta.");
            persistent_data:wipe();
        end
    }
end;

local automation_struct = require("@src/automation/struct");
local is_saramed = game.PlaceId == 8668476218

aztup.flags.aa_bypass = not is_saramed

local autosaramed = {
    isCarnivore = function()
        local character = local_player.character;
        local passives = character:GetAttribute("ssv_Passives");
        return passives and passives:find("Carnivore")
    end,
    
    lowHunger = function()
        local stomach = local_player.character:FindFirstChild('Stomach')
        return (stomach.Value <= (stomach.MaxValue * 0.25))
    end,
    
    lowThirst = function()
        local water = local_player.character:FindFirstChild('Water')
        return (water.Value <= (water.MaxValue * 0.25))
    end,
    
    lowBlood = function()
        local blood = local_player.character:FindFirstChild('Blood')
        return (blood.Value <= (blood.MaxValue * 0.25))
    end,
    
    serverHop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, true, true)
    end,
    
    refillFood = function(self)
        local stomach = local_player.character:FindFirstChild('Stomach')
        local water   = local_player.character:FindFirstChild('Water')
        
        local ingredients = workspace:FindFirstChild('Ingredients')
        
        local function collectIngredient(self, ing)
            self.playerSafeTween(self, ing.CFrame, 170)
            
            repeat
                pcall(function(...)  
                    local_player.root_part.CFrame = ing.CFrame
                end)
                
                pcall(function() 
                    fireproximityprompt(ing.InteractPrompt)
                end)
                
                task.wait()
            until not ing:FindFirstChild('InteractPrompt')
        end
        
        -- Ill be cleaning up this ugly mess
        local function craftFood(recipe)
            if recipe:match('Bread') then
                local args = {
                    {
                        ['Gathered Wheat'] = local_player.instance:FindFirstChild("Gathered Wheat", true) ~= nil,
                    }
                }
                local requests = services.ReplicatedStorage:WaitForChild("Requests")
                local craftRemote = requests:WaitForChild("Craft") :: RemoteFunction
                
                local gatheredWheat = local_player.instance.Backpack:FindFirstChild('Gathered Wheat')
                local gatheredWheatQuantity = gatheredWheat and gatheredWheat:FindFirstChild('Quantity') and gatheredWheat:FindFirstChild('Quantity').Value
                
                repeat
                    task.spawn(function()
                        pcall(function(...)  
                            craftRemote:InvokeServer(unpack(args))
                        end)
                    end)
                    
                    task.spawn(function()
                        pcall(function(...)  
                            local args = {
                                99
                            }
                            
                            local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt'):FindFirstChild('Choice'):InvokeServer(unpack(args))
                        end)
                    end)
                    task.wait(0.5)
                until local_player.instance.Backpack:FindFirstChild('Bread')
                
                return
            end
        end
        
        local function hungerSatiated()
            return stomach.Value >= (stomach.MaxValue * 0.95)
        end
        
        local function thirstQuenched()
            return water.Value >= (water.Value * 0.95)
        end
        
        local function toNearestCampfire(self)
            local campfire = CFrame.new(-2819.03516, 145.119858, 3001.22266, 0.350389659, -1.64259885e-19, -0.936604023, -4.44767584e-20, 1, -1.92017197e-19, 0.936604023, 1.08937955e-19, 0.350389659)
            self.playerSafeTween(self, campfire, 170)
            task.wait(0.5)
        end
        
        local function eat()
            -- Check inventory for pomars
            if not hungerSatiated() and not thirstQuenched() then
                if local_player.instance.Backpack:FindFirstChild('Pomar') then
                    if local_player.instance.Backpack.Pomar:FindFirstChild('Quantity') then
                        local pomarQuantity = local_player.instance.Backpack.Pomar:FindFirstChild('Quantity').Value
                        
                        local_player.instance.Backpack['Pomar'].Parent = local_player.character
                        
                        for i = 0, pomarQuantity do
                            pcall(function(...)  
                                local_player.character['Pomar']:Activate()
                                task.wait(1)
                            end)
                            
                            if hungerSatiated() then break; end
                        end
                    end 
                end
            end
            
            -- Check inventory for soup
            if not hungerSatiated() and not thirstQuenched() then
                if local_player.instance.Backpack:FindFirstChild('Mushroom Soup') then
                    if local_player.instance.Backpack['Mushroom Soup']:FindFirstChild('Quantity') then
                        local msQuantity = local_player.instance.Backpack['Mushroom Soup']:FindFirstChild('Quantity').Value
                        
                        local_player.instance.Backpack['Mushroom Soup'].Parent = local_player.character
                        
                        for i = 0, msQuantity do
                            pcall(function(...)  
                                local_player.character['Mushroom Soup']:Activate()
                                task.wait(1)
                            end)
                            
                            if hungerSatiated() then break; end
                        end
                    end 
                end
            end
            
            -- Check inventory for bread
            if not hungerSatiated() then
                if local_player.instance.Backpack:FindFirstChild('Bread') then
                    if local_player.instance.Backpack['Bread']:FindFirstChild('Quantity') then
                        local breadQuantity = local_player.instance.Backpack['Bread']:FindFirstChild('Quantity').Value
                        
                        local_player.instance.Backpack['Bread'].Parent = local_player.character
                        
                        for i = 0, breadQuantity do
                            pcall(function(...)  
                                local_player.character['Bread']:Activate()
                                task.wait(1)
                            end)
                            
                            if hungerSatiated() then break; end
                        end
                    end 
                end
            end
        end
        
        eat()
        
        if is_saramed then return; end
        
        -- Search for pomars
        if not hungerSatiated() then
            for _, pomar in ingredients:GetChildren() do
                if not pomar.Name:match('Pomar') then continue end
                if not pomar:FindFirstChild('InteractPrompt') then continue end
                if not pomar:IsA('MeshPart') then continue end
                
                collectIngredient(self, pomar)
                if hungerSatiated() then break; end    
            end
            
            eat()
        end
        
        -- Search for ingredients and craft bread
        if not hungerSatiated() then
            local amountCollected = 0
            
            for _, wheat in ingredients:GetChildren() do
                if not wheat.Name:match('Wheat') then continue; end
                if not wheat:FindFirstChild('InteractPrompt') then continue; end
                if not wheat:IsA('MeshPart') then continue; end
                
                collectIngredient(self, wheat)
                amountCollected += 1
                if amountCollected >= 36 then break end
            end
            
            toNearestCampfire(self)
            
            craftFood('Bread')
            
            eat()
        end
        
        if not thirstQuenched() then
            -- Tween to well and drink nigga drink
            local wellCF = CFrame.new(-2814.17163, 145.319962, 3119.74023, 0.61084187, 1.76499301e-19, -0.791752636, -8.8454953e-20, 1, 1.54678768e-19, 0.791752636, -2.44498239e-20, 0.61084187)
            self.playerSafeTween(self, wellCF, 170)
            
            local VIM = Instance.new('VirtualInputManager')
            
            -- DRINK DRINK DRINK
            repeat
                VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game);
                task.wait(0.1);
                VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game);
                task.wait()
            until thirstQuenched()
            
            VIM:Destroy()
        end
    end,
    
    readyWeapon = function()
        --character.CharacterHandler.Requests.DrawWeapon:FireServer(false);
        local character_handler = local_player.character:FindFirstChild("CharacterHandler");
        character_handler.Requests.DrawWeapon:FireServer(true);
    end,
    
    foundMobs = function()
        local mobsExist = false
        for _, mobModel in pairs(workspace:WaitForChild("Live"):GetChildren()) do
            if mobModel:GetAttribute('MOB_rich_name') then
                mobsExist = true
            end
        end
        
        return mobsExist
    end,
    
    clampCFrame = function(cf)
        return CFrame.new(Vector3.new(cf.Position.X, math.clamp(cf.Position.Y, 0, 1000), cf.Position.Z))
    end,
    
    killTarget = function(self, target)
        if not target then return end
        if not target:IsA('Model') then return; end
        
        if target.Name:match(local_player.instance.Name) then return; end
        
        self.readyWeapon()
        self.tempTween(target.HumanoidRootPart.CFrame, 170)
        
        -- Attach to back
        local attach_tween;
        local atb = task.spawn(function()
            while task.wait() do
                if target.Parent == nil then break; end
                if not target:FindFirstChild('HumanoidRootPart') then break; end
                
                local cf = self.clampCFrame(target.HumanoidRootPart.CFrame) * CFrame.new(0, aztup.flags.auto_saramed_attach_to_mob_distance, 0) * CFrame.Angles(math.rad(-90), 0, 0)
                
                --[[
                if target.Name:match("brood") or target.Name:match("brute") then
                    cf = target.HumanoidRootPart.CFrame * CFrame.new(0, -8.5, 5.5) * CFrame.Angles(math.rad(45), 0, 0)
                    --
                    if general:playing_ap_anims(target) then
                        cf = target.HumanoidRootPart.CFrame * CFrame.new(0, -15, 15)
                    end;
                end;
                ]]--
                
                if target.Name:lower():find('buncle') or target.Name:lower():find('knight') then
                    cf = self.clampCFrame(target.HumanoidRootPart.CFrame) * CFrame.new(0, -aztup.flags.auto_saramed_attach_to_mob_distance, 0) * CFrame.Angles(math.rad(90), 0, 0)
                end
                
                --local_player.root_part.CFrame = cf;
                
                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
                
                if (local_player.root_part.Position - cf.Position).Magnitude > 30  then
                    if attach_tween then attach_tween.stop() end
                    attach_tween = Tween.new(cf, true, 100);
                    continue;
                else
                    if attach_tween then attach_tween.stop() end
                    local_player.root_part.CFrame = cf;
                end;
            end

            if attach_tween then attach_tween.stop() end
        end)
        
        self.autoM1(true)
        repeat 
            task.wait();
            aztup.features.m1_hold.held = true;
        until self.healthCheck(tonumber('0.' .. aztup.flags.auto_saramed_minimum_health)) or target.Parent == nil or not aztup.automation:has_any()
        xpcall(function() task.cancel(atb); end, Logger.error)
        self.autoM1(false)
        
        return self.healthCheck(tonumber('0.' .. aztup.flags.auto_saramed_minimum_health))
    end,
    
    autoM1 = function(toggle)
        if not toggle then
            aztup.features.m1_hold.held = false
            aztup.flags.no_aerials = false;
            
            return
        end
        
        aztup.features.m1_hold.held = true;
        aztup.flags.no_aerials = true;
    end,
    
    mineOre = function(self, target: MeshPart)
        if not target then return false; end
        if target.Parent == nil then return false; end
        if not target:IsA('MeshPart') then return false; end
        if not target.Name:match('MagmaOre') then return false; end
        
        self.tempTween(target.CFrame, 170)
        local_player.root_part.CFrame = target.CFrame
        
        xpcall(function(...)  
            for i = 1, 60 do
                local_player.root_part.CFrame = target.CFrame
                pcall(function(...)  
                    local prompt = target:FindFirstChild("InteractPrompt");
                    if target:FindFirstChild("InteractPrompt") then
                        fireproximityprompt(prompt);
                    end;
                end)
                task.wait()
            end
            
            local debounce = tick();
            repeat task.wait() until not target:FindFirstChild("InteractPrompt") or tick() - debounce > 5
        end, Logger.error)
        
        return true
    end,
    
    getClosestOre = function()
        local closest = nil
        
        for _, magmaOre in workspace:GetDescendants() do
            if not magmaOre then continue; end
            if magmaOre.Parent == nil then continue; end
            if not magmaOre:IsA('MeshPart') then continue; end
            if not magmaOre.Name:match('MagmaOre') then continue; end
            if not magmaOre:FindFirstChild('InteractPrompt') then continue; end
            
            if closest == nil then closest = magmaOre; continue; end
            if closest then
                local closestDist = (local_player.root_part.Position - closest.Position).Magnitude
                local magmaOreDist = (local_player.root_part.Position - magmaOre.Position).Magnitude
                
                if magmaOreDist < closestDist then
                    closest = magmaOre
                end
            end
        end
        
        return closest
    end,
    
    depositOre = function(self)
        local deepdrill = workspace:FindFirstChild('Deepdrill')
        local dungeondrill = deepdrill and deepdrill:FindFirstChild('DungeonDrill')
        local fuelport = dungeondrill and dungeondrill:FindFirstChild('FuelPort')
        local hit = fuelport and fuelport:FindFirstChild('Hit')
        
        self.tempTween(hit.CFrame, 170)
        task.wait(1)
    end,
    
    healthCheck = function(percent)
        return local_player.humanoid and local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * percent)
    end,
    
    tempGetClosest = function()
        local live = workspace:FindFirstChild("Live")
        if not live then return nil end
        
        local closest = nil
        local shortestDistance = math.huge
        
        for _, model in live:GetChildren() do
            if not model:IsA("Model") then continue end
            if model == local_player.character then continue end
            
            if model.Name:sub(1,1) ~= "." then continue end
            
            local root = model:FindFirstChild("HumanoidRootPart") 
            or model.PrimaryPart
            if not root then continue end
            
            local humanoid = model:FindFirstChildOfClass("Humanoid")
            if not humanoid then continue end
            
            if humanoid.Health <= 0 then continue end
            if model:FindFirstChild("Torso") and model.Torso:FindFirstChild("RagdollAttach") then continue end
            
            local distance = (root.Position - local_player.root_part.Position).Magnitude
            
            if distance < shortestDistance then
                shortestDistance = distance
                closest = model
            end
        end
        
        return closest
    end,
    
    tempTween = function(cf, speed)
        Tween.new(cf, true, speed).wait();
    end,
    
    playerCheck = function(mag, custom)
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            if player == local_player.instance then continue end
            
            local hmrp = player.Character.HumanoidRootPart
            
            local dist = ((custom or local_player.root_part.Position) - hmrp.Position).Magnitude
            
            if (dist <= mag) then
                return true
            end
        end
        
        return false
    end,
    
    playerSafeTween = function(self, cf, speed)
        -- Check for players
        if self.playerCheck(200) then
            -- Serverhop to small server, will kick for now
            self.serverHop()
            while task.wait() do end
        end
        
        local ylevel = math.random(10000, 30000)
        
        -- Tween up
        local_player.root_part.CFrame = local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0)
        --self.tempTween(local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0), speed)
        
        -- Tween to target location
        self.tempTween(cf + Vector3.new(0, cf.Y + ylevel, 0), speed)
        
        -- Check for players
        if self.playerCheck(200, Vector3.new(cf.X, cf.Y, cf.Z)) then
            -- Serverhop to small server, will kick for now
            self.serverHop()
            while task.wait() do end
        end
        
        -- Tween down
        local_player.root_part.CFrame = cf
        --self.tempTween(cf, speed)
        task.wait(0.3)

        local landed_dist = (local_player.root_part.Position - cf.Position).Magnitude
        if landed_dist > 15 then
            local restore_aa_bypass = aztup.flags.aa_bypass
            aztup.flags.aa_bypass = false

            local_player.root_part.CFrame = cf
            task.wait(0.3)

            aztup.flags.aa_bypass = restore_aa_bypass
        end
    end,
    
    grabChest = function(self)
        local time = 5
        local secondsWaited = 0
        
        for _, chest in pairs(workspace.Thrown:GetChildren()) do
            if not chest:FindFirstChild("Lid") then continue; end
            
            self.tempTween(chest.Lid.CFrame, 170)
            local moreTime = 5
            local moreSecondsWaited = 0
            
            repeat 
                task.wait(.1) 
                pcall(function()
                    fireproximityprompt(chest:FindFirstChildWhichIsA("ProximityPrompt"));
                end);
                pcall(function(...) 
                    self.tempTween(chest.Lid.CFrame, 170)
                end)
                moreSecondsWaited += .1
            until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or not aztup.automation:has_any() or moreSecondsWaited >= moreTime
            
            repeat task.wait(.1); secondsWaited += .1; until not local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt') or not aztup.automation:has_any() or secondsWaited >= time
            
            break;
        end
    end,
}

function autosaramed:checkArea()
    pcall(function(...)  
        if is_etrean then
            require("@src/features/buttons/teleports/eastern")()
        end
        
        if is_depths then
            task.spawn(function()
                aztup.automation:set("auto_saramed", not persistent_data:get("auto_saramed", false));
            end)
            local_player.instance:Kick("You somehow got into the Depths while auto saramed is enabled.");
            getgenv().dont_auto_hop_pls = true;
        end
    end)
end

function autosaramed:pathTosaramed()
    if is_saramed then return; end
    
    if is_eastern then
        local saramedNpc = CFrame.new(-2856.81104, 135.674957, 3375.38403, 0.541101158, 3.91375053e-19, -0.840957522, -3.07401254e-19, 1, 2.67599571e-19, 0.840957522, 1.13712971e-19, 0.541101158)
        
        if self.lowHunger() or self.lowThirst() and not self.isCarnivore() then self.refillFood(self); end
        self.playerSafeTween(self, saramedNpc, 170)
        
        task.wait(0.5)
        
        repeat task.wait() until workspace.NPCs:FindFirstChild('Malisae')
        
        fireproximityprompt(workspace.NPCs.Malisae.InteractPrompt)
        
        task.wait(3)
        
        local args = {
            {
                choice = 'Enter alone.',
            }
        }
        
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
        
        task.wait(5)
    end
end

function autosaramed:checkPlayerStatus()
    if not is_saramed then return end
    
    if self.lowHunger() or self.lowThirst() and not self.isCarnivore() then
        local deepdrill = workspace:FindFirstChild('Deepdrill')
        local dungeonExit = deepdrill:FindFirstChild('DungeonExit')
        
        self.refillFood(self)
        
        if not self.lowHunger() and not self.lowThirst() then return; end
        
        self.tempTween(dungeonExit.CFrame, 170)
        -- Fire touchinterest if there is one
        task.wait(3)
        
        if replicatesignal then
            replicatesignal(local_player.instance.Kill)
            task.delay(1, function()
                if local_player.humanoid.Health <= 1 then return; end
                
                local_player.root_part.CFrame *= CFrame.new(0,9e9,0);
            end);
        else
            local_player.root_part.CFrame *= CFrame.new(0,9e9,0);
        end
    end
end

function autosaramed:startDungeon()
    if not is_saramed then return; end
    
    repeat task.wait() until local_player.character
    
    if not local_player.instance.Backpack:FindFirstChild('Pickaxe') and not local_player.character:FindFirstChild('Pickaxe') then
        Logger:notify('[AUTO SARAMED] - Please buy a pickaxe.')
        repeat task.wait() until local_player.instance.Backpack:FindFirstChild('Pickaxe') or local_player.character:FindFirstChild('Pickaxe')
    end
    
    local deepdrill = workspace:FindFirstChild('Deepdrill')
    
    local deepDrillDist = (deepdrill.DungeonDrill.Switch.Case.Position - local_player.root_part.Position).Magnitude
    local deepEvatorDist = (deepdrill.Drillevator.Switch.Case.Position - local_player.root_part.Position).Magnitude
    
    if deepDrillDist < deepEvatorDist then
        -- Go to deepdrill
        local_player.root_part.CFrame = CFrame.new(local_player.root_part.CFrame.X, deepdrill.DungeonDrill.Switch.Case.CFrame.Y, local_player.root_part.CFrame.Z);
        self.tempTween(deepdrill.DungeonDrill.Switch.Case.CFrame, 170);
        task.wait(1);
        fireproximityprompt(deepdrill.DungeonDrill.Switch.InteractPrompt);
        task.wait(2);
    elseif deepEvatorDist < deepDrillDist then
        --Go to evator
        local_player.root_part.CFrame = CFrame.new(local_player.root_part.CFrame.X, deepdrill.Drillevator.Switch.Case.CFrame.Y, local_player.root_part.CFrame.Z);
        self.tempTween(deepdrill.Drillevator.Switch.Case.CFrame, 170);
        task.wait(1);
        fireproximityprompt(deepdrill.Drillevator.Switch.InteractPrompt);
        task.wait(2);
    end
end

function autosaramed:completeDungeon()
    if not is_saramed then return; end
    
    repeat task.wait(); until self.foundMobs()
    
    repeat
        pcall(function(...)  
            self.killTarget(self, self.tempGetClosest())
        end)
        
        if self.healthCheck(tonumber('0.' .. aztup.flags.auto_saramed_minimum_health)) then break end
        if not aztup.automation:has_any() then break; end
        task.wait()
    until not self.foundMobs()
    
    if not aztup.automation:has_any() then return; end
    
    if self.healthCheck(tonumber('0.' .. aztup.flags.auto_saramed_minimum_health)) then return end
    
    for i = 0, 5 do
        local closestOre = nil
        repeat
            closestOre = self.getClosestOre()
            task.wait()
        until closestOre ~= nil or not aztup.automation:has_any()
        
        if aztup.automation:has_any() then
            self.mineOre(self, closestOre)
        else
            break
        end
    end
    
    if not aztup.automation:has_any() then return; end
    
    self.depositOre(self)
    
    
    -- This is needed because sometimes the fucking sanity causes the player to itch and does not mine the ore or drops it?? I believe i saw it drop the ore when it itched.
    if workspace:FindFirstChild('Deepdrill').DungeonDrill.FuelPort.Display.SurfaceGui.Bar.BackgroundColor3:ToHex() ~= Color3.fromRGB(141, 239, 112):ToHex() then
        repeat
            for _, ore in workspace:GetDescendants() do
                if not ore:IsA('MeshPart') then continue; end
                if not ore.Name:match('MagmaOre') then continue; end
                if not aztup.automation:has_any() then break end
                
                self.mineOre(self, ore)
                break;
            end
            
            self.depositOre(self)
            
            task.wait()
        until workspace:FindFirstChild('Deepdrill').DungeonDrill.FuelPort.Display.SurfaceGui.Bar.BackgroundColor3:ToHex() == Color3.fromRGB(141, 239, 112):ToHex() or not aztup.automation:has_any()
    end
    
    if not aztup.automation:has_any() then return; end
    
    self.grabChest(self)
end

function autosaramed:resetDungeon()
    if not is_saramed then return; end
    if not aztup.automation:has_any() then return; end
    
    local deepdrill = workspace:FindFirstChild('Deepdrill')
    local dungeondrill = deepdrill and deepdrill:FindFirstChild('DungeonDrill')
    local switch = dungeondrill and dungeondrill:FindFirstChild('Switch')
    local radio = dungeondrill and dungeondrill:FindFirstChild('Radio')
    local destructibles = workspace:FindFirstChild("Destructibles");
    
    -- Tween to switch
    self.tempTween(switch.Case.CFrame, 170)
    
    -- Interact prompt
    repeat
        task.wait()
        pcall(function() 
            fireproximityprompt(radio.InteractPrompt)
        end)
        self.tempTween(switch.Case.CFrame, 170)
    until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt')
    
    local prompt = local_player.instance.PlayerGui:FindFirstChild("ChoicePrompt");
    prompt.Choice:FireServer(true)
    
    -- Wait until fireplace is detected
    local dist = math.huge
    
    repeat
        task.wait()
        dist = (destructibles.Campfire:FindFirstChildWhichIsA('Part').Position - local_player.root_part.Position).Magnitude
    until dist <= 150
    
    -- If health is above 50% just skip healing and go back down
    if not self.healthCheck(0.5) then return; end
    
    repeat
        self.tempTween(destructibles.Campfire.Part.CFrame, 170)
        local_player.root_part.CFrame = destructibles.Campfire.Part.CFrame * CFrame.new(0, 1, 0)
        
        task.wait(1)
        
        fireproximityprompt(destructibles.Campfire.InteractPrompt)
        
        task.wait(1)
    until EffectReplicator:FindEffect("Resting") or not aztup.automation:has_any()
    
    repeat task.wait() until local_player.humanoid.Health >= (local_player.humanoid.MaxHealth * 0.5);
    
    local VIM = Instance.new('VirtualInputManager')
    
    VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game);
    task.wait(0.1);
    VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game);
    
    task.wait(1)
    
    VIM:Destroy()
end

return automation_struct:construct({
    persistent_data_store = 'saramed_store',
    persistent_data_flag = 'auto_saramed',
    id = 'auto_saramed',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start',               from = 'idle',                 to = '_check_Area'},
            
            {name = 'path',                from = '_check_Area',          to = '_path_To_saramed'},
            
            {name = 'status',              from = '_path_To_saramed',    to = '_check_Player_Status'},
            
            {name = 'dungeonStart',        from = '_check_Player_Status', to = '_start_Dungeon'},
            
            {name = 'dungeonComplete',     from = '_start_Dungeon',       to = '_complete_Dungeon'},
            
            {name = 'dungeonContinuation', from = '_complete_Dungeon',    to = '_start_Dungeon'},
            {name = 'dungeonReset',        from = '_complete_Dungeon',    to = '_reset_Dungeon'},
            
            {name = 'fullReset',           from = '_reset_Dungeon',       to = '_check_Area'},
            
            {name = 'endFarm',             from = '_check_Area',          to = 'idle'},
            {name = 'endFarm',             from = '_path_To_saramed',    to = 'idle'},
            {name = 'endFarm',             from = '_start_Dungeon',       to = 'idle'},
            {name = 'endFarm',             from = '_check_Player_Status', to = 'idle'},
            {name = 'endFarm',             from = '_reset_Dungeon',       to = 'idle'},
            
            
        },
        callbacks = {
            onenter_check_Area = function(self)
                
                if not aztup.maid.disconnect_handler_saramed then
                    aztup.maid.disconnect_handler_saramed = services.GuiService.ErrorMessageChanged:Connect(function()    
                        local Code = services.GuiService:GetErrorCode().Value
                        
                        if Code >= Enum.ConnectionError.DisconnectErrors.Value then
                            local dataSlot = local_player.instance:GetAttribute('DataSlot');
                            services["MemStorageService"]:SetItem('DataSlot', dataSlot);
                            while task.wait() do
                                pcall(function()
                                    autosaramed.serverHop()
                                end);
                            end;
                        end
                    end);
                end
                
                if not aztup.maid.autoDepositOre and is_saramed then
                    aztup.maid.autoDepositOre = task.spawn(function()
                        while task.wait(0.2) do
                            if local_player.character:FindFirstChild("MagmaOre") then
                                local hit = workspace.Deepdrill.DungeonDrill.FuelPort.Hit;
                                firetouchinterest(local_player.character.MagmaOre, hit, 0)
                                firetouchinterest(local_player.character.MagmaOre, hit, 1)
                            end;
                        end;
                    end);
                    
                end
                
                autosaramed:checkArea()
                
                if aztup.automation:has_any() then
                    self:path()
                else
                    self:endFarm()
                end
            end,
            
            onenter_path_To_saramed = function(self)
                autosaramed:pathTosaramed()
                
                if aztup.automation:has_any() then
                    self:status()
                else
                    self:endFarm()
                end
            end,
            
            onenter_check_Player_Status = function(self)
                autosaramed:checkPlayerStatus()
                
                if aztup.automation:has_any() then
                    self:dungeonStart()
                else
                    self:endFarm()
                end
            end,
            
            onenter_start_Dungeon = function(self)
                autosaramed:startDungeon()
                
                if aztup.automation:has_any() then
                    self:dungeonComplete()
                else
                    self:endFarm()
                end
            end,
            
            onenter_complete_Dungeon = function(self)
                autosaramed:completeDungeon()
                
                if not autosaramed.healthCheck(tonumber('0.' .. aztup.flags.auto_saramed_minimum_health)) and not workspace.Deepdrill.DungeonDrill.DepthDisplay.SurfaceGui.TextLabel.Text:find("2.00") then
                    task.defer(self.dungeonContinuation, self)
                else
                    task.defer(self.dungeonReset, self)
                end
            end,
            
            onenter_reset_Dungeon = function(self)
                autosaramed:resetDungeon()
                self:fullReset()
                
                if aztup.automation:has_any() then
                    self:dungeonStart()
                else
                    self:endFarm()
                end
            end,
        },
    }),
    features = {
        "no_fall",
        "noclip",
        "fly",
        "no_fire",
        "no_stun",
        "fast_swing",
        "m1_hold",
        "auto_equip_weapon",
    },
    
    not_allowed = function()
        return false; --todo
    end,
    
    character_creator_handler_used = false,
    character_creator_handler_opts = {
    }
})

end;

__modules["src/automation/persistent_tasks/auto_voi"] = function()
local automation_struct = require("@src/automation/struct");
local autofarm_util = require("@src/utility/deepwoken/autofarm_utilitys");
local struct;

local auto_voi = {
    playerCheck = function(mag, custom)
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if player == local_player.instance then continue end

            local hrp = player.Character:FindFirstChild("HumanoidRootPart");
            if not hrp then continue end

            local dist = ((custom or local_player.root_part.Position) - hrp.Position).Magnitude;
            if dist <= mag then
                return true;
            end
        end
        return false;
    end,

    mobsCheck = function(mag, custom)
        for _, mob in workspace.Live:GetChildren() do
            if not mob:FindFirstChild("HumanoidRootPart") then continue; end;

            local dist = ((custom or local_player.root_part.Position) - mob:GetPivot().Position).Magnitude;
            if dist <= mag then
                return true;
            end
        end
        return false;
    end,

    serverHop = function()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, "any", true);
    end,

    tempTween = function(cf, speed)
        Tween.new(cf, true, speed or 150).wait();
    end,

    player_safe_tween = function(self, cf, speed)
        if self.playerCheck(200) then
            self.serverHop();
            while task.wait() do end
        end

        local x, _, z = select(1, cf:GetComponents());
        self.tempTween(CFrame.new(x, -1050, z), speed);
        self.tempTween(cf, speed);

        if self.playerCheck(200, cf.Position) then
            self.serverHop();
            while task.wait() do end
        end

        local root = local_player.root_part;
        if not root then return end

        root.CFrame = cf;
        root.AssemblyLinearVelocity = Vector3.zero;
    end,

    autoM1 = function(toggle)
        if not toggle then
            aztup.features.m1_hold.held = false;
            aztup.flags.no_aerials = false;
            return;
        end

        aztup.features.m1_hold.held = true;
        --//aztup.flags.no_aerials = true;
    end,

    healthCheck = function(percent)
        return local_player.humanoid and local_player.humanoid.Health <= (local_player.humanoid.MaxHealth * percent);
    end
};

function auto_voi:generic_humanoid_fight(name, flag)
    repeat task.wait() until local_player.character;
    task.wait(2.5);

    repeat task.wait() until workspace.Live:FindFirstChild(name);
    repeat task.wait() until workspace.Live:FindFirstChild(name) and workspace.Live:FindFirstChild(name):FindFirstChild("HumanoidRootPart");

    aztup.flags.atb_x_offset = 4
    aztup.flags.atb_y_offset = -7
    aztup.flags.atb_z_offset = 0
    aztup_toggles.attach_to_back:SetValue(true);
    aztup.features.attach_to_back.target = workspace.Live:FindFirstChild(name);
    aztup.features.attach_to_back.state = "attaching";
    aztup.flags.atb_rotate = true;
    aztup_toggles.noclip:SetValue(true);

    aztup_toggles.mob_ai_breaker:SetValue(true);
    aztup_options.breaker_type.Value = "Aggressive"
    workspace.Live:FindFirstChild(name):WaitForChild("HumanoidRootPart");

    while task.wait() and not workspace:FindFirstChild("DungeonExit") do
        pcall(function()
            if not EffectReplicator:FindEffect("Equipped") then
                local_player.character.CharacterHandler.Requests.DrawWeapon:FireServer(true);
            end;
        end);

        self:autoM1(true);
    end;

    self:autoM1(false);

    persistent_data:set(flag, true);
    Tween.new(workspace:FindFirstChild("DungeonExit").CFrame, false, 150);
end;

function auto_voi:rat_king()
    if game.PlaceId == 86761619761103 then
        repeat 
            task.spawn(function()
                local_player.instance:RequestStreamAroundAsync(Vector3.new(-2829.87646, 56.4980431, -3300.2854));
            end);
            task.wait(0.1) 
        until workspace:FindFirstChild("GoldenRatBoundary");

        local boundary = workspace:FindFirstChild("GoldenRatBoundary");
        while task.wait() do
            xpcall(function() 
                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
                local_player.root_part.CFrame = boundary.CFrame;
                firetouchinterest(boundary, local_player.root_part, 1);
                firetouchinterest(boundary, local_player.root_part, 0);
            end, warn);
        end;
    else    
        self:generic_humanoid_fight(".ratking1", "done_rat_king");
    end;
end;

function auto_voi:enmity()
    if game.PlaceId == 86761619761103 then
        require("@src/features/buttons/teleports/depths")();
    elseif game.PlaceId == 8668476218 then
        aztup.flags.atb_x_offset = 0
        aztup.flags.atb_y_offset = 6
        aztup.flags.atb_z_offset = 0
        aztup_toggles.attach_to_back:SetValue(true);
        aztup.features.attach_to_back.target = workspace.Live:WaitForChild(".enmity_true1");
        aztup.features.attach_to_back.state = "attaching";
        aztup.flags.atb_rotate = true;
        if not aztup.flags.m1_hold then
            aztup_toggles.m1_hold:SetValue(true);
        end;

aztup_toggles.mob_ai_breaker:SetValue(true);
aztup_options.breaker_type.Value = "Aggressive"
            local_player.character.CharacterHandler.Requests.DrawWeapon:FireServer(true);

            while task.wait() do
            aztup.features.m1_hold.held = not general:playing_ap_anims(workspace.Live[".enmity_true1"]);
            aztup.flags.atb_x_offset = 0
            aztup.flags.atb_z_offset = 0
            if general:playing_ap_anims(workspace.Live[".enmity_true1"]) then
                aztup.flags.atb_x_offset = 0
                aztup.flags.atb_y_offset = general:playing_ap_anims(workspace.Live[".enmity_true1"], {
                    "112050896536834"
                }) and math.random(150, 200) or general:playing_ap_anims(workspace.Live[".enmity_true1"], {
                    "92111402678314"
                }) and -20000 or 200;
                aztup.flags.atb_z_offset = 0;
            else
                aztup.flags.atb_y_offset = 6
            end;

                aztup.flags.atb_prevent_voiding = false;
            aztup.features.attach_to_back.target = workspace.Live[".enmity_true1"];
            aztup.features.attach_to_back.state = "attaching";

                pcall(function() 
                    aztup.automation.requesting_mob_ai_breaker_stop = true;
                for _, enforcer in workspace.Live:GetChildren() do
                    if not enforcer.Name:match("enmity_enforcer") then continue; end
                    if enforcer.Humanoid.Health <= 0 then return; end
                    aztup.automation.requesting_mob_ai_breaker_stop = false;
                        aztup.flags.atb_z_offset = 0
                    aztup.flags.atb_x_offset = 0
                    aztup.features.attach_to_back.target = enforcer;
                    break;
                end;
            end);
        end;
    else
        Logger:long_notify("You will have to manually reach enmity :3")
    end;
end;

function auto_voi:shogun()
    if game.PlaceId == 86761619761103 then
        repeat 
            task.spawn(function()
                local_player.instance:RequestStreamAroundAsync(Vector3.new(-8983.13, 560.461121, -4054.68));
            end);
            task.wait(0.1) 
        until workspace:FindFirstChild("ShogunBoundary");

        local boundary = workspace:FindFirstChild("ShogunBoundary");
        while task.wait() do
            xpcall(function() 
                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
                local_player.root_part.CFrame = boundary.CFrame;
                firetouchinterest(boundary, local_player.root_part, 1);
                firetouchinterest(boundary, local_player.root_part, 0);
            end, warn);
        end;
    else    
        self:generic_humanoid_fight(".shogun1", "done_shogun");
    end;
end;

local state_machine = StateMachine.create({
    initial = "idle",
    events = {
        { name = "start",    from = "idle", to = "_check_area" },
        { name = "shogun",    from = "_check_area", to = "_do_shogun" },
        { name = "rat_king",    from = "_check_area", to = "_do_rat_king" },
        { name = "do_enmity", from = "_check_area", to = "_do_enmity" },
        { name = "do_complete", from = "_check_area", to = "_do_complete" },

        { name = "skip",     from = "_check_area", to = "idle" },
    },
    callbacks = {
        onenter_check_area = function(self)
            aztup.flags.block_input = true;
            aztup_options.blocked_safe_input_user_moves.Value.M1s = true;
            aztup_options.bi_punishable_type.Value = "Always";
            if not persistent_data:get("done_shogun", false) then
                self:shogun();
            elseif not persistent_data:get("done_rat_king", false) then
                self:rat_king();
            else
                if not persistent_data:get("level_up_warn", false) then
                    local_player.instance:Kick("You need to level up before you can continue.");
                    persistent_data:set("level_up_warn", true);
                elseif not persistent_data:get("confirmed_leveled_up", false) then
                    Library:Notify("Please click this button when you have leveled up and finished.", 9e9)
                    local button = Instance.new("TextButton", services.CoreGui.RobloxGui);
                    button.Size = UDim2.fromOffset(200, 50)
                    button.Position = UDim2.fromScale(0.1, 0.5)
                    button.AnchorPoint = Vector2.new(0.5, 0.5)

                    button.BackgroundTransparency = 0.5
                    button.BackgroundColor3 = Color3.fromRGB(50, 50, 50)

                    button.TextColor3 = Color3.fromRGB(255, 255, 255)
                    button.Text = "I have leveled up."
                    button.Activated:Wait();
                    persistent_data:set("confirmed_leveled_up", true);
                    server_utility:rejoin(local_player.instance:GetAttribute("DataSlot") or "A");
                else
                    self:enmity();
                end;
                --self:do_enmity();   
            end;
        end,

        shogun = function(self)
            auto_voi:shogun();
        end,

        rat_king = function(self)            
            auto_voi:rat_king();
        end,

        enmity = function(self)
            auto_voi:enmity();
        end,

        onenter_complete = function(self)
            aztup.automation:set("auto_voi", false);
            Logger:long_notify_sound("Successfully finished voi.")

            if true then return; end
        end,
    }
});

struct = automation_struct:construct({
