__modules["src/automation/persistent_tasks/ministry_notefarm"] = function()
--!nocheck
--todo:
-- FIX CHARACTER CREATION ON LAGGY SERVERS MAKES THE WHOLE AUTOFARM BREAKS (u stay in the inn flying)
-- USE GUILD DONT WORK
-- FALLBACKS IN CASE LAG
-- ADDING A TOGGLE FOR GUILD TREASURE FUNDS

local automation_struct = require("@src/automation/struct");

local notefarm = {
    playerCheck = function(self, mag, custom)
        for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            if player == local_player.instance then continue end
            
            local hmrp = player.Character.HumanoidRootPart
            
            local dist = ((custom or local_player.root_part.Position) - hmrp.Position).Magnitude
            
            if (dist <= mag) then
                return true
            end
        end
        
        return false
    end,
    
    serverHop = function(self)
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, 'any', false)
    end,
    
    player_safe_tween = function(self, cf, speed, level)
        if self:playerCheck(200) then
            self:serverHop()
            while task.wait() do end
        end
        
        local ylevel = -20
        
        if level ~= nil then
            ylevel = level
        end
        
        local_player.root_part.CFrame = local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0)
        
        self:tempTween(cf + Vector3.new(0, cf.Y + ylevel, 0), speed)
        
        if self:playerCheck(200, Vector3.new(cf.X, cf.Y, cf.Z)) then
            self:serverHop()
            while task.wait() do end
        end
        
        local_player.root_part.CFrame = cf
    end,
    
    tempTween = function(self, cf, speed)
        Tween.new(cf, true, speed).wait();
    end,
    
    players_near = function(self, target, mag)
        for _, player in services.Players:GetPlayers() do
            if player == local_player.instance then continue end
            
            if player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                local hmrp = player.Character:FindFirstChild("HumanoidRootPart")
                
                local dist = (hmrp.Position - target.Position).Magnitude
                if (dist <= mag) then
                    return true
                end
            end
        end
        
        return false
    end,
    
    -- dialogue functions ty temp
    sendDialogue_choice = function(self, value)
        local args = {
            {
                choice = value
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
    end,
    
    sendDialogue_exit = function(self)
        local args = {
            {
                exit = true
            }
        }
        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer(unpack(args))
    end,
    
    click = function(self, btn)
        if btn then 
            firesignal(btn.MouseButton1Click) -- https://docs.voltbz.net/docs
            task.wait(0.2) 
        end
    end,
    
    getCurrentNotesAmount = function(self)
        local notesText = local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame.Notes.Amount.Text:gsub("%D", "")
        return tonumber(notesText) or 0
    end,
    
    setBankAmountAndConfirm = function(self, amount)
        repeat task.wait(0.1) until local_player.instance.PlayerGui:FindFirstChild("ChoicePrompt")
        
        local choicePrompt = local_player.instance.PlayerGui.ChoicePrompt
        local sliderFrame = choicePrompt:FindFirstChild("ChoiceFrame", true):FindFirstChild("DescSheet", true):FindFirstChild("SliderSheet", true)
        
        if sliderFrame then
            local genericSlider = sliderFrame:FindFirstChild("GenericSlider")
            if genericSlider then
                local numberBox = genericSlider:FindFirstChild("Number")
                if numberBox and numberBox:IsA("TextBox") then
                    numberBox.Text = tostring(amount)
                    task.wait(0.2)
                    numberBox:CaptureFocus()
                    task.wait(0.1)
                    numberBox:ReleaseFocus()
                    task.wait(0.2)
                end
            end
            
            local buttons = sliderFrame:FindFirstChild("Buttons")
            if buttons then
                local submitButton = buttons:FindFirstChild("Submit")
                if submitButton then
                    self:click(submitButton)
                    return true
                end
            end
        end
        
        return false
    end,
    
    depositAllNotes = function(self)
        local currentNotes = self:getCurrentNotesAmount()
        if currentNotes == 0 then
            return false
        end
        
        local bankGui = local_player.instance.PlayerGui:FindFirstChild("BankGui")
        if not bankGui then return false end
        
        bankGui:WaitForChild("Choice"):FireServer("notes_deposit")
        task.wait(1)
        
        return self:setBankAmountAndConfirm(currentNotes)
    end,
    
    closeBankGuiFunc = function(self)
        local bankGui = local_player.instance.PlayerGui:FindFirstChild("BankGui")
        if bankGui then
            local closeButton = bankGui:FindFirstChild("Close")
            if closeButton then
                self:click(closeButton)
            end
        end
    end,
    
    openBankAndDeposit = function(self)
        local banker = workspace.NPCs:FindFirstChild("Banker")
        if not banker then 
            return false 
        end
        
        game:GetService("ReplicatedStorage").Requests.InteractPrompt:FireServer(banker.InteractPrompt)
        task.wait(1)
        repeat task.wait(0.1) until local_player.instance.PlayerGui:FindFirstChild("DialogueGui") and local_player.instance.PlayerGui.DialogueGui.Enabled
        self:sendDialogue_choice('Can I access my account?')
        task.wait(1)
        repeat 
            task.wait(0.5) 
        until local_player.instance.PlayerGui:FindFirstChild("BankGui")
        
        task.wait(1)
        
        local success = self:depositAllNotes()
        
        self:closeBankGuiFunc()
        self:sendDialogue_exit()
        
        return success
    end,
    
    placeGuildDoor = function(self)
        local guild_placement_pos = {
            CFrame.new(-996.915771, 998.557617, -7053.39062, 0.20362483, 3.06991864e-20, -0.979048967, -3.81919831e-21, 1, 3.05618033e-20, 0.979048967, -2.48395997e-21, 0.20362483),
            CFrame.new(-376.312347, 1109.97266, -6917.1875, 0.830629528, 3.56421993e-19, 0.556825459, -6.59231309e-19, 1, 3.43294301e-19, -0.556825459, -6.52227105e-19, 0.830629528),
            CFrame.new(237.318726, 1135.56323, -7003.09619, 0.981070876, 2.48859064e-20, 0.193649009, -6.12415687e-21, 1, -9.74839719e-20, -0.193649009, 9.44527492e-20, 0.981070876)
        }
        
        for _, location in pairs(guild_placement_pos) do
            local guild_door_near = false
            
            for _, guild_door in workspace:GetChildren() do
                if guild_door_near then continue end
                if not (guild_door:IsA('Part')) or (guild_door:IsA('Part') and not guild_door.Name:find('Guild')) then continue end
                
                local dist = (location.Position - guild_door.Position).Magnitude
                if dist <= 50 or self:players_near(location, 400) then
                    guild_door_near = true
                    continue
                end
            end
            
            if not guild_door_near then
                self:player_safe_tween(location, 250)
                break
            end
        end
        
        task.wait(1)
        
        local_player.instance.Backpack['Chime of Dwelling'].Parent = local_player.character
        local_player.character['Chime of Dwelling']:Activate()
        
        local closest = nil
        
        repeat
            for _, guild_door in workspace:GetChildren() do
                if not guild_door:IsA('Part') then continue end
                if not guild_door.Name:find('GuildDoor') then continue end
                if not guild_door:FindFirstChild('InteractPrompt') then continue end
                
                local dist = (local_player.root_part.Position - guild_door.Position).Magnitude
                if not (dist <= 5) then continue end
                
                closest = guild_door
                break
            end
            
            task.wait()
        until closest
        
        repeat
            pcall(function(...)  
                fireproximityprompt(closest:FindFirstChild('InteractPrompt'))
            end)
            task.wait(.5)
        until local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):find('Base')
        
        task.wait(1)
    end
}

function notefarm:overworld() 
    local function hasKnowledge()
        local knowledge = local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame.ShrinePoints.Amount.Text
        return tonumber(knowledge) and (tonumber(knowledge) > 0)
    end
    
    local function hasNotes()
        local notes = local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame.Notes.Amount.Text:gsub("%D", "")
        return tonumber(notes) > 0
    end
    
    repeat task.wait() until local_player.character

    if hasKnowledge() then
        local knowledgeNpcCF = CFrame.new(-541.776306, 935.564697, -7180.49707, 0.850063145, 5.35196099e-20, 0.526680827, -2.07649427e-20, 1, -6.81021482e-20, -0.526680827, 4.69546296e-20, 0.850063145)
        
        self:player_safe_tween(knowledgeNpcCF, 250)
        
        local soothsayer = workspace.NPCs:FindFirstChild('Soothsayer')
        
        if not soothsayer then
            repeat
                soothsayer = workspace.NPCs:FindFirstChild('Soothsayer')
                task.wait()
            until soothsayer
        end
        
        repeat
            pcall(function()
                fireproximityprompt(soothsayer:FindFirstChildOfClass('ProximityPrompt'))
            end)
            task.wait(.5)
        until local_player.instance.PlayerGui.DialogueGui.Enabled
        
        task.wait(1)
        
        self:sendDialogue_choice('[Share your Knowledge]')
        task.wait(0.5)
        self:sendDialogue_choice(tonumber(local_player.instance.PlayerGui.CurrencyGui.CurrencyFrame.ShrinePoints.Amount.Text))
        task.wait(0.5)
        self:sendDialogue_exit()
        task.wait(0.5)
    end
    
    if hasNotes() then
        if persistent_data:get('use_guild') then
            self:placeGuildDoor()
            
            local guild_name = local_player.instance:GetAttribute('Guild'):lower():gsub("%s*%[.-%]%s*", " "):gsub("^%d+", ""):gsub("z%w+divider", ""):gsub("[^%a%d]", "")
            local banker = nil
            local treasurer = nil
            
            for _, npc in workspace.NPCs:GetChildren() do
                if banker and treasurer then break end
                
                if not npc:IsA('Model') then continue end
                if not npc:GetAttribute('Guild') then continue end
                if not npc:GetAttribute('Guild'):match(guild_name) then continue end
                
                if npc.Name:match('Banker') then
                    banker = npc
                    continue
                end
                
                if npc.Name:match('Treasurer') then
                    treasurer = npc
                    continue
                end
            end
            
            if banker and not persistent_data:get('max_notes', false) then
                self:tempTween(banker.HumanoidRootPart.CFrame * CFrame.new(5, 0, 0), 170)
                notefarm:openBankAndDeposit()
                task.wait(3.5);
                if hasNotes() then
                    persistent_data:set('max_notes', true)
                end 
            end
            
            if hasNotes() then
                self:tempTween(treasurer.HumanoidRootPart.CFrame * CFrame.new(5, 0, 0), 170)
                
                repeat
                    pcall(function(...)  
                        fireproximityprompt(treasurer:FindFirstChildOfClass('ProximityPrompt'))
                    end)
                    task.wait(.5)
                until local_player.instance.PlayerGui.DialogueGui.Enabled
                
                self:sendDialogue_choice("I'd like to add money to the treasury. [Add to Treasury]")
                task.wait(0.5)
                self:sendDialogue_choice(20000)
                task.wait(0.5)
                self:sendDialogue_exit()
            end
            
            return
        end
        
        if not persistent_data:get('max_notes', false) then
            local banker = CFrame.new(1563.5769, 164.524414, -4312.33643, -0.104543328, 0, -0.994520426, 0, 1, 0, 0.994520426, 0, -0.104543328)
             
            self:player_safe_tween(banker * CFrame.new(0, -5, 0), 170, math.random(10000, 30000))
            
            local closestBanker = nil
            
            repeat
                for _, npc in workspace.NPCs:GetChildren() do
                    if not npc.Name:match('Banker') then continue end
                    
                    if closestBanker == nil then
                        closestBanker = npc
                        continue
                    end
                    
                    if closestBanker then
                        local closestDist = (local_player.root_part.Position - closestBanker.HumanoidRootPart.Position).Magnitude
                        local currentDist = (local_player.root_part.Position - npc.HumanoidRootPart.Position).Magnitude
                        
                        if closestDist > currentDist then
                            closestBanker = npc
                        end
                    end
                end
                
                task.wait()
            until closestBanker
            
            notefarm:openBankAndDeposit()
            task.wait(3.5);
            if hasNotes() then
                persistent_data:set('max_notes', true)
            end 
        end
        
        if persistent_data:get('max_notes', false) then
            self:stop()
        end
    end
end

function notefarm:stop()
    aztup.automation:set('ministry_notefarm', not persistent_data:get('ministry_notefarm', false))
    persistent_data:remove('max_notes')
end

local struct;
struct = automation_struct:construct({
    persistent_data_store = 'ministry_notefarm_store',
    persistent_data_flag = 'ministry_notefarm',
    id = 'ministry_notefarm',
    
    state_machine = StateMachine.create({
        initial = "idle",
        events = {
            {name = 'start', from = 'idle', to = '_check_area'},
            
            {name = 'is_etrean', from ='_check_area', to = '_suicide'}, -- how do i use this
            {name = 'overworld', from = '_check_area', to ='_overworld'},
            {name = 'fragments', from = '_check_area', to ='_handle_fragments'},
            {name = 'depths', from = '_check_area', to = '_die'},
            
            {name = 'cc', from = '_check_area', to = '_create_character'},
            {name = 'continuation', from = '_create_character', to = '_check_area'},
        },
        callbacks = {
            onenter_check_area = function(self)
                pcall(function(...)  
                    local is_fragments = local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):match('Fragments of Self')
                    if is_fragments then
                        self:fragments()
                        return
                    end
                end)
                
                pcall(function(...)  
                    local is_character_creation = workspace:FindFirstChild('CharacterCreator') and local_player.character.Parent == workspace.CharacterCreator
                    if is_character_creation then
                        self:cc()
                        task.wait();
                        return;
                    end
                end)
                
                pcall(function(...)  
                    local is_to1 = local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):match('Trial of One')
                    if is_to1 then
                        self:to1()
                        return
                    end
                end) 
                
                local is_depths = local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):match('The Depths')
                if is_depths then
                    self:depths()
                    return
                end
                
                if is_etrean then
                    if local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):find('Base') then
                        require("@src/features/buttons/respawn")()
                        repeat task.wait() until local_player.instance.PlayerGui:FindFirstChild('SpawnPrompt')
                        local_player.instance.PlayerGui.SpawnPrompt.Choice:FireServer('Inn')
                        repeat task.wait() until local_player.character
                    end
                    
                    self:overworld()
                    return
                end
            end,
            
            onenter_create_character = function(self)
                struct:create_character()
                self:continuation()
            end,
            
            onenter_suicide = function(self)
                require("@src/features/buttons/respawn")()
                
                repeat 
                    task.wait() 
                until local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt')
                
                local_player.instance.PlayerGui.ChoicePrompt.Choice:FireServer('Death')
            end,
            
            onenter_handle_fragments = function(self)
                local function handleFrag()
                    local tpLocation = (workspace.NPCs.Self:GetPivot() - Vector3.new(0,15.7,0)) * CFrame.Angles(math.rad(180), math.rad(90), math.rad(180))
                    
                    if notefarm:playerCheck(200, tpLocation.Position) then
                        notefarm:serverHop()
                        while task.wait() do end
                    end
                    
                    local_player.root_part.CFrame = tpLocation;
                    
                    local slot = local_player.instance:GetAttribute("DataSlot");
                    local chooseSlot = [[
                        if not game:IsLoaded() then game.Loaded:Wait(); end;
                        if game.PlaceId ~= 4111023553 then return; end
                        local slot = "%s";
                        queueonteleport('if game.PlaceId == 4111023553 then return; end; xpcall(function() local sound = Instance.new("Sound", game:GetService("CoreGui")); game:GetService("Debris"):AddItem(sound, 6); sound.Volume = 1.3; sound.SoundId = getcustomasset("Frutiger/assets/notification.mp3"); sound:Play(); end, warn);')
                        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("WipeSlot"):InvokeServer(slot)
                        task.wait(0.5)
                    ]]
                    queue_on_teleport(string.format(chooseSlot, slot or "A"))
                    
                    local get_score = services.ReplicatedStorage:WaitForChild("Requests"):WaitForChild("GetScore");
                    get_score.OnClientEvent:Connect(function(v)
                        get_score:FireServer();
                    end);
                    
                    while task.wait() do
                        local_player.root_part.CFrame = tpLocation;
                        if notefarm:playerCheck(200, tpLocation.Position) then
                            notefarm:serverHop()
                            while task.wait() do end
                        end
                        
                        fireproximityprompt(workspace:WaitForChild("NPCs"):WaitForChild("Self"):WaitForChild("InteractPrompt"))
                        game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({
                            choice = '[The End]',
                        })
                    end;
                end
                
                task.delay(40, function()
                    self:serverHop();
                end);
                
                local frag_handler;
                frag_handler = function()
                    if not workspace.NPCs:FindFirstChild('Self') then
                        require("@src/features/buttons/respawn")()
                        repeat task.wait() until local_player.character and workspace.NPCs:FindFirstChild('Self')
                    end
                    
                    xpcall(handleFrag, function()
                        task.wait(0.1); 
                        frag_handler();
                    end);
                end
                
                frag_handler();
            end,
            
            onenter_die = function(self)
                local slot = local_player.instance:GetAttribute("DataSlot");
                server_utility:obliteration(slot)
            end,
            
            onenter_overworld = function(self)
                notefarm:overworld();
                
                local slot = local_player.instance:GetAttribute("DataSlot");
                server_utility:obliteration(slot)
            end,
        }
    }),
    features = {
        "no_fall",
        "noclip",
        "mod_detector",
        "fly",
        "auto_equip_weapon",
    },
    not_allowed = function()
        return false;
    end,
    character_creator_handler_used = true,
    character_creator_handler_opts = {
        gamemode = "Pathfinder",
        origin = "Etris",
    }
})

return struct

end;

__modules["src/automation/persistent_tasks/soup_echofarm"] = function()
--!nocheck

local automation_struct = require("@src/automation/struct");
-- Optional Arteria ownership; legacy execution keeps its original environment.
local task = task;
local Tween = Tween;
local server_utility = server_utility;
local persistent_data = persistent_data;
local native_queue = queue_on_teleport;
local struct;
local farm_scope;
local function queue_on_teleport(source)
    if farm_scope then return farm_scope:queue(source) end;
    return native_queue(source);
end;
local echofarm = {
    playerCheck = function(mag, custom)
         for _, player in services.Players:GetPlayers() do
            if not player.Character then continue end
            if not player.Character:FindFirstChild('HumanoidRootPart') then continue end
            if player == local_player.instance then continue end

            local hmrp = player.Character.HumanoidRootPart

            local dist = ((custom or local_player.root_part.Position) - hmrp.Position).Magnitude

            if (dist <= mag) then
                return true
            end
        end

        return false
    end,
    
    serverHop = function(expiry)
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, true, false, expiry)
    end,

    player_safe_tween = function(self, cf, speed)
        -- Check for players
        if self.playerCheck(300) then
            -- Serverhop to small server, will kick for now
            self.serverHop()
            while task.wait() do end
        end

        --local ylevel = math.random(400, 600)
        local ylevel = -20


        -- Tween up
        local_player.root_part.CFrame = CFrame.new(local_player.root_part.CFrame.X, 0, local_player.root_part.CFrame.Z);
        --self.tempTween(local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0), speed)

        -- Tween to target location
        self.tempTween(CFrame.new(cf.X, 0, cf.Z), speed)

        -- Check for players
        if self.playerCheck(300, cf.Position) then
            -- Serverhop to small server, will kick for now
            self.serverHop()
            while task.wait() do end
        end

        -- Tween down
        local_player.root_part.CFrame = cf
        --self.tempTween(cf, speed)
    end,

    tempTween = function(cf, speed)
        Tween.new(cf, true, speed).wait();
        --local distance = (Vector3.new(cf.X, 0, cf.Z) - Vector3.new(local_player.root_part.Position.X, 0, local_player.root_part.Position.Z)).Magnitude
        --local tween = services.TweenService:Create(local_player.root_part, TweenInfo.new(distance / (speed or 150), Enum.EasingStyle.Linear,Enum.EasingDirection.InOut), {
        --    CFrame = CFrame.new(cf.Position),
        --})
--
        --tween:Play();
        --tween.Completed:Wait();
    end,
}

function echofarm:craft_soup()
    local finished = false

    local function has_pair_or_soup()
        if local_player.instance:FindFirstChild("Backpack"):FindFirstChild("Mushroom Soup") then return true end

        local hasGobletto  = local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil
        local hasDentifilo = local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil
        local hasBrowncap  = local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil

        local count = (hasGobletto and 1 or 0)
                    + (hasDentifilo and 1 or 0)
                    + (hasBrowncap and 1 or 0)
        return count >= 2
    end

    task.spawn(function()
        task.wait(45)
        -- Safety valve for getting stuck, but never wipe before the pair is actually secured
        while not finished and not has_pair_or_soup() do
            task.wait(1)
        end

        if finished then return end

        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:obliteration(slot)
    end);
    local i = 0;
    local function collect_ingredient(ing)
        self.player_safe_tween(self, ing.CFrame, i == 0 and 250 or 280)
        i += 1;
        local cf = ing.CFrame;

        repeat
            Tween.new(cf, true).wait();

            pcall(function(...)  
                fireproximityprompt(ing:FindFirstChildOfClass('ProximityPrompt'))
            end)
            task.wait()
        until ing.Parent == nil
    end

    local function get_closest_ing(ing)
        local closest = nil

        for _, ingredient in workspace:FindFirstChild('Ingredients'):GetChildren() do
            if ingredient.Name:match(ing) then
                if closest == nil then closest = ingredient; continue; end
                if closest then
                    local closestDist = (local_player.root_part.Position - closest.Position).Magnitude
                    local ingredientDist = (local_player.root_part.Position - ingredient.Position).Magnitude
                    if ingredientDist > 1000 then continue; end
                    if ingredientDist < closestDist then closest = ingredient; continue; end
                end
            end
        end

        return closest
    end

    -- Collect Ingredients
    local function get_ing_pos(name)
        local ing = get_closest_ing(name)
        if ing then
            return ing.Position
        end
        return nil
    end

    local function estimate_pair_cost(a, b)
        local posA = get_ing_pos(a)
        local posB = get_ing_pos(b)
        if not posA or not posB then
            return math.huge
        end

        --local closest_campfire = get_closest_campfire(posB);
        --local closest_campfire_magnitude = closest_campfire and (closest_campfire.Position - posB).Magnitude or 0
        return (local_player.root_part.Position - posA).Magnitude
             + (posA - posB).Magnitude-- + closest_campfire_magnitude
    end
    local hasGobletto  = local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil
    local hasDentifilo = local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil
    local hasBrowncap  = local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil

    local count = (hasGobletto and 1 or 0)
                + (hasDentifilo and 1 or 0)
                + (hasBrowncap and 1 or 0)
    if not local_player.instance.Backpack:FindFirstChild("Mushroom Soup", true) and count < 2 then
        local bestPair, bestCost

        local function consider_pair(a, b)
            -- Need at least one missing in the pair, otherwise itrs pointless
            local hasA = local_player.instance.Backpack:FindFirstChild(a) ~= nil
            local hasB = local_player.instance.Backpack:FindFirstChild(b) ~= nil
            if hasA and hasB then return end

            local c = estimate_pair_cost(a, b)
            if c == math.huge then return end
            if not bestCost or c < bestCost then
                bestCost = c
                bestPair = {a, b}
            end
        end

        repeat 
            task.wait() 
            consider_pair("Dentifilo", "Gobletto")
            consider_pair("Browncap", "Gobletto")
            consider_pair("Browncap", "Dentifilo")
        until bestPair and #bestPair == 2;

        if bestPair then
            local runs = 0;
            
            local function update_count()
                hasGobletto  = local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil
                hasDentifilo = local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil
                hasBrowncap  = local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil

                count = (hasGobletto and 1 or 0)
                    + (hasDentifilo and 1 or 0)
                    + (hasBrowncap and 1 or 0)
            end

            while count < 2 do
                if not local_player.instance.Backpack:FindFirstChild(bestPair[1]) then
                    local firstIng = get_closest_ing(bestPair[1])
                    if firstIng then
                        collect_ingredient(firstIng)
                    end
                end

                update_count()

                if count >= 2 then
                    break;
                end

                if not local_player.instance.Backpack:FindFirstChild(bestPair[2]) then
                    local secondIng = get_closest_ing(bestPair[2])
                    if secondIng then
                        collect_ingredient(secondIng)
                    end
                end


                update_count()

                if count >= 2 then
                    break;
                end
                task.wait(0.1);
                runs += 1;
            end;
        end
    end

    -- Craft Soup
    --craft()
    finished = true
end
local struct;
local state_machine = StateMachine.create({
    initial = "idle",
    events = {
        {name = 'start', from = 'idle', to = '_check_area'},
        {name = 'continuation', from = '_create_character', to = '_check_area'},

        {name = 'fragments', from = '_check_area', to = '_handle_fragments'},
        {name = 'soup', from = '_check_area', to = '_craft_soup'},
        {name = 'die', from = '_check_area', to = '_die'},
        {name = 'die', from = '_craft_soup', to = '_die'},

        {name = 'cc', from = '_check_area', to = '_create_character'},
    },
    callbacks = {
        onenter_check_area = function(self)
            local is_character_creation = workspace:FindFirstChild('CharacterCreator') and local_player.character.Parent == workspace.CharacterCreator
            task.delay(60, function() --if not done by 60 seconds, serverhop to avoid potential issues
                echofarm.serverHop();
            end)
            if is_character_creation then
                self:cc()
                repeat 
                    task.wait() 
                    is_character_creation = workspace:FindFirstChild('CharacterCreator') and local_player.character.Parent == workspace.CharacterCreator
                until not is_character_creation;
                return;
            end

            if is_eastern then
                -- Hop
                self:die()
                return
            end

            if is_etrean then
                if local_player.instance:GetAttribute('CurrentArea') and local_player.instance:GetAttribute('CurrentArea'):find('Base') then
                    require("@src/features/buttons/respawn")()
                    repeat task.wait() until local_player.instance.PlayerGui:FindFirstChild('SpawnPrompt')
                    local_player.instance.PlayerGui.SpawnPrompt.Choice:FireServer('Inn')
                    repeat task.wait() until local_player.character
                end

                self:soup()
                return
            end
            
            repeat task.wait() until local_player.instance:GetAttribute('CurrentArea');
            local is_fragments = local_player.instance:GetAttribute('CurrentArea'):match('Fragments of Self')
            if is_fragments then
                self:fragments()
                return
            end
        end,

        onenter_create_character = function(self)
            struct:create_character()
            self:continuation()
        end,

        onenter_die = function(self)
            local slot = local_player.instance:GetAttribute("DataSlot");
            server_utility:obliteration(slot)
        end,

        onenter_craft_soup = function(self)
            local hasGobletto  = local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil
            local hasDentifilo = local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil
            local hasBrowncap  = local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil

            local count = (hasGobletto and 1 or 0)
                        + (hasDentifilo and 1 or 0)
                        + (hasBrowncap and 1 or 0)

            while count < 2 do
                echofarm:craft_soup()
                hasGobletto  = local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil
                hasDentifilo = local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil
                hasBrowncap  = local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil
                count = (hasGobletto and 1 or 0)
                    + (hasDentifilo and 1 or 0)
                    + (hasBrowncap and 1 or 0);
                task.wait()
            end;
            --server_utility:rejoin(local_player.instance:GetAttribute("DataSlot"));
            self:die()
        end,

        onenter_handle_fragments = function(self)
            
            local function handleFrag()
                local tpLocation = (workspace.NPCs.Self:GetPivot() - Vector3.new(0,15.7,0)) * CFrame.Angles(math.rad(-45), 0, 0)

                local function get_closest_campfire(pos)
                    local closest = nil 
                
                    for _, campfire in workspace.Thrown:GetChildren() do
                        if not campfire.Name:match('Campfire') then continue end
                        if not campfire:IsA('Model') then continue end
                    
                        local campfirePart = campfire:FindFirstChildOfClass('Part')
                    
                        if closest == nil then
                            closest = campfirePart
                            continue
                        end
                    
                        if closest then
                            local closestDist = ((pos or local_player.root_part.Position) - closest.Position).Magnitude
                            local campfireDist = ((pos or local_player.root_part.Position) - campfirePart.Position).Magnitude
                        
                            if closestDist > campfireDist then
                                closest = campfirePart
                            end
                        end
                    end
                
                    return closest
                end
            
                local function craft()
                    -- Tween to campfire
                    local campfire = get_closest_campfire()
                    repeat task.wait(); campfire = get_closest_campfire(); until campfire;
                    print("got campfire");
                    campfire = campfire.CFrame
                    echofarm:player_safe_tween(campfire, 2800);
                    task.wait();
                
                    local replicatedStorage = game:GetService("ReplicatedStorage")
                    local requests = replicatedStorage:WaitForChild("Requests")
                    local craftRemote = requests:WaitForChild("Craft") :: RemoteFunction

                    local start = tick();
                    repeat 
                        local hasGobletto  = local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil
                        local hasDentifilo = local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil
                        local hasBrowncap  = local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil

                        if echofarm.playerCheck(130, tpLocation.Position) or echofarm.playerCheck(130, local_player.root_part.Position) then
                            -- Serverhop to small server, will kick for now
                            echofarm.serverHop(300)
                            while task.wait() do end
                        end
                        task.wait()
                        if local_player.instance:FindFirstChild("Backpack") and local_player.instance:FindFirstChild("Backpack"):FindFirstChild("Mushroom Soup", true) then break; end
                        Tween.new(campfire, true, 2000).wait();
                        task.spawn(pcall, function()
                            craftRemote:InvokeServer({
                                Gobletto  = hasGobletto,
                                Dentifilo = hasDentifilo,
                                Browncap  = hasBrowncap,
                            })    
                        end);
                    
                        task.wait();
                    until tick() - start > 10 or local_player.instance:FindFirstChild("Backpack") and local_player.instance:FindFirstChild("Backpack"):FindFirstChild("Mushroom Soup", true);
                end
            
                if not local_player.instance:FindFirstChild("Backpack"):FindFirstChild("Mushroom Soup") and (
                    local_player.instance.Backpack:FindFirstChild("Gobletto") ~= nil or
                    local_player.instance.Backpack:FindFirstChild("Dentifilo") ~= nil or
                    local_player.instance.Backpack:FindFirstChild("Browncap") ~= nil
                ) then
                    craft();
                end;

                if echofarm.playerCheck(230, tpLocation.Position) or echofarm.playerCheck(230, local_player.root_part.Position) then
                    -- Serverhop to small server, will kick for now
                    echofarm.serverHop(300)
                    while task.wait() do end
                end

                local_player.root_part.CFrame = tpLocation;

                local slot = local_player.instance:GetAttribute("DataSlot");
                local chooseSlot = [[
                    if not game:IsLoaded() then
                        game.Loaded:Wait();
                    end;
                    if game.PlaceId ~= 4111023553 then return; end
                    local server = '%s';
                    local slot = "%s";

                    queueonteleport('if game.PlaceId == 4111023553 then return; end; xpcall(function() local sound = Instance.new("Sound", game:GetService("CoreGui")); game:GetService("Debris"):AddItem(sound, 6); sound.Volume = 1.3; sound.SoundId = getcustomasset("Frutiger/assets/notification.mp3"); sound:Play(); end, warn);')

                    local args = {
                        slot
                    }
                    game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("WipeSlot"):InvokeServer(unpack(args))

                    task.wait(0.5)
                ]]
                queue_on_teleport(string.format(chooseSlot, game.JobId, slot or "A"))

                local get_score = services.ReplicatedStorage:WaitForChild("Requests"):WaitForChild("GetScore");
                local score_scope = farm_scope;
                local score_recorded = false;
                local score_connection = get_score.OnClientEvent:Connect(function(v)
                    if score_scope and not score_scope.active then return end;
                    if score_scope and score_recorded then return end;
                    if score_scope then score_recorded = true end;
                    local last_wiped_at = persistent_data:get("wiped_at", nil);
                    local wiped_at = tick();
                    persistent_data:set("echoes_gained", persistent_data:get("echoes_gained", 0) + (v and typeof(v) == "table" and v.Echoes or 0))
                    persistent_data:set("cycle_count", persistent_data:get("cycle_count", 0) + 1)
                    persistent_data:set("wiped_at", wiped_at);
                    task.spawn(pcall, function()

                        if last_wiped_at then
                            task.spawn(xpcall, function()
                                local webhook = persistent_data:get("automation_webhook", nil);

                                if webhook then
                                    
                                    request({
                                        Url = webhook,
                                        Method = "POST",
                                        Headers = {
                                            ["Content-Type"] = "application/json"
                                        },
                                        Body = game:GetService("HttpService"):JSONEncode({
                                            content = " ",
                                            embeds = {
                                                {
                                                    title = "Echo Farm",
                                                    description = string.format("Finished cycle in %.2fs, Gained %i echoes.", wiped_at - last_wiped_at, math.floor(v.Echoes or 0)),
                                                    color = 6724044,
                                                    author = {
                                                        name = ".gg/frutiger",
                                                        icon_url = "https://cdn.discordapp.com/attachments/1211502078200127529/1464075011550613588/PRLOGO.png"
                                                    }
                                                }
                                            },
                                            username = "Frutiger",
                                            avatar_url = "https://cdn.discordapp.com/attachments/1211502078200127529/1464075011550613588/PRLOGO.png",
                                            attachments = {},
                                            flags = 4096
                                        })
                                    })
                                    
                                end;
                            end, warn);
                        end;
                    end);
                    get_score:FireServer();
                end);
                if farm_scope then farm_scope:track(score_connection) end;

                pcall(function()
                    for _, anim in game:GetService("ReplicatedStorage").Assets.Anims.Mobs.Monky:GetChildren() do
                        local a: AnimationTrack = local_player.humanoid:LoadAnimation(anim);
                        a:Play(0,1,0)
                    end;
                end);

                while task.wait() do
                    local_player.root_part.CFrame = tpLocation;
                    if echofarm.playerCheck(100, tpLocation.Position) then
                        -- Serverhop to small server, will kick for now
                        echofarm.serverHop(300)
                        while task.wait() do end
                    end

                    fireproximityprompt(workspace:WaitForChild("NPCs"):WaitForChild("Self"):WaitForChild("InteractPrompt"))
                    game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("SendDialogue"):FireServer({
                        choice = '[The End]',
                    })
                end;
            end

            xpcall(function(...)  
                handleFrag()
            end, 
            function(...)  
                if not workspace.NPCs:FindFirstChild('Self') then
                    require("@src/features/buttons/respawn")()

                    repeat task.wait() until local_player.character
                    repeat task.wait() until workspace.NPCs:FindFirstChild('Self')
                end

                warn(...);
                handleFrag()
            end)
        end
    }
});
