			end

			return false
		end,

		rings = function(loot)
			local stat_loot_rings = aztup_options.stat_loot_dropdown.Value['Rings']
			local stat_loot_rings_precise = aztup_options.precise_stat_loot.Value['Rings']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_rings_health},
				{"ETH", aztup.flags.stat_loot_rings_ether},
				{"SAN", aztup.flags.stat_loot_rings_sanity},
				{"Posture", aztup.flags.stat_loot_rings_posture},
				{"Monster Dmg", aztup.flags.stat_loot_rings_monsterdamage}
			}

			if stat_loot_rings and image_rect_offset == self.icon_offsets.rings or image_rect_offset == self.icon_offsets.treasure or loot.Name:lower():find("ring") or loot.Name:lower():find("band") and not loot.Name:lower():find('bandana') then
				if stat_loot_rings_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		arms = function(loot)
			local stat_loot_arms = aztup_options.stat_loot_dropdown.Value['Arms']
			local stat_loot_arms_precise = aztup_options.precise_stat_loot.Value['Arms']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_arms_health},
				{"ETH", aztup.flags.stat_loot_arms_ether},
				{"Monster Dmg", aztup.flags.stat_loot_arms_monsterdamage},
				{"Physical Armor", aztup.flags.stat_loot_arms_physicalarmour},
				{"Elemental Armor", aztup.flags.stat_loot_arms_elementalarmour},
				{"Monster Armor", aztup.flags.stat_loot_arms_monsterarmour}
			}

			if stat_loot_arms and image_rect_offset == self.icon_offsets.arms then
				if stat_loot_arms_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end,

		legs = function(loot)
			local stat_loot_legs = aztup_options.stat_loot_dropdown.Value['Legs']
			local stat_loot_legs_precise = aztup_options.precise_stat_loot.Value['Legs']
			local stats_to_check = {
				{"HP", aztup.flags.stat_loot_arms_health},
				{"ETH", aztup.flags.stat_loot_arms_ether},
				{"Monster DMG", aztup.flags.stat_loot_arms_monsterdamage}
			}

			if stat_loot_legs and image_rect_offset == self.icon_offsets.legs then
				if stat_loot_legs_precise then
					if precise_stats(stats_to_check, stats_text) then return true end
				else
					if stats(stats_to_check, stats_text) then return true end
				end
			end

			return false
		end
    }

    for item_type, func in pairs(item_types) do
        if aztup_options.loot_options.Value['Stat Loot'] and func(loot) then
            self.info_loot(remote, loot)
            return true
        end
    end

    return false
end

function auto_loot:always_loot(remote, loot)
    local color = loot.BackgroundColor3

    local function loot_relics(loot)
        local option_selected = aztup_options.always_loot_dropdown.Value['Relics']
        local is_relic_rarity = self.identify_color(self, color:ToHex(), 1):lower() == 'relic'
        return option_selected and is_relic_rarity
    end

    local function loot_enchant_stones(loot)
        local function found_enchant(loot)
            for _, name in pairs(auto_loot.enchants) do
                if loot.Name:find(name) then
                    return true
                end
            end

            return false
        end

        local option_selected = aztup_options.always_loot_dropdown.Value['Enchant Stones']
        local is_legendary_rarity = self.identify_color(self, color:ToHex(), 1):lower() == 'legendary'

        return option_selected and is_legendary_rarity and found_enchant(loot)
    end

    local function loot_legendary_weapons(loot)
        local option_selected = aztup_options.always_loot_dropdown.Value['Legendary Weapons']
		local is_weapon = loot:FindFirstChild('Icon') and loot:FindFirstChild("Icon").ImageRectOffset.X == auto_loot.icon_offsets.weapons
		local is_legendary_rarity = self.identify_color(self, color:ToHex(), 1):lower() == "legendary"
		return option_selected and is_weapon and is_legendary_rarity and not self.is_overweight()
    end

    local function loot_deep_gems(loot)
        local function is_gem(loot)
            if loot:FindFirstChild('Title') then
                local name = loot.Title.Text
                if name:lower():match('gem') and not name:lower():match('vibrant gem') then
                    return true
                end
            end

            return false
        end

        local option_selected = aztup_options.always_loot_dropdown.Value['Deep Gems']
        local is_mythic_rarity = self.identify_color(self, color:ToHex(), 1):lower() == 'mythic'

        return option_selected and is_mythic_rarity and not self.is_overweight() and is_gem(loot)
    end

    if aztup_options.loot_options.Value['Always Loot Items'] and (loot_relics(loot) or loot_enchant_stones(loot) or loot_legendary_weapons(loot) or loot_deep_gems(loot)) then
        self.info_loot(remote, loot)
        return true
    end

    return false
end

function auto_loot:main()
    local choice_prompt = local_player.instance.PlayerGui:FindFirstChild('ChoicePrompt')
    local choice_frame = choice_prompt and choice_prompt:FindFirstChild('ChoiceFrame')
    local options = choice_frame and choice_frame:FindFirstChild('Options')
    local remote = choice_prompt and choice_prompt:FindFirstChild('Choice')

    if not choice_prompt then return end
    if not choice_frame then return end
    if not self.is_loot_container(choice_prompt) then return end

    if not self.chest_check(options) then
        local count = 0

        for _, loot_object in options:GetChildren() do
            if not loot_object:IsA('TextButton') then continue end
            if not loot_object.AutoButtonColor then count += 1; continue end

            if not aztup.flags.auto_loot then break end

            if self:always_loot(remote, loot_object) then count += 1; continue end
            if self.is_overweight() then continue end

            if self:item_loot(remote, loot_object) then count += 1; continue end
            if self:stat_loot(remote, loot_object) then count += 1; continue end
            if self:loot_all(remote, loot_object) then count += 1; continue end
        end

        if not (count == 0) then return end
    else
        self.fire_loot_all(remote)
    end
end

local last_time = 0;
return Feature:new("auto_loot", services.RunService.RenderStepped, function() 
    if tick() - last_time < 1 / 10 then return end
    last_time = tick()
    pcall(function(...)  
        auto_loot:main()
    end)
end)

end;

__modules["src/features/auto-parry/auto-parry"] = function()
local DefendActionManager = require("@src/features/auto-parry/defend-action-manager")
getgenv().DefendActionManager = DefendActionManager
getgenv().Latency = require("@src/utility/latency")

local function checkRange(obj, rangeCheck)
	if not (obj and obj.Position and local_player and local_player.root_part) then
		return false, math.huge
	end
	local distance = (obj.Position - local_player.root_part.Position).Magnitude
	return distance <= rangeCheck, distance
end

local function checkRangeFromPing(obj, rangeCheck, speed)
	if not (obj and obj.Position and local_player and local_player.root_part) then
		return false, math.huge, 0
	end
	local distance = (obj.Position - local_player.root_part.Position).Magnitude
	local ping = (Latency and Latency.get_ping and Latency:get_ping()) or 0
	distance -= (speed or 0) * (ping * 2)
	return distance <= rangeCheck, distance, (speed and speed ~= 0) and (ping / speed) or 0
end

local last_parry_at = tick()

-- Wall-clock ceiling for the pending-wait loops below. Every one of them waits
-- for a projectile to close in or despawn; they yield each pass, so they cannot
-- freeze the client, but a projectile that never despawns and never reaches the
-- player leaves the loop alive forever. One thread per such projectile adds up,
-- so a pass that outlives this is abandoned. Far longer than any real flight.
local PENDING_TIMEOUT = 15;

local thrown = workspace:FindFirstChild("Thrown") or workspace:WaitForChild("Thrown", 10)
if thrown then
	aztup.maid:give_task(thrown.ChildAdded:Connect(LPH_NO_VIRTUALIZE(function(part)
		if not (aztup and aztup.flags and aztup.flags.auto_parry) then
			return
		end
		if not (part and part.Parent and local_player and local_player.root_part) then
			return
		end

		local live = workspace:FindFirstChild("Live")
		if not live then
			return
		end

		if part.Name == "ArdourBall2" then
			local nomad
			for _, child in live:GetChildren() do
				if child.Name:match("nomad") then
					nomad = child
					break
				end
			end

			if not nomad then
				return
			end
			local cond = false
			local __pending_t1 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t1 then return end
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if
					math.abs(pos_delta.X) < 15
					and math.abs(pos_delta.Y) < 15
					and math.abs(pos_delta.Z) < 15
					and tick() - last_parry_at >= 0.1
				then
					cond = true
				elseif not part.Parent then
					cond = true
					return
				end
			until cond
			if not part.Parent then
				return
			end

			general:generic_parry_ap_task(nomad)
		elseif part.Name == "SlotBall" then
			local __pending_t2 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t2 then return end
				task.wait()
			until not part.Parent or (part.Position - local_player.root_part.Position).Magnitude < 20
			if not part.Parent then
				return
			end

			local current_angel
			for _, angel in live:GetChildren() do
				if angel.Name:match(".angel") then
					current_angel = angel
					break
				end
			end

			general:generic_parry_ap_task(current_angel)
		elseif part.Name == "BoneSpear" then
			local has_bonekeeper, bk
			for _, child in live:GetChildren() do
				if child.Name:match("boneboy") then
					has_bonekeeper = true
					bk = child
					break
				end
			end

			if has_bonekeeper then
				task.wait(2.15)
			end

			local __pending_t3 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t3 then return end
				task.wait()
			until not part.Parent
				or (part.Position - local_player.root_part.Position).Magnitude
					< (workspace:FindFirstChild("Layer2Floor1") and 30 or 75)
			if not part.Parent then
				return
			end

			if not workspace:FindFirstChild("Layer2Floor1") then
				local w = 0.2 - ((Latency and Latency.get_ping and Latency:get_ping()) or 0)
				if w > 0 then
					task.wait(w)
				end
			end

			general:generic_parry_ap_task(bk or workspace.Live:GetChildren()[2])
		elseif part.Name == "Flamewalker" and aztup.flags.no_rosen_fire then
			part.CanTouch = false

			local touch = part:WaitForChild("TouchInterest", 3.5)
			if touch then
				services.Debris:AddItem(touch, 0)
			end
		elseif part.Name == "Cyclone" then
			local backpack = local_player.instance:FindFirstChild("Backpack")
			if not backpack then
				return
			end
			if backpack:FindFirstChild("Mantra:EruptionBlood{{Scarlet Cyclone}}") then
				return
			end

			local user
			for _, player in services.Players:GetPlayers() do
				if
					player:FindFirstChild("Backpack")
					and player.Backpack:FindFirstChild("Mantra:EruptionBlood{{Scarlet Cyclone}}", true)
				then
					user = player.Character
					break
				end
			end

			if not user then
				return
			end

			local __pending_t4 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t4 then return end
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if math.abs(pos_delta.X) < 12 and math.abs(pos_delta.Y) < 15 and math.abs(pos_delta.Z) < 12 then
					general:generic_parry_ap_task(user)
					break
				end
			until not part.Parent
		elseif part.Name:find("AraneaProjectile") or part.Name:find("SuperArrow") then
			local allowed_targets = aztup_options.allowed_targets.Value
			if not allowed_targets.PVP and not allowed_targets.All then
				return
			end

			local name = part.Name:split("_")[2]
			if not name then
				return
			end
			local user = services.Players:FindFirstChild(name)
			if not user then
				return
			end
			if user == local_player.instance then
				return
			end

			local __pending_t5 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t5 then return end
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if math.abs(pos_delta.X) < 12 and math.abs(pos_delta.Y) < 15 and math.abs(pos_delta.Z) < 12 then
					general:generic_parry_ap_task(user.Character)
					break
				end
			until not part.Parent
		elseif part.Name:find("ShadeArrow") then
			local allowed_targets = aztup_options.allowed_targets.Value
			if not allowed_targets.PVP and not allowed_targets.All then
				return
			end

			local name = part.Name:split("_")[2]
			if not name then
				return
			end
			local user = services.Players:FindFirstChild(name)
			if not user then
				return
			end
			if user == local_player.instance then
				return
			end

			local __pending_t6 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t6 then return end
				task.wait()
				local pos_delta = (part.Position - local_player.root_part.Position)

				if math.abs(pos_delta.X) < 15 and math.abs(pos_delta.Y) < 16 and math.abs(pos_delta.Z) < 15 then
					general:generic_parry_ap_task(user.Character)
					break
				end
			until not part.Parent
		elseif part.Name == "Bullet" and not checkRange(part, 10) then
			local closest_player
			local closest_distance = math.huge
			for _, char in workspace:WaitForChild("Live"):GetChildren() do
				if char and char:FindFirstChild("HumanoidRootPart") then
					local distance = (part.Position - char.HumanoidRootPart.Position).Magnitude
					if distance < closest_distance then
						closest_distance = distance
						closest_player = char
					end
				end
			end

			if closest_distance > 120 then
				return
			end

			local __pending_t7 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t7 then return end
				task.wait()
			until (checkRangeFromPing(part, 20, 20)) or not part.Parent
			if not part.Parent then
				return
			end

			if closest_player and closest_player ~= local_player.character then
				general:generic_parry_ap_task(closest_player)
			end
		elseif part.Name == "SeekerOrb" then
			local closest_player
			local closest_distance = math.huge
			for _, char in workspace:WaitForChild("Live"):GetChildren() do
				if char and char:FindFirstChild("HumanoidRootPart") then
					local distance = (part.Position - char.HumanoidRootPart.Position).Magnitude
					if distance < closest_distance then
						closest_distance = distance
						closest_player = char
					end
				end
			end

			if closest_distance > 150 then
				return
			end

			local __pending_t8 = tick() + PENDING_TIMEOUT;
			repeat
				if tick() > __pending_t8 then return end
				task.wait()
			until (checkRange(part, 2)) or not part.Parent
			if not part.Parent then
				return
			end

			
			local rocketPropulsion = part:WaitForChild('RocketPropulsion', 10)
			if (not rocketPropulsion or rocketPropulsion.Target ~= local_player.root_part) then return end			
			task.wait(0.3 - Latency:get_ping());

			if closest_player and closest_player ~= local_player.character then
				general:generic_parry_ap_task(closest_player)
			end
		end
	end)))
end

local last_telegraph_attach = tick()

function run_af()
	if not aztup.flags.auto_feint then
        return    
end;

    if not EffectReplicator:FindEffect("LightAttack") and not EffectReplicator:FindEffect("MidAttack") then
        return    
end;

    if EffectReplicator:FindEffect("FeintCool") then
