    ids = { "85523657178401" },
    default_chance = 100,
    allow_block_input = true,
    allow_parry_to_roll = true,
    ignore_early_end = false,

    run = function(action)
        local distance = self:distance() or 0
        local speed = speed_of(track)
        local when

        if speed >= 0.7 then
            when = 0.15
        else
            when = 0.18
        end

        if distance >= 10 then
            when = when + 0.03
        end

        if distance >= 20 then
            when = when + 0.04
        end

        if distance >= 40 then
            when = when + 0.45
        end

        when = math.clamp(when, 0.15, 0.80)

        action.when = when
        action.type = "Parry"
        action.hitbox = Vector3.new(20, 40, 40)
        action.offset = CFrame.new(0, 0, -20)
        action.name = string.format("(speed:%.2f dist:%.2f when:%.3f) Light Mayhem Silentheart", speed, distance, when)

        action:push()
        return action
    end
}
 end)();
