__modules["src/features/auto-parry/handlers/animator-handler"] = function()
local profiler = require("@src/utility/profiler")
local anti_ap_breaker = require("@src/features/auto-parry/handlers/anti-ap-breaker")
local trace = require("@src/utility/trace")

-- Contatori al secondo.
--
-- Il cronometro ha escluso in_hitbox: nessuna delle sue quattro parti supera
-- 2ms. Se il lag e' generale, allora non e' una funzione lenta ma una funzione
-- chiamata troppe volte -- e quello un cronometro non lo vede. Questi contatori
-- dicono quante volte al secondo passa ciascun percorso.
local n_run, n_hb, n_desc, n_anim = 0, 0, 0, 0;

local rate_thread = task.spawn(function()
    local last = tick();
    while true do
        task.wait(1);
        local now = tick();
        if now - last >= 0.9 then
            trace.write("RATE", "run=%d in_hitbox=%d descendant=%d anim_played=%d",
                n_run, n_hb, n_desc, n_anim);
            n_run, n_hb, n_desc, n_anim = 0, 0, 0, 0;
            last = now;
        end;
    end;
end);
-- Arteria unloads/reinjects without leaving the diagnostic loop behind.
aztup.maid:give_task(function() pcall(task.cancel, rate_thread) end);

-- Divisione sicura per track.Speed (vedi base.lua).
-- track.Speed puo' essere 0, e x/0 da' infinito: quel valore si propaga fino a
-- "wait time invalid: inf" e l'auto-parry salta l'azione.
local function speed_of(track)
    local s = track and track.Speed;
    if type(s) ~= "number" or s ~= s or s < 1e-6 then
        return 1;
    end;
    return s;
end;



local random = Random.new();
local cached = {};

-- Last time the "wait time invalid" line was printed. Declared here so it
-- survives across calls to the action loop -- inside the loop it would reset
-- every iteration and never rate limit anything.
local skip_notified_at = 0;
function getInfo(id)
    local success, info = pcall(function()
        if not cached[id] then
            cached[id] = game:GetService("MarketplaceService"):GetProductInfo(id);
        end
        return cached[id]
    end)
    if success then
        return info
    end
    return {Name=''}
end

local encrypted_timing_data = require("@src/features/auto-parry/data/encrypted_timing_data");
local custom_timings = require("@src/features/auto-parry/data/custom_timings");
local ap_breaker_tracks = setmetatable({}, { __mode = "k" });

break_anims = function(track, time, data, action_type, self)
    if not data then return end
    if track:HasTag("FRUTIGER_BREAKER_IGNORE") then return end

    if aztup.flags.ap_breaker and aztup_options.ap_breaker_type.Value == "Tester Aggressive 1 (Blatant)" and not track.Looped and speed_of(track) > 0.1 then
        while track.IsPlaying do
            
            
            
            
            
            

            track:AdjustWeight(0, 50);
            
            task.wait();
        end;
    end;

    if aztup.flags.ap_breaker and aztup_options.ap_breaker_type.Value == "Aggressive 3 (Blatant)" and not track.Looped and speed_of(track) > 0.1 then
        ap_breaker_tracks[track] = true;
        track.Priority = Enum.AnimationPriority.Movement;
        
        
        track:Stop(9e9);
        task.wait((track.Length / speed_of(track)) - Latency:half_ping());
        track.TimePosition = track.Length;
        track:Play(0.1,0,0)
        track:AdjustWeight(0, 0.1);
        ap_breaker_tracks[track] = nil;
    end;
end;

process = function(timing_data)
    for index, item in encrypted_timing_data.keys do
        if timing_data[item] or not timing_data[index] then continue end
        timing_data[item] = timing_data[index];
        timing_data[index] = nil;
    end

    timing_data.actions = table.clone(timing_data.actions);
    for timing_number, action in timing_data.actions do
        if not action then continue end
        
        action = table.clone(action);
        for index, item in encrypted_timing_data.action_keys do
            if action[item] or not action[index] then continue end
            action[item] = action[index];
            action[index] = nil;
        end

        if action.when then
            action.when = action.when - encrypted_timing_data.key;
        end

        timing_data.actions[timing_number] = action;
    end

    timing_data.enc = false;
    return timing_data 
end

local track_still_active

track_still_active = LPH_JIT_MAX(function(track: AnimationTrack, entity)
    if ap_breaker_tracks[track] then
        return true    
end;

    return track.IsPlaying or anti_ap_breaker:is_fully_dead(track, entity) == false
end)

