__modules["src/features/automation/auto_equip_weapon"] = function()
local feature = Feature:new("auto_equip_weapon");

local function is_using_utility_tool()
    local character = local_player.character;
    if not character then return false end;

    return character:FindFirstChildOfClass("Tool") ~= nil
end

local function draw_weapon()
    if is_using_utility_tool() then return end;

    local character = local_player.character;
    local character_handler = character and character:FindFirstChild("CharacterHandler");
    local requests = character_handler and character_handler:FindFirstChild("Requests");
    local draw_weapon_remote = requests and requests:FindFirstChild("DrawWeapon");

    if draw_weapon_remote then
        draw_weapon_remote:FireServer(true);
    end
end

function feature:enable()
	self.removed_hook = EffectReplicatorHandler:hook("removed", function(effect)
		if effect.Class ~= "Equipped" then return end;

        task.delay(0.1, function()
            if EffectReplicator:FindEffect("Equipped") then return end;
            draw_weapon();
        end);
	end);

    self.running = true;
    task.spawn(function()
        while self.running do
            if not EffectReplicator:FindEffect("Equipped") then
                draw_weapon();
            end;

            task.wait(1);
        end;
    end);
end;

function feature:disable()
	if self.removed_hook then
		self.removed_hook:remove();
	end;

    self.running = false;
end;

return feature

end;

__modules["src/features/automation/auto_fish"] = function()

local feature = Feature:new("auto_fish");
local dontrun = false
local lastSend
local maid = {}
local connection

function feature:enable()
    dontrun = false
    lastSend = tick()

    local RunService = game:GetService("RunService")

    connection = RunService.RenderStepped:Connect(function()
        if dontrun then return end
        if not local_player or not local_player.character then return end
        local character = local_player.character

        local fishingGui = local_player.instance and local_player.instance.PlayerGui and local_player.instance.PlayerGui:FindFirstChild("FishingGui")
        if not fishingGui or not fishingGui.Enabled then
            local rod = character:FindFirstChild("Fishing Rod") or (local_player.instance and local_player.instance.Backpack and local_player.instance.Backpack:FindFirstChild("Fishing Rod"))
            if tick() - lastSend > 2.5 and rod and workspace:FindFirstChild("Thrown") and not workspace.Thrown:FindFirstChild("Bobby_" .. local_player.instance.Name) then
                rod:Activate()
                task.wait(0.25)
                rod:Deactivate()
            end
            return
        end

        local mainFrame = fishingGui:FindFirstChild("MainFrame")
        if mainFrame then
            local holdA = mainFrame:FindFirstChild("HoldA") and mainFrame.HoldA.Visible
            local holdD = mainFrame:FindFirstChild("HoldD") and mainFrame.HoldD.Visible
            local holdS = mainFrame:FindFirstChild("HoldS") and mainFrame.HoldS.Visible

            local args = {
                {
                    a = holdA,
                    d = holdD,
                    s = holdS
                }
            }

            pcall(function()
                local fishingRod = local_player.instance and local_player.instance.Backpack and local_player.instance.Backpack:FindFirstChild("Fishing Rod")
                if fishingRod and fishingRod:FindFirstChild("InputUpdate") then
                    fishingRod.InputUpdate:FireServer(unpack(args))
                end
            end)

            pcall(function()
                local fishingRod = character:FindFirstChild("Fishing Rod")
                if fishingRod and fishingRod:FindFirstChild("InputUpdate") then
                    fishingRod.InputUpdate:FireServer(unpack(args))
                end
            end)
        end

        lastSend = tick()
    end)
    maid.auto_fish = connection
end

function feature:disable()
    dontrun = false
    if connection then
        connection:disconnect()
        connection = nil
    end
    if maid.auto_fish then
        maid.auto_fish = nil
    end
end

return feature

end;

__modules["src/features/automation/auto_flow_state"] = function()

local feature = Feature:new("auto_flow_state")

local dontrun = false
local maid = {}
local connection


local TARGET_ANIMATION_IDS = {
    "rbxassetid://110691694093015",
    "rbxassetid://85523657178401",
    "rbxassetid://100709561068031",
    "rbxassetid://139465383955578",
    "rbxassetid://82111969749817",
    "rbxassetid://101880653361558",
    "rbxassetid://132164383275060",
    "rbxassetid://72748965289041",
    "rbxassetid://12564120372",
}

local function isTargetAnimation(animId)
    for _, id in ipairs(TARGET_ANIMATION_IDS) do
        if animId == id then return true end
    end
    return false
end

function feature:enable()
    dontrun = false
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local Character = LocalPlayer and LocalPlayer.Character
    local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")

    if not Humanoid then return end

    if maid.animConn then maid.animConn:Disconnect() end
    maid.animConn = Humanoid.AnimationPlayed:Connect(function(track)
        if dontrun then return end
        if not track or not track.Animation or not track.Animation.AnimationId then return end
        local animId = track.Animation.AnimationId
        if isTargetAnimation(animId) then
            
            local flow = LocalPlayer.Backpack:FindFirstChild("Talent:Flow State") or Character:FindFirstChild("Talent:Flow State")
            if flow then
                local activateRt = flow:FindFirstChild("ActivateRt")
                if activateRt then
                    activateRt:FireServer()
                end
            end
        end
    end)
    maid.auto_flow_state = maid.animConn
end

function feature:disable()
    dontrun = false
    if maid.animConn then
        maid.animConn:Disconnect()
        maid.animConn = nil
    end
    if maid.auto_flow_state then
        maid.auto_flow_state = nil
    end
end

return feature

end;

