__modules["src/features/automation/auto_sprint"] = function()
local sprint_keys, started_sprint, feature = {
    Enum.KeyCode.W,
    Enum.KeyCode.A,
    Enum.KeyCode.S,
    Enum.KeyCode.D
}, nil, nil;


