__modules["src/features/automation/auto_wisp"] = function()


local feature = Feature:new("auto_wisp")

local WISP_INPUT_MAP = { Z = 1, X = 2, C = 3, V = 4 }

function feature:enable()
	local ritualSpellInput = game:GetService("ReplicatedStorage")
		:WaitForChild("Requests")
		:WaitForChild("Mantras")
		:WaitForChild("RitualSpellInput")

	local cws = nil
	local cwp = nil
	local locked = false
	local lastShift = nil
	local lastUpdate = nil

	self.eventConnection = ritualSpellInput.OnClientEvent:Connect(function(name, data)
		if name == "start" then
			cws = data
			cwp = 1
			locked = false
			lastShift = nil
			lastUpdate = nil
		elseif name == "shift" and cws and cwp then
			cwp = cwp + 1
			lastShift = os.clock()
			locked = false
		elseif name == "close" then
			cws = nil
			cwp = nil
			locked = false
			lastShift = nil
			lastUpdate = nil
		end
	end)

	self.renderConnection = game:GetService("RunService").RenderStepped:Connect(function()
		if not cws or not cwp then
			return
		end
		if cwp > #cws then
			return
		end
		if locked then
			return
		end

		local delay = aztup_options.auto_wisp_delay and aztup_options.auto_wisp_delay.Value or 0
		if lastShift and os.clock() - lastShift <= 0.15 + delay then
			return
		end

		local letter = cws:sub(cwp, cwp)
		if letter ~= "Z" and letter ~= "X" and letter ~= "C" and letter ~= "V" then
			return
		end

		if not EffectReplicator:HasEffect("RitualCastingSpell") then
			return
		end
		if EffectReplicator:HasEffect("Knocked") then
			return
		end

		locked = true
		lastUpdate = os.clock()

		pcall(function()
			ritualSpellInput:FireServer(WISP_INPUT_MAP[letter])
		end)

		task.delay(0.5 + delay, function()
			locked = false
		end)
	end)
end

function feature:disable()
	if self.eventConnection then
		self.eventConnection:Disconnect()
		self.eventConnection = nil
	end
	if self.renderConnection then
		self.renderConnection:Disconnect()
		self.renderConnection = nil
	end
end

return feature

end;

__modules["src/features/automation/backstab_movestacker"] = function()

local feature = Feature:new("backstab_movestacker");

function feature:enable()
    local ready = false;
	self.added_hook = EffectReplicatorHandler:hook("added", function(effect)
		if effect.Class == "backstabDebounce" then
            ready = true;
            task.delay(3, function()
                ready = false;
            end)
        end
	end);
 
    self.removed_hook = EffectReplicatorHandler:hook("removed", function(effect)
		if effect.Class == "Action" and ready then
            task.wait(Latency:half_ping())
            ready = false;

            local backpack = local_player.instance:FindFirstChild("Backpack");
			if not backpack then return end;

            local mantras = table.clone(aztup_options.backstab_movestacker_mantras.Value);
            local decided_mantra;
	        for _, effect in EffectReplicator:GetEffects() do
	        	if effect.Class == "ToolLockCD" then
	        		local tool = backpack:FindFirstChild(effect.Value);
                    if tool and tool:GetAttribute("DefaultName") then
                        mantras[tool:GetAttribute("DefaultName")] = nil;
                    end
	        	end
	        end

            decided_mantra = next(mantras);
            if not decided_mantra then return end

            local mantra_tool;
            for _, tool in pairs(backpack:GetChildren()) do
                if tool:IsA("Tool") and tool:GetAttribute("DefaultName") == decided_mantra then
                    mantra_tool = tool;
                    break                
end
            end
            
			if not mantra_tool then return end;
			
			local character_handler = local_player.character:FindFirstChild("CharacterHandler");
			local requests = character_handler and character_handler:FindFirstChild("Requests");
			local activate_mantra = requests and requests:FindFirstChild("ActivateMantra");

			activate_mantra:FireServer(mantra_tool)			
		end
	end);
end;

function feature:disable()
	if self.added_hook then
		self.added_hook:remove();
	end;
    
	if self.removed_hook then
		self.removed_hook:remove();
	end;
end;

return feature

end;

