__modules["src/features/buttons/tp_to_guildbase"] = function()
return function()
    local target = aztup_options.guildbase_teleport_type.Value;
    if not target then
        return Library:Notify("Invalid teleport selection.", 15)    
end

    local guild_door do 
        for _, door in workspace:GetChildren() do
            if door.Name:match("GuildDoor_") and (door:GetAttribute("GuildName") or door.Name) == target then
                guild_door = door
                break
            end
        end
    end;

    if not guild_door then
        return Library:Notify("Failed to find guildbase.", 15)    
end;

    local guild_exit = workspace:FindFirstChild(guild_door.Name:gsub("GuildDoor", "GuildExitDoor"));

    if not guild_exit then
        return Library:Notify("Failed to find guildbase.", 15)    
end;

    return LoopUtil.run_for(25, function()
        if not local_player.root_part then return end

        if guild_door and (local_player.root_part.Position - guild_door.Position).Magnitude < 20 then
            LoopUtil.run_for(0.5, function()
                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
            end)
            return true        
end;

        local_player.root_part.CFrame = guild_exit.CFrame;
        return fireproximityprompt(guild_exit.InteractPrompt)    
end)
end 

end;

__modules["src/features/buttons/tp_to_objectives"] = function()
local ingredients = workspace:FindFirstChild("Ingredients");
local npcs = workspace:FindFirstChild("NPCs");
local live = workspace:FindFirstChild("Live");

local requests = services.ReplicatedStorage:WaitForChild("Requests");
local send_dialogue = requests and requests:WaitForChild("SendDialogue");

function safe_tween(tween)
    if aztup.maid.objective_tween then aztup.maid.objective_tween.stop() end
    aztup.maid.objective_tween = tween
    aztup.maid.objective_tween.wait()
    aztup.maid.objective_tween = nil
end
function close_prompt()
    local start = tick();

    while tick() - start < 2 do
        send_dialogue:FireServer({exit=true});
        task.wait();
    end
end
function getPosition(instance)
    if instance:IsA("BasePart") then
        return instance.Position
    end

    if instance:IsA("Model") then
        if instance.GetPivot then
            return instance:GetPivot().Position
        elseif instance.PrimaryPart then
            return instance.PrimaryPart.Position
        else
            return nil
        end
    end

    if instance:IsA("ObjectValue") and instance.Value then
        return getPosition(instance.Value)
    end
    return nil
end

function getNearest(list, filter)
    local closestObject;
    local closest = 9e9;
    for i, v in pairs(list) do
        local pos = getPosition(v)
        if filter(v) and pos and (pos - local_player.root_part.Position).Magnitude < closest then
            closest = (pos - local_player.root_part.Position).Magnitude;
            closestObject = v;
        end
    end
    return closestObject
end;

