__modules["src/features/combat/anim_speed_changer"] = function()
local feature = Feature:new("anim_speed_changer", services.RunService.PreAnimation);
local random = Random.new();

feature.toggle_conversion_map = {
    ["Critical"] = "Criticals",
    ["Untagged"] = "Untagged",
    ["Spell"] = "Spells",
    ["Bell"] = "Bells",
    ["M1"] = "M1s"
}

feature.slider_conversion_map = {
    ["Critical"] = "anim_critical_speed", 
    ["Untagged"] = "anim_untagged_speed",
    ["Spell"] = "anim_spell_speed",
    ["Bell"] = "anim_bell_speed",
    ["M1"] = "anim_m1_speed"
}

feature.last_seen_at = {};
feature.stepping = {};

function feature:handle(track: AnimationTrack, data: any)
    if not aztup.flags.anim_speed_changer then 
        return    
end;

    local action_type = data.action_type;    
    if not aztup_options.anim_speed_changer_types.Value[self.toggle_conversion_map[action_type] ] then
        return    
end

    local multiplier = aztup.flags[self.slider_conversion_map[action_type] ];
    local chosen;

    if aztup.flags.switch_speeds then
        chosen = random:NextNumber() < 0.5 and multiplier.min or multiplier.max;
    else
        chosen = random:NextNumber(multiplier.min, multiplier.max);
    end

    local at = table.insert(self.stepping, {
        track = track,
        speed = chosen
    });

    track.Ended:Once(function() 
        table.remove(self.stepping, table.find(self.stepping, at));
    end)
end;    

function feature.update()
    local self = feature;
    for index, item in self.stepping do
        local track: AnimationTrack = item.track;
        local speed = item.speed;

        if not track.IsPlaying then
            table.remove(self.stepping, index);
            continue        
end

        if self.last_seen_at[track] == track.Speed then continue end

        track:AdjustSpeed(track.Speed * speed);
        self.last_seen_at[track] = track.Speed;
    end
end

feature.func = feature.update; 
return feature

end;

__modules["src/features/combat/attach_to_back"] = function()

local self = Feature:new("attach_to_back", services.RunService.PostSimulation);

function self:get_target()
    local live = workspace:FindFirstChild("Live");
    if not live then return nil end;
    
    local targets = aztup_options.allowed_atb_targets.Value;

    local mouse = local_player.instance:GetMouse();
    local mouse_x = mouse.X;
    local mouse_y = mouse.Y + services.GuiService:GetGuiInset().Y;

    for _, entity in live:GetChildren() do
        local is_mob = entity.Name:sub(1, 1) == ".";
        local is_plr = not is_mob;
        if is_mob and not targets.Mobs then
            continue        
end;

        if is_plr and not targets.Players then
            continue        
end;

        local plr = is_plr and services.Players:GetPlayerFromCharacter(entity);
        local is_gld = is_plr and general:is_teammate(plr);
        if is_gld and not targets.Guildmates then
            continue        
end;

        if not entity.PrimaryPart then
            continue        
end;

        if entity == local_player.character then
            continue        
end;

        local size = Vector3.new(4, 5, 6)
        local floored_position = entity.PrimaryPart.CFrame - (size / 2)
	    local maxs = (floored_position + size).Position
	    local mins = floored_position.Position


	    local points = {
	    	Vector3.new(mins.X, mins.Y, mins.Z),
	    	Vector3.new(mins.X, maxs.Y, mins.Z),
	    	Vector3.new(maxs.X, maxs.Y, mins.Z),
	    	Vector3.new(maxs.X, mins.Y, mins.Z),
	    	Vector3.new(maxs.X, maxs.Y, maxs.Z),
	    	Vector3.new(mins.X, maxs.Y, maxs.Z),
	    	Vector3.new(mins.X, mins.Y, maxs.Z),
	    	Vector3.new(maxs.X, mins.Y, maxs.Z),
	    }

        for idx, point in next, points do
            local screen_point, on_screen = workspace.CurrentCamera:WorldToViewportPoint(point)
            if on_screen then
                if screen_point.X > mouse_x - 90 and screen_point.X < mouse_x + 90 then
                    if screen_point.Y > mouse_y - 90 and screen_point.Y < mouse_y + 90 then
                        return entity                    
end
                end
            end
        end
    end;

    return nil
end;

function self:getting_target()
    local target = self:get_target();

    if target then
        self.highlight.Adornee = target;
        self.highlight.Parent = target;
    else
        self.highlight.Adornee = nil;
        self.highlight.Parent = nil;
    end

    if target and (services.UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) or services.UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)) then
        self.target = target;
        self.state = "attaching";
    end
end

function self:attaching(dt)
    if not self.target or not self.target:FindFirstChild("HumanoidRootPart") or not self.target.Parent then
        self.state = "getting_target";
        return    
end 

    self.x_offset = math.clamp(self.x_offset,-150, 150)
    self.y_offset = math.clamp(self.y_offset,-150, 150)
    self.z_offset = math.clamp(self.z_offset,-150, 150)

    if self.orig_x_offset ~= aztup.flags.atb_x_offset then
        self.orig_x_offset = aztup.flags.atb_x_offset;
        self.x_offset = aztup.flags.atb_x_offset;
    elseif self.x_offset ~= aztup.flags.atb_x_offset then
        aztup_options.atb_x_offset:SetValue(self.x_offset);
    end

    if self.orig_z_offset ~= aztup.flags.atb_z_offset then
        self.orig_z_offset = aztup.flags.atb_z_offset;
        self.z_offset = aztup.flags.atb_z_offset;
    elseif self.z_offset ~= aztup.flags.atb_z_offset then 
        aztup_options.atb_z_offset:SetValue(self.z_offset);
    end
    
    if self.orig_y_offset ~= aztup.flags.atb_y_offset then
        self.orig_y_offset = aztup.flags.atb_y_offset;
        self.y_offset = aztup.flags.atb_y_offset;
    elseif self.y_offset ~= aztup.flags.atb_y_offset then
        aztup_options.atb_y_offset:SetValue(self.y_offset);
    end

    if services.UserInputService:IsKeyDown(Enum.KeyCode.A) then
        self.x_offset = self.x_offset - (aztup.flags.atb_speed * dt);
    end 

    if services.UserInputService:IsKeyDown(Enum.KeyCode.D) then
        self.x_offset = self.x_offset + (aztup.flags.atb_speed * dt);
    end

    if services.UserInputService:IsKeyDown(Enum.KeyCode.S) then
        self.z_offset = self.z_offset + (aztup.flags.atb_speed * dt);
    end 
    
    if services.UserInputService:IsKeyDown(Enum.KeyCode.W) then
        self.z_offset = self.z_offset - (aztup.flags.atb_speed * dt);
    end

    if services.UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
        self.y_offset = self.y_offset - (aztup.flags.atb_speed * dt);
    end
    
    if services.UserInputService:IsKeyDown(Enum.KeyCode.Space) then
        self.y_offset = self.y_offset + (aztup.flags.atb_speed * dt);
    end

    local target_cframe = self.target.HumanoidRootPart.CFrame;
    if aztup.flags.atb_lock_rotation then
        target_cframe = CFrame.new(target_cframe.Position);
    end;

    local void_point = workspace:FindFirstChild("Layer2Floor1") and 18.5 or 0;
    if aztup.flags.atb_prevent_voiding and target_cframe.Y < void_point then
        target_cframe = CFrame.new(target_cframe.X, void_point, target_cframe.Z);
    end;

    local back_cframe = target_cframe * CFrame.new(self.x_offset, self.y_offset, self.z_offset);
    local distance = ((back_cframe.Position - local_player.root_part.Position) * Vector3.new(1,0,1)).Magnitude;

    self.highlight.Adornee = self.target;
    self.highlight.Parent = self.target;

    if distance > 30 then
        self.current_tween = Tween.new(back_cframe, true, 150);
    else
        local_player.root_part.CFrame = back_cframe;

        if aztup.flags.atb_rotate then
            local look_cframe = CFrame.new(local_player.root_part.Position, target_cframe.Position);
            local_player.root_part.CFrame = look_cframe;
        end
    end
end

function self.update(dt)
    if self.current_tween then
        self.current_tween.stop();
    end

    self[self.state](self, dt);
end

function self:enable()
    self.x_offset = aztup.flags.atb_x_offset;
    self.z_offset = aztup.flags.atb_z_offset;
    self.y_offset = aztup.flags.atb_y_offset;

    self.orig_x_offset = aztup.flags.atb_x_offset;
    self.orig_z_offset = aztup.flags.atb_z_offset;
    self.orig_y_offset = aztup.flags.atb_y_offset;

    self.state = "getting_target";
    self.target = nil;
    self.highlight = Instance.new("Highlight");
    self.highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
    self.highlight.FillColor = Library.AccentColor;
    self.highlight.OutlineColor = Library.AccentColor;
    self.highlight.FillTransparency = 0.9;
    self.highlight.OutlineTransparency = 0;
end

function self:disable()
    if self.current_tween then
        self.current_tween.stop();
    end

    if self.highlight then 
        self.highlight:Destroy();
        self.highlight = nil;
    end
end

self.func = self.update;
return self

end;

__modules["src/features/combat/auto_air_counter"] = function()
local target_filter = require("@src/features/auto-parry/util/target-filter");

return Feature:new("auto_air_counter", scheduler:add_task(0.1), function()
    local character_handler = local_player.character and local_player.character:FindFirstChild("CharacterHandler")
    local requests = character_handler and character_handler:FindFirstChild("Requests")
    local anti_air = requests and requests:FindFirstChild("AntiAir");
    if not anti_air then return end;

    local live = workspace:FindFirstChild("Live");
    if not live then return end

    if not aztup.flags.air_counter_on_ground and not general:in_air() then
        return    
end
    
    local in_range = {};
    for _, item in live:GetChildren() do
        if item.Name:sub(1,1) == "." or not item:FindFirstChild("HumanoidRootPart") then continue end

        if aztup.flags.air_counter_ally_check then
            if target_filter.is_allowed(item, {
                PVP = true
            }) then
                continue            
end
        end

        local hrp = item.HumanoidRootPart;
        local distance = (hrp.Position - local_player.root_part.Position).Magnitude;

        if distance <= aztup.flags.air_counter_range then
            table.insert(in_range, item);
        end
    end

    for _, target in next, in_range do
        anti_air:FireServer(target);
    end
end)

end;

__modules["src/features/combat/auto_ardour"] = function()

local feature = Feature:new("auto_ardour");

local function has_passive(passive_name)
	return EffectReplicator and EffectReplicator.Passives and EffectReplicator.Passives[passive_name] ~= nil
end;

function feature:enable()
	self.added_hook = EffectReplicatorHandler:hook("added", function(effect)
		if not local_player.instance or not local_player.character then return end;

		local character = local_player.character;
		if not has_passive("Murmur: Ardour") then return end
		
		local attach = workspace.Thrown and workspace.Thrown:FindFirstChild("Attach_" .. character.Name)
		local weapon = attach and attach:FindFirstChild("HandWeapon")
		if not weapon then return end;

		if weapon:FindFirstChild("ArdourHum") then
			return		
end;

		local character_handler = character:FindFirstChild("CharacterHandler");
		local requests = character_handler and character_handler:FindFirstChild("Requests");
		local ardour = requests and requests:FindFirstChild("Ardour");

		if ardour then
			ardour:FireServer();
		end;

		return nil	
end);
end;

function feature:disable()
	if self.added_hook then
		self.added_hook:remove();
	end;
end;

return feature

end;

__modules["src/features/combat/auto_dustlunge"] = function()
local feature = Feature:new("auto_dustlunge");

local runService = game:GetService("RunService")
local players = game:GetService("Players")
local currentSimulationPart = nil
local isFeatureEnabled = false

local defaultConfig = {
    hitboxType = "Block",
    sizeX = 2, sizeY = 6, sizeZ = 10,
    shiftOffset = -5
}


local function cleanupSimulation()
    if currentSimulationPart then
        currentSimulationPart:Destroy()
        currentSimulationPart = nil
    end
end

local function runSimulationStep()
    if not isFeatureEnabled then return end
    if not aztup.features.auto_dustlunge.held or EffectReplicator:FindEffect("GrabCD") then 
        if currentSimulationPart then currentSimulationPart:Destroy() end
        return    
end

    local character = players.LocalPlayer.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then return end

    local config = defaultConfig
    local size = Vector3.new(config.sizeX, config.sizeY, config.sizeZ)
    local usedCFrame = root.CFrame

    if config.shiftOffset ~= 0 then
        usedCFrame = usedCFrame * CFrame.new(0, 0, config.shiftOffset)
    end

    if not currentSimulationPart or currentSimulationPart.Parent ~= workspace then
        if currentSimulationPart then currentSimulationPart:Destroy() end
        currentSimulationPart = Instance.new("Part")
        currentSimulationPart.Name = "HitboxSimulationPart"
        currentSimulationPart.Anchored = true
        currentSimulationPart.CanCollide = false
        currentSimulationPart.CanQuery = false
        currentSimulationPart.CanTouch = false
        currentSimulationPart.Material = Enum.Material.ForceField
        currentSimulationPart.CastShadow = false
        currentSimulationPart.Transparency = aztup.flags.auto_dustlunge_debug and 0.5 or 1.0
    end

    currentSimulationPart.Size = size
    if config.hitboxType == "Block" then
        currentSimulationPart.Shape = Enum.PartType.Block
        currentSimulationPart.CFrame = usedCFrame
    end;

    currentSimulationPart.Parent = workspace

    local live = workspace:FindFirstChild("Live")
    local instances = {}
    if live then
        for _, child in next, live:GetChildren() do
            if child ~= character then
                table.insert(instances, child)
            end
        end
    end

    local sprinting = EffectReplicator:FindEffect("Sprinting");
    if #instances > 0 then
        local params = OverlapParams.new()
        params.FilterDescendantsInstances = instances
        params.FilterType = Enum.RaycastFilterType.Include
        local ok, parts = pcall(function()
            return workspace:GetPartsInPart(currentSimulationPart, params)
        end)
        currentSimulationPart.Color = (ok and parts and #parts > 0) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)

        if (ok and parts and #parts > 0) then
            local char = parts[1]:FindFirstAncestorWhichIsA("Model");
            if not char or not char:FindFirstChild("Humanoid") or not char:FindFirstChild("HumanoidRootPart") then return end

			local dotProduct = (char.HumanoidRootPart.Position - local_player.root_part.Position):Dot(local_player.root_part.CFrame.LookVector);
			if (dotProduct <= 0) then return end; 
            if sprinting then
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests").ServerSprint:FireServer(false);
                task.wait(1 / 20);
            end;

            local script_crouched = false;
            if not EffectReplicator:FindEffect("Crouching") then
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests"):WaitForChild("ServerCrouch"):FireServer(true);
                script_crouched = true;
            end;

            local start = tick();
            repeat task.wait() until EffectReplicator:FindEffect("Crouching") or tick() - start > Latency:get_ping() * 2;
            if tick() - start > Latency:get_ping() * 2 then
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests"):WaitForChild("ServerCrouch"):FireServer(false);
                if sprinting then
                    local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests").ServerSprint:FireServer(true);
                end;
                return            
end;
            task.spawn(function()
                local remote = KeyHandler:get_cache("LeftClick") or KeyHandler:get_key("LeftClick");
                if not remote or not remote:IsDescendantOf(local_player.character) or not remote.Parent then
                    remote = KeyHandler:get_key("LeftClick");
                end


                if not remote then return end
                remote:FireServer(false, local_player.instance:GetMouse().Hit, {
                	S = false,
                	NOAERIALS = true, 
                	Space = false,
                	Right = services.UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2),
                	W = false,
                	Left = true,
                    ctrl = false
                }); 
            end);
            task.wait(1 / 20);
            if script_crouched then
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests"):WaitForChild("ServerCrouch"):FireServer(false);
            else
                local VIM = Instance.new("VirtualInputManager");
                VIM:SendKeyEvent(true, Enum.KeyCode.LeftControl, false, game);
                VIM:SendKeyEvent(false, Enum.KeyCode.LeftControl, false, game);
            end;

            if sprinting then
                local_player.character:WaitForChild("CharacterHandler"):WaitForChild("Requests").ServerSprint:FireServer(true);
            end;
        end;
    else
        currentSimulationPart.Color = Color3.fromRGB(255,0,0)
    end
end

function feature:enable()
    cleanupSimulation()
    isFeatureEnabled = true
end

function feature:disable()
    isFeatureEnabled = false
    cleanupSimulation()
end

function feature:refresh()
    if isFeatureEnabled then
        cleanupSimulation()
    end
end

aztup.maid:give_task(scheduler:add_task(1 / 5):Connect(runSimulationStep))

return feature

end;

__modules["src/features/combat/auto_golden_tongue"] = function()

local feature = Feature:new("auto_golden_tongue");
local last_update = 0;

function feature:enable()
	self.added_hook = EffectReplicatorHandler:hook("added", function(effect)
		if os.clock() - last_update < 1 then return end;
		if not aztup.flags.auto_golden_tongue then return end

		local character = local_player.character;
		local passives = character:GetAttribute("ssv_Passives");
		if passives and not passives:find("Golden Tongue") then return end

		local replicator = getgenv().EffectReplicator;
		if not replicator then return end; 

		if not replicator:FindEffect("Danger") then return end
		if replicator:FindEffect("GoldCool") then
			return		
end;

		local textservice = game:GetService("TextChatService");
		local channels = textservice:FindFirstChild("TextChannels");
		local general = channels and channels:FindFirstChild("RBXGeneral");
		local system = channels and channels:FindFirstChild("RBXSystem");
		local mode = aztup_options.auto_golden_tongue_mode.Value;

		if system and mode == "Blatant" then
			last_update = os.clock();
			system:SendAsync("/e");
		elseif general and mode == "Legit" then
			local key = ({
				[0] = "w",
				[1] = "a",
				[2] = "s",
				[3] = "d",
			})[math.random(0,3)];

			last_update = os.clock();
			general:SendAsync(key);
		end;
		
		return nil	
end);
end;

function feature:disable()
	if self.added_hook then
		self.added_hook:remove();
	end;
end;

return feature

end;

