__modules["src/features/exploits/boat_teleport"] = function()
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local self;
self = Feature:new("boat_teleport", services.UserInputService.InputBegan, function(input, gp)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end

    local player_gui = local_player.instance:FindFirstChild("PlayerGui");
    if not player_gui then return end

    local map_gui = player_gui:FindFirstChild("MapGui");
    if not map_gui or not map_gui.Enabled then return end

    local map_centre = game:GetService("ReplicatedStorage"):FindFirstChild("MAP_CENTRE");
    local centre = CFrame.identity
    centre = map_centre and map_centre.Value or centre;
    

    local bounds = Vector3.new(20000, 0, 20000)
    local map_bounds = game:GetService("ReplicatedStorage"):FindFirstChild("MAP_BOUNDS");
    bounds = map_bounds and map_bounds.Value or bounds;


    local map_container = map_gui.MainFrame.Scroll.MapClip.MapContainer

    local mouse_pos = services.UserInputService:GetMouseLocation()
    local frame_size = map_container.AbsoluteSize
    local frame_pos = map_container.AbsolutePosition + Vector2.new(0, game:GetService("GuiService"):GetGuiInset().Y)

    local scale_from_screen = (mouse_pos - frame_pos) / frame_size
    local uv = UDim2.fromScale(scale_from_screen.X, scale_from_screen.Y)
    local v67 = Vector3.new((uv.X.Scale - 0.5) * 2, 0, (uv.Y.Scale - 0.5) * 2) * bounds
    local map_cf = CFrame.new(centre:PointToWorldSpace(v67))

    if not EffectReplicator then return end
    local steering = EffectReplicator:FindEffect("Steering");
    if not steering then return end 
    steering = steering.Value;

    local ship = steering:FindFirstAncestorWhichIsA("Model");
    if not ship then return end 
    local character_handler = local_player.character:FindFirstChild("CharacterHandler");
    if not character_handler then return end 

    local equip_weapon = character_handler.Requests.DrawWeapon;
    if not equip_weapon then return end 

    local cancel_interact = character_handler.Requests.CancelInteract;
    if not cancel_interact then return end 

    if self.cd and tick() - self.cd < 10 then return end;
    self.cd = tick();
    local start_tick = tick();

    steering:WaitForChild("ShipControls"):FireServer("d", true, local_player.root_part.CFrame)
    local rep_requests = services.ReplicatedStorage:WaitForChild("Requests");
    rep_requests.MapOpen:FireServer(false);

    local last_non_owner = tick();
    repeat
        if not EffectReplicator:FindEffect("Steering") then break end

        equip_weapon:FireServer(true);
        
        local steering_effect = EffectReplicator:FindEffect("Steering");
        if not steering_effect then break end

        if steering_effect.Tags.WheelSteer then
            local controls = ship:FindFirstChild("ShipControls");
            if controls then
                controls:FireServer(({
                    "a",
                    "d", 
                    "w"
                })[math.random(1, 3)], math.random() > 0.5)
            end
        end

        ship:PivotTo(CFrame.new(map_cf.X, 0, map_cf.Z));

        if ship and ship:FindFirstChild("Hull") then
            if sf_isnetworkowner(ship.Hull) then
                if tick() - last_non_owner > 0.3 then
                    cancel_interact:FireServer()
                end
            else
                last_non_owner = tick();
            end
        end

        task.wait();
        
        equip_weapon:FireServer(false);
    until tick() - start_tick > 2.5 and (local_player.character:GetAttribute("MapPos") - map_cf.Position).Magnitude < 100 or tick() - start_tick > 15
    steering:WaitForChild("ShipControls"):FireServer("d", false)

    character_handler.Requests.CancelInteract:FireServer();
end)

return self

end;

