__modules["src/features/exploits/raknet_fakelag"] = function()

local feat = Feature:new("fakelag")

local buffer_reader = {}
buffer_reader.__index = buffer_reader

function buffer_reader:u8()
	local value = buffer.readu8(self.buffer, self.position)
	self.position = self.position + 1
	return value
end

function buffer_reader:u32()
	local value = buffer.readu32(self.buffer, self.position)
	self.position = self.position + 4
	return value
end

function buffer_reader:u64()
	local low = self:u32()
	local high = self:u32()
	return high * 4294967296 + low
end

function buffer_reader:varint()
	local result = 0
	local shift = 0

	while true do
		local byte = self:u8()

		result = result + bit32.lshift(bit32.band(byte, 0x7F), shift)

		if bit32.band(byte, 0x80) == 0 then
			break
		end

		shift = shift + 7

		if shift > 63 then
			error("varint too large")
		end
	end

	return result
end

function buffer_reader:instance_ref()
	local peer_id = self:varint()
	local id = self:u32()

	return {
		peer = peer_id,
		id = id,
	}
end

function buffer_reader:remaining()
	return buffer.len(self.buffer) - self.position
end

function buffer_reader:new(buffer)
	return setmetatable({
		position = 0,
		buffer = buffer,
	}, { __index = buffer_reader })
end



local serialized_buffer = {}
serialized_buffer.__index = serialized_buffer

function serialized_buffer:to_hex()
	local hex = {}

	for i = 0, buffer.len(self.buffer) - 1 do
		table.insert(hex, string.format("%02X", buffer.readu8(self.buffer, i)))
	end

	return "<" .. table.concat(hex, ", ") .. ">"
end

function serialized_buffer:new(buffer)
	return setmetatable({
		buffer = buffer,
	}, { __index = serialized_buffer })
end



local buffer_writer = {}
buffer_writer.__index = buffer_writer

function buffer_writer:u8(value)
	self.queue[#self.queue + 1] = { type = "u8", value = value }
	self.size = self.size + 1
end

function buffer_writer:u32(value)
	self.queue[#self.queue + 1] = { type = "u32", value = value }
	self.size = self.size + 4
end

function buffer_writer:u64(value)
	self:u32(bit32.band(value, 0xFFFFFFFF))
	self:u32(bit32.rshift(value, 32))
end

function buffer_writer:varint(value)
	repeat
		local byte = bit32.band(value, 0x7F)
		value = bit32.rshift(value, 7)

		if value ~= 0 then
			byte = bit32.bor(byte, 0x80)
		end

		self:u8(byte)
	until value == 0
end

function buffer_writer:instance_ref(ref)
	self:varint(ref.peer)
	self:u32(ref.id)
end

function buffer_writer:serialize()
	local raw_buffer = buffer.create(self.size)
	local position = 0

	for _, item in ipairs(self.queue) do
		if item.type == "u8" then
			buffer.writeu8(raw_buffer, position, item.value)
			position = position + 1
		elseif item.type == "u32" then
			buffer.writeu32(raw_buffer, position, item.value)
			position = position + 4
		end
	end

	if position ~= self.size then
		error("serialization size mismatch")
	end

	return serialized_buffer:new(raw_buffer)
end

function buffer_writer:new()
	return setmetatable({
		size = 0,
		queue = {},
	}, { __index = buffer_writer })
end

local packets_sent = 0
local last_accepted_t1 = nil
function hook(packet)
    local data = packet.AsBuffer
	local reader = buffer_reader:new(data)
	local packet_id = reader:u8()
	if packet_id ~= 0x1B then
		return
	end

	local t1 = reader:u64()
	local t2 = reader:u64()
	local wrapped_packet_id = reader:u8()
	if wrapped_packet_id == 0x85 then
	    local ref = reader:instance_ref()

	    local remaining = reader:remaining()

	    
	    local writer = buffer_writer:new()


	    
	    writer:u8(0x1B)

	    packets_sent = packets_sent + 1

	    local forced_timestamp = nil
	    if packets_sent % (aztup.flags.fakelag_amount) == 0 or not last_accepted_t1 then
	    	forced_timestamp = t1
	    	last_accepted_t1 = t1
	    else
	    	forced_timestamp = last_accepted_t1 - 1
	    end


	    writer:u64(forced_timestamp)
	    writer:u64(t2)
	    writer:u8(wrapped_packet_id)
	    writer:varint(ref.peer)
	    writer:u32(ref.id)

	    local start_at = reader.position
	    local end_at = (reader.position + remaining) - 1
	    for position = start_at, end_at do
	    	writer:u8(buffer.readu8(reader.buffer, position))
	    end

	    
	    local serialized_buffer = writer:serialize()
	    local output_buffer = serialized_buffer.buffer

	    raknet.send(output_buffer, packet.Priority, packet.Reliability, packet.OrderingChannel)

	    packet:Block()
    end
end;

local hooked = false;
function feat:enable()
	hooked = true;
    raknet.add_send_hook(hook)
end
 
function feat:disable()
	if not hooked then return end
    raknet.remove_send_hook(hook)
	hooked = false;
end

return feat

end;

__modules["src/features/exploits/voi_teleport"] = function()
local loop_util = require("@src/utility/loop");

local self;
self = Feature:new("voi_teleport", services.UserInputService.InputBegan, function(input, gp)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end

    local player_gui = local_player.instance:FindFirstChild("PlayerGui");
    if not player_gui then return end

    local map_gui = player_gui:FindFirstChild("MapGui");
    if not map_gui or not map_gui.Enabled then return end

    local map_centre = game:GetService("ReplicatedStorage"):FindFirstChild("MAP_CENTRE");
    local centre = CFrame.identity
    centre = map_centre and map_centre.Value or centre;
    

    local bounds = Vector3.new(20000, 0, 20000)
    local map_bounds = game:GetService("ReplicatedStorage"):FindFirstChild("MAP_BOUNDS");
    bounds = map_bounds and map_bounds.Value or bounds;


    local map_frame = map_gui.MainFrame.Scroll.MapClip

    local mouse_pos = services.UserInputService:GetMouseLocation()
    local frame_pos = map_frame.AbsolutePosition
    local frame_size = map_frame.AbsoluteSize

    local uv = (mouse_pos - frame_pos) / frame_size
    local map_cf = centre * CFrame.new(((uv.X - 0.5) * 2) * bounds.X, 0, ((uv.Y - 0.5) * 2) * bounds.Z)
    self:goto(map_cf);
end)

function self:goto(map_cf)
    local boundarys = {};
    for _, child in workspace:GetChildren() do
        if not child.Name:match("Boundary") then continue end
        if not child:IsA("BasePart") then continue end
        if not child:FindFirstChild("TouchInterest") then continue end

        table.insert(boundarys, child);
    end;      

    if #boundarys == 0 then
        
        repeat 
            local_player.instance:RequestStreamAroundAsync(Vector3.new(-9264.10645, 560.461121, 2245.23169));
            task.wait(0.1) 
        until workspace:FindFirstChild("Merit Keep Boundary");

        table.insert(boundarys, workspace:FindFirstChild("Merit Keep Boundary"));
    end;

    local boundary;
    for _, boundary_part in pairs(boundarys) do
        if (boundary_part.Position - local_player.root_part.Position).Magnitude > 50 then
            boundary = boundary_part;
            break        
end;
    end;

    boundary = boundary or boundarys[1];

    if not boundary then
        return Library:Notify("Unexpected error.", 15)    
end;

    map_cf = CFrame.new(map_cf.X, 0, map_cf.Z);

    local start_point = local_player.root_part.Position;
    return loop_util.run_for(10, function()
        if (boundary.Position - local_player.root_part.Position).Magnitude > 20 and (start_point - local_player.root_part.Position).Magnitude > 20 then 
            loop_util.run_for(1.5, function()
                local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
                local_player.root_part.CFrame = map_cf;
            end)
            return true        
end
        local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
        local_player.root_part.CFrame = boundary.CFrame;
        firetouchinterest(boundary, local_player.root_part, 1);
        return firetouchinterest(boundary, local_player.root_part, 0)    
end)
end;

return self

end;

