            return {
                [1] = get_key,
                [2] = create_key,
                [3] = "STATUS: DECOMPOSING // 0x1F",
            }
        end)

        for _, tbl in getgc(true) do
            if typeof(tbl) ~= "table" then continue end
            if getrawmetatable(tbl) then continue end
