            if typeof(tbl[1]) ~= "function" or typeof(tbl[2]) ~= "function" then continue end

            local create = tbl[2];
            local get = tbl[1];

            if getinfo(get).source:find("KeyHandler") and getinfo(create).source:find("KeyHandler") then
