function loader.initialize()
    local loaded, failed, skipped = 0, 0, 0;

    for id, module in pairs(MODULES) do
        if aztup.features[id] then
            loaded = loaded + 1;
            continue;
        end;

        local ok, feature = pcall(require, module);
        if not ok then
            failed = failed + 1;
            warn(string.format("[features] %s (%s) failed to load: %s", id, module, tostring(feature)));
            continue;
        end;

        if feature == nil then
            -- Side-effect module. src/features/auto-parry/auto-parry.lua is the
            -- example: it returns nil, but requiring it installs the projectile
            -- handlers and publishes getgenv().DefendActionManager, which
            -- animator-handler calls 56 times. It is flag-driven, not a Feature,
            -- so there is nothing to register — loading it is the whole job.
            loaded = loaded + 1;
        elseif type(feature) == "table" and type(feature.disable) == "function" then
            aztup.features[id] = feature;
            loaded = loaded + 1;
        elseif type(feature) == "table" then
            -- A plain table, not a Feature. Registering it would make
            -- init.lua's detach call a disable() that does not exist
            -- ("[detach none] attempt to call missing method 'disable'").
            skipped = skipped + 1;
        elseif type(feature) == "function" then
            -- button-style module: the UI wires these through Func, not features
            aztup.functions = aztup.functions or {};
            aztup.functions[id] = feature;
            loaded = loaded + 1;
        else
            failed = failed + 1;
            warn(string.format("[features] %s (%s) returned %s", id, module, type(feature)));
        end;
    end;

    if skipped > 0 then
        warn(string.format("[features] %d module(s) returned a plain table, not registered", skipped));
    end;

    getgenv().FRUTIGER_registry = { loaded = loaded, failed = failed, modules = MODULES, options = OPTION_ONLY };

    if not aztup.silent_mode and Logger and Logger.log then
        Logger.log(string.format("[features] registered %d, failed %d", loaded, failed));
    end;
end;

function loader.get(id)
    return aztup.features[id];
end;

function loader.is_option(id)
    return table.find(OPTION_ONLY, id) ~= nil;
end;

-- >>> HAND-WRITTEN
-- Nothing hand-written yet. Anything placed between the HAND-WRITTEN
-- markers survives `node tools/gen-registry.js` verbatim. Everything
-- above them is regenerated from the tree and will be replaced.
-- <<< HAND-WRITTEN

return loader;

end;

__modules["src/features/misc/anchor"] = function()
local feat = Feature:new("anchor");

function feat:enable()
    if not local_player.character then return end
    self.effect = EffectReplicator:CreateEffect("FreezeRoot", {});
end;

function feat:disable()
    if self.effect then
        task.defer(function()
            self.effect:Remove(true);
        end);
    end;
end;

return feat

end;

__modules["src/features/misc/apply_fflags"] = function()
local feat = Feature:new("apply_fflags");
local old_flags;

function feat:enable()
    if not isfile("fflags.json") then
        return Logger:long_notify("fflags.json not found, please paste your fflags into the executor workspace under that name.")    
end

    local applying_flags_file = readfile("fflags.json");
    if not applying_flags_file then
        return Logger:long_notify("failed to read file.")    
end

    local success, applying_flags = pcall(function() return services.HttpService:JSONDecode(applying_flags_file) end);
    if not success then
        return Logger:long_notify("failed to decode json, make sure it's valid: " .. applying_flags)    
end

    if persistent_data:get("old_fflags", nil) then
        old_flags = persistent_data:get("old_fflags", nil); 
    else
        old_flags = {};
    end

    for flag, value in old_flags do
        pcall(function() 
            setfflag(flag, value);
        end)
    end

    for flag, value in applying_flags do
        pcall(function() 
            local old_flag = getfflag(flag);
            old_flags[flag] = old_flag;
            setfflag(flag, value);
        end)
    end

    return true
end;

function feat:disable()
    if old_flags then
        for flag, value in pairs(old_flags) do
            pcall(function() setfflag(flag, value) end);
        end
    end
end;

return feat

end;

__modules["src/features/misc/build_stealer"] = function()
local feature = Feature:new("build_stealer")

local toggled = false
local players = game:GetService("Players")
local HttpService = game:GetService("HttpService")

local function getSelectedPlayer()
    local playerName = aztup_options.build_stealer_target.Value
    if playerName and playerName ~= "" then
        return players:FindFirstChild(playerName)
    end
    return nil
end

local function onBuildStealPlayer(player, clipboard)
    if not player then
        return
    end
    
    local character = player.Character
    if not character then
        return
    end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then
        return
    end

    local backpack = player:FindFirstChild("Backpack")
    if not backpack then
        return
    end

    local AttributePoints = 0
    local Power = 0 
    for i, v in pairs(character:GetAttributes()) do
        if i:match("Stat") then
            AttributePoints = AttributePoints + v
        end
    end
    for i = 1, 20 do
        if AttributePoints <= 15 then
            break        
end
        AttributePoints = AttributePoints - 15
        Power = Power + 1
    end

    local level = math.min(20, math.max(1, Power));

    
    local data = {
        version = 3,
        stats = {
            buildName = string.format("%s %s's Stolen Build", os.date("%B %d %Y"), player.Name),
            buildDescription = "Talents are not stealable anymore - This is just the opponents stats.",
            buildAuthor = "frutiger",
            power = level,
            pointsUntilNextPower = 67,
            points = 67,
            pointSpent = 67,
            traitPoints = 0,
            traits = {
                Vitality = character:GetAttribute("Trait_Health"),
                Erudition = character:GetAttribute("Trait_Ether"),
                Songchant = character:GetAttribute("Trait_MantraDamage"),
                Proficiency = character:GetAttribute("Trait_WeaponDamage"),
            },
            meta = {
                Race = "None",
                Oath = "None",
                Murmur = "None",
                Bell = "None",
                Origin = "Castaway",
                Outfit = "None",
            },
        },
        attributes = {
            weapon = {
                ["Heavy Wep."] = character:GetAttribute("Stat_WeaponHeavy"),
                ["Medium Wep."] = character:GetAttribute("Stat_WeaponMedium"),
                ["Light Wep."] = character:GetAttribute("Stat_WeaponLight"),
            },
            base = {
                Strength = character:GetAttribute("Stat_Strength"),
                Fortitude = character:GetAttribute("Stat_Fortitude"),
                Agility = character:GetAttribute("Stat_Agility"),
                Intelligence = character:GetAttribute("Stat_Intelligence"),
                Willpower = character:GetAttribute("Stat_Willpower"),
                Charisma = character:GetAttribute("Stat_Charisma"),
            },
            attunement = {
                Flamecharm = character:GetAttribute("Stat_ElementFire"),
                Frostdraw = character:GetAttribute("Stat_ElementIce"),
                Thundercall = character:GetAttribute("Stat_ElementLightning"),
                Galebreathe = character:GetAttribute("Stat_ElementWind"),
                Shadowcast = character:GetAttribute("Stat_ElementShadow"),
                Ironsing = character:GetAttribute("Stat_ElementMetal"),
                Bloodrend = character:GetAttribute("Stat_ElementBlood"),
            },
        },
        content = {
            mantraModifications = {},
            notes = "",
        },
        meta = {
            tags = {},
            isPrivate = true,
        },
        talents = {},
        mantras = {},
        weapons = "",
        enchant = "",
        motif = "",
        preShrine = {
            base = {
                Strength = 100,
                Fortitude = 100,
                Agility = 100,
                Intelligence = 100,
                Willpower = 100,
                Charisma = 100,
            },
            weapon = {
                ["Heavy Wep."] = 100,
                ["Medium Wep."] = 100,
                ["Light Wep."] = 100,
            },
            attunement = {
                Flamecharm = 100,
                Frostdraw = 100,
                Thundercall = 100,
                Galebreathe = 100,
                Shadowcast = 100,
                Ironsing = 100,
                Bloodrend = 100,
            },
        },
        postShrine = nil,
        favoritedTalents = {},
    }

    data.postShrine = data.attributes

    local meta = data.stats.meta
    local notes = {}

    for _, child in next, backpack:GetChildren() do
        if child.Name:match("Resonance:") then
            meta.Bell = child.Name:gsub("Resonance:", "")
        end

        if child.Name:match("Mantra") and child:GetAttribute("DisplayName") then
            local isRecalled = child.Name:match("RecalledMantra")
            notes[#notes + 1] = (isRecalled and "[RECALLED MANTRA]" or "[USED MANTRA]")
                .. " "
                .. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or "NO RICH STATS?")

            if not isRecalled then
                data.mantras[#data.mantras + 1] = child:GetAttribute("DisplayName")
                data.content.mantraModifications[child:GetAttribute("DisplayName")] = {}
            end
        end

        if child.Name == "Weapon" then
            notes[#notes + 1] = "[USED WEAPON] " .. (child:GetAttribute("RichStats") and child:GetAttribute("RichStats"):gsub("\n", " | ") or child.Name)
        end
    end
    for _, instance in next, character:GetChildren() do
        if instance.Name == "Ring" then
            local ringName = instance:GetAttribute("DisplayName")
                or instance:GetAttribute("EquipmentRef")
                or instance.Name
            notes[#notes + 1] = string.format("[EQUIPPED RING] %s\n", ringName)
                .. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | ") or instance.Name)
        end

        if instance.Name == "Shirt" then
            notes[#notes + 1] = "[EQUIPPED SHIRT ID] " .. instance.ShirtTemplate
        end

        if instance.Name == "Pants" then
            notes[#notes + 1] = "[EQUIPPED PANTS ID] " .. instance.PantsTemplate
        end

        if
            instance.Name:match("Equipment")
            and instance:GetAttribute("RichStats")
            and instance:GetAttribute("DisplayName")
        then
            notes[#notes + 1] = string.format(
                "[EQUIPPED EQUIPMENT] [%s] %s",
                instance.Name,
                instance:GetAttribute("DisplayName")
            ) .. (instance:GetAttribute("RichStats") and instance:GetAttribute("RichStats"):gsub("\n", " | "))
        end
    end

    notes[#notes + 1] = string.format("[HEALTH] %.2f/%.2f", humanoid.Health, humanoid.MaxHealth)

    data.content.notes = table.concat(notes, "\n\n")

    
    local response = request({
        Url = "https://deepwoken.co/api/proxy/builds",
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json",
            ["Accept"] = "application/json",
            ["Origin"] = "https://deepwoken.co",
            ["Referer"] = "https://deepwoken.co/builder",
            ["Sec-Fetch-Site"] = "same-origin",
            ["Sec-Fetch-Mode"] = "cors",
            ["Sec-Fetch-Dest"] = "empty",
        },
        Body = HttpService:JSONEncode(data)
    })

    if not response then
        return
    end

    if not response.Success then
        return
    end

    if not response.Body then
        return
    end

    local decoded = HttpService:JSONDecode(response.Body)

    if not decoded or not decoded.id then
        return
    end

    
    local buildUrl = string.format("https://deepwoken.co/builder?id=%s", decoded.id)
    
    if clipboard then
        setclipboard(buildUrl)
    end

    local path = string.format("%s %s Stolen Build", os.date("%B %d %Y"), player.Name);
    Logger:notify_sound(string.format("Successfully stole %s's build, %s & saved to file.", player.Name, buildUrl))

    if not isfolder("Frutiger/Stolen Builds") then
        makefolder("Frutiger/Stolen Builds")
    end
    writefile("Frutiger/Stolen Builds/" .. path .. ".txt", string.format([[https://decay
stolen on %s
build url: %s
%s]], os.date("%B %d %Y"), buildUrl, data.content.notes));
end

function feature:enable()
    if toggled then 
        return 
    end
    
    toggled = true
    aztup_options.build_stealer_target:OnChanged(function()
        local player = getSelectedPlayer()
        if player then
            onBuildStealPlayer(player,true)
        end
    end)

    if is_chime then
        local stolen = false;
        for _, player in services.Players:GetPlayers() do
            if player ~= services.Players.LocalPlayer then
                onBuildStealPlayer(player)
                stolen = true;
                break            
end
        end

        if not stolen then
            services.Players.PlayerAdded:Connect(function(player)
                if stolen then return end
                task.wait(15);
                onBuildStealPlayer(player)
            end)
        end
    end
    
end

function feature:disable()
    if not toggled then
        return
    end
    
    toggled = false
end

return feature

end;

__modules["src/features/misc/hair_id_stealer"] = function()
local feature = Feature:new("hair_id_stealer")

local toggled = false
local players = game:GetService("Players")

local function getSelectedPlayer()
    local playerName = aztup_options.hair_id_stealer_target.Value 
    if playerName and playerName ~= "" then
        return players:FindFirstChild(playerName)
    end
    return nil
end

local function onHairStealPlayer(player)
    if not player then return end
    
    local liveFolder = workspace:FindFirstChild("Live") and workspace.Live:FindFirstChild(player.Name)
    if not liveFolder then
        warn("Could not find folder for: " .. player.Name)
        return
    end

    local foundIds = {}
    
    for _, item in pairs(liveFolder:GetChildren()) do
        if item.Name:sub(1, 6) == "Asset:" then
            local id = item.Name:match("%d+")
            if id then
                table.insert(foundIds, id)
            end
        end
    end

    if #foundIds > 0 then
        local result = table.concat(foundIds, ", ")
        setclipboard(result)
        
        Logger:notify_sound(string.format("Successfully stole %s's hair IDs. Copied to clipboard.", player.Name))
    else
        Logger:notify_sound("Failed to find any hair IDs for " .. player.Name)
    end
end

function feature:enable()
    if toggled then return end
    toggled = true
    
    aztup_options.hair_id_stealer_target:OnChanged(function()
        if not toggled then return end
        local player = getSelectedPlayer()
        if player then
            onHairStealPlayer(player)
        end
    end)
end

function feature:disable()
    if not toggled then return end
    toggled = false
end

return feature

end;

__modules["src/features/misc/linoria_watermark"] = function()


local last_update = tick();
local custom_name = not LPH_OBFUSCATED and isfile("custom_name.txt") and readfile("custom_name.txt") or nil;
aztup.maid:give_task(scheduler:add_task(0.5):Connect(function()
    if not Latency then return end
    last_update = tick();

    if not services.Stats:FindFirstChild("FrameRateManager") then return end
    
    local frame_rate_manager = services.Stats.FrameRateManager;
    local performance_stats = services.Stats.PerformanceStats;
    local memory_val = performance_stats and performance_stats.Memory;

    local fps = 1000 / frame_rate_manager.RenderAverage:GetValue();
    local color_in_hex = Library.AccentColor:ToHex()

    local show_mem_data = aztup_toggles.WatermarkShowsMem and aztup_toggles.WatermarkShowsMem.Value;

    local watermark, raw_watermark = ('FRUTIGER // <font color=\"#%s\">DECOMPOSING</font> %i<font color="#%s">fps</font> %i<font color="#%s">ms</font>'):format(
        color_in_hex,
        math.floor(fps),
        color_in_hex,
        math.floor(Latency:get_ping() * 1000),
        color_in_hex
    ), ('%s %ifps %ims'):format(
        "FRUTIGER",
        math.floor(fps),
        math.floor(Latency:get_ping() * 1000)
    );

    if memory_val and show_mem_data then
        watermark ..= (' %.2f<font color="#%s">gb</font>'):format(
            memory_val:GetValue() / 1000,
            color_in_hex
        )

        raw_watermark ..= (' %.2fgb'):format(
            memory_val:GetValue() / 1000
        )
    end

    Library:SetWatermark(watermark, raw_watermark); 
end));

return nil

end;

