end);

return

end;

__modules["src/features/misc/override_roblox_reset"] = function()
local feature_class;
feature_class = Feature:new("no_respawn_time");

local original_bindable = Instance.new("BindableEvent");
original_bindable.Event:Connect(function()
    local events = game:GetService("ReplicatedStorage"):FindFirstChild("Requests");
    if not events then return end
    
    events.Reset:FireServer();
end)

local pr_bindable = Instance.new("BindableEvent");
pr_bindable.Event:Connect(require("@src/features/buttons/respawn"))

function feature_class:enable()
    self.was_on = true;

    repeat task.wait() until pcall(function()
        game:GetService("StarterGui"):SetCore("ResetButtonCallback", pr_bindable)
    end);
end;

function feature_class:disable()
    if not self.was_on then return end
    game:GetService("StarterGui"):SetCore("ResetButtonCallback", original_bindable)
end;

return feature_class

end;

__modules["src/features/misc/proximity_list"] = function()
if is_chime then return end



local Converted = {
	["_ScreenGui"] = Instance.new("ScreenGui");
	["_Frame"] = Instance.new("Frame");
	["_TextLabel"] = Instance.new("TextLabel");
	["_UIStroke"] = Instance.new("UIStroke");
	["_Frame1"] = Instance.new("Frame");
	["_TextLabel1"] = Instance.new("TextLabel");
	["_UIStroke1"] = Instance.new("UIStroke");
}

local getasset = getcustomasset;
local sound = {} do
    function sound.new(filePath, speed, volume, isLink, link)
        local self = setmetatable(sound, {});
        
        self.soundAsset = getasset(filePath);
        self.speed = speed;
        self.volume = volume;
        self.sound = Instance.new("Sound", services.CoreGui)
        return self    
end;
    function sound:play()
        self.sound.SoundId = self.soundAsset
        self.sound.PlaybackSpeed = self.speed
        self.sound.Volume = 0;
        game:GetService("TweenService"):Create(self.sound, TweenInfo.new(0.1), {
            Volume = self.volume
        }):Play();
        self.sound:Play();
        game:GetService("Debris"):AddItem(self.sound, 1.5);
    end;
end;

function exit_sound()
    if not aztup.flags.notify_with_sound then return end
    
    sound.new("Frutiger/Assets/proximity.mp3", 0.9, aztup.flags.player_proximity_vol, true):play();
end;

function enter_sound()
    if not aztup.flags.notify_with_sound then return end

    sound.new("Frutiger/Assets/proximity.mp3", 1.1, aztup.flags.player_proximity_vol, true):play();
end;



Converted["_ScreenGui"].Parent = game:GetService("CoreGui")
Converted["_ScreenGui"].DisplayOrder = -1000
Converted["_ScreenGui"].ZIndexBehavior = Enum.ZIndexBehavior.Sibling
Converted["_ScreenGui"].OnTopOfCoreBlur = true;

Converted["_Frame"].ZIndex = 0;
Converted["_Frame"].AnchorPoint = Vector2.new(0.5, 0.5)
Converted["_Frame"].BackgroundColor3 = Library.MainColor
Converted["_Frame"].BorderSizePixel = 2;
Converted["_Frame"].Position = UDim2.new(0.5, 0, 0.15, 0)
Converted["_Frame"].Size = UDim2.new(0, 150, 0, 42)
Converted["_Frame"].Parent = Converted["_ScreenGui"] 
Converted["_Frame"].ClipsDescendants = true;
Library:AddUIScale(Converted["_Frame"]);

local stroke = Instance.new("UIStroke", Converted["_Frame"]);
stroke.Thickness = 1;
stroke.ZIndex = 999;
stroke.Name = "THIS";
stroke.Color = Library.AccentColor; 
stroke.LineJoinMode = Enum.LineJoinMode.Miter;
task.spawn(function()
    repeat task.wait() until lexend.regular;
Converted["_TextLabel"].FontFace = lexend.regular
end);
Converted["_TextLabel"].ZIndex = 1
stroke.ZIndex = Converted["_TextLabel"].ZIndex + 1;
Converted["_TextLabel"].Text = "proximity"
Converted["_TextLabel"].TextColor3 = Library.FontColor
Converted["_TextLabel"].TextSize = 16
Converted["_TextLabel"].TextWrapped = true
Converted["_TextLabel"].BorderSizePixel = 1;
 
Converted["_TextLabel"].BackgroundColor3 = Library.BackgroundColor
Converted["_TextLabel"].BorderColor3 = Library.OutlineColor
Converted["_TextLabel"].Size = UDim2.new(1, 0, 0, 22)
Converted["_TextLabel"].Parent = Converted["_Frame"]

Converted["_UIStroke"].Color = Color3.fromRGB(0, 0, 0)
Converted["_UIStroke"].Parent = Converted["_TextLabel"]


Converted["_Frame1"].BackgroundColor3 = Color3.fromRGB(255, 255, 255)
Converted["_Frame1"].BackgroundTransparency = 1
Converted["_Frame1"].BorderColor3 = Color3.fromRGB(0, 0, 0)
Converted["_Frame1"].BorderSizePixel = 0
Converted["_Frame1"].Position = UDim2.new(0, 0, 0, 22)
Converted["_Frame1"].Size = UDim2.new(1, 0, 1, -22)
Converted["_Frame1"].Parent = Converted["_Frame"]

Converted["_TextLabel1"].FontFace = lexend.regular
Converted["_TextLabel1"].Text = "Ace Yuset - 30m"
Converted["_TextLabel1"].TextColor3 = Library.FontColor
Converted["_TextLabel1"].TextSize = 14
Converted["_TextLabel1"].BackgroundTransparency = 1
Converted["_TextLabel1"].BorderSizePixel = 0
Converted["_TextLabel1"].Size = UDim2.new(1, 0, 0, 20)
Converted["_TextLabel1"].Visible = false;

Converted["_UIStroke1"].Color = Color3.fromRGB(0, 0, 0)
Converted["_UIStroke1"].Parent = Converted["_TextLabel1"]

local character_holder = Converted["_Frame1"];
local sample_label = Converted["_TextLabel1"]:Clone();
local labelMap = {}
local ui_list_layout = Instance.new("UIListLayout", character_holder);
ui_list_layout.FillDirection = Enum.FillDirection.Vertical;
ui_list_layout.SortOrder = Enum.SortOrder.LayoutOrder;

for _, item in Converted do
    if not item:IsA("Frame") and not item:IsA("TextLabel") then continue end
    
    item.InputChanged:Connect(function(input, t)
        if t or input.UserInputType ~= Enum.UserInputType.MouseWheel then return end

        local direction = input.Position.Z > 0 and 1 or -1
        
        for _, item in Converted do
            if not item:IsA("Frame") and not item:IsA("TextLabel") and not item:IsA("UIStroke") then continue end

            if item:IsA("UIStroke") then
                item.Transparency = math.clamp(item.Transparency - (direction * 0.1), 0, 0.9)
                continue            
end

            if item.BackgroundTransparency <= 0.7 then
                item.BackgroundTransparency = math.clamp(item.BackgroundTransparency - (direction * 0.1), 0, 0.7)
            end;
            
            if item.BackgroundTransparency <= 0.7 then
                item.BackgroundTransparency = math.clamp(item.BackgroundTransparency - (direction * 0.1), 0, 0.7)
            end;
            
            if item:IsA("TextLabel") then
                item.TextTransparency = math.clamp(item.TextTransparency - (direction * 0.1), 0, 0.7)
            end
        end; 

        if stroke.Transparency <= 0.7 then
            stroke.Transparency = math.clamp(stroke.Transparency - (direction * 0.1), 0, 0.7)
        end
    end)
end

function clear_objects()
    for _, object in pairs(character_holder:GetChildren()) do
        if object ~= ui_list_layout then
            object:Destroy();
        end;
    end;
end;

function get_in_range()
    local in_range = {};
    for _, player in pairs(services.Players:GetPlayers()) do
        if player == local_player.instance then continue end

        if player.Character and player.Character:FindFirstChild("HumanoidRootPart") and player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.Health > 0 then
            local distance = (local_player.root_part.Position - player.Character.HumanoidRootPart.Position).Magnitude;
            if distance <= aztup.flags.player_proximity_range then
                table.insert(in_range, {player = player, distance = distance});
            end;
        end;
    end;

    return in_range
end;

function update_size()
    
    local size = Vector2.new(130, 22);
    for _, label in character_holder:GetChildren() do
        if label:IsA("UIListLayout") then continue end
        if not label.Visible then
            label:Destroy();
            continue        
end;
        local text_size = label.TextBounds / Library:GetUIScale()

        if size.X < text_size.X then
            size = Vector2.new(text_size.X, size.Y)
        end

        size += Vector2.new(0, 20)
    end;

    if size.Y <= 23 then
        Converted._ScreenGui.Enabled = false;
    end;

    Converted._Frame.Size = UDim2.new(0, size.X + 20, 0, size.Y);
    
end;

local function format_distance(distance)
	return aztup_options.distance_naming.Value == "studs" and ("%is"):format(distance) or (distance > 1000 and ("%.1fkm"):format(distance / 1000) or ("%im"):format(distance))
end;

function add_object(name, distance, voidwalker, char)
    local new_label: TextLabel = sample_label:Clone();
    new_label.Text = name .. " (" .. format_distance(distance) .. ")";
    new_label.TextTransparency = 0;
    new_label.TextColor3 = voidwalker and Library.AccentColor or Library.FontColor;
    new_label.Visible = true;
    new_label.Parent = character_holder;
    update_size();

    local clicked = new_label.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end

        aztup.features.leaderboard_spectate:force_spectate(char)
    end)

    new_label:GetPropertyChangedSignal("Parent"):Once(function() 
        clicked:Disconnect();
    end);
    
    return new_label
end;

Library:AddToRegistry(Converted["_Frame"], {
    BackgroundColor3 = "MainColor"
})

Library:AddToRegistry(stroke, {
    Color = "AccentColor"
}, true)

Library:AddToRegistry(Converted["_TextLabel"], {
    BackgroundColor3 = "BackgroundColor",
    TextColor3 = "FontColor",
})

Library:AddToRegistry(sample_label, {
    TextColor3 = "FontColor"
})    

Library:MakeDraggableScale(Converted["_Frame"], 22, true); 
aztup.proximity = Converted["_Frame"];
aztup.maid:give_task(Converted["_ScreenGui"]);
Converted["_ScreenGui"].Enabled = false;

clear_objects();



local function sync_labels(currently_in_range)
    
    table.sort(currently_in_range, function(a, b)
        
        
        return a.distance < b.distance    
end)

    local seen = {}
    local updated = false
    local order = 0

    for _, data in ipairs(currently_in_range) do
        local plr = data.player
        local key = plr.UserId
        seen[key] = true

        local label = labelMap[key]
        local txt = (plr:GetAttribute("CharacterName") or plr.Name) .. " (" .. format_distance(data.distance) .. ")"

        if not label or not label.Parent then
            enter_sound()

            local is_voidwalker = plr:FindFirstChild("Backpack") and (plr.Backpack:FindFirstChild("Talent:Voideye") or plr.Backpack:FindFirstChild("Talent:Grasp of Eylis"));
            if aztup.flags.notify_in_range then
                Logger:notify((plr:GetAttribute("CharacterName") or "") .. " [" .. plr.Name .. "]" .. " has entered your proximity range" .. (is_voidwalker and not is_depths and ", User is a voidwalker." or "."));
            end;

            label = add_object(plr:GetAttribute("CharacterName") or plr.Name, data.distance, is_voidwalker and not is_depths, plr)
            labelMap[key] = label
            updated = true
        else
            if label.Text ~= txt then
                label.Text = txt
                updated = true
            end
        end

        
        label.LayoutOrder = order
        order += 1
    end

    for key, label in pairs(labelMap) do
        if not seen[key] then
            
            if aztup.flags.notify_in_range then 
                
                local plr = services.Players:GetPlayerByUserId(key)
                if not plr then 
                    Logger:notify("A logged out player has left your proximity range."); 
                else
                    Logger:notify((plr:GetAttribute("CharacterName") or "") .. " [" .. plr.Name .. "]" .. " has left your proximity range.");
                end;
                
                
            end;

            exit_sound();
            label:Destroy()
            labelMap[key] = nil
            updated = true
        end
    end

    if updated then
        update_size()
    end
end

local feature = Feature:new("proximity_list", scheduler:add_task(0.15), function()
    if not local_player.character or not local_player.root_part then return end
    local frame = Converted["_Frame"];
    local y_scale = frame.Position.Y.Scale;
    
    local y_offset = frame.AbsoluteSize.Y / 2;

    if y_scale >= 0.5 then
        y_offset = -y_offset;
    end
    Converted["_Frame"].Position = UDim2.new(frame.Position.X.Scale, 0, y_scale, y_offset)

    if Library.Toggled or Converted._Frame.Size.Y.Offset >= 23 then
        Converted._ScreenGui.Enabled = aztup.flags.show_list;
    elseif Converted._Frame.Size.Y.Offset <= 23 then
        Converted._ScreenGui.Enabled = false;
    end

    local currently_in_range = get_in_range()
    sync_labels(currently_in_range)
end);


function feature:enable()
    table.clear(labelMap);
    clear_objects();
    update_size();

    Converted["_ScreenGui"].Enabled = true;
end;

function feature:disable()
    Converted["_ScreenGui"].Enabled = false;
end;

function feature:set_transparency(trans)
    for _, item in Converted do
        if not item:IsA("Frame") and not item:IsA("TextLabel") and not item:IsA("UIStroke") then continue end

        if item:IsA("UIStroke") then
            item.Transparency = math.clamp(trans, 0, 0.9)
            continue        
end

        if item.BackgroundTransparency <= 0.7 then
            item.BackgroundTransparency = math.clamp(trans, 0, 0.7)
        end;
        
        if item.BackgroundTransparency <= 0.7 then
            item.BackgroundTransparency = math.clamp(trans, 0, 0.7)
        end;
        
        if item:IsA("TextLabel") then
            item.TextTransparency = math.clamp(trans, 0, 0.7)
        end
    end; 

    if stroke.Transparency <= 0.7 then
        stroke.Transparency = math.clamp(trans, 0, 0.7)
    end
end

return feature

end;

__modules["src/features/misc/spotify_widget"] = function()
--[[
    src/features/misc/spotify_widget.lua  — STUB

    Stripped from the OSS release. Required by src/ui/tabs/ui.lua:3, and
    src/utility/librarys/managers/SaveManager.lua reads
    aztup.spotify_widget.Position when saving window layout.

    Returns a table whose `new` yields a widget-shaped object with a settled
    Position, so the save path has something to serialise instead of nil.
]]

local widget = {};
widget.__index = widget;

widget.new = function()
    return setmetatable({
        Position = UDim2.fromOffset(0, 0),
        Visible = false,
    }, widget);
end;

function widget:SetVisible(value)
    self.Visible = value and true or false;
    return self;
end;

function widget:Destroy()
    return nil;
end;

return widget;

end;

__modules["src/features/misc/streamer_mode"] = function()

local server_region;
local server_name;
local server_age;

local feat = Feature:new("streamer_mode", services.RunService.Stepped, function() 
    local_player.instance:SetAttribute("Hidden", true);
end);

function feat:get_name(str)
	local hash = 0

	for i = 1, #str do
		hash = bit32.band(hash * 31 + string.byte(str, i), 0xFFFFFFFF)
	end

	if hash >= 0x80000000 then
		hash -= 0x100000000
	end

	return string.format("%08x", hash)
end

function feat:enable()
    server_region = game:GetService("ReplicatedStorage"):WaitForChild("SERVER_REGION");
    server_name = game:GetService("ReplicatedStorage"):WaitForChild("SERVER_NAME");
    server_age = game:GetService("ReplicatedStorage"):WaitForChild("SERVER_AGE");

    for _, object in local_player.instance:GetDescendants() do
        if object.Name == "Slot" and object.Parent.Name == "CharacterInfo" then
            object.Text = object.Text:gsub(local_player.instance.UserId, "0");
        elseif object.Name == "Character" and object.Parent.Name == "CharacterInfo" then
            object.Text = "";
        end 
    end;

    if not server_region.Value:find("USA") then
        server_region.Value = server_region.Value:split(", ")[#server_region.Value:split(", ")]
    end
    server_name.Value = game.JobId:sub(1,8)
    server_age.Value = "0d 0h 0m";

    self.server_age_connection = server_age.Changed:Connect(function()
        if server_age.Value == "0d 0h 0m" then return end
        server_age.Value = "0d 0h 0m";
    end);
end;

function feat:disable()
    if self.server_age_connection then
        self.server_age_connection:Disconnect();
        self.server_age_connection = nil;
    end
end;

return feat

end;

__modules["src/features/misc/talent_highlighter"] = function()



local OriginalStore = {}
OriginalStore.__index = OriginalStore
function OriginalStore.new()
    return setmetatable({stored = false}, OriginalStore)
end
function OriginalStore:mark(data, index)
    if not self.stored then
        self.data, self.index, self.value, self.stored = data, index, data[index], true
    end
end
function OriginalStore:set(data, index, value)
    self:mark(data, index)
    data[index] = value
end
function OriginalStore:restore()
    if self.stored then
        pcall(function() self.data[self.index] = self.value end)
        self.stored = false
    end
end

local OriginalStoreManager = {}
OriginalStoreManager.__index = OriginalStoreManager
function OriginalStoreManager.new()
    return setmetatable({inner = {}}, OriginalStoreManager)
end
function OriginalStoreManager:add(data, index, value)
    local object = self.inner[data] or OriginalStore.new()
    object:set(data, index, value)
    self.inner[data] = object
end
function OriginalStoreManager:restore()
    for _, store in next, self.inner do
        store:restore()
    end
    self.inner = {}
end

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local HttpService = game:GetService("HttpService")
local RunService = game:GetService("RunService")

local TalentPickerData = nil
local TalentsData = nil
local talentHighlighterMap = OriginalStoreManager.new()
local virtualElements = {}
local isRefreshing = false

local nameCache = {}
local buildLookup = {}
local lastUpdate = 0
local UPDATE_INTERVAL = 0.5 

local function cleanName(str)
    if not str or str == "" then return "" end
    if nameCache[str] then return nameCache[str] end
    local cleaned = str:gsub(" [HVY]", ""):gsub(" [LHT]", ""):gsub(" [MED]", ""):lower():gsub("%s*%[.-%]%s*", " "):gsub("^%d+", ""):gsub("z%w+divider", ""):gsub("[^%a%d]", "")
    nameCache[str] = cleaned
    return cleaned
end

local function checkReqs(talent, stats)
    if not talent or not stats then return false end
    if talent.requirements and talent.requirements.stats then
        for stat, required in pairs(talent.requirements.stats) do
            local current = stats[stat] or 0
            if current < required then
                return false
            end
        end
        return true
    end
    if talent.reqs then
        for _, cat in ipairs({"base", "weapon", "attunement"}) do
            local catReqs = talent.reqs[cat]
            if catReqs then
                for stat, required in pairs(catReqs) do
                    if required > 0 then
                        local current = stats[stat] or 0
                        if current < required then
                            return false
                        end
                    end
                end
            end
        end
        return true
    end
    return false
end

local function getTableLength(t)
    local count = 0
    for _ in pairs(t or {}) do count = count + 1 end
    return count
end

local function flattenAttributes(attrs)
    if not attrs then return {} end
    local flattened = {}
    if attrs.weapon then
        for k, v in pairs(attrs.weapon) do
            flattened[k] = v
        end
    end
    if attrs.attunement then
        for k, v in pairs(attrs.attunement) do
            flattened[k] = v
        end
    end
    if attrs.base then
        for k, v in pairs(attrs.base) do
            flattened[k] = v
        end
    end
    return flattened
end

local function normalizeBuildData(data)
    if not data then return nil end
    return {
        talents = data.talents or {},
        mantras = data.mantras or {},
        attributes = flattenAttributes(data.attributes),
        preShrine = flattenAttributes(data.preShrine),
    }
end

local function refreshMissingTalents()
    if not TalentPickerData or isRefreshing then return end
    isRefreshing = true
    
    local backpack = LocalPlayer.PlayerGui:FindFirstChild("BackpackGui")
    if not backpack then isRefreshing = false return end
    
    local talentScroll = backpack.RightFrame.TalentSheet.Container.TalentScroll
    if not talentScroll then isRefreshing = false return end
    
    for _, el in pairs(virtualElements) do if el then el:Destroy() end end
    table.clear(virtualElements)
    
    local template = nil
    for _, child in ipairs(talentScroll:GetDescendants()) do
        if (child:IsA("Frame") or child:IsA("TextButton")) and not child.Name:find("Missing_") then
            if child:FindFirstChild("Title") and child:FindFirstChild("Icon") then
                template = child
                break
            end
        end
    end
    
    if not template then isRefreshing = false return end
    
    local par = talentScroll
    for _, item in ipairs(talentScroll:GetDescendants()) do
        if item.Name == "Outfit" or item.Name == "Quest" or item.Name == "Race" then
            par = item
            break
        end
    end
    
    local ownedNames = {}
    for _, item in ipairs(talentScroll:GetDescendants()) do
        local title = item:FindFirstChild("Title")
        if title and not item.Name:find("Missing_") then 
            ownedNames[cleanName(title.Text)] = true 
        end
    end
    
    for _, plannedName in ipairs(TalentPickerData.talents or {}) do
        local cleanedPlanned = cleanName(plannedName)
        if not ownedNames[cleanedPlanned] then
            local clone = template:Clone()
            clone.Name = "Missing_" .. cleanedPlanned
            clone.BackgroundColor3 = Color3.new(1, 1, 1)
            clone.BackgroundTransparency = 0.95
            
            local title = clone:FindFirstChild("Title")
            if title then
                title.Text = plannedName
                title.TextColor3 = Library.AccentColor
                title.TextTransparency = 0
            end
            
            local icon = clone:FindFirstChild("Icon")
            if icon then icon.Visible = false end
            
            local stroke = clone:FindFirstChildOfClass("UIStroke") or Instance.new("UIStroke", clone)
            stroke.Enabled, stroke.Transparency, stroke.Thickness = true, 0.8, 1
            stroke.Color = Color3.new(1, 1, 1)
            
            table.insert(virtualElements, clone)
            clone.Parent = par
        end
    end
    
    task.delay(0.5, function() isRefreshing = false end)
end

local function applyHighlight(item, talentScroll)
    if not TalentPickerData or not TalentsData then return end
    
    local title = item:FindFirstChild("Title")
    local border = item:FindFirstChild("Border")
    
    local innerCard = item:FindFirstChild("CardFrame")
    if innerCard then
        border = border or innerCard:FindFirstChild("Border")
        title = title or innerCard:FindFirstChild("Title")
    end
    
    if not border then
        for _, child in ipairs(item:GetChildren()) do
            if child:IsA("ImageLabel") and child.Name ~= "Icon" then
                border = child
                break
            end
        end
    end
    
    if title or border then
        local nameText = (title and title.Text ~= "") and title.Text or item.Name
        local cleanedLabel = cleanName(nameText)
        local cleanedUncleaned = nameText:lower()
        
        if cleanedLabel:match('roll2') or cleanedLabel:match('fold') then return end
        
        local targetColor = Color3.fromRGB(255, 0, 100)
        
        for _, mantraName in ipairs(TalentPickerData.mantras or {}) do
            if cleanName(mantraName):match(cleanedLabel) then
                targetColor = Color3.fromRGB(0, 255, 120)
                break
            end
        end
        
        if buildLookup[cleanedLabel] then
            local talentObj = TalentsData.talents and TalentsData.talents[cleanedUncleaned]
            if talentObj then
                local preCheck = checkReqs(talentObj, TalentPickerData.preShrine)
                local postCheck = checkReqs(talentObj, TalentPickerData.attributes)
                local isPre = preCheck and not postCheck
                if isPre then
                    targetColor = Color3.fromRGB(255, 187, 0)
                else
                    targetColor = Color3.fromRGB(0, 255, 120)
                end
            else
                targetColor = Color3.fromRGB(0, 255, 120)
            end
        end
        
        if item.Name:find('Missing_') then
            local talentObj = TalentsData.talents and TalentsData.talents[cleanedUncleaned]
            if talentObj then
                local preCheck = checkReqs(talentObj, TalentPickerData.preShrine)
                local postCheck = checkReqs(talentObj, TalentPickerData.attributes)
                local isPre = preCheck and not postCheck
                if isPre then
                    targetColor = Color3.fromRGB(247, 0, 255)
                else
                    targetColor = Color3.fromRGB(255, 187, 0)
                end
            else
                targetColor = Color3.fromRGB(255, 187, 0)
            end
        end
        
        if title and talentScroll and title:IsDescendantOf(talentScroll) then
            talentHighlighterMap:add(title, "TextColor3", targetColor)
            talentHighlighterMap:add(title, "TextTransparency", 0.25)
            local stroke = title:FindFirstChildOfClass("UIStroke")
            if stroke then
                talentHighlighterMap:add(stroke, "Color", targetColor)
                talentHighlighterMap:add(stroke, "Transparency", 0.25)
            end
        end
        
        if border and border:IsA("ImageLabel") and border.Name ~= "Icon" then
            talentHighlighterMap:add(border, "ImageColor3", targetColor)
        end
    end
end

local function applyAttributes()
    local preshrineLabels = {
        ["Heavy Wep."] = local_player.instance.PlayerGui.BackpackGui.RightFrame.JournalFrame.Panels.AttributeFrame.Sheets.RightSheets.WeaponSheet.Container.WeaponHeavy.Abbrev,
