__modules["src/features/movement/knocked_ownership"] = function()
local self = Feature:new("knocked_ownership", is_chime and Instance.new("BindableEvent").Event or game:GetService("RunService").RenderStepped);

local picked_tool;

function self:pick()
    local parts = {};

    for _, handle in local_player.instance.Backpack:QueryDescendants("Tool > BasePart") do
        if handle.Name ~= "Handle" then continue end
     
        local tool = handle.Parent;
        if tool:FindFirstChildWhichIsA("LuaSourceContainer") and not tool:FindFirstChild("Training") or tool.Name == "Weapon Manual" then continue end
     
        table.insert(parts, handle);
    end;

    table.sort(parts, function(a, b)
        return a.Size.Magnitude < b.Size.Magnitude    
end)

    return parts[1] and parts[1].Parent
end

function self:equip()
    picked_tool = self:pick();
    if not picked_tool then return end

    local_player.humanoid:EquipTool(picked_tool);
end;

function self:unequip()
    if not picked_tool or picked_tool.Parent ~= local_player.character then return end

    picked_tool.Parent = local_player.instance.Backpack;
    picked_tool = nil;
end;

function self.update()
    if not EffectReplicator:FindEffect("Knocked") then
        self:unequip();
        return    
end

    local character = local_player.character;
    if not character then return end

    if not picked_tool then
        self:equip();
    else
        self:unequip();
    end;
end;

function self:disable()
    self:unequip();
end;

return self

end;

__modules["src/features/movement/multiply_s"] = function()
local RunService = game:GetService("RunService")
local last_update = 0;
local random = Random.new();
local speed_mult = 1;

local self;
self = Feature:new("multiply_s", RunService.RenderStepped, LPH_NO_VIRTUALIZE(function(dt)
    local min = math.min(aztup.flags.min_speed_mult, aztup.flags.max_speed_mult);
    local max = math.max(aztup.flags.min_speed_mult, aztup.flags.max_speed_mult);

    speed_mult = random:NextInteger(min, max);

    if tick() - last_update > 0.1 and not (aztup_options.multiplier_type.Value == "CFrame (legit)" or aztup_options.multiplier_type.Value == "CFrame (blatant)")  then
        last_update = tick();
            
        self.speed_mult = speed_mult;
    elseif (aztup_options.multiplier_type.Value == "CFrame (legit)" or aztup_options.multiplier_type.Value == "CFrame (blatant)") and local_player.humanoid.WalkSpeed > 5 then
        if aztup_options.multiplier_type.Value == "CFrame (legit)" and local_player.humanoid.WalkSpeed < 6 or local_player.humanoid.MoveDirection.Magnitude <= 0 then
            return        
end;

        local_player.root_part.CFrame += (local_player.humanoid.MoveDirection.Unit * dt) * (speed_mult / 10);
        self.speed_mult = 0;
    end;
end));

function self:enable()
    last_update = 0;
end;

return self

end;

