    if not EffectReplicator:FindEffect("TPSafe") then
        EffectReplicator:CreateEffect("TPSafe");
    end;

    for _, part in local_player.character:QueryDescendants('BasePart[CanCollide = true]') do
        part.CanCollide = false;
        
        if not table.find(modified_parts, part) then
            table.insert(modified_parts, part);
        end;
    end;

    return
end));

function feature:disable()
    for _, modified_part in modified_parts do
        modified_part.CanCollide = true;
    end;

    table.clear(modified_parts);
end;

return feature

end;

__modules["src/features/movement/speed"] = function()
local feature = Feature:new("speed", game:GetService("RunService").PreSimulation, LPH_NO_VIRTUALIZE(function()
    if is_chime and aztup.flags.chime_safety then
        return aztup_toggles.speed:SetValue(false)    
end;

    if aztup.flags.fly then return end


    local direction = Vector3.zero;

    if local_player.humanoid.MoveDirection.Magnitude > 0 then
        direction = local_player.humanoid.MoveDirection.Unit;
    end

    local_player.root_part.AssemblyLinearVelocity *= Vector3.new(0,1,0);
    local_player.root_part.AssemblyLinearVelocity += direction * aztup.flags.walk_speed

    local sensor = local_player.root_part:FindFirstChild("GroundSensor");
    if sensor and sensor.SensedPart then
        local sensed_part = sensor.SensedPart;
        if sensed_part.CollisionGroup == "Ship" then
            local ship_model = sensed_part:FindFirstAncestorOfClass("Model");
            if ship_model and ship_model:FindFirstChild("BodyVelocity", true) then
                local velocity = ship_model:FindFirstChild("BodyVelocity", true).Velocity;
                local_player.root_part.AssemblyLinearVelocity += Vector3.new(velocity.X, 0, velocity.Z);
            end
        end
    end

    return
end));

function feature:enable()
    EffectReplicator:CreateEffect("OverrideSpeedCap");
end;

function feature:disable()
    local effect = EffectReplicator:FindEffect("OverrideSpeedCap");
    if effect then
        effect:Debris(1);
    end;
end;

return feature

end;

__modules["src/features/movement/tick_rate"] = function()
local RunService = game:GetService("RunService")
local last_update = 0;
local random = Random.new();
local last = tick();
local tick_rate = 1;

local feat = Feature:new("tickrate", RunService.RenderStepped, LPH_NO_VIRTUALIZE(function()
    if EffectReplicator:FindEffect("Knocked") or EffectReplicator:FindEffect("Ragdoll") then return end
    
    local now = tick()
    local dt = now - last

    if dt < 1/12.5 then
        return
    end

    if aztup.flags.fly or aztup.flags.speed or aztup.flags.vehicle_speed then
        last_update = now;
        last = now;
        return    
end

    if now - last_update > 1.5 and aztup and aztup.flags then
        local min = math.min(aztup.flags.min_tick_rate, aztup.flags.max_tick_rate);
        local max = math.max(aztup.flags.min_tick_rate, aztup.flags.max_tick_rate);

        tick_rate = random:NextInteger(min, max);
        last_update = now;
    end

    services.RunService:Pause()
    workspace:StepPhysics(dt * (tick_rate / 100), { local_player.root_part })
    services.RunService:Run()

    last = now;
end));

function feat:enable()
    last = tick();
    last_update = 0;
end;

return feat

end;

__modules["src/features/qol/aggressive_optimize_game"] = function()
local self = Feature:new("aggressive_optimize_game");

local function is_on()
    return aztup.flags.aggressive_optimize_game
end

function self:opti_world_client()
    local last_world_client_func;
    local function apply()
        task.wait(1);

        local hi = "WorldClient";
        local cns = getconnections(services.RunService.PreRender);
        return LPH_NO_VIRTUALIZE(function() 
            local conn;
            for _, object in cns do
                local func = object.Function;
                if not func or not getinfo(func).source:find(hi) then
                    continue                
end
            
                if last_world_client_func == func then
                    return task.delay(1, apply)                
end
            
                last_world_client_func = func;
                object:Disable();
                conn = object;
            end
        
            local last_update = tick();
        
            return services.RunService.PreRender:Connect(function()
                if tick() - last_update < 1 / 15 or not conn then return end
                last_update = tick();

                return conn:Fire(tick() - last_update)
            end)
        end)()    
end;

    apply();
    local_player.instance.PlayerGui.ChildAdded:Connect(function(object) 
        if not is_on() then return end
        if object.Name ~= "WorldClient" then return end

        apply();
    end)
end


self.enable = function()
    if aztup.automation:has_any() or aztup.automation:should_auto_start() then return end

    self:opti_world_client();
    return
end;

return self

end;

