return Feature:new("roll2_revealer", scheduler:add_task(2.75), function()
    last_update = tick();

    local player_gui = local_player.instance:FindFirstChild("PlayerGui")
    if not player_gui then return end
    local talent_gui = player_gui:FindFirstChild("TalentGui");
    if not talent_gui then return end
    local choice_frame = talent_gui:FindFirstChild("ChoiceFrame");
    if not choice_frame then return end


    for _, choice in choice_frame:GetChildren() do
        local card_frame = choice:FindFirstChild("CardFrame");
        if not card_frame then continue end
        local title = card_frame:FindFirstChild("Title"); 
        if not title or title.Text ~= "Roll 2" then continue end 

        for _, item in game:GetService("ReplicatedStorage").Requests.Get:InvokeServer().TalentChoice.Selection do
            if item.Name == "Roll 2" then
                title.Text = "Revealed Roll 2";
                card_frame.Details.Desc.Text = "\nwill be a mix of these:\n" .. item.Selection[1].Name .. ", " .. item.Selection[2].Name.. ", " .. item.Selection[3].Name.. ", " .. item.Selection[4].Name;
            end
        end;
    end;
end)

end;

__modules["src/features/spoofing/agility_spoofer"] = function()

local last_update = 0
local feature
local old_agility
local was_on = false
local parser = require("@src/utility/deepwoken/ssv_parser");

feature = Feature:new("agility_spoofer", game:GetService("RunService").Heartbeat, (function()
        if tick() - last_update < (aztup.flags.agility_spoof_health and 0.075 or 1) then return end
        last_update = tick()

        local character = local_player.character
        if not character then return end

        local passive = character:FindFirstChild("PassiveAgility")
        if not passive then return end

        if aztup.flags.agility_spoofer then
            if not was_on then
                old_agility = passive.Value
                was_on = true
            end

            local target_agility = 8 + (aztup.flags.agility_spoof_amount / 10) * 2;
            if aztup.flags.agility_spoof_health then
                target_agility *= 1 + math.clamp((local_player.humanoid.Health / local_player.humanoid.MaxHealth) * aztup.flags.disallow_scaling_multiplier, 0, aztup.flags.disallow_scaling_multiplier);
            end
            

            passive.Value = target_agility;
        elseif was_on then
            passive.Value = old_agility
            was_on = false
        end
    end
))

function feature:enable()
    local character = local_player.character
    if not character then return end

    local passive = character:FindFirstChild("PassiveAgility")
    if passive then
        old_agility = passive.Value
        was_on = true
    end
end

function feature:disable()
    if not was_on then return end

    local character = local_player.character
    if not character then return end

    local passive = character:FindFirstChild("PassiveAgility")
    if passive and old_agility then
        passive.Value = old_agility
    end

    was_on = false
end

return feature

end;

