local feature = Feature:new("chain_counter");
feature.current = Converted["_Frame"];

local sg = Instance.new("ScreenGui", game:GetService("CoreGui"));
sg.IgnoreGuiInset = true;
sg.Enabled = false;
feature.current.Parent = sg;
aztup.maid:give_task(sg);

function feature:enable()
    sg.Enabled = true;
	feature.stacks = 0;

	self.added_hook = EffectReplicatorHandler:hook("added", function(effect)
		setthreadidentity(8)
		if effect.Class == "PerfectStack" then
			for _, frame in pairs(feature.current:GetChildren()) do
				services.TweenService:Create(frame, TweenInfo.new(1), {
					BackgroundTransparency = 1
				}):Play();
			end;
			feature.stacks = 0;
		elseif effect.Class == "PerfectionCool" then
			feature.stacks = math.min(feature.stacks + 1, 20);

			for _, frame in pairs(feature.current:GetChildren()) do
				if tonumber(frame.Name) > feature.stacks then
					services.TweenService:Create(frame, TweenInfo.new(1), {
						BackgroundTransparency = 1
					}):Play();
					continue				
end;

				services.TweenService:Create(frame, TweenInfo.new(0.25), {
					BackgroundTransparency = 0.65
				}):Play();
			end;
		end
	end);
	
	self.removing_hook = EffectReplicatorHandler:hook("removed", function(effect)
		if effect.Class == "PerfectStack" then
			for _, frame in pairs(feature.current:GetChildren()) do
				services.TweenService:Create(frame, TweenInfo.new(1), {
					BackgroundTransparency = 1
				}):Play();
			end;
			feature.stacks = 0;
			
		end;
	end);

	
    for _, frame in pairs(feature.current:GetChildren()) do
        frame.BackgroundTransparency = 1;
    end;
end;

function feature:disable()
	if self.removing_hook then
		self.added_hook:remove();
		self.removing_hook:remove();
	end;

    sg.Enabled = false;

    for _, frame in pairs(feature.current:GetChildren()) do
        frame.BackgroundTransparency = 1;
    end;
end;

return feature

end;

__modules["src/features/visuals/free_cam"] = function()
local old_y;
local feature;
local last_restream = tick();
local safe_spot = false;
feature = Feature:new("free_cam", services.RunService.RenderStepped, function() 
    if not local_player.character then return end
    
    feature.freecam.set_speed(aztup.flags.free_cam_speed or 1);
    if not aztup.flags.safe_spot then return end
    safe_spot = true;
    if tick() - last_restream > 2.5 then
        last_restream = tick();
        task.spawn(pcall, function() 
            local_player.instance:RequestStreamAroundAsync(workspace.CurrentCamera.CFrame.Position, 1000);
        end)
    end;

    
    
    
    
    
    
    local_player.root_part.AssemblyLinearVelocity = Vector3.zero;
    local_player.root_part.CFrame = CFrame.new(local_player.root_part.Position.X, old_y + 100000, local_player.root_part.Position.Z);
end);

function feature:enable()
    old_y = local_player.root_part and local_player.root_part.Position.Y or 0;
    
    feature.freecam = require("@src/utility/freecam");
    feature.freecam.enter();
    
    feature.was_in = true;
    safe_spot = false;
    local_player.instance:SetAttribute("Freecam", true);
end;

function feature:disable()
    if not self.was_in then return end
    local_player.instance:SetAttribute("Freecam", false);

    if safe_spot then 
        local_player.root_part.CFrame = CFrame.new(local_player.root_part.Position.X, old_y, local_player.root_part.Position.Z);
    end

    feature.freecam.exit();
end;

return feature

end;

