        end;
    
        local pr_player_container = Instance.new("Folder", game:GetService("CoreGui"));
        pr_player_container.Name = "FRUTIGER_PLAYER_CONTAINER";

        local character_map = {};
    
        function PlayerESP.new(character, player)
