__modules["src/utility/asset_id"] = function()









local AssetId = {}


local PROTOCOL = {
    UNKNOWN = 1,
    NULL = 2,
    RBXASSET = 3,
    RBXTEMP = 4,
    RBXASSETID = 5,
    ENCRYPTEDASSETID = 6,
    HTTP = 7,
    FILE = 8,
    RBXHTTP = 9,
    RBXAPP = 10,
    RBXTHUMB = 11,
    RBXGAMEASSET = 12,
    RBXASSETHASH = 13,
    RBXRUNTIME = 14,
}

AssetId.PROTOCOL = PROTOCOL



local function compare_eq(str: string, pos: number, len: number, s: string): boolean
    return string.sub(str, pos + 1, pos + len) == s
end



function AssetId.classify(str: string): number
    local len = #str

    if len == 0 then
        return PROTOCOL.NULL
    end

    if len < 10 then
        if len < 5 then
            return PROTOCOL.UNKNOWN
        end
    elseif compare_eq(str, 0, 3, "rbx") then
        local c = string.byte(str, 4)

        if c == 116 then 
            if compare_eq(str, 4, 6, "emp://") then
                return PROTOCOL.RBXTEMP
            end

            return compare_eq(str, 4, 7, "humb://") and PROTOCOL.RBXTHUMB or PROTOCOL.UNKNOWN
        end

        if c == 97 then 
            if compare_eq(str, 4, 11, "ssethash://") then
                return PROTOCOL.RBXASSETHASH
            elseif compare_eq(str, 4, 7, "sset://") then
                return PROTOCOL.RBXASSET
            elseif compare_eq(str, 4, 9, "ssetid://") then
                return PROTOCOL.RBXASSETID
            end

            return compare_eq(str, 4, 5, "pp://") and PROTOCOL.RBXAPP or PROTOCOL.UNKNOWN
        end

        if len < 23 then
            if len == 10 then
                return PROTOCOL.UNKNOWN
            end
        elseif compare_eq(str, 3, 19, "encryptedassetid://") then
            return PROTOCOL.ENCRYPTEDASSETID
        end

        if compare_eq(str, 3, 7, "http://") then
            return PROTOCOL.RBXHTTP
        end

        if len < 16 then
            if len < 14 then
                return PROTOCOL.UNKNOWN
            end
        elseif compare_eq(str, 3, 12, "gameasset://") then
            return PROTOCOL.RBXGAMEASSET
        end

        return compare_eq(str, 3, 10, "runtime://") and PROTOCOL.RBXRUNTIME or PROTOCOL.UNKNOWN
    end

    
    if compare_eq(str, 0, 4, "http") then
        return PROTOCOL.HTTP
    end

    if len >= 8 and compare_eq(str, 0, 7, "file://") then
        return PROTOCOL.FILE
    end

    return PROTOCOL.UNKNOWN
end



local function parse_id_at(str: string, offset: number): (string?, string?)
    if #str < offset + 1 then
        return nil, "<error:  missing assetid>"
    end

    local first = string.byte(str, offset + 1)
    if first < 48 or first > 57 then
        return nil, "<error:  assetid does not start with a number>"
    end

    
    local window = string.sub(str, offset + 1, offset + 19)
    local digits = string.match(window, "^[0-9]+") :: string

    return digits, nil
end


local function ascii_lower(str: string): string
    return (string.gsub(str, "[A-Z]", function(c: string)
        return string.char(string.byte(c) + 32)
    end))
end


function AssetId.get_id(str: string): (string?, string?)
    local protocol = AssetId.classify(str)

    if protocol == PROTOCOL.RBXASSETID then
        return parse_id_at(str, 13)
    end

    if protocol == PROTOCOL.HTTP or protocol == PROTOCOL.RBXHTTP then
        
        local head = ascii_lower(string.sub(str, 1, 128))
        local found = string.find(head, "id=", 1, true)

        if not found then
            return nil, "<error: id not found in first 128 char for http AssetId>"
        end

        return parse_id_at(head, (found - 1) + 3)
    end

    if protocol == PROTOCOL.FILE then
        return nil, "<error: file:// not allowed>"
    elseif protocol == PROTOCOL.RBXTEMP then
        return nil, "<error: rbxtemp:// not allowed>"
    elseif protocol == PROTOCOL.RBXASSET then
        return nil, "<error: rbxasset:// file not found>"
    elseif protocol == PROTOCOL.NULL then
        return nil, "<error: null id>"
    end

    return nil, "<error: unknown AssetId protocol>"
end


function AssetId.normalize(str: string): string
    local id, err = AssetId.get_id(str)
    return id and ("rbxassetid://" .. id) or (err :: string)
end

return AssetId

end;

__modules["src/utility/bindablefunction"] = function()




export type Callback = (...any) -> ...any

export type BindableFunction = {
    _connect: RBXScriptConnection?,
    _target: any?,
    _method: Callback?,
    __call: (BindableFunction,...any) -> ...any,
    bind: (BindableFunction, target: any, method: Callback?) -> Callback,
    disconnect: (BindableFunction) -> (),
}

local BindableFunction = {}
BindableFunction.__index = BindableFunction

function BindableFunction.new(callback: Callback?)
    local self = setmetatable({
        _connect = nil,
        _target = nil,
        _method = callback,
    }, BindableFunction)

    return self
end





function BindableFunction:bind(target: any, method: Callback?): Callback
    self._target = target
    if method then
        self._method = method
    end

    local function boundCallback(...: any)
        if not self._method then
            return
        end
        return self._method(self._target, ...)
    end

    return boundCallback
end

function BindableFunction:__call(...: any): ...any
    if not self._method then
        return
    end
    return self._method(self._target, ...)
end

return BindableFunction

end;

__modules["src/utility/custom_font"] = function()
local custom_font = {}




function custom_font.make_lexend_font()
    local font_custom_asset = getcustomasset("Frutiger/fonts/Lexend.ttf")
    local font_custom_asset_bold = getcustomasset("Frutiger/fonts/Lexend-Bold.ttf")
    local font_custom_asset_medium = getcustomasset("Frutiger/fonts/Lexend-Medium.ttf")

    writefile("Frutiger/fonts/Lexend.json", game:GetService("HttpService"):JSONEncode({
        name = "Lexend",
        faces = {
            {
                name = "Regular",
                weight = 400,      
                style = "normal",
                assetId = font_custom_asset
            },
            {
                name = "Medium",
                weight = 500,
                style = "normal",
                assetId = font_custom_asset_medium
            },
            {
                name = "Bold",
                weight = 700,
                style = "normal",
                assetId = font_custom_asset_bold
            }
        }
    }))

    local path_asset = getcustomasset("Frutiger/fonts/Lexend.json");
    local fonts = {
        regular = Font.new(
            path_asset,
            Enum.FontWeight.Regular,
            Enum.FontStyle.Normal
        ),
        medium = Font.new(
            path_asset,
            Enum.FontWeight.Medium,
            Enum.FontStyle.Normal
        ),
        bold = Font.new(
            path_asset,
            Enum.FontWeight.Bold,
            Enum.FontStyle.Normal
        )
    };

    
    
    local done = 0;
    for _, font in pairs(fonts) do
        task.spawn(function()
            -- pcall'd so `done` always advances. An uncaught throw in here used
            -- to leave the counter permanently short of 3.
            pcall(function()
                local params = Instance.new("GetTextBoundsParams")
                params.Text = "Preload"
                params.Font = font
                params.Size = 16
                game:GetService("TextService"):GetTextBoundsAsync(params)
                params:Destroy()
            end)
            done += 1;
        end)
    end

    -- Bounded wait. The original was an unbounded
    --     repeat task.wait() until done == 3
    -- which never returned if a preload thread threw — hanging the entire
    -- script at init with no error and no path out. A font that fails to
    -- preload is not worth a dead client.
    local deadline = tick() + 5;
    repeat task.wait() until done == 3 or tick() > deadline;
    return fonts
end

return custom_font.make_lexend_font()

end;

__modules["src/utility/deepwoken/action_tracker"] = function()
local tracker = {};
tracker.__index = tracker;

function tracker:can_parry()
	if not EffectReplicator:FindEffect("Equipped") then
		return false
	end

	return not EffectReplicator:FindEffect("ParryCool")
end


function tracker:can_dodge()
	if EffectReplicator:HasAny("NoRoll", "PreventRoll", "Stun") then
		return false
	end

	return true
end

function tracker:activate_request(mantra)
	self.on_mantra_request:Fire(mantra);
end

function tracker.new(player_data)
    local self = setmetatable({}, tracker);
	self.on_mantra_request = Instance.new("BindableEvent");
	self.last_equip_call = false;

	player_data.character_added:connect(function()
		tracker.last_equip_call = false;
	end);

    return self
end

return tracker

end;

