__modules["src/utility/deepwoken/effect_replicator_handler"] = function()






if not getloadedmodules then
    return game:GetService(STR_TBL_SF_INVOKE("Players")).LocalPlayer:Kick(STR_TBL_SF_INVOKE("Executor is unsupported. [missing getloadedmodules, effect_replicator_handler]"))
end;


local Maid = require("@src/utility/maid");
local EffectReplicatorHandler = {};
EffectReplicatorHandler.__index = EffectReplicatorHandler;
EffectReplicatorHandler.hooks = {};
EffectReplicatorHandler.maid = Maid.new();

function EffectReplicatorHandler:hook(type, func)
    local hook = {};
    function hook:remove()
        table.remove(EffectReplicatorHandler.hooks, self.index);
    end; 

    hook.type = type;
    hook.call = func;
    hook.index = table.insert(EffectReplicatorHandler.hooks, hook);

    return hook
end;

function EffectReplicatorHandler:connect()
    self.maid:do_cleaning();

    local RawEffectReplicator = game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator");
    if not table.find(getloadedmodules(), RawEffectReplicator) then
        repeat task.wait(0.06) warn("getloadedmodules might be failing!") until table.find(getloadedmodules(), RawEffectReplicator);
    end;
    local EffectReplicator = base_require(game:GetService("ReplicatedStorage"):WaitForChild("EffectReplicator"));
    getgenv().EffectReplicator = EffectReplicator;

    self.maid:give_task(EffectReplicator.EffectAdded:Connect(function(effect)
        setthreadidentity(8);
        for _, hook in pairs(EffectReplicatorHandler.hooks) do
            if hook.type == "added" and hook.call then
                task.spawn(xpcall, function()
                    hook.call(effect);
                end, function(err)
                    Logger.error(string.format("effectreplicator added hook: %s", err));
                end);
            end;
        end;
    end));
    
    self.maid:give_task(EffectReplicator.EffectRemoved:Connect(function(effect)
        for _, hook in pairs(EffectReplicatorHandler.hooks) do
            if hook.type == "removed" then
                xpcall(function()
                    hook.call(effect);
                end, function(err) 
                    Logger.error(string.format("effectreplicator removed hook: %s", err));
                end);
            end;
        end;  
    end));
end;

task.spawn(pcall, function()
    while not pcall(function() aztup.maid:give_task(EffectReplicatorHandler.maid); end) do task.wait() end;
end);

task.spawn(pcall, function()
    local update = game:GetService("ReplicatedStorage"):WaitForChild("Requests"):WaitForChild("EffectReplication"):WaitForChild("_update");
    update.OnClientEvent:Connect(function(effect)
        if effect.updateType == "clear" or effect.updateType == "updatecontainer" then
            EffectReplicatorHandler:connect();  
        end;
    end);

    EffectReplicatorHandler:connect();
end);
return EffectReplicatorHandler

end;

__modules["src/utility/deepwoken/general_utilitys"] = function()


local general = {}; 
local collision_utils = base_require(game:GetService("ReplicatedStorage"):WaitForChild("Modules"):WaitForChild("CollisionUtils"));
general.collision_utils = collision_utils;

function general:in_air()
    local sensor = local_player.root_part:FindFirstChild("GroundSensor");
    if EffectReplicator:HasEffect("Swimming") then
        return false    
elseif EffectReplicator:HasEffect("AirBorne") then
        return true    
elseif sensor and not sensor.SensedPart then
        if not collision_utils.solidParams then return false end
        return not collision_utils:Raycast(local_player.root_part.Position, Vector3.new(0, -(sensor.SearchDistance + 3), 0), collision_utils.solidParams)    
end

    return false
end;

function general:get_highest_point(x: number, z: number)
    local filter = {};
    local live = workspace:FindFirstChild("Live");
    local npcs = workspace:FindFirstChild("NPCs");
    if live then table.insert(filter, live); end
    if npcs then table.insert(filter, npcs); end

    local params = RaycastParams.new()
    params.FilterDescendantsInstances = filter
    params.FilterType = Enum.RaycastFilterType.Blacklist

    local floor = workspace:Raycast(Vector3.new(x, 5000, z), Vector3.new(0, -10000, 0), params);
    if floor and floor.Instance then
        return floor.Position.Y + 1.3    
end;

    local holder_sea = workspace:FindFirstChild("HolderSea", true);
    if holder_sea then
        return holder_sea.Position.Y + 1.3    
end;

    return 50000
end;

function general:is_teammate(player)
    local myGuild = local_player.instance:GetAttribute('Guild') or '';
    local playerGuild = player:GetAttribute('Guild') or '';
    if myGuild == '' then return end

    return myGuild == playerGuild
end;

local current_boxes = {};

local function trim_boxes()
    local max_boxes = (aztup and aztup.flags and aztup.flags.max_boxes) or 0
    if max_boxes <= 0 then return end
    while #current_boxes > max_boxes do
        local pair = table.remove(current_boxes, 1)
        if pair then
            for _, part in pair do
                if part and part.Parent then
                    part:Destroy()
                end
            end
        end
    end
end
local function draw_hitbox(hitbox: Vector3, root_pos: CFrame, enemy_pos: CFrame, offset: CFrame, is_ball: boolean?, ok: boolean, too_far: boolean, hidden: boolean?, hit_color: Color3?, miss_color: Color3?)
    local camera: Camera = workspace.CurrentCamera or {Position = Vector3.zero};
    if (enemy_pos.Position - camera.CFrame.Position).Magnitude > 300 then
        return
    end

    trim_boxes()

    local fake_root = nil
    if ok then
        fake_root = Instance.new("Part")
        fake_root.Size = Vector3.new(2, 2, 1)
        fake_root.CFrame = root_pos
        fake_root.Anchored = true
        fake_root.CanCollide = false
        fake_root.Material = Enum.Material.ForceField
        fake_root.CastShadow = false
    end

    local hitbox_part = Instance.new("Part")
    hitbox_part.Size = hitbox
    hitbox_part.CFrame = enemy_pos * (offset or CFrame.new())
    hitbox_part.Anchored = true
    hitbox_part.CanCollide = false
    hitbox_part.Material = Enum.Material.ForceField
    hitbox_part.Shape = is_ball and Enum.PartType.Ball or Enum.PartType.Block
    hitbox_part.CastShadow = false

    if fake_root then
        table.insert(current_boxes, { hitbox_part, fake_root })
    else
        table.insert(current_boxes, { hitbox_part })
    end

    local trans = 1 - (((aztup and aztup.flags and aztup.flags.hb_trans) or 0) / 100)
    hitbox_part.Transparency = trans
    if fake_root then
        fake_root.Transparency = trans
    end

    hitbox_part.Parent = workspace
    if fake_root then
        fake_root.Parent = workspace
    end

    local lifetime = (hidden or not aztup.flags.view_hitboxes or too_far) and 0 or 1
    services.Debris:AddItem(hitbox_part, lifetime)
    if fake_root then
        services.Debris:AddItem(fake_root, lifetime)
    end

    hitbox_part.Color = ok and (hit_color or Color3.new(0, 1, 0)) or (miss_color or Color3.new(1, 0, 0))
    if fake_root then
        fake_root.Color = hit_color or Color3.new(0, 1, 0)
    end

    if hidden or not aztup.flags.view_hitboxes or too_far then
        hitbox_part.Transparency = 1
        if fake_root then
            fake_root.Transparency = 1
        end
    else
        services.TweenService:Create(hitbox_part, TweenInfo.new(1), { Transparency = 1 }):Play()
        if fake_root then
            services.TweenService:Create(fake_root, TweenInfo.new(1), { Transparency = 1 }):Play()
        end
    end
end

function general:in_hitbox_with_pos(root_pos: CFrame, enemy_pos: CFrame, hitbox: Vector3, offset: CFrame, hidden: boolean?, is_ball: boolean?, hit_color: Color3?, miss_color: Color3?)  
    local too_far = false
    if local_player and local_player.root_part then
        too_far = (root_pos.Position - local_player.root_part.Position).Magnitude > 200
    end

    if (root_pos.Position - local_player.root_part.Position).Magnitude > (200 + (hitbox.Magnitude * 2)) then
        return false
    end

    local ok = false
    if is_ball then
        local probe = Instance.new("Part")
        probe.Size = hitbox
        probe.CFrame = enemy_pos * (offset or CFrame.new())
        probe.Anchored = true
        probe.Shape = Enum.PartType.Ball
        probe.CanCollide = false
        probe.Transparency = 1
        probe.CanQuery = true
        probe.Parent = workspace

        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Include
        overlap.FilterDescendantsInstances = { 
            (function()
                local pr = Instance.new("Part")
                pr.Size = Vector3.new(2, 2, 1)
                pr.CFrame = root_pos
                pr.Anchored = true
                pr.CanCollide = false
                pr.Transparency = 1
                pr.CanQuery = true
                pr.Parent = workspace
                return pr
            end)()
        }

        local parts = services.Workspace:GetPartsInPart(probe, overlap)
        ok = #parts > 0

        
        for _, inst in overlap.FilterDescendantsInstances do
            inst:Destroy()
        end
        probe:Destroy()
    else

        local root_probe = Instance.new("Part")
        root_probe.Size = Vector3.new(2, 2, 1)
        root_probe.CFrame = root_pos
        root_probe.Anchored = true
        root_probe.CanCollide = false
        root_probe.Transparency = 1
        root_probe.CanQuery = true
        root_probe.Parent = workspace

        local overlap = OverlapParams.new()
        overlap.FilterType = Enum.RaycastFilterType.Include
        overlap.FilterDescendantsInstances = { root_probe }

        local parts = services.Workspace:GetPartBoundsInBox(enemy_pos * (offset or CFrame.new()), hitbox, overlap)
        ok = #parts > 0

        services.Debris:AddItem(root_probe, 0);
    end

    
    if aztup and aztup.flags and aztup.flags.view_hitboxes and not hidden and not too_far then
        draw_hitbox(hitbox, root_pos, enemy_pos, offset, is_ball, ok, too_far, hidden, hit_color, miss_color)
    end

    return ok
end
function general:in_hitbox(
    a: any,
    b: any,
    c: any,
    d: any,
    e: any?,
    f: any?
)
    
    
    
    
    

    local hitbox: Vector3
    local offset: CFrame
    local root_pos: CFrame
    local enemy_pos: CFrame
    local hidden: boolean?
    local is_ball: boolean? 

    if typeof(a) == "Vector3" and typeof(b) == "CFrame" then
        
        hitbox = a
        offset = b
        root_pos = c
        enemy_pos = d
        hidden = e
        is_ball = f
    else
        
        root_pos = a
        enemy_pos = b
        hitbox = c
        offset = d
        local show = e

        
        
        hidden = (show == false)
        is_ball = nil
    end

    return self:in_hitbox_with_pos(root_pos, enemy_pos, hitbox, offset, hidden, is_ball)
end;

function general:is_ap_anim(id)
    local data;
    for _, timing in timings do
        if timing.ids and table.find(timing.ids, tostring(id:match("%d+"))) then
            data = timing;
        end;
    end;   

    return data ~= nil
end;

function general:playing_ap_anims(entity, ids)
    local humanoid = entity and entity:FindFirstChild("Humanoid")
    if not humanoid then return false end
    for _, track in humanoid:GetPlayingAnimationTracks() do
        if ids then
            if table.find(ids, track.Animation.AnimationId) then
                continue            
end;
        end

        local data;
        for _, timing in timings do
            if timing.ids and table.find(timing.ids, tostring(track.Animation.AnimationId:match("%d+"))) then
                data = timing;
            end;
        end;   
        
        if data then
            return true        
end;
    end;

    return false
end;

local Keybinds = base_require(game:GetService("ReplicatedStorage"):WaitForChild("KeyBinds"..""));
function general:generic_parry_ap_task(entity: Model)
    if aztup_options.filters.Value["Dont Parry If Holding Block"] and Keybinds.IsActionHeld("Block") then
        return pcall(function()
            setthreadidentity(8);
            Logger:notify_sound("Holding F.");
        end)    
end;

    DefendActionManager:queue_generic_parry_task(entity);
end;

function general:raw_is_holding_f()
    return Keybinds.IsActionHeld("Block")
end;

function general:is_holding_f()
    return aztup_options.filters.Value["Dont Parry If Holding Block"] and Keybinds.IsActionHeld("Block")
end;

general.friends = {};
function general:is_friends_with_sync(plr)
    return general.friends[plr.UserId]
end

local owner_runtime = aztup;
task.spawn(function() 
    for _, plr in services.Players:GetPlayers() do
        pcall(function() 
            local is_friends = local_player.instance:IsFriendsWithAsync(plr.UserId);
            if is_friends then
                general.friends[plr.UserId] = local_player.instance:IsFriendsWithAsync(plr.UserId);
            end;
        end)
    end

    if owner_runtime.alive == false then return end;
    owner_runtime.maid:give_task(services.Players.PlayerAdded:Connect(function(plr)
        if general.friends[plr.UserId] ~= nil then return end

        local is_friends = local_player.instance:IsFriendsWithAsync(plr.UserId);
        if not is_friends then return end

        general.friends[plr.UserId] = local_player.instance:IsFriendsWithAsync(plr.UserId);
    end));
end)

return general

end;

__modules["src/utility/deepwoken/safe_tween"] = function()

local safeNAN;
safeNAN = function(v369)  
    
    if v369 == v369 then
        return v369    
elseif typeof(v369) == "Vector3" then
        local l_v369_0 = v369;
        return (Vector3.new(safeNAN(l_v369_0.X), safeNAN(l_v369_0.Y), safeNAN(l_v369_0.Z)))    
elseif typeof(v369) == "CFrame" then
        local l_v369_1 = v369;
        local v372 = safeNAN(l_v369_1.Position);
        local l_Rotation_0 = l_v369_1.Rotation;
        if l_Rotation_0 ~= l_Rotation_0 then
            l_Rotation_0 = CFrame.identity;
        end;
        return CFrame.new(v372) * l_Rotation_0    
elseif typeof(v369) == "number" then
        return v369 == v369 and v369 or 0    
else
        return v369    
end;
end;

local last_lagback = 0;
local threads = {};
return {
    new = function(target_cframe, ping_based, speed)
        speed = speed or 190

        if aztup.flags.force_tween_speed then
            speed = aztup.flags.force_tween_speed_value;
        end;

        if aztup.flags.force_no_tween_ping_comp then
            ping_based = false;
        end;

        local target_cframe = target_cframe

        local conn
        conn = services.RunService.PreSimulation:Connect(function(dt)
            if not local_player or not local_player.root_part then
                return
            end

            local target_pos = typeof(target_cframe) == "function" and target_cframe().Position or target_cframe.Position

            local root = local_player.root_part
            local current_pos = root.Position
            local offset = target_pos - current_pos
            local distance = offset.Magnitude

            if distance <= 0.01 or distance ~= distance then
                return
            end

            if target_pos.Magnitude >= 1000000 then
                if conn then
                    conn:Disconnect()
                    conn = nil
                end

                return            
end;

            local_player.root_part.AssemblyLinearVelocity = Vector3.zero
            local_player.root_part.CFrame = CFrame.new(root.CFrame.X, target_pos.Y, root.CFrame.Z)

            local dir = offset.Unit
            local move_speed = ping_based and speed * math.max(0.6, 1 - Latency:get_ping()) or speed
            
            local root_attachment = local_player.root_part:FindFirstChild("RootAttachment");
            local align_position = root_attachment and root_attachment:FindFirstChild("AlignPosition");
            if align_position then
                
                last_lagback = tick();
            end

            if tick() - last_lagback < 1 then
                move_speed = math.min(80, move_speed * 0.75);
            end;

            local step = move_speed * dt

            if step > distance then
                step = distance
            end

            if offset.Magnitude <= 0.01 then
                return
            end

            if not aztup.flags.dont_fly_on_tween then
                root.Velocity = Vector3.zero;
            end;
            
            root.CFrame = safeNAN(root.CFrame + safeNAN(dir * step))
        end)


        table.insert(threads, {
            task = task.spawn(function()
                if not local_player or not local_player.root_part then
                    return
                end
                local root = local_player.root_part
                while ((typeof(target_cframe) == "function" and target_cframe().Position or target_cframe.Position) - root.Position).Magnitude > 10 do
                    task.wait()
                end

                root.CFrame = typeof(target_cframe) == "function" and target_cframe() or target_cframe

                if conn then
                    conn:Disconnect()
                    conn = nil
                end
            end),
            conn = conn
        })

        return {
            stop = function()
                if conn then
                    conn:Disconnect()
                    conn = nil
                end
            end,
            wait = function()
                if not local_player or not local_player.root_part then
                    return
                end

                local root = local_player.root_part

                while ((typeof(target_cframe) == "function" and target_cframe().Position or target_cframe.Position) - root.Position).Magnitude > 10 do
                    task.wait()
                end
            end,
        }
    end,
    stop_all = function()
        for _, thread in threads do
            if thread.conn then
                thread.conn:Disconnect();
            end;

            if thread.task then
                pcall(task.cancel, thread.task);
            end;
        end;

        table.clear(threads);
    end,
    register_lagback = function()
        last_lagback = tick();
    end
}

end;

__modules["src/utility/deepwoken/servers"] = function()
local servers = {};

local function decode_asset(asset)
    local decoded = services.EncodingService:Base64Decode(buffer.fromstring(asset));
    local decompress = services.EncodingService:DecompressBuffer(decoded, Enum.CompressionAlgorithm.Zstd);
    return buffer.tostring(decompress)
end;

local hop_script = decode_asset(inline_asset_b96("@assets/hopper.lua"));

function kick_window(message)
    task.spawn(pcall, function()
        local_player.instance:Kick("Serverhopping...");
        task.wait();
        
        local roblox_prompt_gui = services.CoreGui:FindFirstChild("RobloxPromptGui")
        if not roblox_prompt_gui then
            return
        end
    
        roblox_prompt_gui.promptOverlay.ErrorPrompt.TitleFrame.ErrorTitle.TextColor3 = Color3.fromRGB(125, 196, 228)
        roblox_prompt_gui.promptOverlay.ErrorPrompt.TitleFrame.ErrorTitle.Text = "Frutiger"
        roblox_prompt_gui.promptOverlay.ErrorPrompt.MessageArea.ErrorFrame.ErrorMessage.Text = message
    end);
    while task.wait() do
        game:GetService("TeleportService"):Teleport(4111023553);
    end;
end;

return { 
    hop = function(_, slot, small, do_sound, expiry)
        local hop_script = string.format(hop_script, slot or "A", small ~= nil and tostring(small) or 'false', tostring(do_sound), 'false')

        if game.PlaceId ~= 4111023553 then 
            xpcall(function()
                local blacklisted_servers = isfile("Frutiger/hopper blacklisted servers.json") and game:GetService("HttpService"):JSONDecode(readfile("Frutiger/hopper blacklisted servers.json")) or {};
                
                for id, server in blacklisted_servers do
                    if server.expiry < tick() then
                        blacklisted_servers[id] = nil;
                    end;
                end;

                local function blacklist(server, expiry)
                    blacklisted_servers[server] = {
                        expiry = tick() + (expiry or 900)
                    }
                
                    writefile("Frutiger/hopper blacklisted servers.json", game:GetService("HttpService"):JSONEncode(blacklisted_servers));
                end;

                blacklist(game.JobId, expiry or (10 * 60))
            end, warn);

            writefile("hopper.lua", hop_script);
            queue_on_teleport(hop_script);
            kick_window("Serverhopping...");
        end;
    end,
    rejoin = function(self, slot)
        self:custom(slot, game.JobId);
    end,
    custom = function(_, slot, id)
        local rejoin_script = string.format([[
        if not game:IsLoaded() then
            game.Loaded:Wait();
        end;
        if game.PlaceId ~= 4111023553 then return; end
        local server = '%s';
        local slot = "%s";

        queueonteleport('if game.PlaceId == 4111023553 then return; end; xpcall(function() local sound = Instance.new("Sound", game:GetService("CoreGui")); game:GetService("Debris"):AddItem(sound, 6); sound.Volume = 1.3; sound.SoundId = getcustomasset("Frutiger/assets/notification.mp3"); sound:Play(); end, warn);')

        while task.wait() do
            game:GetService("ReplicatedStorage").Requests:WaitForChild("StartMenu"):WaitForChild("PickSlot"):FireServer(slot, {
                PrivateTest = false
            });
            task.wait(0.3);
            game:GetService("ReplicatedStorage").Requests.StartMenu:WaitForChild("PickServer"):FireServer(server);
        end;
        ]], id, slot or "A");
        if game.PlaceId ~= 4111023553 then  
            queue_on_teleport(rejoin_script); 
            
            kick_window("rejoining...")
            return        
else
            print("cant be called here");
        end;
    end,
    obliteration = function(_, slot, small, sound)
        local obl_script = string.format(hop_script, slot or "A", small ~= nil and tostring(small) or 'false', tostring(sound), 'true')
        if game.PlaceId ~= 4111023553 then 
            queue_on_teleport(obl_script);
            kick_window("wiping...");
            return        
else
            print("cant be called here");
        end;
    end,
    quick_hop = function(self)
        self:hop(local_player.instance:GetAttribute("DataSlot") or "A", 'false', 'false')
    end;
}

end;

__modules["src/utility/deepwoken/ssv_parser"] = function()

local passive_parser = {} do 
    passive_parser.__index = passive_parser;
    function passive_parser.parse(character)
        local self = setmetatable({}, passive_parser);
        self.passives = EffectReplicator.Passives;
        self.character = character;

        return self    
end;
    
    function passive_parser:get_passive(index)
        if not self.passives then return nil end;
        return self.passives[index]    
end;

    function passive_parser:get_all_passives()
        if not self.passives then return {}end;
        return self.passives    
end;

    function passive_parser:add_passive(new_passive)
        EffectReplicator.Passives[new_passive] = true;
    end;

    function passive_parser:remove_passive(passive_to_remove)
        if not self.passives then return end;
        local had = EffectReplicator.Passives[passive_to_remove];
        EffectReplicator.Passives[passive_to_remove] = nil;

        return had    
end;

    function passive_parser:save()
    end;

    function passive_parser:destroy()
        self.character = nil;
        self.passives = nil;
        self = nil;
    end;
end;

return passive_parser

end;

__modules["src/utility/fflags"] = function()
local fflags = {} do
    fflags.current = isfile("Frutiger/fflags.txt") and readfile("Frutiger/fflags.txt") or "{}";

    function fflags:get_main()
        if not self.cached then
            self.cached = services.HttpService:JSONDecode(self.current or "{}");
        end
        return self.cached    
end

    function fflags:get(flag)
        return self:get_main()[flag]    
end;

    function fflags:set(flag, value)
        local decoded = services.HttpService:JSONDecode(self.current);
        decoded[flag] = value;
        self.current = services.HttpService:JSONEncode(decoded);
        self.cached = services.HttpService:JSONDecode(self.current or "{}");
        writefile("Frutiger/fflags.txt", self.current);
    end;
end

return fflags 

end;

__modules["src/utility/freecam"] = function()
fcRunning = false
local Camera = workspace.CurrentCamera
workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
	local newCamera = workspace.CurrentCamera
	if newCamera then
		Camera = newCamera
	end
end)

local INPUT_PRIORITY = Enum.ContextActionPriority.High.Value

local cameraPos = Vector3.new()
local cameraRot = Vector2.new()

NAV_KEYBOARD_SPEED = Vector3.new(1, 1, 1)

Input = {} do

	keyboard = {
		W = 0,
		A = 0,
		S = 0,
		D = 0,
		E = 0,
		Q = 0,
		Up = 0,
		Down = 0,
		LeftShift = 0,
	}

	mouse = {
		Delta = Vector2.new(),
	}

	PAN_MOUSE_SPEED = Vector2.new(1, 1)*(math.pi/64)
	NAV_ADJ_SPEED = 0.75
	NAV_SHIFT_MUL = 0.25

	navSpeed = 2

	function Input.Vel(dt)
		navSpeed = math.clamp(navSpeed + dt*(keyboard.Up - keyboard.Down)*NAV_ADJ_SPEED, 0.01, 4)

		local kKeyboard = Vector3.new(
			keyboard.D - keyboard.A,
			keyboard.E - keyboard.Q,
			keyboard.S - keyboard.W
		)*NAV_KEYBOARD_SPEED

		local shift = services.UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)

		return (kKeyboard)*(navSpeed*(shift and NAV_SHIFT_MUL or 1))
	end

	function Input.Pan(dt)
		local kMouse = mouse.Delta*PAN_MOUSE_SPEED
		mouse.Delta = Vector2.new()
		return kMouse
	end

	do
		function Keypress(action, state, input)
			keyboard[input.KeyCode.Name] = state == Enum.UserInputState.Begin and 1 or 0
			return Enum.ContextActionResult.Sink
		end

		function MousePan(action, state, input)
			local delta = input.Delta
			mouse.Delta = Vector2.new(-delta.y, -delta.x)
			return Enum.ContextActionResult.Sink
		end

		function Zero(t)
			for k, v in pairs(t) do
				t[k] = v*0
			end
		end

		function Input.StartCapture()
			services.ContextActionService:BindActionAtPriority("FreecamKeyboard",Keypress,false,INPUT_PRIORITY,
				Enum.KeyCode.W,
				Enum.KeyCode.A,
				Enum.KeyCode.S,
				Enum.KeyCode.D,
				Enum.KeyCode.E,
				Enum.KeyCode.Q,
				Enum.KeyCode.Up,
				Enum.KeyCode.Down
			)
			services.ContextActionService:BindActionAtPriority("FreecamMousePan",MousePan,false,INPUT_PRIORITY,Enum.UserInputType.MouseMovement)
		end

		function Input.StopCapture()
			navSpeed = 1
			Zero(keyboard)
			Zero(mouse)
			services.ContextActionService:UnbindAction("FreecamKeyboard")
			services.ContextActionService:UnbindAction("FreecamMousePan")
		end
	end
end

function GetFocusDistance(cameraFrame)
	local znear = 0.1
	local viewport = Camera.ViewportSize
	local projy = 2*math.tan(70/2)
	local projx = viewport.x/viewport.y*projy
	local fx = cameraFrame.rightVector
	local fy = cameraFrame.upVector
	local fz = cameraFrame.lookVector

	local minVect = Vector3.new()
	local minDist = 512

	for x = 0, 1, 0.5 do
		for y = 0, 1, 0.5 do
			local cx = (x - 0.5)*projx
			local cy = (y - 0.5)*projy
			local offset = fx*cx - fy*cy + fz
			local origin = cameraFrame.p + offset*znear
			local _, hit = workspace:FindPartOnRay(Ray.new(origin, offset.unit*minDist))
			local dist = (hit - origin).magnitude
			if minDist > dist then
				minDist = dist
				minVect = offset.unit
			end
		end
	end

	return fz:Dot(minVect)*minDist
end

local function StepFreecam(dt)
	
	local vel = Input.Vel(dt)
	local pan = Input.Pan(dt)

	local zoomFactor = math.sqrt(math.tan(math.rad(70/2))/math.tan(math.rad(70/2)))

	cameraRot = cameraRot + pan*Vector2.new(0.75, 1)*8*(dt/zoomFactor)
	cameraRot = Vector2.new(math.clamp(cameraRot.x, -math.rad(90), math.rad(90)), cameraRot.y%(2*math.pi))

	local cameraCFrame = CFrame.new(cameraPos)*CFrame.fromOrientation(cameraRot.x, cameraRot.y, 0)*CFrame.new(vel*Vector3.new(1, 1, 1)*64*dt)
	cameraPos = cameraCFrame.p

	Camera.CFrame = cameraCFrame
	Camera.Focus = cameraCFrame*CFrame.new(0, 0, -GetFocusDistance(cameraCFrame))
end

local PlayerState = {} do
	mouseBehavior = ""
	mouseIconEnabled = ""
	cameraType = ""
	cameraFocus = ""
	cameraCFrame = ""

	function PlayerState.Push()

		cameraType = Camera.CameraType
		Camera.CameraType = Enum.CameraType.Custom

		cameraCFrame = Camera.CFrame
		cameraFocus = Camera.Focus

		mouseIconEnabled = services.UserInputService.MouseIconEnabled
		services.UserInputService.MouseIconEnabled = true

		mouseBehavior = services.UserInputService.MouseBehavior
		services.UserInputService.MouseBehavior = Enum.MouseBehavior.Default
	end

	function PlayerState.Pop()

		Camera.CameraType = cameraType
		cameraType = nil

		Camera.CFrame = cameraCFrame
		cameraCFrame = nil

		Camera.Focus = cameraFocus
		cameraFocus = nil

		services.UserInputService.MouseIconEnabled = mouseIconEnabled
		mouseIconEnabled = nil

		services.UserInputService.MouseBehavior = mouseBehavior
		mouseBehavior = nil
	end
end

function StartFreecam(pos)
	if fcRunning then
		StopFreecam()
	end
	local cameraCFrame = Camera.CFrame
	if pos then
		cameraCFrame = pos
	end
	cameraRot = Vector2.new()
	cameraPos = cameraCFrame.p

	PlayerState.Push()
	services.RunService:BindToRenderStep("Freecam", Enum.RenderPriority.Camera.Value, StepFreecam)
	Input.StartCapture()
	fcRunning = true
end

function StopFreecam()
	if not fcRunning then return end
	Input.StopCapture()
	services.RunService:UnbindFromRenderStep("Freecam")
	PlayerState.Pop()
	fcRunning = false
end

return {
	exit = StopFreecam,
	enter = StartFreecam,
	set_speed = function(speed)
		NAV_KEYBOARD_SPEED = speed
	end
}

end;

__modules["src/utility/frutiger/chrome"] = function()
--[[
    src/utility/frutiger/chrome.lua

    Native chrome, borrowed widgets.

    The library keeps doing what it is good at -- toggles, sliders, dropdowns,
    dependency boxes, keybinds, config round-tripping. Rewriting that would mean
    reproducing 16 constructors, 16 Library methods and 103 option objects
    across 60 files.

    What it is bad at is being the frame around those widgets. Its chrome fights
    decoration: it re-tweens properties, rebuilds pieces on tab switch, and
    bakes a font per label, so fonts, torn borders and glitch effects can only
    be bolted on from outside. So the chrome is replaced and the widget tree
    transplanted into it.

    The shell lives INSIDE Outer, the library's window frame, and that is the
    whole trick:

    *   Outer already carries the UIScale, so the transplanted widgets render at
        the scale the user set without any of it being re-derived.

    *   Outer already carries the drag binding -- MakeUIDraggable(Outer, 21) at
        ui.lua:1297, a 21px grab zone at the top -- and this shell puts its title
        bar in exactly that strip, so dragging keeps working untouched.

    *   The theme overlay is also a child of Outer at scale 1,1, so it resizes
        with the new window instead of drifting away from it. Parenting the
        shell to the ScreenGui instead would have desynced all three.

    *   Outer.Visible is the library's own show/hide state (Library:Toggle sets
        it at ui.lua ~2369), so visibility needs no syncing at all --
        everything is inside it.

    How the pieces are moved:

    *   Tab switching is Tab:ShowTab() (ui.lua ~1882), which sets
        TabFrame.Visible. Those frames live inside the library's content frame,
        so the whole content frame moves in one piece.

    *   It is moved at its MEASURED size, never stretched. Every tab page inside
        uses fixed offsets and two 266px columns; letting it resize drags them
        out of position -- the trap the sidebar pass already fell into once.

    *   The library's own chrome (title, strip, separator, search) is hidden by
        hiding Inner, but LEFT ALIVE. Tab:ShowTab() still writes to
        TabButtonLabel, the underline and the registry, and those have to keep
        resolving.
]]

local chrome = {};

local SIDEBAR_WIDTH = 150;
local TITLE_HEIGHT = 26;
local TAB_HEIGHT = 26;
local TAB_PADDING = 2;

-- Palette source, so the shell is themed rather than hardcoded. pcall'd because
-- a missing theme should cost the colours, not the chrome.
local theme_module = nil;
pcall(function() theme_module = require("@src/utility/frutiger/theme") end);

-- ── helpers ────────────────────────────────────────────────────────────────
local function gui_children(parent)
    local out = {};
    for _, child in ipairs(parent:GetChildren()) do
        if child:IsA("GuiObject") then
            out[#out + 1] = child;
        end;
    end;
    return out;
end;

local function make(class, props)
    local object = Instance.new(class);
    for key, value in next, props do
        object[key] = value;
    end;
    return object;
end;

-- ── locate the library's pieces ────────────────────────────────────────────
local function find_window_body(outer)
    for _, child in ipairs(gui_children(outer)) do
        if child.Name ~= "FRUTIGER_OVERLAY" then
            return child;
        end;
    end;
    return nil;
end;

local function find_strip(root)
    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("Frame") then
            local layout = descendant:FindFirstChildOfClass("UIListLayout");
            if layout
                and layout.FillDirection == Enum.FillDirection.Horizontal
                and descendant.AbsoluteSize.X > descendant.AbsoluteSize.Y * 4 then
                return descendant;
            end;
        end;
    end;
    return nil;
end;

-- ── build ──────────────────────────────────────────────────────────────────
local function build(outer)
    local inner = find_window_body(outer);
    if not inner then
        return false, "no window body";
    end;

    local strip = find_strip(inner);
    if not strip then
        return false, "no tab strip";
    end;

    local holder = strip.Parent;
    local container = holder and holder.Parent;
    if not holder or not container then
        return false, "no frame chain";
    end;

    local content;
    for _, sibling in ipairs(gui_children(holder)) do
        if sibling ~= strip and sibling.AbsoluteSize.Y > 100 then
            content = content or sibling;
        end;
    end;
    if not content then
        return false, "no content frame";
    end;

    -- measure BEFORE moving, and restore at exactly this size
    local content_size = content.AbsoluteSize;

    -- ── the shell ──────────────────────────────────────────────────────────
    local window_width = SIDEBAR_WIDTH + content_size.X;
    local window_height = TITLE_HEIGHT + content_size.Y;

    -- Colours come from the palette rather than literals. These were hardcoded
    -- black/white during the CONSOLE pass and were never updated, so the shell
    -- root stayed #000000 behind a light theme -- the whole UI sat on black.
    local theme = theme_module;
    local palette = (theme and theme.extra) or {};
    local GLASS = palette.glass or Color3.fromRGB(244, 251, 255);
    local EDGE  = Color3.fromRGB(255, 255, 255);   -- soft white edge, per the brief
    local SKY   = palette.sky   or Color3.fromRGB(159, 212, 239);
    local AQUA  = palette.aqua  or Color3.fromRGB(41, 168, 224);
    local INK   = palette.ink   or Color3.fromRGB(14, 61, 92);

    local root = make("Frame", {
        Name = "FRUTIGER_CHROME",
        BackgroundColor3 = GLASS,
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        Position = UDim2.fromScale(0, 0),
        ZIndex = 1,
        Parent = outer,
    });

    make("UICorner", { CornerRadius = UDim.new(0, 6), Parent = root });

    local stroke = make("UIStroke", {
        Color = EDGE,
        Thickness = 1,
        Parent = root,
    });
    make("UICorner", { CornerRadius = UDim.new(0, 6), Parent = stroke });

    -- title bar. sits inside Outer's existing 21px drag zone.
    local title_bar = make("Frame", {
        Name = "title",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, TITLE_HEIGHT),
        ZIndex = 2,
        Parent = root,
    });

    local title_label = make("TextLabel", {
        Name = "title_text",
        BackgroundTransparency = 1,
        Font = Enum.Font.RobotoMono,
        Text = string.format("FRUTIGER // USER_%03d", math.random(1, 999)),
        TextColor3 = INK,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        Size = UDim2.new(1, -12, 1, 0),
        Position = UDim2.fromOffset(8, 0),
        ZIndex = 2,
        Parent = title_bar,
    });

    make("Frame", {
        Name = "title_rule",
        BackgroundColor3 = EDGE,
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 1),
        Position = UDim2.new(0, 0, 0, TITLE_HEIGHT - 1),
        ZIndex = 2,
        Parent = root,
    });

    -- sidebar
    local sidebar = make("Frame", {
        Name = "sidebar",
        BackgroundTransparency = 1,
        Size = UDim2.new(0, SIDEBAR_WIDTH, 1, -TITLE_HEIGHT),
        Position = UDim2.fromOffset(0, TITLE_HEIGHT),
        ZIndex = 2,
        Parent = root,
    });

    make("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, TAB_PADDING),
        Parent = sidebar,
    });
    make("UIPadding", {
        PaddingLeft = UDim.new(0, 6),
        PaddingRight = UDim.new(0, 6),
        PaddingTop = UDim.new(0, 6),
        Parent = sidebar,
    });

    make("Frame", {
        Name = "sidebar_rule",
        BackgroundColor3 = EDGE,
        BorderSizePixel = 0,
        Size = UDim2.new(0, 1, 1, -TITLE_HEIGHT),
        Position = UDim2.new(0, SIDEBAR_WIDTH, 0, TITLE_HEIGHT),
        ZIndex = 2,
        Parent = root,
    });

    -- content host
    local host = make("Frame", {
        Name = "content_host",
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        Size = UDim2.fromOffset(content_size.X, content_size.Y),
        Position = UDim2.fromOffset(SIDEBAR_WIDTH + 1, TITLE_HEIGHT),
        ZIndex = 1,
        Parent = root,
    });

    -- ── transplant ─────────────────────────────────────────────────────────
    content.Parent = host;
    content.Position = UDim2.fromOffset(0, 0);
    content.Size = UDim2.fromOffset(content_size.X, content_size.Y);

    -- ── hide the library chrome, keep it alive ─────────────────────────────
    pcall(function() inner.Visible = false end);
    pcall(function() outer.BackgroundTransparency = 1 end);

    -- ── resize the library window around the new chrome ────────────────────
    -- Outer keeps its UIScale, its drag binding and the theme overlay child,
    -- all of which follow this size.
    pcall(function()
        outer.Size = UDim2.fromOffset(window_width, window_height);
    end);

    -- ── tabs ───────────────────────────────────────────────────────────────
    local window = Library.FrutigerWindow;
    local entries = {};

    local function sorted_tabs()
        -- Window.TabOrder is the library's authoritative order, and it is an
        -- array of Tab OBJECTS in creation order (ui.lua:2290).
        --
        -- The first version sorted by tab.LayoutOrder, which does not exist:
        -- Tab:SetLayoutOrder writes to TabButton.LayoutOrder, not to the Tab.
        -- So the comparator compared nil with nil and returned false every
        -- time, and table.sort produced arbitrary order.
        local order = window.TabOrder;
        if type(order) == "table" and #order > 0 then
            local ordered = {};
            for _, tab in ipairs(order) do
                if tab then
                    ordered[#ordered + 1] = tab;
                end;
            end;
            return ordered;
        end;

        -- fallback for a window built without TabOrder
        local tabs = window.Tabs or {};
        local names = {};
        for name in next, tabs do
            names[#names + 1] = name;
        end;
        table.sort(names);

        local out = {};
        for _, name in ipairs(names) do
            if tabs[name] then
                out[#out + 1] = tabs[name];
            end;
        end;
        return out;
    end;

    local function paint_active(active)
        for tab, entry in next, entries do
            local is_active = (tab == active);
            pcall(function()
                entry.frame.BackgroundColor3 = is_active and AQUA or GLASS;
                entry.label.TextColor3 = INK;
            end);
        end;
    end;

    local function build_entries()
        local ordered = sorted_tabs();

        for index, tab in ipairs(ordered) do
            if not entries[tab] then
                local row = make("Frame", {
                    Name = "tab_" .. index,
                    BackgroundColor3 = GLASS,
                    BorderSizePixel = 0,
                    Size = UDim2.new(1, 0, 0, TAB_HEIGHT),
                    LayoutOrder = index,
                    ZIndex = 3,
                    Parent = sidebar,
                });
                make("UICorner", { CornerRadius = UDim.new(0, 4), Parent = row });
                make("UIStroke", {
                    Color = EDGE,
                    Thickness = 1,
                    Parent = row,
                });

                local label = make("TextLabel", {
                    Name = "label",
                    BackgroundTransparency = 1,
                    Font = Enum.Font.RobotoMono,
                    Text = tostring(tab.Name or ("TAB_" .. index)):upper(),
                    TextColor3 = INK,
                    TextSize = 12,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    Size = UDim2.new(1, -12, 1, 0),
                    Position = UDim2.fromOffset(8, 0),
                    ZIndex = 4,
                    Parent = row,
                });

                entries[tab] = { frame = row, label = label };

                -- clicking drives the library's own tab switch, so its internal
                -- state (ActiveTab, search refresh, registry) stays correct
                row.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 then
                        pcall(function() tab:ShowTab() end);
                        paint_active(tab);
                    end
                end);
            end
        end;

        if window.ActiveTab then
            paint_active(window.ActiveTab);
        elseif ordered[1] then
            pcall(function() ordered[1]:ShowTab() end);
            paint_active(ordered[1]);
        end;
    end;

    build_entries();

    -- The library can add or rebuild tabs (search, config load), so re-sync for
    -- a while rather than assuming the set is fixed.
    task.spawn(function()
        for _ = 1, 10 do
            task.wait(1);
            pcall(build_entries);
            pcall(function() paint_active(Library.FrutigerWindow.ActiveTab) end);
        end;
    end);

    chrome.root = root;
    chrome.sidebar = sidebar;
    chrome.host = host;
    chrome.title = title_label;
    chrome.entries = entries;
    chrome.transplanted = content;
    chrome.outer = outer;

    return true;
end;

function chrome.apply()
    if chrome.applied then
        return true;
    end;

    if not Library or not Library.ScreenGui or not Library.FrutigerWindow then
        return false;
    end;

    local outer = Library.FrutigerWindow.Holder;
    if not outer then
        return false;
    end;

    local ok, result, reason = pcall(build, outer);
    if not ok then
        warn("[frutiger] chrome failed:", result);
        return false;
    end;
    if not result then
        warn("[frutiger] chrome skipped:", reason);
        return false;
    end;

    chrome.applied = true;
    return true;
end;

-- ── keybind list ───────────────────────────────────────────────────────────
-- Library.KeybindFrame (ui.lua:1246) is a PanelComponent panel: four nested
-- fills with the text buried inside them.
--
--     Outer    accent-coloured, BorderSizePixel 1   <- the border you see
--       Inner  main fill
--         Header   background fill, 22px
--           HeaderLabel  "Keybinds", centred
--         Divider  outline-coloured 1px
--         Content  (transparent) <- the entries live here
--
-- So stripping the background is a walk: every Frame in the panel loses its
-- fill and its classic border. The labels are untouched, which is the point --
-- text only, no box.
--
-- The header is centred because it used to sit inside a filled bar. With the
-- bar gone it reads as a stray float in the middle of nothing, so it is aligned
-- left to line up with the entries under it.

-- Which corner the bind list sits in. Bottom-left: the anchor is the bottom
-- edge, so the list grows upward as binds are added and the bottom stays put.
--
-- Flip these two to move it -- Vector2.new(0, 0) is top-left, Vector2.new(1, 1)
-- is bottom-right. Note the bottom-anchored Y value (1) is also what tells
-- toggle.lua to skip its vertical-centre compensation; a centre anchor (0.5)
-- would drag the list down as it grows.
local KEYBIND_ANCHOR = Vector2.new(0, 1);
local KEYBIND_MARGIN = 10;

-- Corner position, computed from the camera viewport in OFFSETS rather than
-- from scale.
--
-- Scale-1 Y does not mean "the bottom of the screen" here: the library's
-- ScreenGui has IgnoreGuiInset = false and GuiService reports a 58px inset, so
-- ScreenGui.AbsoluteSize is 1920x1022 against a 1920x1080 viewport. Anchoring
-- at scale 1 left the panel 68px above the physical bottom -- measured. Offsets
-- are absolute screen pixels, so they land where you actually want.
--
-- Offsets also suit the library: toggle.lua's resize code reads
-- Position.Y.Offset, and SaveManager stores the position as a UDim2 anyway.
--
-- NOT divided by the frame's UIScale. I tried that and measurement killed it.
--
-- A UIScale scales the frame's SIZE but leaves the position OFFSET where it is:
-- AbsoluteSize goes 220 -> 213 at scale 0.97 while the offset still lands at its
-- literal pixel value. Dividing by the scale therefore put the panel 23px PAST
-- the bottom edge at the default scale -- I introduced a bug while trying to fix
-- one, and the only reason I caught it is that I measured instead of assuming.
--
-- Measured at scale 0.97: an offset of 1070 renders a bottom edge of exactly
-- 1070, which is the 10px gap intended. The plain viewport offset is correct.
--
-- The frame parameter is kept so callers stay uniform and a future reader can
-- see it was considered rather than missed.
local function corner_position(frame)
    local camera = workspace.CurrentCamera;
    local viewport = (camera and camera.ViewportSize) or Vector2.new(1920, 1080);

    local x = (KEYBIND_ANCHOR.X == 1)
        and (viewport.X - KEYBIND_MARGIN)
        or KEYBIND_MARGIN;

    local y = (KEYBIND_ANCHOR.Y == 1)
        and (viewport.Y - KEYBIND_MARGIN)
        or KEYBIND_MARGIN;

    return UDim2.fromOffset(x, y);
end;

function chrome.restyle_keybinds()
    if not Library or not Library.KeybindFrame then
        return false;
    end;

    local frame = Library.KeybindFrame;

    -- bottom-left. The list reads as an overlay on the game rather than a
    -- panel, and the left edge is otherwise clear once the quest tracker is
    -- dismissed.
    pcall(function()
        frame.AnchorPoint = KEYBIND_ANCHOR;
        frame.Position = corner_position(frame);
    end);

    -- Re-place on the two things that move it.
    --
    -- The offset is divided by the UI Scale, so moving the UI Scale slider moves
    -- the panel -- and without this, nothing corrects it, which is how it ended
    -- up hanging off the bottom of the screen. Same for a viewport resize.
    pcall(function()
        local ui = frame:FindFirstChildOfClass("UIScale");
        if ui then
            ui:GetPropertyChangedSignal("Scale"):Connect(function()
                pcall(function() frame.Position = corner_position(frame) end);
            end);
        end;
    end);

    pcall(function()
        local camera = workspace.CurrentCamera;
        if camera then
            camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                pcall(function() frame.Position = corner_position(frame) end);
            end);
        end;
    end);

    -- Show the bind list only while the menu is open.
    --
    -- The library parents this frame to the ScreenGui rather than to Outer, so
    -- Library:Toggle -- which fades Outer:GetDescendants() and then sets
    -- Outer.Visible -- neither fades nor hides it. It is built as an always-on
    -- overlay, which is what left it on screen after the menu closed.
    --
    -- Mirroring the window's own visibility keeps the two in step, including
    -- the fade: the library sets Outer.Visible at the END of the toggle, so this
    -- follows once the fade has finished rather than cutting it short.
    pcall(function()
        local window = Library.FrutigerWindow;
        local holder = window and window.Holder;
        if holder then
            frame.Visible = holder.Visible;
            holder:GetPropertyChangedSignal("Visible"):Connect(function()
                pcall(function() frame.Visible = holder.Visible end);
            end);
        end;
    end);

    local stripped = 0;

    for _, descendant in ipairs(frame:GetDescendants()) do
        if descendant:IsA("Frame") then
            local ok = pcall(function()
                descendant.BackgroundTransparency = 1;
                descendant.BorderSizePixel = 0;
            end);
            if ok then
                stripped = stripped + 1;
            end;
        elseif descendant:IsA("TextLabel") then
            -- the panel title, once centred in its bar
            if descendant.Text and descendant.Text:lower():find("keybind") then
                pcall(function()
                    descendant.TextXAlignment = Enum.TextXAlignment.Left;
                end);
            end;
        end;
    end;

    pcall(function()
        frame.BackgroundTransparency = 1;
        frame.BorderSizePixel = 0;
    end);

    chrome.keybind_frame = frame;
    chrome.keybinds_stripped = stripped;

    -- SaveManager persists and restores a keybindPosition (SaveManager.lua:149
    -- saves, :266 restores), and that restore can land after this runs. An older
    -- saved position is offset-based, which under this anchor puts the panel off
    -- screen. So re-assert for a few seconds; once the position has been saved
    -- back as ours, later launches restore correctly on their own.
    task.spawn(function()
        for _, delay in ipairs({ 0.5, 1.5, 3, 5, 8 }) do
            task.wait(delay);
            local current = chrome.keybind_frame;
            if current and current.Parent then
                pcall(function()
                    current.AnchorPoint = KEYBIND_ANCHOR;
                    current.Position = corner_position(current);
                end);
            end;
        end;
    end);

    return true;
end;

return chrome;

end;

__modules["src/utility/frutiger/dress"] = function()
--[[
    src/utility/frutiger/dress.lua

    Applies the material kit across the existing tree. Nothing is rebuilt and no
    logic is touched -- this only reads geometry and sets appearance.

    It is deliberately conservative. An earlier attempt at classifying "buttons"
    by shape matched 589 elements, because almost every row in this UI is a
    small frame with a fill and a label: toggle rows, slider rows, dropdown
    rows, section headers. Styling all of them as buttons would have made the
    interface look like a wall of pills.

    So it only touches things it can identify without ambiguity:

      dividers   hairline frames. The brief asks for fewer strong lines and this
                 is where most of them are -- there are 341 of them in the live
                 tree, drawn in the theme's edge colour at full opacity.
      cards      large fills, 155 of them. These become layered glass: softer
                 border, vertical light, corner, and a soft shadow underneath.
      spacing    list padding, so rows stop touching.

    Buttons, toggles, sliders and dropdowns are NOT in this pass. They need to
    be matched by their actual structure rather than by size, and getting that
    wrong is how you end up with everything styled the same.
]]

local dress = {};

local theme_module = nil;
pcall(function() theme_module = require("@src/utility/frutiger/theme") end);

local kit = nil;
pcall(function() kit = require("@src/utility/frutiger/material") end);

local visible = nil;
pcall(function() visible = require("@src/utility/frutiger/visible") end);

if not visible then
    visible = { menu = function() return true end, on_open = function() end };
end;

local COLORS = (kit and kit.colors) or {};

local DIVIDER_MAX_HEIGHT = 3;
local DIVIDER_TRANSPARENCY = 0.72;

local CARD_MIN_WIDTH = 200;
local CARD_MIN_HEIGHT = 80;

local is_panel = function(object)
    return object:GetAttribute("glass_panel") == true;
end;

-- The chrome and the overlay are authored in their own modules and already have
-- their look; dressing them here would fight those modules.
--
-- The check stops at the chrome's DIRECT children, not anywhere beneath it. The
-- library's whole widget tree was transplanted into FRUTIGER_CHROME by
-- chrome.lua, so excluding anything under the chrome excluded the entire
-- interface -- which is what happened: only 36 of 341 dividers were softened
-- and the rest were silently skipped as "owned".
local function owned_elsewhere(object)
    local node = object;
    local depth = 0;

    while node do
        local name = node.Name;

        if name == "FRUTIGER_OVERLAY"
            or name == "glass_shadow"
            or name == "glass_specular" then
            return true;
        end;

        if name == "FRUTIGER_CHROME" then
            -- depth 0 is the shell itself; depth 1 is its own furniture (title,
            -- sidebar, rules). Deeper than that is transplanted content, which
            -- must be dressed.
            return depth <= 1;
        end;

        depth = depth + 1;
        node = node.Parent;
    end;

    return false;
end;

-- ── dividers ───────────────────────────────────────────────────────────────
-- The brief: reduce the amount of strong divider lines. There are 341 of these
-- and they are drawn at full opacity in the edge colour, which is most of why
-- the interface reads as busy. Softened rather than deleted -- they still do
-- the job of separating rows, they just stop competing with the content.
function dress.dividers()
    local softened = 0;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        if descendant:IsA("Frame") then
            local size = descendant.AbsoluteSize;

            if size.X >= 60 and size.Y > 0 and size.Y <= DIVIDER_MAX_HEIGHT
                and descendant.BackgroundTransparency < 0.9
                and not owned_elsewhere(descendant) then

                pcall(function()
                    descendant.BackgroundColor3 = Color3.fromRGB(255, 255, 255);
                    descendant.BackgroundTransparency = DIVIDER_TRANSPARENCY;
                end);
                softened = softened + 1;
            end;
        end;
    end;

    return softened;
end;

-- ── cards ──────────────────────────────────────────────────────────────────
function dress.cards()
    local dressed = 0;
    if not kit then
        return 0;
    end;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        if descendant:IsA("Frame")
            and not is_panel(descendant)
            and not owned_elsewhere(descendant) then

            local size = descendant.AbsoluteSize;

            if size.X >= CARD_MIN_WIDTH and size.Y >= CARD_MIN_HEIGHT
                and descendant.BackgroundTransparency > 0
                and descendant.BackgroundTransparency < 0.6 then

                local ok = pcall(function()
                    kit.panel(descendant, {
                        radius = 12,
                        stroke_transparency = 0.62,
                        depth = 3,
                        top_transparency = 0.60,
                        mid_transparency = 0.94,
                        bottom_transparency = 0.86,
                    });
                end);
                if ok then
                    dressed = dressed + 1;
                end;
            end;
        end;
    end;

    return dressed;
end;

-- ── spacing ────────────────────────────────────────────────────────────────
-- OFF, and deliberately left off.
--
-- The brief asks for more vertical breathing room and the obvious lever is
-- UIListLayout padding. The library does not size containers from the layout,
-- though -- it computes each section's height from its own row metrics. So
-- widening the padding makes rows overflow a container whose height was already
-- decided, and the overflow lands on whatever comes next.
--
-- Measured: padding at 6px produced 52946 overlapping text pairs across 1938
-- labels. Setting every layout's padding back to 0 in the same session dropped
-- it to 0. That is not a subtle regression, it is the entire interface drawn on
-- top of itself.
--
-- Real spacing means moving the container heights with it, which is a change to
-- how the library lays sections out rather than restyling after the fact. Not
-- worth the risk just for padding, so it stays at the library's own value.
local MIN_ROW_PADDING = 0;

function dress.spacing()
    local loosened = 0;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        local layout = descendant:IsA("UIListLayout") and descendant or nil;
        if layout and not owned_elsewhere(layout.Parent) then
            local ok = pcall(function()
                local current = layout.Padding
                if current.Offset < MIN_ROW_PADDING then
                    layout.Padding = UDim.new(0, MIN_ROW_PADDING)
                    loosened = loosened + 1
                end
            end)
        end
    end

    return loosened
end;

-- ── shadow cleanup ─────────────────────────────────────────────────────────
-- material.panel used to give every card a shadow, which is a translucent
-- offset copy of the card -- and on a light window that reads as a tinted
-- rectangle rather than a shadow. They are no longer created; this removes any
-- that already exist, so a session that is already running cleans up instead of
-- keeping them until the next injection.
function dress.clear_shadows()
    local removed = 0;
    local root = Library and Library.ScreenGui;
    if not root then return 0 end;

    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant.Name == "glass_shadow" then
            pcall(function() descendant:Destroy() end);
            removed = removed + 1;
        end;
    end;

    return removed;
end;

-- ── typography ─────────────────────────────────────────────────────────────
-- Remove every outline from text.
--
-- There is no bold font in this UI: all 2246 text elements resolve to
-- Enum.FontWeight.Regular, and only six labels anywhere use a Lexend
-- medium/bold face. The heaviness was an OUTLINE -- and outlines on text read
-- as bold.
--
-- The main source is Library:ApplyTextStroke, which adds a black 1px UIStroke
-- to every label; that one is fixed at source. This pass exists for the rest:
-- the InfoLogger's labels and the intro message are built on separate paths
-- that add their own stroke, and measured, they were the last 7 elements still
-- outlined after the source fix.
--
-- Cheaper than the other passes: it only descends into text elements rather
-- than doing anything per-frame or per-object.
function dress.typography()
    local cleared = 0;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        if descendant:IsA("TextLabel")
            or descendant:IsA("TextBox")
            or descendant:IsA("TextButton") then

            if descendant.TextStrokeTransparency < 1 then
                descendant.TextStrokeTransparency = 1;
                cleared = cleared + 1;
            end;

            for _, child in ipairs(descendant:GetChildren()) do
                if child:IsA("UIStroke") and child.Transparency < 1 then
                    child.Transparency = 1;
                    cleared = cleared + 1;
                end;
            end;
        end;
    end;

    return cleared;
end;

-- ── contrast follow-up ─────────────────────────────────────────────────────
-- Dressing changes fills, so anything the contrast guard fixed earlier can end
-- up light-on-light again. Cheap to re-run; it only touches text that is still
-- unreadable.
function dress.recheck()
    if theme_module and theme_module.fix_contrast then
        pcall(theme_module.fix_contrast);
    end;
end;

function dress.apply()
    if dress.applied then
        return true;
    end;
    if not Library or not Library.ScreenGui then
        return false;
    end;

    dress.softened_dividers = dress.dividers();
    dress.dressed_cards = dress.cards();
    dress.loosened_layouts = dress.spacing();
    dress.cleared_outlines = dress.typography();
    dress.shadows_removed = dress.clear_shadows();
    dress.recheck();

    dress.applied = true;

    -- Lazy content (tab pages, dropdown options, dependency boxes) is built on
    -- first visit, so keep re-dressing for a while as it appears.
    -- Gated on visibility for the same reason as the theme guard: four
    -- full-tree walks every 2 seconds is real cost, and all of it is invisible
    -- while the menu is shut.
    task.spawn(function()
        for _ = 1, 20 do
            task.wait(2);
            if visible.menu() then
                pcall(dress.dividers);
                pcall(dress.cards);
                pcall(dress.spacing);
                pcall(dress.typography);
        pcall(dress.clear_shadows);
                pcall(dress.clear_shadows);
                pcall(dress.recheck);
            end;
        end;
    end);

    -- Lazy content is built on first visit, so re-dress on each open rather
    -- than hoping a timer happened to catch it.
    visible.on_open(function()
        pcall(dress.dividers);
        pcall(dress.cards);
        pcall(dress.typography);
        pcall(dress.recheck);
    end);

    return true;
end;

return dress;

end;

__modules["src/utility/frutiger/glass"] = function()
--[[
    src/utility/frutiger/glass.lua

    Makes the shell read as glass rather than as a painted panel.

    Four things do that, and they only work together:

    1.  TRANSLUCENCY. An opaque fill is a wall. The window root drops to ~80%
        opacity so the game shows through it. Without this nothing else matters.

    2.  DIFFUSION. Plain transparency looks like a hole, not a pane. The frost
        layer (theme.lua) supplies the faint speckle that reads as frosted glass.
        It is deliberately at single-digit alpha -- the grunge theme ran grain at
        4-5x this strength and it read as dirt rather than diffusion.

    3.  GRADIENT. Real glass is not evenly lit. A vertical UIGradient lightens
        the top and cools the bottom, which is what makes a flat fill look like
        a curved surface catching light.

    4.  EDGE. A glass edge catches the light, so the border is brighter than the
        fill, not darker. A darker outline is the tell that something is painted
        rather than transparent.

    Panels inside get a much smaller transparency than the root. The root is
    behind everything so it can afford to be clear; the panels carry text, and a
    panel that is too clear puts dark text on whatever the player happens to be
    standing in front of.
]]

local glass = {};

-- Dials. The root can be quite clear because nothing sits directly on it; the
-- panels cannot, because text does.
local ROOT_TRANSPARENCY = 0.20;
local PANEL_TRANSPARENCY = 0.12;
local MIN_PANEL_WIDTH = 150;
local MIN_PANEL_HEIGHT = 120;

local theme_module = nil;
pcall(function() theme_module = require("@src/utility/frutiger/theme") end);

local function luminance(color)
    return 0.299 * color.R + 0.587 * color.G + 0.114 * color.B;
end;

local function colors_close(a, b)
    return math.abs(a.R - b.R) < 0.04
       and math.abs(a.G - b.G) < 0.04
       and math.abs(a.B - b.B) < 0.04;
end;

function glass.apply()
    if glass.applied then
        return true;
    end;
    if not Library or not Library.ScreenGui then
        return false;
    end;

    local WHITE = Color3.fromRGB(255, 255, 255);
    local SKY = Color3.fromRGB(198, 230, 248);

    local outer = Library.FrutigerWindow and Library.FrutigerWindow.Holder;
    local chrome = outer and outer:FindFirstChild("FRUTIGER_CHROME");

    -- ── the window pane ────────────────────────────────────────────────────
    if chrome then
        pcall(function()
            chrome.BackgroundTransparency = ROOT_TRANSPARENCY;
        end);

        -- vertical light: bright at the top, cooler toward the bottom
        pcall(function()
            local gradient = chrome:FindFirstChildOfClass("UIGradient");
            if not gradient then
                gradient = Instance.new("UIGradient");
                gradient.Name = "glass_gradient";
                gradient.Parent = chrome;
            end;
            gradient.Rotation = 90;
            gradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(0.45, Color3.fromRGB(243, 251, 255)),
                ColorSequenceKeypoint.new(1.00, SKY),
            });
        end);

        -- catch the light on the edge rather than darkening it
        pcall(function()
            local stroke = chrome:FindFirstChildOfClass("UIStroke");
            if stroke then
                stroke.Color = WHITE;
                stroke.Thickness = 1.5;
                stroke.Transparency = 0.10;
                stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border;
            end;
        end);

        glass.chrome = chrome;
    end;

    -- ── inner panels ───────────────────────────────────────────────────────
    -- Only large, flat, palette-coloured fills, and only ones that are currently
    -- fully opaque. Small elements (toggle knobs, slider thumbs, dividers) are
    -- left alone: they need to stay solid to read, and translucency there just
    -- muddies them.
    local softened = 0;
    local main = Library.MainColor;
    local background = Library.BackgroundColor;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        local ok = pcall(function()
            if not descendant:IsA("Frame") then
                return;
            end;
            if descendant.BackgroundTransparency ~= 0 then
                return;
            end;

            local size = descendant.AbsoluteSize;
            if size.X < MIN_PANEL_WIDTH or size.Y < MIN_PANEL_HEIGHT then
                return;
            end;

            local fill = descendant.BackgroundColor3;
            if not (colors_close(fill, main) or colors_close(fill, background)) then
                return;
            end;

            -- Do not soften the shell itself; it already has its own value, and
            -- softening an opaque ancestor of everything would compound.
            if descendant.Name == "FRUTIGER_CHROME" then
                return;
            end;

            descendant.BackgroundTransparency = PANEL_TRANSPARENCY;

            -- give panels the same vertical light as the window, at a gentler
            -- strength, so they read as the same material
            if not descendant:FindFirstChildOfClass("UIGradient") then
                local gradient = Instance.new("UIGradient");
                gradient.Name = "glass_gradient";
                gradient.Rotation = 90;
                gradient.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(1.00, Color3.fromRGB(232, 246, 254)),
                });
                gradient.Parent = descendant;
            end;

            softened = softened + 1;
        end);
    end;

    glass.applied = true;
    glass.softened = softened;
    glass.transparency = { root = ROOT_TRANSPARENCY, panel = PANEL_TRANSPARENCY };

    return true;
end;

return glass;

end;

__modules["src/utility/frutiger/hover"] = function()
--[[
    src/utility/frutiger/hover.lua

    Hover effect for the CONSOLE theme: the element inverts.

    The library already has a hover, but it is only a faint tint -- it spawns a
    child Frame inside the hovered element with BackgroundColor3 =
    Library.AccentColor and tweens its transparency (ui.lua ~2156). On a black
    surface that is almost invisible, and it never touches the label.

    This inverts instead: a black row goes solid white with black text, a light
    element goes the other way, with a two-frame flicker on the way in. Same
    spirit as the "inversione dei colori" in the art brief.

    Finding targets: the library ships ZERO TextButtons -- everything clickable
    is a Frame with an input connection, which cannot be queried. So elements
    are matched on shape instead: a fill you can see, a label inside, 14-44px
    tall, at least 80px wide. That measured 463 elements on a live client.
]]

local hover = {};

local visible = nil;
pcall(function() visible = require("@src/utility/frutiger/visible") end);
if not visible then
    visible = { menu = function() return true end, on_open = function() end };
end;

local states = setmetatable({}, { __mode = "k" });
local attached_count = 0;

-- The palette, for the accent used on hover. pcall'd because a missing theme
-- should cost the hover tint, not the hover.
local theme_module = nil;
pcall(function() theme_module = require("@src/utility/frutiger/theme") end);

-- One step now -- no flicker. The Frutiger version lights the row up rather
-- than blinking it, so the multi-frame toggle that read as a failing monitor is
-- gone. Three steps was the previous grunge behaviour.
local FLICKER_STEPS = 1;
local FLICKER_DELAY = 0.028;

-- ── target selection ───────────────────────────────────────────────────────
local function has_label(object)
    for _, child in ipairs(object:GetDescendants()) do
        if child:IsA("TextLabel") then
            return true;
        end;
    end;
    return false;
end;

local function is_candidate(object)
    if states[object] then
        return false;
    end;

    local ok, result = pcall(function()
        if object:IsA("TextButton") or object:IsA("ImageButton") then
            return true;
        end;

        if not (object:IsA("Frame") or object:IsA("TextBox")) then
            return false;
        end;

        local height = object.AbsoluteSize.Y;
        if height < 14 or height > 44 then
            return false;
        end;
        if object.AbsoluteSize.X < 80 then
            return false;
        end;

        -- needs some fill to invert; a fully transparent layout row has nothing
        -- to turn white
        if object.BackgroundTransparency >= 0.9 then
            return false;
        end;

        return has_label(object);
    end);

    return ok and result == true;
end;

-- ── the effect ─────────────────────────────────────────────────────────────
local function collect_text(object)
    local list = {};
    for _, child in ipairs(object:GetDescendants()) do
        if child:IsA("TextLabel") or child:IsA("TextBox") then
            list[#list + 1] = child;
        end;
    end;
    return list;
end;

-- Frutiger hover: the element lights up in the accent, it does not invert.
--
-- The previous pass flipped black to white and back, which read as a terminal
-- blink and is the opposite of this theme. Here the fill goes to the sky accent
-- and the label goes dark.
--
-- Dark text rather than white on purpose: the contrast guard (theme.fix_contrast)
-- darkens light text sitting on a light fill, and the accent is light enough to
-- trip it. Dark text on the accent satisfies the guard instead of fighting it.
local function hover_targets()
    local theme = theme_module;
    local accent = (theme and theme.extra and theme.extra.aqua) or Color3.fromRGB(41, 168, 224);
    local ink = (theme and theme.extra and theme.extra.ink) or Color3.fromRGB(14, 61, 92);
    return accent, ink;
end;

local function paint(state, inverted)
    local object = state.object;

    if inverted then
        pcall(function()
            object.BackgroundColor3 = state.target_bg;
            object.BackgroundTransparency = state.target_transparency;
        end);
        for _, label in ipairs(state.targets) do
            pcall(function() label.TextColor3 = state.target_text end);
        end;
    else
        pcall(function()
            if state.original_bg then
                object.BackgroundColor3 = state.original_bg;
            end;
            object.BackgroundTransparency = state.original_transparency;
        end);
        for index, label in ipairs(state.targets) do
            local original = state.original_text[index];
            if original then
                pcall(function() label.TextColor3 = original end);
            end;
        end;
    end;
end;

-- Snapshot at enter, not at attach. The library repaints text colours on theme
-- changes, so a snapshot taken when the connection was made goes stale and
-- leaving the element would restore a colour from an earlier theme.
local function snapshot(state)
    local object = state.object;

    state.targets = collect_text(object);
    state.original_text = {};
    for index, label in ipairs(state.targets) do
        state.original_text[index] = label.TextColor3;
    end;

    state.original_bg = object.BackgroundColor3;
    state.original_transparency = object.BackgroundTransparency;

    local background, text = hover_targets();
    state.target_bg = background;
    state.target_text = text;
    -- keep the fill visible, but only as opaque as the original was: a row that
    -- is already a solid panel should not become translucent on hover
    state.target_transparency = math.min(object.BackgroundTransparency, 0.10);
end;

local function on_enter(object)
    local state = states[object];
    if not state then
        return;
    end;

    snapshot(state);
    state.hovered = true;
    state.token = (state.token or 0) + 1;
    local token = state.token;

    -- flicker in rather than fade. 1-2 hard toggles over ~60ms.
    task.spawn(function()
        for step = 1, FLICKER_STEPS do
            if not state.hovered or state.token ~= token then
                return;
            end;
            paint(state, step % 2 == 1);
            task.wait(FLICKER_DELAY);
        end;
        if state.hovered and state.token == token then
            paint(state, true);
        end;
    end);
end;

local function on_leave(object)
    local state = states[object];
    if not state then
        return;
    end;

    state.hovered = false;
    state.token = (state.token or 0) + 1;   -- invalidate any in-flight flicker
    paint(state, false);
end;

-- ── attach ─────────────────────────────────────────────────────────────────
function hover.apply()
    if not Library or not Library.ScreenGui then
        return 0;
    end;

    local attached = 0;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        if is_candidate(descendant) then
            local state = { object = descendant };
            states[descendant] = state;

            local ok = pcall(function()
                descendant.MouseEnter:Connect(function() on_enter(descendant) end);
                descendant.MouseLeave:Connect(function() on_leave(descendant) end);
            end);

            if ok then
                attached = attached + 1;
                attached_count = attached_count + 1;
            else
                states[descendant] = nil;
            end;
        end;
    end;

    return attached;
end;

-- The library builds tab contents and dropdown options lazily, so new elements
-- keep appearing after the first pass.
function hover.start_watchdog()
    if hover.watching then
        return;
    end;
    hover.watching = true;

    -- Gated: this is a full-tree walk, and it was running whether or not the
    -- menu was on screen.
    task.spawn(function()
        for _ = 1, 8 do
            task.wait(2);
            if visible.menu() then
                pcall(hover.apply);
            end;
        end;
    end);
end;

function hover.count()
    return attached_count;
end;

return hover;

end;

__modules["src/utility/frutiger/material"] = function()
--[[
    src/utility/frutiger/material.lua

    The styling kit. Every visual in this theme comes from here rather than being
    set per element, so the material stays consistent and a change to the
    language is one edit instead of two hundred.

    What it provides, and why each exists:

      corner      rounded geometry. Glass has no sharp edges.
      stroke      a soft border. Bright, never a hard coloured outline -- heavy
                  borders are what make a glass UI read as a flat dashboard with
                  blue trim rather than as layered panes.
      gradient    the vertical light. Top edge brighter (reflected light),
                  middle clear, bottom faintly cyan. This is what sells a flat
                  fill as a curved surface.
      shadow      depth. Roblox cannot blur, so this is a translucent offset
                  frame behind the element. It reads as a soft drop shadow at
                  small depths and avoids looking like a hard cast.
      specular    a small radial white highlight from the orb texture, placed
                  off-centre. Individually barely visible; collectively it is
                  what makes the surfaces feel wet.
      hover       brightness and tint on MouseEnter / MouseLeave. Tweened, so it
                  feels like light moving rather than a state flip.
      press       a small scale and dim on click, so buttons feel physical.

    Everything is instance-driven and pcall-guarded: a missing texture or a
    locked property costs one highlight, never the interface.
]]

local material = {};

local TWEEN = game:GetService("TweenService");

-- ── palette ────────────────────────────────────────────────────────────────
local theme_module = nil;
pcall(function() theme_module = require("@src/utility/frutiger/theme") end);

local extra = (theme_module and theme_module.extra) or {};

material.colors = {
    glass    = extra.glass or Color3.fromRGB(234, 251, 255),
    bgGlass  = extra.bgGlass or Color3.fromRGB(220, 245, 255),
    sky      = extra.sky or Color3.fromRGB(216, 243, 255),
    cyan     = extra.aqua or Color3.fromRGB(55, 199, 255),
    cyan2    = extra.cyan2 or Color3.fromRGB(93, 216, 255),
    cyan3    = extra.cyan3 or Color3.fromRGB(123, 229, 255),
    white    = Color3.fromRGB(255, 255, 255),
    ink      = extra.ink or Color3.fromRGB(32, 56, 74),
    muted    = extra.muted or Color3.fromRGB(85, 115, 131),
    shadow   = Color3.fromRGB(78, 150, 180),
};

-- standard timings
material.FAST = 0.15;
material.SOFT = 0.22;

-- ── primitives ─────────────────────────────────────────────────────────────
local function find_class(object, class)
    for _, child in ipairs(object:GetChildren()) do
        if child:IsA(class) then
            return child;
        end;
    end;
    return nil;
end;

-- True when the object positions its own children itself. Adding an instance to
-- such an object (or beside one) makes it a layout item too, which silently
-- doubles the row count and overlaps everything.
--
-- This was not theoretical: the first version of panel() gave 82 cards both a
-- shadow (a SIBLING frame) and a specular (a CHILD image), so every
-- list-layout container was asked to lay out roughly twice as many rows as it
-- had. The result was text drawn on top of text across the whole interface.
local function layout_managed(object)
    if not object then
        return false;
    end;

    for _, child in ipairs(object:GetChildren()) do
        if child:IsA("UIListLayout")
            or child:IsA("UIGridLayout")
            or child:IsA("UITableLayout") then
            return true;
        end;
    end;

    return false;
end;

function material.corner(object, radius)
    radius = radius or 12;
    local existing = find_class(object, "UICorner");
    if existing then
        pcall(function() existing.CornerRadius = UDim.new(0, radius) end);
        return existing;
    end;

    local corner = Instance.new("UICorner");
    corner.CornerRadius = UDim.new(0, radius);
    corner.Parent = object;
    return corner;
end;

function material.stroke(object, options)
    options = options or {};
    local stroke = find_class(object, "UIStroke");
    if not stroke then
        stroke = Instance.new("UIStroke");
        stroke.Parent = object;
    end;

    pcall(function()
        stroke.Color = options.color or material.colors.white;
        stroke.Thickness = options.thickness or 1;
        stroke.Transparency = options.transparency or 0.55;
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border;
    end);

    return stroke;
end;

-- top brighter, middle clear, bottom faint cyan. Left subtle on purpose: an
-- aggressive ramp looks like a plastic gradient rather than glass.
function material.gradient(object, options)
    options = options or {};
    local gradient = find_class(object, "UIGradient");
    if not gradient then
        gradient = Instance.new("UIGradient");
        gradient.Name = "glass";
        gradient.Parent = object;
    end;

    pcall(function()
        gradient.Rotation = options.rotation or 90;
        gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.00, options.top or material.colors.white),
            ColorSequenceKeypoint.new(0.50, options.middle or material.colors.glass),
            ColorSequenceKeypoint.new(1.00, options.bottom or material.colors.cyan3),
        });
        gradient.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0.00, options.top_transparency or 0.55),
            NumberSequenceKeypoint.new(0.45, options.mid_transparency or 0.90),
            NumberSequenceKeypoint.new(1.00, options.bottom_transparency or 0.80),
        });
    end);

    return gradient;
end;

-- Roblox has no blur, so a shadow is a translucent offset copy sitting behind.
-- Small depths only: at large offsets the lack of blur becomes obvious and it
-- looks like a dupe rather than a shadow.
function material.shadow(object, options)
    options = options or {};
    if object:FindFirstChild("glass_shadow") then
        return;
    end;

    -- A shadow is a SIBLING. Beside a layout-managed object it becomes an
    -- extra row in that layout, which is how the overlap started.
    if layout_managed(object.Parent) then
        return nil;
    end;

    local depth = options.depth or 3;
    local shadow = Instance.new("Frame");
    shadow.Name = "glass_shadow";
    shadow.BackgroundColor3 = options.color or material.colors.shadow;
    shadow.BackgroundTransparency = options.transparency or 0.86;
    shadow.BorderSizePixel = 0;
    shadow.Active = false;
    shadow.ZIndex = math.max(0, (object.ZIndex or 1) - 1);
    shadow.Size = object.Size;
    shadow.Position = object.Position + UDim2.fromOffset(0, depth);
    shadow.AnchorPoint = object.AnchorPoint;
    shadow.Parent = object.Parent;

    local radius = options.radius or 12;
    local corner = Instance.new("UICorner");
    corner.CornerRadius = UDim.new(0, radius);
    corner.Parent = shadow;

    object:GetPropertyChangedSignal("Size"):Connect(function()
        pcall(function() shadow.Size = object.Size end);
    end);
    object:GetPropertyChangedSignal("Position"):Connect(function()
        pcall(function() shadow.Position = object.Position + UDim2.fromOffset(0, depth) end);
    end);

    return shadow;
end;

function material.specular(object, options)
    options = options or {};
    local texture = theme_module and theme_module.textures and theme_module.textures.orb;
    if not texture then
        return nil;
    end;

    -- A specular is a CHILD, so it is also a layout item when the host lays
    -- out its own children.
    if layout_managed(object) then
        return nil;
    end;

    local dot = Instance.new("ImageLabel");
    dot.Name = "glass_specular";
    dot.BackgroundTransparency = 1;
    dot.BorderSizePixel = 0;
    dot.Image = texture;
    dot.ImageColor3 = material.colors.white;
    dot.ImageTransparency = options.transparency or 0.80;
    dot.AnchorPoint = options.anchor or Vector2.new(0, 0);
    dot.Position = options.position or UDim2.new(0, 3, 0, 2);
    dot.Size = options.size or UDim2.fromOffset(14, 14);
    dot.ZIndex = (object.ZIndex or 1) + 1;
    dot.Active = false;
    dot.Parent = object;

    return dot;
end;

-- ── motion ─────────────────────────────────────────────────────────────────
local function tween(object, properties, duration, style)
    local info = TweenInfo.new(
        duration or material.SOFT,
        style or Enum.EasingStyle.Quad,
        Enum.EasingDirection.Out
    );
    local ok, result = pcall(function()
        return TWEEN:Create(object, info, properties);
    end);
    if ok and result then
        result:Play();
    end;
    return result;
end;

material.tween = tween;

-- Adds a soft light-up on hover. Written to record the element's CURRENT values
-- at enter rather than at attach: the library repaints colours on theme change,
-- so a snapshot taken at attach time goes stale and leaving would restore an
-- older theme's colour.
function material.hover(object, options)
    options = options or {};
    if object:GetAttribute("glass_hover") then
        return;
    end;
    object:SetAttribute("glass_hover", true);

    local state = {};

    object.MouseEnter:Connect(function()
        state.bg = object.BackgroundColor3;
        state.transparency = object.BackgroundTransparency;

        local target = options.tint or material.colors.cyan2;
        tween(object, {
            BackgroundColor3 = state.bg:Lerp(target, options.strength or 0.45),
            BackgroundTransparency = math.max(0, state.transparency - (options.lift or 0.10)),
        }, material.FAST);
    end);

    object.MouseLeave:Connect(function()
        if not state.bg then
            return;
        end;
        tween(object, {
            BackgroundColor3 = state.bg,
            BackgroundTransparency = state.transparency,
        }, material.FAST);
    end);
end;

function material.press(object, options)
    options = options or {};
    if object:GetAttribute("glass_press") then
        return;
    end;
    object:SetAttribute("glass_press", true);

    local base = options.scale or 0.985;

    -- Captured on press, not at attach and not on release. At attach it is stale
    -- by the time anything is clicked; on release the size is already the
    -- shrunken one, so restoring it would leave the button permanently small.
    local before = nil;

    object.MouseButton1Down:Connect(function()
        before = object.Size;
        tween(object, { Size = UDim2.new(
            before.X.Scale * base, before.X.Offset * base,
            before.Y.Scale * base, before.Y.Offset * base
        ) }, 0.08);
    end);

    object.MouseButton1Up:Connect(function()
        if before then
            tween(object, { Size = before }, 0.14);
        end;
    end);
end;

-- ── composites ─────────────────────────────────────────────────────────────
function material.panel(object, options)
    options = options or {};
    material.corner(object, options.radius or 12);
    material.stroke(object, {
        color = options.stroke_color,
        transparency = options.stroke_transparency or 0.55,
        thickness = options.stroke_thickness or 1,
    });
    material.gradient(object, options);

    -- Shadows are opt-in, and off.
    --
    -- They were on for every panel. Roblox has no blur, so material.shadow is a
    -- translucent OFFSET COPY of the object, and 43 of them were live. On a
    -- light translucent window that does not read as a soft shadow -- it reads
    -- as a tinted rounded rectangle, visible through the panel above it and
    -- extending past its edge. Reported as "a square left on the screen" when
    -- the window is moved.
    --
    -- Real depth needs real blur, which Roblox does not give a ScreenGui. An
    -- approximation that produces visible rectangles is worse than no shadow.
    if options.shadow == true then
        material.shadow(object, { radius = options.radius or 12, depth = options.depth or 3 });
    end;
    if options.specular ~= false then
        material.specular(object, options.specular_options);
    end;
    object:SetAttribute("glass_panel", true);
    return object;
end;

-- A button is a panel that reacts: brighter on hover, smaller on press.
function material.button(object, options)
    options = options or {};
    options.radius = options.radius or 10;
    material.panel(object, options);
    material.hover(object, options);
    material.press(object, options);
    object:SetAttribute("glass_button", true);
    return object;
end;

-- A pill is a button with full rounding -- used for compact controls where the
-- radius should read as a capsule rather than a card.
function material.pill(object, options)
    options = options or {};
    options.radius = math.huge;   -- clamped by Roblox to half the height
    return material.button(object, options);
end;

return material;

end;

__modules["src/utility/frutiger/migrate"] = function()
--[[
    src/utility/frutiger/migrate.lua

    DECAY shipped previously as "Project Rain". Every install from before the
    rename still has a `Project Rain/` folder holding the user's configs,
    fflags, asset cache, logs and script state. A straight folder rename would
    present everyone with a blank slate.

    This copies the legacy tree forward once, and leaves the old folder in place
    untouched so a rollback still works. Runs from luarmor_init_script before
    src/init.lua creates any folder, because init.lua's `if not isfolder(...)
    then makefolder(...) end` checks would otherwise create empty directories
    first and the migration would skip.

    Note: `ProjectRainRewrite` handled elsewhere in src/ui/config_converter.lua
    is an even older layout and is deliberately not touched here.
]]

local migrate = {};

-- Newest-first. Both are real folder names that have shipped.
local LEGACY  = { "Console", "Decay", "Project Rain" };
local CURRENT = "Frutiger";

local function normalize(path)
    return (path:gsub("\\", "/"));
end;

local function copy_tree(source, destination)
    if not isfolder(destination) then
        local ok = pcall(makefolder, destination);
        if not ok then
            return 0;
        end;
    end;

    local ok, entries = pcall(listfiles, source);
    if not ok or type(entries) ~= "table" then
        return 0;
    end;

    local prefix = normalize(source) .. "/";
    local copied = 0;

    for _, entry in next, entries do
        local normalized = normalize(entry);

        -- listfiles may hand back an absolute path; fall back to the leaf.
        local relative;
        if normalized:sub(1, #prefix) == prefix then
            relative = normalized:sub(#prefix + 1);
        else
            relative = normalized:match("([^/]+)$") or "";
        end;

        if relative ~= "" then
            local target = destination .. "/" .. relative;

            if isfolder(entry) then
                copied = copied + copy_tree(entry, target);
            elseif isfile(entry) then
                local read_ok, contents = pcall(readfile, entry);
                if read_ok and contents then
                    local write_ok = pcall(writefile, target, contents);
                    if write_ok then
                        copied = copied + 1;
                    end;
                end;
            end;
        end;
    end;

    return copied;
end;

local MARKER = CURRENT .. "/migrated_from_legacy.txt";

local function count_files(path)
    local ok, entries = pcall(listfiles, path);
    if not ok or type(entries) ~= "table" then
        return 0;
    end;

    local n = 0;
    for _, entry in next, entries do
        if isfile(entry) then
            n = n + 1;
        end;
    end;

    return n;
end;

-- Returns the number of files copied. Zero means "nothing to do", which is the
-- normal case on a fresh install and on every run after the first.
function migrate.run()
    local ok, result = pcall(function()
        -- Two legacy names now. "Project Rain" is the original release; "Decay"
        -- was the intermediate rename that shipped for a while. Both have to be
        -- checked, in newest-first order, or an install that upgraded through
        -- Decay strands its configs.
        local source;
        for _, candidate in ipairs(LEGACY) do
            if isfolder(candidate) then
                source = candidate;
                break;
            end;
        end;

        if not source then
            return 0;                                  -- nothing to migrate from
        end;
        if isfile(MARKER) then
            return 0;                                  -- already done, once and for all
        end;

        -- Was: `if isfolder(CURRENT) then return 0 end`. That latch was wrong.
        -- A run that died partway leaves Frutiger/ present but partial, and the
        -- migration would then never fire again — stranding the user's configs
        -- in the old folder permanently with no message. Only treat the
        -- destination as done when it already holds at least as many files as
        -- the source.
        if isfolder(CURRENT) then
            local legacy_count = count_files(source);
            local current_count = count_files(CURRENT);
            if legacy_count > 0 and current_count >= legacy_count then
                return 0;
            end;
        end;

        local copied = copy_tree(source, CURRENT);

        -- Written on every attempt, so a partial destination is retried on the
        -- next run rather than being treated as finished.
        pcall(writefile, MARKER, string.format(
            "copied %d file(s) from '%s'\n%s\n",
            copied, source, os.date("%Y-%m-%d %H:%M:%S")
        ));

        migrate.last_source = source;
        return copied;
    end);

    if not ok then
        warn("[frutiger] migration failed:", result);
        return 0;
    end;

    if result and result > 0 then
        print(string.format("[frutiger] migrated %d file(s) from '%s' to '%s'",
            result, migrate.last_source or "?", CURRENT));
    end;

    return result or 0;
end;

return migrate;

end;

__modules["src/utility/frutiger/round"] = function()
--[[
    src/utility/frutiger/round.lua

    Rounds the corners of every visible element in the UI.

    Post-pass again, same as theme.lua and sidebar.lua: nothing in the library
    is edited, elements are decorated after they exist.

    Rules, in order of how much they matter:

    1.  Never touch an element that already has a UICorner. Several controls in
        this library build their own (toggle knobs are circular), and
        overwriting those flattens them.

    2.  Only round things where a corner is actually visible: an element with a
        background you can see, or a UIStroke that needs to follow the shape.
        Rounding a transparent layout container does nothing except clip its
        children unexpectedly.

    3.  Skip pure image elements (icons). Rounding a bitmap crops its artwork.

    4.  The theme overlay gets the same radius as the window it sits in, and so
        do its layers. ClipsDescendants on a rounded frame does not reliably
        clip to the rounded shape, so without this the square grain and
        scanlines would show through the window's rounded corners.
]]

local round = {};

local visible = nil;
pcall(function() visible = require("@src/utility/frutiger/visible") end);
if not visible then
    visible = { menu = function() return true end, on_open = function() end };
end;

local RADIUS = 12.0;

local function add_corner(object, radius)
    if object:FindFirstChildOfClass("UICorner") then
        return false;
    end;

    local ok = pcall(function()
        local corner = Instance.new("UICorner");
        corner.CornerRadius = UDim.new(0, radius);

        -- UICorner is not affected by sibling order, but parenting last keeps
        -- it out of the way of the library's own child lookups.
        corner.Parent = object;
    end);

    return ok;
end;

local function should_round(object)
    if not object:IsA("GuiObject") then
        return false;
    end;

    -- already shaped by the library
    if object:FindFirstChildOfClass("UICorner") then
        return false;
    end;

    local stroke = object:FindFirstChildOfClass("UIStroke");

    -- a pure image element: rounding would crop the artwork
    if object:IsA("ImageLabel") and object.Image ~= "" and not stroke then
        return object.BackgroundTransparency < 0.95;
    end;

    -- visible fill, or a border that has to follow the shape
    if object.BackgroundTransparency < 0.95 then
        return true;
    end;

    return stroke ~= nil;
end;

function round.apply()
    if not Library or not Library.ScreenGui then
        return 0;
    end;

    local applied = 0;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        if should_round(descendant) then
            local radius = RADIUS;

            -- Clamp against the SHORTEST dimension, not the height. Clamping on
            -- height alone turns thin elements into pills -- a 3px-wide slider
            -- track was getting a 6px radius and rendering as a lens.
            local size = descendant.AbsoluteSize;
            local shortest = math.min(size.X, size.Y);
            if shortest > 0 and shortest < RADIUS * 2 then
                radius = math.max(1, math.floor(shortest / 2));
            end;

            if add_corner(descendant, radius) then
                applied = applied + 1;
            end;
        end;
    end;

    -- the overlay has to match the window it lives in, layers included
    pcall(function()
        local window = Library.FrutigerWindow and Library.FrutigerWindow.Holder;
        local holder = window and window:FindFirstChild("FRUTIGER_OVERLAY");
        if not holder then
            return;
        end;

        add_corner(holder, RADIUS);
        for _, child in ipairs(holder:GetChildren()) do
            if child:IsA("GuiObject") then
                add_corner(child, RADIUS);
            end;
        end;
    end);

    return applied;
end;

-- The library builds some elements lazily -- dropdown options, tooltips, tab
-- contents on first visit -- so a one-shot pass misses them. Cheap to re-scan.
function round.start_watchdog()
    if round.watching then
        return;
    end;
    round.watching = true;

    -- Gated: this is a full-tree walk, and it was running whether or not the
    -- menu was on screen.
    task.spawn(function()
        for _ = 1, 8 do
            task.wait(2);
            if visible.menu() then
                pcall(round.apply);
            end;
        end;
    end);
end;

return round;

end;

__modules["src/utility/frutiger/sidebar"] = function()
--[[
    src/utility/frutiger/sidebar.lua

    Turns the library's horizontal tab strip into a left sidebar, and moves the
    window title into that sidebar as its header.

    Same philosophy as frutiger/theme.lua: this is a post-pass over the built UI,
    not an edit to the 2500-line library. The library stays swappable.

    The layout it operates on (measured from the live tree):

        Outer (550x550)
          Inner (548x548)
            TextLabel  "FRUTIGER // USER_xxx"   546x19   <- title, moves to sidebar
            TextBox    search                136x21   top-right, shifts by W
            container (546x525)
              holder (546x525)
                separator                     546x2
                STRIP                         546x22   <- becomes the sidebar
                  [ 110, 109, 109, 109, 109 ]          5 tab frames
                content (546x525 at y+22)
                  column A 266 wide
                  column B 266 wide

    The window is widened by SIDEBAR_WIDTH rather than squeezing the two 266px
    content columns, so nothing inside a groupbox reflows or clips. Content
    keeps its exact width and just moves right.
]]

local sidebar = {};

local SIDEBAR_WIDTH = 132;
local TAB_HEIGHT = 22;
local TAB_PADDING = 3;

-- ── helpers ────────────────────────────────────────────────────────────────
local function gui_children(parent)
    local out = {};
    for _, child in ipairs(parent:GetChildren()) do
        if child:IsA("GuiObject") then
            out[#out + 1] = child;
        end;
    end;
    return out;
end;

local function add_width(object, delta)
    object.Size = UDim2.new(
        object.Size.X.Scale, object.Size.X.Offset + delta,
        object.Size.Y.Scale, object.Size.Y.Offset
    );
end;

local function shift_x(object, delta)
    object.Position = UDim2.new(
        object.Position.X.Scale, object.Position.X.Offset + delta,
        object.Position.Y.Scale, object.Position.Y.Offset
    );
end;

local function text_of(object)
    local ok, text = pcall(function() return object.Text end);
    if not ok or type(text) ~= "string" then
        return "";
    end;
    return (text:gsub("<[^>]+>", ""));
end;

-- ── locate ─────────────────────────────────────────────────────────────────
-- The tab strip is the only wide, short Frame carrying a horizontal
-- UIListLayout with a handful of children. Matching on shape rather than on a
-- name or child index survives the library renaming or reordering things.
local function find_strip(root)
    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("Frame") then
            local layout = descendant:FindFirstChildOfClass("UIListLayout");
            if layout and layout.FillDirection == Enum.FillDirection.Horizontal then
                local count = #gui_children(descendant);
                if count >= 2 and count <= 12
                    and descendant.AbsoluteSize.X > descendant.AbsoluteSize.Y * 4 then
                    return descendant, layout;
                end;
            end;
        end;
    end;
    return nil;
end;

-- The window title. Matched structurally, not by brand string: this used to
-- search for "DECAY" and would have silently stopped finding the title when the
-- script was renamed to CONSOLE, leaving the header stuck in the old place.
-- The title is the window body's own TextLabel, so look at direct children and
-- take the topmost.
local function find_title(inner)
    local best;
    for _, child in ipairs(gui_children(inner)) do
        if child:IsA("TextLabel") then
            if not best or child.AbsolutePosition.Y < best.AbsolutePosition.Y then
                best = child;
            end;
        end;
    end;
    return best;
end;

local function find_search_box(root)
    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("TextBox") then
            return descendant;
        end;
    end;
    return nil;
end;

-- ── apply ──────────────────────────────────────────────────────────────────
local function build(outer)
    local strip, layout = find_strip(outer);
    if not strip or not layout then
        return false, "no horizontal tab strip found";
    end;

    local holder = strip.Parent;
    local container = holder and holder.Parent;

    -- Inner is the first *direct* child Frame that isn't the theme overlay.
    -- FindFirstChildWhichIsA would hand back FRUTIGER_OVERLAY, which is also a
    -- Frame, and we would widen the overlay instead of the window body.
    local inner;
    for _, child in ipairs(gui_children(outer)) do
        if child.Name ~= "FRUTIGER_OVERLAY" then
            inner = child;
            break;
        end;
    end;

    if not holder or not container or not inner then
        return false, "could not resolve the frame chain";
    end;

    local siblings = gui_children(holder);
    local separator, content;
    for _, sibling in ipairs(siblings) do
        if sibling ~= strip then
            if sibling.AbsoluteSize.Y <= 6 then
                separator = separator or sibling;
            elseif sibling.AbsoluteSize.Y > 100 then
                content = content or sibling;
            end;
        end;
    end;

    local search = find_search_box(inner);
    local title = find_title(inner);

    -- Measure before touching anything. Once the window is resized these
    -- values are gone.
    local content_width = content and content.AbsoluteSize.X or nil;
    local separator_height = separator and separator.AbsoluteSize.Y or nil;

    -- ── widen ──────────────────────────────────────────────────────────────
    -- Only the window itself is widened outright. Its descendants are mostly
    -- scale-sized (Inner is 1,-2 of Outer, and so on), so they follow on their
    -- own -- explicitly widening those double-counts. The earlier version did
    -- exactly that and produced an 812px Inner inside a 682px window.
    add_width(outer, SIDEBAR_WIDTH);

    -- Only genuinely fixed-width frames along the chain need help. Threshold is
    -- on Scale, not Offset: anything mostly scaled is already relative.
    for _, object in ipairs({ inner, container, holder }) do
        if object and object.Size.X.Scale <= 0.5 then
            add_width(object, SIDEBAR_WIDTH);
        end;
    end;

    -- The separator is a hairline that should span whatever the window is now.
    if separator then
        separator.Size = UDim2.new(1, 0, 0, separator_height or separator.Size.Y.Offset);
    end;

    -- Content is pinned to the width it had and pushed right by the sidebar.
    -- Left to scale it would stretch across the new window and drag both 266px
    -- columns out of position.
    if content and content_width then
        content.Size = UDim2.new(0, content_width, content.Size.Y.Scale, content.Size.Y.Offset);
        content.Position = UDim2.new(0, SIDEBAR_WIDTH, content.Position.Y.Scale, content.Position.Y.Offset);
    end;

    -- Right-anchored widgets keep their gap to the edge by shifting by the same
    -- amount -- but only when they are fixed-offset. One anchored with scale 1
    -- is already following the widened parent, and shifting it again pushes it
    -- clean off the window (measured: search box at x=1260 in a window that
    -- ends at 1301).
    if search and search.Position.X.Scale <= 0.5 then
        shift_x(search, SIDEBAR_WIDTH);
    end;

    -- ── the strip becomes the sidebar ──────────────────────────────────────
    strip.Position = UDim2.new(0, 6, 0, 24);
    strip.Size = UDim2.new(0, SIDEBAR_WIDTH - 12, 1, -30);

    layout.FillDirection = Enum.FillDirection.Vertical;
    layout.HorizontalAlignment = Enum.HorizontalAlignment.Left;
    layout.Padding = UDim.new(0, TAB_PADDING);

    -- ── the title becomes the sidebar header ───────────────────────────────
    if title then
        title.Position = UDim2.new(0, 8, 0, 5);
        title.Size = UDim2.new(0, SIDEBAR_WIDTH - 16, 0, 16);
        title.TextXAlignment = Enum.TextXAlignment.Left;
        pcall(function() title.TextSize = 13 end);
        pcall(function()
            local stroke = title:FindFirstChildOfClass("UIStroke");
            if stroke then stroke.Transparency = 0.35 end;
        end);
    end;

    sidebar.strip = strip;
    sidebar.layout = layout;
    sidebar.title = title;
    sidebar.content = content;
    sidebar.outer = outer;

    return true;
end;

-- The library re-sizes and re-shows tab buttons on switch, which can undo the
-- row sizing. Cheap to re-assert; called on tab click and by a short watchdog.
function sidebar.reassert()
    if not sidebar.strip or not sidebar.strip.Parent then
        return false;
    end;

    local ok = pcall(function()
        local children = gui_children(sidebar.strip);
        local count = #children;
        if count == 0 then
            return;
        end;

        -- fill the column, sharing any leftover height across the tabs so a
        -- short sidebar doesn't leave a ragged gap at the bottom
        local available = sidebar.strip.AbsoluteSize.Y - (TAB_PADDING * (count - 1));
        local height = math.floor(available / count);
        if height < TAB_HEIGHT then
            height = TAB_HEIGHT;
        end;
        if height > 34 then
            height = 34;
        end;

        for _, tab in ipairs(children) do
            tab.Size = UDim2.new(1, 0, 0, height);
        end;
    end);

    return ok;
end;

function sidebar.apply()
    if sidebar.applied then
        return true;
    end;

    if not Library then
        return false;
    end;

    local outer = Library.FrutigerWindow and Library.FrutigerWindow.Holder;
    if not outer then
        return false;
    end;

    local ok, result, reason = pcall(build, outer);
    if not ok then
        warn("[frutiger] sidebar failed:", result);
        return false;
    end;
    if not result then
        warn("[frutiger] sidebar skipped:", reason);
        return false;
    end;

    sidebar.applied = true;
    sidebar.reassert();

    -- re-assert on tab clicks: the library touches sizes on switch
    pcall(function()
        for _, tab in ipairs(gui_children(sidebar.strip)) do
            tab.InputBegan:Connect(function()
                task.wait();
                sidebar.reassert();
            end);
        end;
    end);

    -- and once more shortly after, covering the library's own post-build pass
    task.spawn(function()
        for _ = 1, 6 do
            task.wait(0.25);
            sidebar.reassert();
        end;
    end);

    return true;
end;

return sidebar;

end;

__modules["src/utility/frutiger/theme"] = function()
--[[
    src/utility/frutiger/theme.lua

    The DECAY look. Palette, fonts, and a procedural overlay that sits inside
    the menu window.

    Scoping decisions:

    1.  The overlay is parented INTO Library.FrutigerWindow, not screenspaced over
        the game. It moves when you drag the window, resizes with it, and is
        clipped to it — the game world stays clean. An earlier version was a
        full-screen ScreenGui in gethui(); that was wrong.

    2.  Layer ZIndex is derived at build time from the window's own highest
        descendant ZIndex rather than hardcoded. The library uses 9999 for
        window content and 999999 for drag/tooltip layers, so a fixed value
        either gets buried or paints over tooltips. Deriving it means the grain
        sits above content and below tooltips automatically.

    3.  Nothing here is required to succeed. Every step is pcall'd and every
        lookup degrades to nil. A missing texture costs grain, not the client.

    Textures come from tools/gen-textures.js, are inlined into the bundle by
    tools/bundle.js as base64(zstd(bytes)), written out on first run and loaded
    with getcustomasset — the same path the fonts and sounds already use.
]]

local theme = {};

-- ── palette ────────────────────────────────────────────────────────────────
-- Near-absolute black, carbon grey, desaturated mould green, dirty beige,
-- rust. No saturated or clean values anywhere.

-- Frutiger Aero / liquid glass. Bright, airy, watery, translucent.
--
-- The palette is deliberately low-contrast between its own slots: everything is
-- a pale cyan or an ice white, and the ONLY strong values are the cyan accent
-- and the text. Structure comes from transparency and highlights, not from
-- outlines -- heavy borders are what makes a glass UI read as a flat dashboard
-- with blue trim.
--
-- Text is the one place contrast is allowed to be strong, because it has to sit
-- on translucent surfaces over arbitrary scenery.
theme.palette = {
    FontColor       = "20384a",   -- primary text: navy-grey, not black
    MainColor       = "eafbff",   -- glass card fill
    AccentColor     = "37c7ff",   -- cyan accent: selections, toggles, sliders
    BackgroundColor = "dcf5ff",   -- window glass
    OutlineColor    = "ffffff",   -- soft white border, never a hard blue line
};

theme.extra = {
    -- glass fills, lightest to deepest
    glass   = Color3.fromRGB(234, 251, 255),   -- #EAFBFF
    bgGlass = Color3.fromRGB(220, 245, 255),   -- #DCF5FF
    sky     = Color3.fromRGB(216, 243, 255),   -- #D8F3FF

    -- cyan family, for accents and glows
    aqua    = Color3.fromRGB(55, 199, 255),    -- #37C7FF
    cyan2   = Color3.fromRGB(93, 216, 255),    -- #5DD8FF
    cyan3   = Color3.fromRGB(123, 229, 255),   -- #7BE5FF

    -- text
    ink     = Color3.fromRGB(32, 56, 74),      -- #20384A primary
    text2   = Color3.fromRGB(41, 72, 90),      -- #29485A
    muted   = Color3.fromRGB(85, 115, 131),    -- #557383 secondary, e.g. "N/A"

    white   = Color3.fromRGB(255, 255, 255),
    lime    = Color3.fromRGB(126, 200, 80),
};

-- Condensed industrial for headings, technical mono for everything else.
theme.fonts = {
    heading = Enum.Font.Oswald,
    body    = Enum.Font.RobotoMono,
};

-- ── textures ───────────────────────────────────────────────────────────────
local visible = nil;
pcall(function() visible = require("@src/utility/frutiger/visible") end);

-- Guard against the module failing to load: without it nothing would ever run,
-- which is worse than running too often.
if not visible then
    visible = { menu = function() return true end, on_open = function() end };
end;

local TEXTURE_DIR = "Frutiger/Textures";
local TEXTURE_NAMES = { "gloss", "frost", "bubbles", "sheen", "orb" };

theme.textures = {};

local function ensure_folder(dir)
    if isfolder(dir) then
        return true;
    end;
    return (pcall(makefolder, dir));
end;

local function ensure_texture(name)
    local path = TEXTURE_DIR .. "/" .. name .. ".png";

    if not isfile(path) then
        if not ensure_folder(TEXTURE_DIR) then
            return nil;
        end;

        -- inline_asset_b96 and decode_asset are globals published by
        -- src/luarmor_init_script.lua and src/init.lua respectively.
        local ok, contents = pcall(function()
            return decode_asset(inline_asset_b96("@assets/Textures/" .. name .. ".png"));
        end);

        if not ok or type(contents) ~= "string" or #contents == 0 then
            return nil;
        end;

        if not pcall(writefile, path, contents) then
            return nil;
        end;
    end;

    local ok, asset = pcall(getcustomasset, path);
    return ok and asset or nil;
end;

function theme.load_textures()
    for _, name in next, TEXTURE_NAMES do
        theme.textures[name] = ensure_texture(name);
    end;
    return theme.textures;
end;

-- ── overlay ────────────────────────────────────────────────────────────────

-- Library.FrutigerWindow is the linoria Window OBJECT, not the frame — it carries
-- .Tabs, .TabOrder and a .Holder field. The actual GUI is Window.Holder
-- (ui.lua:2388 `Window.Holder = Outer`). Handing the object straight to
-- :GetDescendants() throws, and build_overlay then swallowed that, so resolve
-- it here and never let a table through.
local function as_instance(candidate)
    if typeof(candidate) == "Instance" then
        return candidate;
    end;
    if type(candidate) == "table" then
        for _, key in ipairs({ "Holder", "Frame", "Container", "Root" }) do
            local value = rawget(candidate, key);
            if typeof(value) == "Instance" then
                return value;
            end;
        end;
    end;
    return nil;
end;

-- The frame everything hangs off. Returns nil if nothing resolves, so the
-- caller can skip cleanly instead of erroring.
local function find_window()
    if not Library then
        return nil;
    end;

    for _, candidate in ipairs({ Library.FrutigerWindow, Library.Window, Library.ScreenGui }) do
        local instance = as_instance(candidate);
        if instance then
            return instance;
        end;
    end;

    return nil;
end;

-- Highest ZIndex anywhere under the window. The overlay has to clear the
-- window's own content without hardcoding a number that goes stale.
local function max_zindex(root)
    local highest = 0;
    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("GuiObject") and descendant.ZIndex > highest then
            highest = descendant.ZIndex;
        end;
    end;
    return highest;
end;

-- A previous build (or a previous injection) may have left a screenspaced
-- overlay behind. Clear it before building the scoped one.
function theme.destroy_previous()
    for _, container in ipairs({
        (type(gethui) == "function" and pcall(gethui) and gethui()) or nil,
        game:GetService("CoreGui"),
    }) do
        if container then
            for _, child in ipairs(container:GetChildren()) do
                if child.Name == "FRUTIGER_OVERLAY" then
                    pcall(function() child:Destroy() end);
                end;
            end;
        end;
    end;
end;

local function layer(parent, name, image, props)
    if not image then
        return nil;
    end;

    local frame = Instance.new("ImageLabel");
    frame.Name = name;
    frame.BackgroundTransparency = 1;
    frame.BorderSizePixel = 0;
    frame.Image = image;
    frame.Size = UDim2.fromScale(1, 1);
    frame.Position = UDim2.fromScale(0, 0);

    for key, value in next, props do
        frame[key] = value;
    end;

    frame.Parent = parent;
    return frame;
end;

function theme.build_overlay()
    if theme.overlay and theme.overlay.Parent then
        return theme.overlay;
    end;

    local window = find_window();
    if not window then
        return nil;
    end;

    pcall(theme.destroy_previous);

    local base = math.min(max_zindex(window) + 1, 999990);

    -- The holder is what clips: the grain tiles and the vignette get cut to the
    -- window's rectangle, so nothing bleeds over the game or over other windows.
    local holder = Instance.new("Frame");
    holder.Name = "FRUTIGER_OVERLAY";
    holder.BackgroundTransparency = 1;
    holder.BorderSizePixel = 0;
    holder.Size = UDim2.fromScale(1, 1);
    holder.Position = UDim2.fromScale(0, 0);
    holder.ClipsDescendants = true;
    holder.Active = false;
    holder.ZIndex = base;

    local ok = pcall(function()
        holder.Parent = window;
    end);
    if not ok then
        holder:Destroy();
        return nil;
    end;

    theme.overlay = holder;
    theme.window = window;
    theme.base_zindex = base;

    -- Frutiger Aero stacks four things, in this order:
    --
    --   gloss    the curved-glass highlight across the top. Static, stretched.
    --   bubbles  translucent spheres, tiled, drifting slowly upward.
    --   sheen    a soft highlight band that sweeps down the panel occasionally.
    --
    -- No grain, no scanlines, no vignette. All three read as damage or CRT on a
    -- light glossy surface, which is the opposite of what this theme is.

    theme.gloss = layer(holder, "gloss", theme.textures.gloss, {
        ZIndex = base + 1,
        ImageTransparency = 0.42,
        ScaleType = Enum.ScaleType.Stretch,
    });

    -- Frost sits under the bubbles. It is the diffusion that makes the pane read
    -- as glass rather than as a plain see-through hole.
    theme.frost = layer(holder, "frost", theme.textures.frost, {
        ZIndex = base + 2,
        ImageTransparency = 0.55,
        TileSize = UDim2.fromOffset(128, 128),
    });

    theme.bubbles = layer(holder, "bubbles", theme.textures.bubbles, {
        ZIndex = base + 3,
        ImageTransparency = 0.52,
        TileSize = UDim2.fromOffset(256, 256),
    });

    theme.sheen = layer(holder, "sheen", theme.textures.sheen, {
        ZIndex = base + 4,
        ImageTransparency = 0.35,
        ScaleType = Enum.ScaleType.Stretch,
        Size = UDim2.new(1, 0, 0, 96),
        Position = UDim2.new(0, 0, -1, 0),
        Visible = false,
    });

    return holder;
end;

-- ── motion ─────────────────────────────────────────────────────────────────
-- Slow and calm, which is the opposite of what was here before. The previous
-- pass deliberately jittered grain at 12fps and jolted the pane sideways to
-- read as a failing monitor. On Frutiger that is just a broken UI.

function theme.start_motion()
    if theme.motion_started then
        return;
    end;
    theme.motion_started = true;

    local RunService = game:GetService("RunService");
    local rnd = Random.new();

    -- Bubbles rise. Each step nudges the tile offset upward so the whole field
    -- drifts, then wraps -- cheaper than animating instances and seamless
    -- because the texture tiles.
    task.spawn(function()
        local offset = 0;
        while theme.overlay and theme.overlay.Parent do
            if not visible.menu() then
                -- Nothing to animate while hidden, and RenderStepped:Wait()
                -- wakes every single frame. Sleep instead.
                task.wait(0.25);
            else
                if theme.bubbles then
                    offset = (offset - 0.35) % 256;
                    theme.bubbles.Position = UDim2.fromOffset(0, offset);
                end;
                RunService.RenderStepped:Wait();
            end;
        end;
    end);

    -- The sheen sweeps down over ~2.4s, then waits 9-22s. It is hidden between
    -- passes rather than parked off-screen, so it cannot flash at the edges.
    task.spawn(function()
        while theme.overlay and theme.overlay.Parent do
            task.wait(rnd:NextNumber(9, 22));

            if not visible.menu() then
                task.wait(1);
                continue;
            end;

            local height = theme.overlay.AbsoluteSize.Y;
            if theme.sheen and height > 0 then
                theme.sheen.Visible = true;
                local start = tick();
                local duration = 2.4;

                while tick() - start < duration and theme.overlay.Parent do
                    local t = (tick() - start) / duration;
                    theme.sheen.Position = UDim2.fromOffset(0, t * (height + 96) - 96);
                    -- fade in and out so it never pops
                    theme.sheen.ImageTransparency = 0.35 + math.abs(t - 0.5) * 0.5;
                    RunService.RenderStepped:Wait();
                end;

                theme.sheen.Visible = false;
            end;
        end;
    end);
end;

-- ── library integration ────────────────────────────────────────────────────
function theme.apply_colors()
    if not Library then
        return false;
    end;

    for key, hex in next, theme.palette do
        local ok = pcall(function()
            Library[key] = Color3.fromHex(hex);
        end);
        if not ok then
            return false;
        end;
    end;

    pcall(function()
        Library.AccentColorDark = Library:GetDarkerColor(Library.AccentColor);
    end);

    return true;
end;

-- ── recolour pass ──────────────────────────────────────────────────────────
-- Setting Library.MainColor and calling ApplyTheme is not enough. The library
-- only repaints elements it registered via AddToRegistry; the window chrome
-- (the outer Frame, the inner container, the hairline separator, UIStrokes)
-- bakes its colours at creation and is never revisited. Measured after a
-- palette change: Library.MainColor was #434343 while Inner still rendered
-- #1b2b34, the old PR blue.
--
-- So capture the palette that was live when the UI was built, then walk the
-- tree and swap any colour that still matches one of those values.

-- Property sets per class. Hoisted so the loop allocates nothing, and so the
-- class check happens once per object rather than once per property.
--
-- A plain Frame genuinely has no TextColor3, ImageColor3 or PlaceholderColor3,
-- and reading one raises.
local PROPS_FRAME   = { "BackgroundColor3", "BorderColor3" };
local PROPS_TEXT    = { "BackgroundColor3", "BorderColor3", "TextColor3" };
local PROPS_TEXTBOX = { "BackgroundColor3", "BorderColor3", "TextColor3", "PlaceholderColor3" };
local PROPS_IMAGE   = { "BackgroundColor3", "BorderColor3", "ImageColor3" };

local function colors_close(a, b)
    return math.abs(a.R - b.R) < 0.02
       and math.abs(a.G - b.G) < 0.02
       and math.abs(a.B - b.B) < 0.02;
end;

-- Which old palette entry each PROPERTY should be matched against.
--
-- The first version built one flat old-value -> new-value table and matched any
-- property against any entry, first hit wins. That is ambiguous whenever the
-- outgoing palette repeats a value, and the CONSOLE palette repeated two:
-- FontColor, AccentColor and OutlineColor were all #ffffff, and MainColor and
-- BackgroundColor were both #000000. So a white-filled toggle knob could be
-- matched through FontColor and repainted dark navy -- 693 elements came out
-- dark that way when switching to a light theme.
--
-- Matching per property removes the ambiguity: a fill is only ever compared
-- against the old fills, text against the old text, and so on.
local PROPERTY_SOURCE = {
    -- OutlineColor belongs here too: the library paints dividers and separators
    -- with BorderColor3 = OutlineColor, i.e. OutlineColor IS their background, so
    -- leaving it out meant every divider kept the previous theme's edge colour.
    BackgroundColor3  = { "MainColor", "BackgroundColor", "OutlineColor" };
    TextColor3        = { "FontColor", "AccentColor" };
    PlaceholderColor3 = { "FontColor" };
    BorderColor3      = { "OutlineColor" };
    Color             = { "OutlineColor", "AccentColor" };   -- UIStroke
};

function theme.recolor(previous)
    if not Library or not Library.ScreenGui or type(previous) ~= "table" then
        return 0;
    end;

    -- build a lookup per source key, so each property knows where to look
    local by_key = {};
    for key, old in next, previous do
        local hex = theme.palette[key];
        if hex and typeof(old) == "Color3" then
            by_key[key] = { old = old, new = Color3.fromHex(hex) };
        end;
    end;

    local function luminance_of(color)
        return 0.299 * color.R + 0.587 * color.G + 0.114 * color.B;
    end;

    -- which way round the palette being applied is, for the polarity fallback
    local theme_luminance = luminance_of(Color3.fromHex(theme.palette.MainColor));

    local function remap(object, property)
        local sources = PROPERTY_SOURCE[property];
        if not sources then
            return false;
        end;

        -- Read directly. All five properties exist on every GuiObject, so the
        -- guarded read was five wasted pcalls per object -- across 15742
        -- descendants that is ~78000 calls per pass, which is a visible hitch
        -- every time the pass ran rather than a rounding error.
        local current = object[property];
        if typeof(current) ~= "Color3" then
            return false;
        end;

        for _, key in ipairs(sources) do
            local pair = by_key[key];
            if pair and colors_close(current, pair.old) then
                object[property] = pair.new;
                return true;
            end;
        end;

        -- Polarity fallback, for elements the library paints with a LITERAL
        -- black or white instead of a palette colour.
        --
        -- Measured: with a light palette applied, 688 elements stayed pure
        -- #000000 -- toggle knobs and slider thumbs among them. They match no
        -- palette entry, so the loop above cannot see them, and they are not
        -- created late either, so the tree watcher cannot either. They are
        -- simply hardcoded, and they only look wrong when the theme's polarity
        -- is the opposite of theirs.
        if property == "BackgroundColor3" and theme_luminance > 0.5 then
            if luminance_of(current) < 0.15 then
                object[property] = Color3.fromHex(theme.palette.MainColor);
                return true;
            end;
        end;
        if property == "TextColor3" and theme_luminance < 0.5 then
            if luminance_of(current) > 0.85 then
                object[property] = Color3.fromHex(theme.palette.FontColor);
                return true;
            end;
        end;

        return false;
    end;

    if next(by_key) == nil then
        return 0;
    end;

    local changed = 0;

    for _, descendant in ipairs(Library.ScreenGui:GetDescendants()) do
        if descendant:IsA("GuiObject") then
            -- Which properties this class actually has. One IsA chain per object
            -- replaces five pcalls per object, and it is what the pcall was
            -- really guarding: a plain Frame carries no TextColor3, and reading
            -- it raises. Removing the pcall without this threw and aborted the
            -- entire recolour, which is a worse failure than being slow.
            local properties = PROPS_FRAME;

            if descendant:IsA("TextBox") then
                properties = PROPS_TEXTBOX;
            elseif descendant:IsA("TextLabel") then
                properties = PROPS_TEXT;
            elseif descendant:IsA("ImageLabel") or descendant:IsA("ImageButton") then
                properties = PROPS_IMAGE;
            end;

            for _, property in ipairs(properties) do
                if remap(descendant, property) then
                    changed = changed + 1;
                end;
            end;
        end;

        if descendant:IsA("UIStroke") then
            if remap(descendant, "Color") then
                changed = changed + 1;
            end;
        end;
    end;

    return changed;
end;

-- ── contrast guard ─────────────────────────────────────────────────────────
-- With a white accent, the library's derived shades (AccentColorDark and its
-- relatives) come out light grey. Anything that ends up light-filled with white
-- text on top is unreadable.
--
-- Measured on the "enable Ping Compensation" notification: a stable #a3a2a5
-- fill at full opacity behind #ffffff text.
--
-- The guard darkens the TEXT, not the fill. It used to darken the fill, which
-- was wrong for the common case: the library paints AccentColor as a BACKGROUND
-- for hover fills, dropdown selections and toggles, and with a white accent that
-- is a white fill. Blacking those out would erase the accent entirely and you
-- could no longer see what is selected. Inverting the text instead keeps the
-- white fill and puts black on it, which is readable AND still shows selection.
--
-- Safe against the hover inversion, which produces the same pairing
-- deliberately: white fill, black text.

local function luminance(color)
    return 0.299 * color.R + 0.587 * color.G + 0.114 * color.B;
end;

local CONTRAST_DARK = Color3.fromRGB(12, 12, 12);

-- The nearest ancestor that actually paints something, walking up until a fill
-- is found. This is the whole point: text is very rarely a direct child of the
-- thing it sits on. A toggle label lives inside a row with
-- BackgroundTransparency = 1, inside a groupbox, inside the panel. Checking only
-- the label's own parent finds nothing and the guard does nothing -- which is
-- exactly what happened, and why the toggle labels stayed white on a light
-- panel while the slider labels (which sit on a filled track) came out dark.
local function nearest_fill(object)
    local node = object.Parent;

    while node and node ~= Library.ScreenGui do
        if node:IsA("GuiObject") then
            local transparency = node.BackgroundTransparency;
            if transparency and transparency < 0.6 then
                return node.BackgroundColor3;
            end;
        end;

        node = node.Parent;
    end;

    return nil;
end;

-- Pick whichever of the palette's text colour and a hard dark reads better on
-- the fill behind it. Using FontColor keeps the result on-theme; the hard
-- constant is the fallback for a palette whose own text colour is light.
local function readable_text_on(background)
    local candidates = { CONTRAST_DARK };

    local ok, hex = pcall(function() return theme.palette.FontColor end);
    if ok and hex then
        candidates[#candidates + 1] = Color3.fromHex(hex);
    end;

    local background_luminance = luminance(background);
    local best;

    for _, candidate in ipairs(candidates) do
        local distance = math.abs(luminance(candidate) - background_luminance);
        if not best or distance > best.distance then
            best = { color = candidate, distance = distance };
        end;
    end;

    return best and best.color or CONTRAST_DARK;
end;

-- `root` scopes the pass to a subtree. Scanning only what was just added turns
-- this from O(whole tree) into O(what changed), which matters: a full pass
-- measured 34ms across 15742 descendants, and the add-hook was firing several
-- times a second.
function theme.fix_contrast(root)
    if not Library or not Library.ScreenGui then
        return 0;
    end;

    root = root or Library.ScreenGui;

    local fixed = 0;
    local candidates = {};

    if root:IsA("TextLabel") or root:IsA("TextBox") then
        candidates[1] = root;
    end;

    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("TextLabel") or descendant:IsA("TextBox") then
            candidates[#candidates + 1] = descendant;
        end;
    end;

    for _, descendant in ipairs(candidates) do
        local text_luminance = luminance(descendant.TextColor3);

        -- only text that is currently light is at risk
        if text_luminance > 0.7 then
            local fill = nearest_fill(descendant);

            -- ...and only when what is behind it is also light
            if fill and luminance(fill) > 0.5 then
                descendant.TextColor3 = readable_text_on(fill);
                fixed = fixed + 1;
            end;
        end;
    end;

    return fixed;
end;

-- ── reactive guard ─────────────────────────────────────────────────────────
-- The guard used to run on a fixed schedule -- a few passes over the first 30
-- seconds. Dropdown options, tooltips and dependency-box children are built
-- when they are first OPENED, which can be minutes later, so they were never
-- covered: their option labels stayed white on the white accent fill and were
-- unreadable until a hover inverted them.
--
-- Instead of guessing when, react to the tree changing. Debounced, because
-- building a dropdown adds a burst of instances and one pass at the end is
-- enough for all of them.

function theme.watch()
    if theme.watching or not Library or not Library.ScreenGui then
        return false;
    end;
    theme.watching = true;

    local queued = false;
    local pending = {};
    local pending_count = 0;
    local PENDING_LIMIT = 300;

    local function schedule(instance)
        if instance then
            pending_count = pending_count + 1;
            if pending_count <= PENDING_LIMIT then
                pending[#pending + 1] = instance;
            end;
        end;

        if queued then
            return;
        end;
        queued = true;

        task.delay(0.35, function()
            queued = false;

            local batch = pending;
            local overflowed = pending_count > PENDING_LIMIT;
            pending = {};
            pending_count = 0;

            -- THE GATE. All of this exists to style a window that is usually not
            -- on screen, and while it is shut none of it is visible.
            if not visible.menu() then
                return;
            end;

            -- Only the subtrees that just appeared. Nothing else can have
            -- changed, and a full pass costs 34ms across 15742 descendants.
            if overflowed then
                pcall(theme.fix_contrast);
                return;
            end;

            for _, added in ipairs(batch) do
                if added.Parent then
                    pcall(theme.fix_contrast, added);
                end;
            end;
        end);
    end;

    pcall(function()
        Library.ScreenGui.DescendantAdded:Connect(schedule);
    end);

    -- Backstop for repaints that do not add instances: the library re-applies
    -- registry colours on theme changes and on show, which can put white text
    -- back on a light fill without anything being added.
    -- Backstop only. While the menu is shut this costs one comparison every
    -- 5s. It used to do two full-tree passes on that schedule regardless.
    -- No periodic full recolour.
    --
    -- Recolouring exists to convert elements built BEFORE the palette changed.
    -- Anything created afterwards is built from Library.MainColor and friends,
    -- which are already the new values, so it needs no conversion. That makes
    -- the whole pass a one-shot at apply time, not a recurring one -- and at
    -- 70ms per run across 15742 descendants, recurring was the framerate.
    task.spawn(function()
        for _ = 1, 60 do
            task.wait(5);
            if visible.menu() then
                pcall(theme.fix_contrast);
            end;
        end;
    end);

    visible.on_open(function()
        pcall(theme.fix_contrast);
    end);

    return true;
end;

-- Makes CONSOLE selectable in the theme dropdown, not just forced on.
function theme.register()
    local ok, ThemeManager = pcall(require, "@src/utility/librarys/managers/ThemeManager");
    if not ok or type(ThemeManager) ~= "table" or type(ThemeManager.BuiltInThemes) ~= "table" then
        return false;
    end;

    local HttpService = game:GetService("HttpService");
    ThemeManager.BuiltInThemes["FRUTIGER"] = { 22, HttpService:JSONDecode(HttpService:JSONEncode(theme.palette)) };
    return true;
end;

function theme.apply()
    if theme.applied then
        return true;
    end;

    pcall(theme.load_textures);
    pcall(theme.register);

    -- Capture the palette that was live when the UI was built, before
    -- apply_colors overwrites it. This is the "from" set for the recolour pass.
    local previous = {};
    if Library then
        for key in next, theme.palette do
            pcall(function() previous[key] = Library[key] end);
        end;
    end;

    local colors = pcall(theme.apply_colors);

    -- repaint the live UI if the manager is reachable
    pcall(function()
        local ThemeManager = require("@src/utility/librarys/managers/ThemeManager");
        ThemeManager:ApplyTheme(theme.palette);
        if aztup and aztup.tabs then
            for _, tab in next, aztup.tabs do
                if tab and tab.Tab then
                    ThemeManager:ApplyToTab(tab.Tab);
                end;
            end;
        end;
    end);

    -- apply_colors + ApplyTheme only cover registered elements. This catches
    -- the window chrome, separators and strokes that the library bakes once and
    -- never revisits.
    local recoloured = pcall(function()
        return theme.recolor(previous);
    end);

    -- Then re-run the registry itself. Some properties are produced by
    -- registered FUNCTIONS, not stored values -- the window title builds its
    -- string from Library.AccentColor at evaluation time and is only evaluated
    -- when the registry updates. Nothing re-ran it after the palette change, so
    -- the title kept rendering the old accent (#6699cc, the PR blue) behind a
    -- white AccentColor.
    pcall(function()
        if type(Library.UpdateColorsUsingRegistry) == "function" then
            Library:UpdateColorsUsingRegistry();
        end;
    end);

    pcall(theme.fix_contrast);

    pcall(theme.build_overlay);
    pcall(theme.start_motion);

    theme.applied = true;
    theme.previous_palette = previous;

    -- Everything the library builds AFTER this point -- dropdown options,
    -- tooltips, dependency-box children, notifications -- is covered by the
    -- reactive guard rather than a fixed schedule. The old schedule ran for 30s
    -- and by definition missed anything opened later, which is how dropdown
    -- options stayed white-on-white until a hover inverted them.
    pcall(theme.watch);

    return colors and recoloured;
end;

return theme;

end;

__modules["src/utility/frutiger/visible"] = function()
--[[
    src/utility/frutiger/visible.lua

    Whether the menu is actually open.

    Every expensive thing the theme does -- recolouring the tree, checking
    contrast, dressing dividers and cards, attaching hover handlers, rounding
    corners -- exists purely to style a window that is, most of the time, not on
    screen. Running any of it while the menu is closed costs framerate and buys
    nothing, because nobody can see the result.

    That was the reported problem: framerate tanking during play, with the menu
    shut. The theme had a DescendantAdded hook that reran a full-tree recolour
    and contrast pass whenever anything was added, debounced by 0.2s. In a live
    game instances are added constantly, so it was firing several times a second
    across ~2000 elements, forever, while hidden.

    The gate is also how the work gets scheduled properly: instead of guessing
    when to re-run, run once whenever the window becomes visible.
]]

local visible = {};

local function holder()
    local library = Library or (getgenv and getgenv().Library);
    if not library then
        return nil;
    end;

    local window = library.FrutigerWindow or library.DecayWindow or library.Window;
    return window and window.Holder or nil;
end;

function visible.menu()
    local object = holder();
    if not object then
        return false;
    end;

    local ok, value = pcall(function() return object.Visible end);
    return ok and value == true;
end;

-- Calls `callback` each time the menu transitions to visible. Returns the
-- connection, or nil if there is nothing to watch yet.
function visible.on_open(callback)
    local object = holder();
    if not object then
        return nil;
    end;

    local ok, connection = pcall(function()
        return object:GetPropertyChangedSignal("Visible"):Connect(function()
            if object.Visible then
                pcall(callback);
            end;
        end);
    end);

    return ok and connection or nil;
end;

return visible;

end;

__modules["src/utility/instancewatcher"] = function()


local InstanceWatcher = {} do 
    InstanceWatcher.__index = InstanceWatcher;

    function InstanceWatcher.new(parent_instance, match_function, callback_function, should_wait): InstanceWatcher
        local self = setmetatable({}, InstanceWatcher);

        self.parent_instance = parent_instance;
        self.match_function = match_function;
        self.callback_function = callback_function;

        aztup.maid:give_task(self.parent_instance.ChildAdded:Connect(function(child_instance)
            if self.match_function(child_instance) then
                self.callback_function(child_instance)
            else
                task.delay(0.1, function()
                    if child_instance.Parent and self.match_function(child_instance) then
                        self.callback_function(child_instance)
                    end
                end)
            end
        end));

        task.spawn(function() 
            for _, child_instance in parent_instance:GetChildren() do
                task.spawn(function() 
                    if self.match_function(child_instance) then
                        self.callback_function(child_instance)
                    end
                end)

                if should_wait then
                    task.wait();
                end;
            end
        end);
        
        return self
    end
end

getgenv().InstanceWatcher = InstanceWatcher
return InstanceWatcher

end;

__modules["src/utility/irc"] = function()
local irc = {}
irc.__index = irc




local function toWsUrl(server, port)
	
	if type(server) == "string" and (server:sub(1, 5) == "ws://" or server:sub(1, 6) == "wss://") then
		return server
	end
	return ("ws://%s:%d"):format(tostring(server), tonumber(port) or 80)
end

local function normalizeIrcLine(s)
	
	s = tostring(s or "")
	if s:sub(-2) ~= "\r\n" then
		s = s .. "\r\n"
	end
	return s
end

function irc.new(server, port, nickname)
	local self = setmetatable({}, irc)
	self.server = server
	self.port = port
	self.nickname = nickname
	self.connection = nil

	self._inbuf = ""
	self._queue = {}
	self._closed = false

	return self
end

function irc:connect()
	local url = toWsUrl(self.server, self.port)
	self.connection = WebSocket.connect(url)

	self._closed = false
	self._inbuf = ""
	self._queue = {}

	
	self.connection.OnMessage:Connect(function(payload)
		if self._closed then
			return
		end

		self._inbuf ..= tostring(payload)

		while true do
			local i, j = self._inbuf:find("\r\n", 1, true)
			if not i then
				break
			end
			local line = self._inbuf:sub(1, i - 1)
			table.insert(self._queue, line)
			self._inbuf = self._inbuf:sub(j + 1)
		end
	end)

	self.connection.OnClose:Connect(function()
		self._closed = true
	end)

	
	self.connection:Send(normalizeIrcLine("NICK " .. self.nickname))
	self.connection:Send(normalizeIrcLine("USER " .. self.nickname .. " 0 * :" .. self.nickname))
end

function irc:sendMessage(channel, message)
	if self.connection and not self._closed then
		self.connection:Send(normalizeIrcLine("PRIVMSG " .. channel .. " :" .. message))
	end
end

function irc:receiveMessage()
	
	if #self._queue > 0 then
		return table.remove(self._queue, 1)
	end
	return nil
end

function irc:disconnect()
	if self.connection then
		if not self._closed then
			
			pcall(function()
				self.connection:Send(normalizeIrcLine("QUIT"))
			end)
		end
		pcall(function()
			self.connection:Close()
		end)
		self.connection = nil
		self._closed = true
	end
end

return irc

end;

__modules["src/utility/latency"] = function()
local latency = {};
local ping = services.Stats:FindFirstChild("Data Ping", true);
local notified = false;

function latency:get_ping()
    if not ping then
        if not notified then
            notified = true;
            Logger:short_notify("Cant find ping stat, Ignore this if kicked.");
        end
        return 0    
end

    local val;
    local old = getthreadidentity();
    setthreadidentity(8);
    val = ping:GetValue();
    setthreadidentity(old);
    return val / 1000
end;

function latency:half_ping()
    return latency:get_ping() / 2
end;

return latency

end;

__modules["src/utility/librarys/components/button"] = function()




return function(Library, context)
	local Component = {}

	local function processButtonParams(target, ...)
		local props = select(1, ...)
		if type(props) == 'table' then
			target.Text = props.Text
			target.Func = props.Func
			target.DoubleClick = props.DoubleClick
			target.Tooltip = props.Tooltip
		else
			target.Text = select(1, ...)
			target.Func = select(2, ...)
		end

		assert(type(target.Func) == 'function', 'AddButton: `Func` callback is missing.')
	end

	local function createBaseButton(button)
		local outer = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, -4, 0, 20);
			ZIndex = 5;
		})

		local inner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = outer;
		})

		local label = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 14;
			Text = button.Text;
			ZIndex = 6;
			Parent = inner;
		})

		
		
		
		
		
		
		
		

		Library:AddToRegistry(outer, { BorderColor3 = 'Black' })
		Library:AddToRegistry(inner, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor' })

		Library:OnHighlight(outer, outer,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		return outer, inner, label
	end

	local function initEvents(button)
		local function waitForEvent(event, timeout, validator)
			local bindable = Instance.new('BindableEvent')
			local connection = event:Once(function(...)
				if type(validator) == 'function' and validator(...) then
					bindable:Fire(true)
				else
					bindable:Fire(false)
				end
			end)
			task.delay(timeout, function()
				connection:disconnect()
				bindable:Fire(false)
			end)
			return bindable.Event:Wait()
		end

		local function validateClick(input)
			if not Library.Toggled then
				return false
			end
			
			if Library:MouseIsOverOpenedFrame() then
				return false
			end

			if input.UserInputType ~= Enum.UserInputType.MouseButton1 then
				return false
			end

			return true
		end

		button.Outer.InputBegan:Connect(function(input)
			if not validateClick(input) or button.Locked then
				return
			end

			if button.DoubleClick then
				Library:RemoveFromRegistry(button.Label)
				Library:AddToRegistry(button.Label, { TextColor3 = 'AccentColor' })

				
				button.Label.Text = 'Are you sure?'
				button.Locked = true

				services.TweenService:Create(button.Label, TweenInfo.new(0.125), {
					TextColor3 = Library.AccentColor
				}):Play();

				task.wait(0.125);

				local clicked = waitForEvent(button.Outer.InputBegan, 2, validateClick)

				Library:RemoveFromRegistry(button.Label)
				Library:AddToRegistry(button.Label, { TextColor3 = 'FontColor' })

				button.Label.TextColor3 = Library.FontColor
				button.Label.Text = button.Text
				task.defer(rawset, button, 'Locked', false)

				if clicked then
					Library:SafeCallback(button.Func)
				end

				return
			end

			Library:SafeCallback(button.Func)
		end)
	end

	function Component.AddButton(self, ...)
		local button = {}
		processButtonParams(button, ...)

		if self.Objects then
			table.insert(self.Objects, {
				internal_name = "button_" .. tostring(#self.Objects + 1), settings = {
					Text = button.Text;
					Tooltip = button.Tooltip;
				}, Type = "Button"
			})
		end

		local groupbox = self
		local container = groupbox.Container

		button.Outer, button.Inner, button.Label = createBaseButton(button)
		button.Outer.Parent = container

		initEvents(button)

		function button:AddTooltip(tooltip)
			if type(tooltip) == 'string' then
				Library:AddToolTip(tooltip, self.Outer)
			end
			return self
		end

		function button:AddButton(...)
			local subButton = {}
			processButtonParams(subButton, ...)

			self.Outer.Size = UDim2.new(0.5, -2, 0, 20)

			subButton.Outer, subButton.Inner, subButton.Label = createBaseButton(subButton)
			subButton.Outer.Position = UDim2.new(1, 3, 0, 0)
			subButton.Outer.Size = UDim2.fromOffset(self.Outer.AbsoluteSize.X / Library:GetUIScale() - 2, self.Outer.AbsoluteSize.Y / Library:GetUIScale())
			subButton.Outer.Parent = self.Outer

			function subButton:AddTooltip(tooltip)
				if type(tooltip) == 'string' then
					Library:AddToolTip(tooltip, self.Outer)
				end
				return subButton
			end

			Library:RegisterSearchEntry(groupbox, {
				Kind = 'Button';
				Text = subButton.Text;
				Target = subButton.Outer;
			})

			if type(subButton.Tooltip) == 'string' then
				subButton:AddTooltip(subButton.Tooltip)
			end

			initEvents(subButton)
			return subButton
		end

		if type(button.Tooltip) == 'string' then
			button:AddTooltip(button.Tooltip)
		end

		groupbox:AddBlank(5)
		groupbox:Resize()

		return button
	end

	function Component.AddDivider(self)
		local groupbox = self
		local container = self.Container

		groupbox:AddBlank(2)
		local dividerOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, -4, 0, 5);
			ZIndex = 5;
			Parent = container;
		})

		local dividerInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = dividerOuter;
		})

		Library:AddToRegistry(dividerOuter, { BorderColor3 = 'Black' })
		Library:AddToRegistry(dividerInner, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor' })

		groupbox:AddBlank(9)
		groupbox:Resize()
end

	return Component
end

end;

__modules["src/utility/librarys/components/colorpicker"] = function()




return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local RenderStepped = context.RenderStepped
	local ScreenGui = context.ScreenGui or Library.ScreenGui

	local Component = {}

	function Component.AddColorPicker(self, Idx, Info)
		local ToggleLabel = self.TextLabel;

		assert(Info.Default, 'AddColorPicker: Missing default value.');

		local ColorPicker = {
			Value = Info.Default;
			Transparency = Info.Transparency or 0;
			Type = 'ColorPicker';
			Title = type(Info.Title) == 'string' and Info.Title or 'Color picker',
			Callback = Info.Callback or function(Color) end;
		};

		function ColorPicker:SetHSVFromRGB(Color)
			local H, S, V = Color3.toHSV(Color);

			ColorPicker.Hue = H;
			ColorPicker.Sat = S;
			ColorPicker.Vib = V;
		end;

		ColorPicker:SetHSVFromRGB(ColorPicker.Value);

		local DisplayFrame = Library:Create('Frame', {
			BackgroundColor3 = ColorPicker.Value;
			BorderColor3 = Library:GetDarkerColor(ColorPicker.Value);
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(0, 14, 0, 14);
			ZIndex = 6;
			Parent = ToggleLabel;
		});

		local CheckerFrame = Library:Create('ImageLabel', {
			BorderSizePixel = 0;
			Size = UDim2.new(0, 13, 0, 13);
			ZIndex = 5;
			Image = 'http://www.roblox.com/asset/?id=12977615774';
			Visible = not not Info.Transparency;
			Parent = DisplayFrame;
		});

		local PickerFrameOuter = Library:Create('Frame', {
			Name = 'Color';
			BackgroundColor3 = Color3.new(1, 1, 1);
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.fromOffset(DisplayFrame.AbsolutePosition.X, DisplayFrame.AbsolutePosition.Y + 18),
			Size = UDim2.fromOffset(230, Info.Transparency and 271 or 253);
			Visible = false;
			ZIndex = 15;
			Parent = ScreenGui,
		});

		Library:AddUIScale(PickerFrameOuter);

		DisplayFrame:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			PickerFrameOuter.Position = UDim2.fromOffset(DisplayFrame.AbsolutePosition.X, DisplayFrame.AbsolutePosition.Y + 18);
		end)

		if type(ColorPicker.Title) == 'string' and ColorPicker.Title ~= '' then
			Library:RegisterSearchEntry(self, {
				Kind = 'ColorPicker';
				Text = ColorPicker.Title;
				Tab = self.Tab or self;
				Target = DisplayFrame;
				Focus = function()
					Library:FocusSearchTarget(DisplayFrame)
				end;
			})
		end

		local PickerFrameInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 16;
			Parent = PickerFrameOuter;
		});

		local Highlight = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Size = UDim2.new(1, 0, 0, 2);
			ZIndex = 17;
			Parent = PickerFrameInner;
		});

		local SatVibMapOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.new(0, 4, 0, 25);
			Size = UDim2.new(0, 200, 0, 200);
			ZIndex = 17;
			Parent = PickerFrameInner;
		});

		local SatVibMapInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 18;
			Parent = SatVibMapOuter;
		});

		local SatVibMap = Library:Create('ImageLabel', {
			BorderSizePixel = 0;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 18;
			Image = 'rbxassetid://4155801252';
			Parent = SatVibMapInner;
		});

		local HueSelectorOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.new(0, 208, 0, 25);
			Size = UDim2.new(0, 15, 0, 200);
			ZIndex = 17;
			Parent = PickerFrameInner;
		});

		local HueSelectorInner = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(1, 1, 1);
			BorderSizePixel = 0;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 18;
			Parent = HueSelectorOuter;
		});

		local HueCursor = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(1, 1, 1);
			AnchorPoint = Vector2.new(0, 0.5);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(1, 0, 0, 1);
			ZIndex = 18;
			Parent = HueSelectorInner;
		});

		local HueBoxOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.fromOffset(4, 228),
			Size = UDim2.new(0.5, -6, 0, 20),
			ZIndex = 18,
			Parent = PickerFrameInner;
		});

		local HueBoxInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 18,
			Parent = HueBoxOuter;
		});

		Library:Create('UIGradient', {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
				ColorSequenceKeypoint.new(1, Color3.fromRGB(212, 212, 212))
			});
			Rotation = 90;
			Parent = HueBoxInner;
		});

		local HueBox = Library:Create('TextBox', {
			BackgroundTransparency = 1;
			Position = UDim2.new(0, 5, 0, 0);
			Size = UDim2.new(1, -5, 1, 0);
			FontFace = Library.Font;
			PlaceholderColor3 = Color3.fromRGB(190, 190, 190);
			PlaceholderText = 'Hex color',
			Text = '#FFFFFF',
			TextColor3 = Library.FontColor;
			TextSize = 14;
			TextStrokeTransparency = 1;
			TextXAlignment = Enum.TextXAlignment.Left;
			ZIndex = 20,
			Parent = HueBoxInner;
		});

		Library:ApplyTextStroke(HueBox);

		local RgbBoxBase = Library:Create(HueBoxOuter:Clone(), {
			Position = UDim2.new(0.5, 2, 0, 228),
			Size = UDim2.new(0.5, -6, 0, 20),
			Parent = PickerFrameInner
		});

		local RgbBox = Library:Create(RgbBoxBase.Frame:FindFirstChild('TextBox'), {
			Text = '255, 255, 255',
			PlaceholderText = 'RGB color',
			TextColor3 = Library.FontColor
		});

		local TransparencyBoxOuter, TransparencyBoxInner, TransparencyCursor;

		if Info.Transparency then 
			TransparencyBoxOuter = Library:Create('Frame', {
				BorderColor3 = Color3.new(0, 0, 0);
				Position = UDim2.fromOffset(4, 251);
				Size = UDim2.new(1, -8, 0, 15);
				ZIndex = 19;
				Parent = PickerFrameInner;
			});

			TransparencyBoxInner = Library:Create('Frame', {
				BackgroundColor3 = ColorPicker.Value;
				BorderColor3 = Library.OutlineColor;
				BorderMode = Enum.BorderMode.Inset;
				Size = UDim2.new(1, 0, 1, 0);
				ZIndex = 19;
				Parent = TransparencyBoxOuter;
			});

			Library:AddToRegistry(TransparencyBoxInner, { BorderColor3 = 'OutlineColor' });

			Library:Create('ImageLabel', {
				BackgroundTransparency = 1;
				Size = UDim2.new(1, 0, 1, 0);
				Image = 'http://www.roblox.com/asset/?id=12978095818';
				ZIndex = 20;
				Parent = TransparencyBoxInner;
			});

			TransparencyCursor = Library:Create('Frame', {
				BackgroundColor3 = Color3.new(1, 1, 1);
				AnchorPoint = Vector2.new(0.5, 0);
				BorderColor3 = Color3.new(0, 0, 0);
				Size = UDim2.new(0, 1, 1, 0);
				ZIndex = 21;
				Parent = TransparencyBoxInner;
			});
		end;

		local DisplayLabel = Library:CreateLabel({
			Size = UDim2.new(1, 0, 0, 14);
			Position = UDim2.fromOffset(5, 5);
			TextXAlignment = Enum.TextXAlignment.Left;
			TextSize = 14;
			Text = ColorPicker.Title,
			TextWrapped = false;
			ZIndex = 16;
			Parent = PickerFrameInner;
		});

		local ContextMenu = {}
		do
			ContextMenu.aztup_options = {}
			ContextMenu.Container = Library:Create('Frame', {
				BorderColor3 = Color3.new(),
				ZIndex = 14,

				Visible = false,
				Parent = ScreenGui
			})

			Library:AddUIScale(ContextMenu.Container)

			ContextMenu.Inner = Library:Create('Frame', {
				BackgroundColor3 = Library.BackgroundColor;
				BorderColor3 = Library.OutlineColor;
				BorderMode = Enum.BorderMode.Inset;
				Size = UDim2.fromScale(1, 1);
				ZIndex = 15;
				Parent = ContextMenu.Container;
			});

			Library:Create('UIListLayout', {
				Name = 'Layout',
				FillDirection = Enum.FillDirection.Vertical;
				SortOrder = Enum.SortOrder.LayoutOrder;
				Parent = ContextMenu.Inner;
			});

			Library:Create('UIPadding', {
				Name = 'Padding',
				PaddingLeft = UDim.new(0, 4),
				Parent = ContextMenu.Inner,
			});

			local function updateMenuPosition()
				ContextMenu.Container.Position = UDim2.fromOffset(
					(DisplayFrame.AbsolutePosition.X + DisplayFrame.AbsoluteSize.X) + 4,
					DisplayFrame.AbsolutePosition.Y + 1
				)
			end

			local function updateMenuSize()
				local menuWidth = 60
				for _, label in next, ContextMenu.Inner:GetChildren() do
					if label:IsA('TextLabel') then
						menuWidth = math.max(menuWidth, label.TextBounds.X / Library:GetUIScale())
					end
				end

				ContextMenu.Container.Size = UDim2.fromOffset(
					menuWidth + 8,
					ContextMenu.Inner.Layout.AbsoluteContentSize.Y / Library:GetUIScale() + 4
				)
			end

			DisplayFrame:GetPropertyChangedSignal('AbsolutePosition'):Connect(updateMenuPosition)
			ContextMenu.Inner.Layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(updateMenuSize)

			task.spawn(updateMenuPosition)
			task.spawn(updateMenuSize)

			Library:AddToRegistry(ContextMenu.Inner, {
				BackgroundColor3 = 'BackgroundColor';
				BorderColor3 = 'OutlineColor';
			});

			function ContextMenu:Show()
				self.Container.Visible = true
			end

			function ContextMenu:Hide()
				self.Container.Visible = false
			end

			function ContextMenu:AddOption(Str, Callback)
				if type(Callback) ~= 'function' then
					Callback = function() end
				end

				local Button = Library:CreateLabel({
					Active = false;
					Size = UDim2.new(1, 0, 0, 15);
					TextSize = 13;
					Text = Str;
					ZIndex = 16;
					Parent = self.Inner;
					TextXAlignment = Enum.TextXAlignment.Left,
				});

				Library:OnHighlight(Button, Button,
					{ TextColor3 = 'AccentColor' },
					{ TextColor3 = 'FontColor' }
				);

				Button.InputBegan:Connect(function(Input)
					if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
						return
					end

					Callback()
				end)
			end

			ContextMenu:AddOption('Copy color', function()
				Library.ColorClipboard = ColorPicker.Value
				Library:Notify('Copied color!', 2)
			end)

			ContextMenu:AddOption('Paste color', function()
				if not Library.ColorClipboard then
					return Library:Notify('You have not copied a color!', 2)
				end
				ColorPicker:SetValueRGB(Library.ColorClipboard)
			end)

			ContextMenu:AddOption('Copy HEX', function()
				pcall(setclipboard, ColorPicker.Value:ToHex())
				Library:Notify('Copied hex code to clipboard!', 2)
			end)

			ContextMenu:AddOption('Copy RGB', function()
				pcall(setclipboard, table.concat({ math.floor(ColorPicker.Value.R * 255), math.floor(ColorPicker.Value.G * 255), math.floor(ColorPicker.Value.B * 255) }, ', '))
				Library:Notify('Copied RGB values to clipboard!', 2)
			end)

		end

		Library:AddToRegistry(PickerFrameInner, { BackgroundColor3 = 'BackgroundColor'; BorderColor3 = 'OutlineColor'; });
		Library:AddToRegistry(Highlight, { BackgroundColor3 = 'AccentColor'; });
		Library:AddToRegistry(SatVibMapInner, { BackgroundColor3 = 'BackgroundColor'; BorderColor3 = 'OutlineColor'; });
		Library:AddToRegistry(HueBoxInner, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor'; });
		Library:AddToRegistry(RgbBoxBase.Frame, { BackgroundColor3 = 'MainColor'; BorderColor3 = 'OutlineColor'; });
		Library:AddToRegistry(RgbBox, { TextColor3 = 'FontColor', });
		Library:AddToRegistry(HueBox, { TextColor3 = 'FontColor', });

		local SequenceTable = {};

		for Hue = 0, 1, 0.1 do
			table.insert(SequenceTable, ColorSequenceKeypoint.new(Hue, Color3.fromHSV(Hue, 1, 1)));
		end;

		Library:Create('UIGradient', {
			Color = ColorSequence.new(SequenceTable);
			Rotation = 90;
			Parent = HueSelectorInner;
		});

		HueBox.FocusLost:Connect(function(enter)
			if enter then
				local success, result = pcall(Color3.fromHex, HueBox.Text)
				if success and typeof(result) == 'Color3' then
					ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = Color3.toHSV(result)
				end
			end

			ColorPicker:Display()
		end)

		RgbBox.FocusLost:Connect(function(enter)
			if enter then
				local r, g, b = RgbBox.Text:match('(%d+),%s*(%d+),%s*(%d+)')
				if r and g and b then
					ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib = Color3.toHSV(Color3.fromRGB(r, g, b))
				end
			end

			ColorPicker:Display()
		end)

		function ColorPicker:Display()
			ColorPicker.Value = Color3.fromHSV(ColorPicker.Hue, ColorPicker.Sat, ColorPicker.Vib);
			SatVibMap.BackgroundColor3 = Color3.fromHSV(ColorPicker.Hue, 1, 1);

			Library:Create(DisplayFrame, {
				BackgroundColor3 = ColorPicker.Value;
				BackgroundTransparency = ColorPicker.Transparency;
				BorderColor3 = Library:GetDarkerColor(ColorPicker.Value);
			});

			if TransparencyBoxInner then
				TransparencyBoxInner.BackgroundColor3 = ColorPicker.Value;
				TransparencyCursor.Position = UDim2.new(1 - ColorPicker.Transparency, 0, 0, 0);
			end;

			HueCursor.Position = UDim2.new(0, 0, ColorPicker.Hue, 0);

			HueBox.Text = '#' .. ColorPicker.Value:ToHex()
			RgbBox.Text = table.concat({ math.floor(ColorPicker.Value.R * 255), math.floor(ColorPicker.Value.G * 255), math.floor(ColorPicker.Value.B * 255) }, ', ')

			Library:SafeCallback(ColorPicker.Callback, ColorPicker.Value);
			Library:SafeCallback(ColorPicker.Changed, ColorPicker.Value);
		end;

		function ColorPicker:OnChanged(Func)
			ColorPicker.Changed = Func;
			Func(ColorPicker.Value)
		end;

		function ColorPicker:Show()
			for Frame, Val in next, Library.OpenedFrames do
				if Frame.Name == 'Color' then
					Frame.Visible = false;
					Library.OpenedFrames[Frame] = nil;
				end;
			end;

			PickerFrameOuter.Visible = true;
			Library.OpenedFrames[PickerFrameOuter] = true;
		end;

		function ColorPicker:Hide()
			PickerFrameOuter.Visible = false;
			Library.OpenedFrames[PickerFrameOuter] = nil;
		end;

		function ColorPicker:SetValue(HSV, Transparency)
			local Color = Color3.fromHSV(HSV[1], HSV[2], HSV[3]);

			ColorPicker.Transparency = Transparency or 0;
			ColorPicker:SetHSVFromRGB(Color);
			ColorPicker:Display();
		end;

		function ColorPicker:SetValueRGB(Color, Transparency)
			ColorPicker.Transparency = Transparency or 0;
			ColorPicker:SetHSVFromRGB(Color);
			ColorPicker:Display();
		end;

		SatVibMap.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
					local MinX = SatVibMap.AbsolutePosition.X;
					local MaxX = MinX + SatVibMap.AbsoluteSize.X;
					local MouseX = math.clamp(Mouse.X, MinX, MaxX);

					local MinY = SatVibMap.AbsolutePosition.Y;
					local MaxY = MinY + SatVibMap.AbsoluteSize.Y;
					local MouseY = math.clamp(Mouse.Y, MinY, MaxY);

					ColorPicker.Sat = (MouseX - MinX) / (MaxX - MinX);
					ColorPicker.Vib = 1 - ((MouseY - MinY) / (MaxY - MinY));
					ColorPicker:Display();

					RenderStepped:Wait();
				end;

				Library:AttemptSave();
			end;
		end);

		HueSelectorInner.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
					local MinY = HueSelectorInner.AbsolutePosition.Y;
					local MaxY = MinY + HueSelectorInner.AbsoluteSize.Y;
					local MouseY = math.clamp(Mouse.Y, MinY, MaxY);

					ColorPicker.Hue = ((MouseY - MinY) / (MaxY - MinY));
					ColorPicker:Display();

					RenderStepped:Wait();
				end;

				Library:AttemptSave();
			end;
		end);

		DisplayFrame.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				if PickerFrameOuter.Visible then
					ColorPicker:Hide()
				else
					ContextMenu:Hide()
					ColorPicker:Show()
				end;
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame() then
				ContextMenu:Show()
				ColorPicker:Hide()
			end
		end);

		if TransparencyBoxInner then
			TransparencyBoxInner.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
						local MinX = TransparencyBoxInner.AbsolutePosition.X;
						local MaxX = MinX + TransparencyBoxInner.AbsoluteSize.X;
						local MouseX = math.clamp(Mouse.X, MinX, MaxX);

						ColorPicker.Transparency = 1 - ((MouseX - MinX) / (MaxX - MinX));

						ColorPicker:Display();

						RenderStepped:Wait();
					end;

					Library:AttemptSave();
				end;
			end);
		end;

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				local AbsPos, AbsSize = PickerFrameOuter.AbsolutePosition, PickerFrameOuter.AbsoluteSize;

				if Mouse.X < AbsPos.X or Mouse.X > AbsPos.X + AbsSize.X
					or Mouse.Y < (AbsPos.Y - 20 - 1) or Mouse.Y > AbsPos.Y + AbsSize.Y then

					ColorPicker:Hide();
				end;

				if not Library:IsMouseOverFrame(ContextMenu.Container) then
					ContextMenu:Hide()
				end
			end;

			if Input.UserInputType == Enum.UserInputType.MouseButton2 and ContextMenu.Container.Visible then
				if not Library:IsMouseOverFrame(ContextMenu.Container) and not Library:IsMouseOverFrame(DisplayFrame) then
					ContextMenu:Hide()
				end
			end
		end))

		ColorPicker:Display();
		ColorPicker.DisplayFrame = DisplayFrame

		aztup_options[Idx] = ColorPicker;

		return self	
end

	return Component
end

end;

__modules["src/utility/librarys/components/dropdown"] = function()




return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local ScreenGui = context.ScreenGui or Library.ScreenGui
	local TweenService = game:GetService('TweenService')

	local Component = {}

	local function getPlayersString()
		local PlayerList = game:GetService('Players'):GetPlayers()

		for i = 1, #PlayerList do
			PlayerList[i] = PlayerList[i].Name
		end

		table.sort(PlayerList, function(str1, str2) return str1 < str2 end)

		return PlayerList
	end

	local function getTeamsString()
		local TeamList = game:GetService('Teams'):GetTeams()

		for i = 1, #TeamList do
			TeamList[i] = TeamList[i].Name
		end

		table.sort(TeamList, function(str1, str2) return str1 < str2 end)

		return TeamList
	end

	function Component.AddDropdown(self, Idx, Info)
		Info.Searchable = if typeof(Info.Searchable) == 'boolean' then Info.Searchable else false
		if Info.SpecialType == 'Player' then
			Info.Values = getPlayersString()
			Info.AllowNull = true
		elseif Info.SpecialType == 'Team' then
			Info.Values = getTeamsString()
			Info.AllowNull = true
		end

		assert(Info.Values, 'AddDropdown: Missing dropdown value list.')
		assert(Info.AllowNull or Info.Default, 'AddDropdown: Missing default value. Pass `AllowNull` as true if this was intentional.')

		if not Info.Text then
			Info.Compact = true
		end
		
		if self.Objects then
			table.insert(self.Objects, {
				internal_name = Idx, settings = Info
			})
		end;

		local Dropdown = {
			Values = Info.Values;
			Value = Info.Multi and {};
			Multi = Info.Multi;
			Type = 'Dropdown';
			Flag = Idx;
			SpecialType = Info.SpecialType;
			Callback = Info.Callback or function(_) end;
			Name = Info.Text
		}

		local Groupbox = self
		local Container = Groupbox.Container
		local RelativeOffset = 0

		if not Info.Compact then
			Library:CreateLabel({
				Size = UDim2.new(1, 0, 0, 10);
				TextSize = 14;
				Text = Info.Text;
				TextXAlignment = Enum.TextXAlignment.Left;
				TextYAlignment = Enum.TextYAlignment.Bottom;
				ZIndex = 5;
				Parent = Container;
			})

			Groupbox:AddBlank(3)
		end

		for _, Element in next, Container:GetChildren() do
			if not Element:IsA('UIListLayout') then
				RelativeOffset = RelativeOffset + Element.Size.Y.Offset
			end
		end

		
		
		
		
		
		local DropdownOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, -4, 0, 20);
			ZIndex = 5;
			Parent = Container;
		})

		Library:AddToRegistry(DropdownOuter, {
			BorderColor3 = 'Black';
		})

		local DropdownInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = DropdownOuter;
		})

		if type(Info.Text) == 'string' and Info.Text ~= '' then
			Library:RegisterSearchEntry(Groupbox, {
				Kind = 'Dropdown';
				Text = Info.Text;
				Tab = Groupbox.Tab or Groupbox;
				Target = DropdownOuter;
				Focus = function()
					Library:FocusSearchTarget(DropdownOuter)
				end;
			})
		end

		Library:AddToRegistry(DropdownInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local function SetChromeHidden(Hidden)
			DropdownOuter.BackgroundTransparency = Hidden and 1 or 0
			DropdownOuter.BorderSizePixel = Hidden and 0 or 1
			DropdownInner.BackgroundTransparency = Hidden and 1 or 0
			DropdownInner.BorderSizePixel = Hidden and 0 or 1
		end

		local MAX_DROPDOWN_ITEMS = 8
		local BUTTON_HEIGHT = 20

		local Overlay = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			BorderMode = Enum.BorderMode.Inset;
			Visible = false;
			ZIndex = 20;
			Parent = ScreenGui;
		})

		Library:AddUIScale(Overlay)

		Library:AddToRegistry(Overlay, {
			BorderColor3 = 'Black';
		})

		local OverlayInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 21;
			Parent = Overlay;
		})

		Library:AddToRegistry(OverlayInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local ListOpened = false
		local ListContentHeight = MAX_DROPDOWN_ITEMS * 20

		local function RecalculateOverlay()
			local Height = BUTTON_HEIGHT + (ListOpened and ListContentHeight or 0)
			Overlay.Position = UDim2.fromOffset(DropdownOuter.AbsolutePosition.X, DropdownOuter.AbsolutePosition.Y)
			Overlay.Size = UDim2.fromOffset(DropdownOuter.AbsoluteSize.X / Library:GetUIScale(), ListOpened and Height - 3 or Height)
		end

		RecalculateOverlay()

		
		
		
		
		
		local DropdownInnerSearch
		if Info.Searchable then
			DropdownInnerSearch = Library:Create('TextBox', {
				BackgroundTransparency = 1;
				Visible = false;
				Position = UDim2.new(0, 5, 0, 0);
				Size = UDim2.new(0.9, -5, 0, BUTTON_HEIGHT);
				FontFace = Library.Font;
				PlaceholderColor3 = Color3.fromRGB(190, 190, 190);
				PlaceholderText = 'Search...';
				Text = '';
				TextColor3 = Library.FontColor;
				TextSize = 14;
				TextStrokeTransparency = 1;
				TextXAlignment = Enum.TextXAlignment.Left;
				ClearTextOnFocus = false;
				ZIndex = 23;
				Parent = DropdownInner;
			})

			Library:ApplyTextStroke(DropdownInnerSearch)

			Library:AddToRegistry(DropdownInnerSearch, {
				TextColor3 = 'FontColor';
			})
		end

		local DropdownArrow = Library:Create('ImageLabel', {
			AnchorPoint = Vector2.new(0, 0.5);
			BackgroundTransparency = 1;
			Position = UDim2.new(1, -16, 0, BUTTON_HEIGHT / 2);
			Size = UDim2.new(0, 12, 0, 12);
			Image = 'http://www.roblox.com/asset/?id=6282522798';
			ZIndex = 7;
			Parent = DropdownInner;
		})

		local ItemList = Library:CreateLabel({
			Position = UDim2.new(0, 1, 0, 2);
			Size = UDim2.new(1, -1, 0, BUTTON_HEIGHT - 2);
			TextSize = 14;
			Text = 'Select...';
			TextXAlignment = Enum.TextXAlignment.Left;
			TextYAlignment = Enum.TextYAlignment.Top;
			TextWrapped = true;
			ZIndex = 8;
			Parent = DropdownInner;
		})

		if type(Info.Tooltip) == 'string' then
			Library:AddToolTip(Info.Tooltip, DropdownOuter)
		end

		local ListInner = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 0, 0, BUTTON_HEIGHT);
			Size = UDim2.new(1, 0, 1, -BUTTON_HEIGHT);
			Visible = false;
			ZIndex = 21;
			Parent = OverlayInner;
		})

		DropdownOuter:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			RecalculateOverlay()
		end)

		DropdownOuter:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
			RecalculateOverlay()
		end)

		Library:OnHighlight(DropdownOuter, DropdownOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		Library:OnHighlight(DropdownOuter, Overlay,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		Library:OnHighlight(ListInner, Overlay,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		local Scrolling = Library:Create('ScrollingFrame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			CanvasSize = UDim2.new(0, 0, 0, 0);
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 21;
			Parent = ListInner;

			TopImage = 'rbxasset://textures/ui/Scroll/scroll-middle.png',
			BottomImage = 'rbxasset://textures/ui/Scroll/scroll-middle.png',

			ScrollBarThickness = 3,
			ScrollBarImageColor3 = Library.AccentColor,
		})

		Library:AddToRegistry(Scrolling, {
			ScrollBarImageColor3 = 'AccentColor'
		})

		Library:Create('UIListLayout', {
			Padding = UDim.new(0, 0);
			FillDirection = Enum.FillDirection.Vertical;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = Scrolling;
		})

		function Dropdown:Display()
			local Values = Dropdown.Values
			local Str = ''

			if Info.Multi then
				for _, Value in next, Values do
					if Dropdown.Value[Value] then
						Str = Str .. Value .. ', '
					end
				end

				Str = Str:sub(1, #Str - 2)
			else
				Str = Dropdown.Value or ''
			end

			ItemList.Text = (Str == '' and 'Select...' or Str)
			Library:UpdateDependencyBoxes()
		end

		function Dropdown:GetActiveValues()
			if Info.Multi then
				local T = {}
				for Value, _ in next, Dropdown.Value do
					table.insert(T, Value)
				end
				return T
			end

			return Dropdown.Value and 1 or 0
		end

		local built = false;
		function Dropdown:BuildDropdownList()
			local Values = Dropdown.Values
			local Buttons = {}

			for _, Element in next, Scrolling:GetChildren() do
				if not Element:IsA('UIListLayout') then
					Element:Destroy()
				end
			end

			local Count = 0
			local searchTerm = DropdownInnerSearch and string.lower(DropdownInnerSearch.Text)

			for _, Value in next, Values do
				if Info.Searchable and #searchTerm > 0 then
					local StringValue = typeof(Value) == 'Instance' and Value.Name or Value
					if not string.lower(StringValue):find(searchTerm, 1, true) then
						continue
					end
				end

				local ButtonState = {}
				Count = Count + 1

				local Button = Library:Create('Frame', {
					BackgroundColor3 = Library.OutlineColor;
					BackgroundTransparency = 1;
					BorderSizePixel = 0;
					Size = UDim2.new(1, -1, 0, 20);
					ZIndex = 23;
					Active = true;
					Parent = Scrolling;
				})

				Library:AddToRegistry(Button, {
					BackgroundColor3 = 'OutlineColor';
				})

				local ButtonLabel = Library:CreateLabel({
					Active = false;
					Size = UDim2.new(1, -6, 1, 0);
					Position = UDim2.new(0, 6, 0, 0);
					TextSize = 14;
					Text = Value;
					TextXAlignment = Enum.TextXAlignment.Left;
					ZIndex = 24;
					Parent = Button;
				})

				Library:OnHighlight(Button, Button,
					{ BackgroundTransparency = 0 },
					{ BackgroundTransparency = 1 }
				)

				local Selected = Info.Multi and Dropdown.Value[Value] or (Dropdown.Value == Value)

				function ButtonState:UpdateButton()
					if Info.Multi then
						Selected = Dropdown.Value[Value]
					else
						Selected = Dropdown.Value == Value
					end

					ButtonLabel.TextColor3 = Selected and Library.AccentColor or Library.FontColor
					Library.RegistryMap[ButtonLabel].Properties.TextColor3 = Selected and 'AccentColor' or 'FontColor'
				end

				ButtonLabel.InputBegan:Connect(function(Input)
					if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
						return
					end

					local Try = not Selected

					if Dropdown:GetActiveValues() == 1 and (not Try) and (not Info.AllowNull) then
						return
					end

					if Info.Multi then
						Selected = Try

						if Selected then
							Dropdown.Value[Value] = true
						else
							Dropdown.Value[Value] = nil
						end
					else
						Selected = Try

						if Selected then
							Dropdown.Value = Value
						else
							Dropdown.Value = nil
						end

						for _, OtherButton in next, Buttons do
							OtherButton:UpdateButton()
						end
					end

					ButtonState:UpdateButton()
					Dropdown:Display()

					Library:SafeCallback(Dropdown.Callback, Dropdown.Value)
					Library:SafeCallback(Dropdown.Changed, Dropdown.Value)

					Library:AttemptSave()
				end)

				ButtonState:UpdateButton()
				Buttons[Button] = ButtonState
			end

			Scrolling.CanvasSize = UDim2.fromOffset(0, (Count * 20) + 1)
			ListContentHeight = math.clamp(Count * 20, 0, MAX_DROPDOWN_ITEMS * 20) + 8
			RecalculateOverlay()
			Dropdown:Display()
		end

		function Dropdown:SetValues(NewValues)
			if NewValues then
				Dropdown.Values = NewValues
			end

			
			Dropdown:BuildDropdownList()
		end

		function Dropdown:OpenDropdown()
			if Info.Searchable then
				ItemList.Visible = false
				DropdownInnerSearch.Text = ''
				DropdownInnerSearch.Visible = true
				DropdownInnerSearch.Parent = OverlayInner
			end

			DropdownArrow.Parent = OverlayInner
			ItemList.Parent = OverlayInner
			SetChromeHidden(true)

			ListOpened = true
			ListInner.Visible = true
			Overlay.Visible = true
			RecalculateOverlay()
			Library.OpenedFrames[ListInner] = true
			DropdownArrow.Rotation = 180
			ItemList.ZIndex = 22;
			DropdownArrow.ZIndex = 22;

			if not built then
				Dropdown:BuildDropdownList()
				built = true;
			end
		end

		function Dropdown:CloseDropdown()
			if Info.Searchable then
				DropdownInnerSearch.Text = ''
				DropdownInnerSearch.Visible = false
				ItemList.Visible = true
				DropdownInnerSearch.Parent = DropdownInner
			end
			ItemList.ZIndex = 7;
			DropdownArrow.ZIndex = 7;
			DropdownArrow.Parent = DropdownInner
			ItemList.Parent = DropdownInner
			SetChromeHidden(false)

			ListOpened = false
			ListInner.Visible = false
			Overlay.Visible = false
			RecalculateOverlay()
			Library.OpenedFrames[ListInner] = nil
			DropdownArrow.Rotation = 0
		end

		function Dropdown:OnChanged(Func)
			Dropdown.Changed = Func
			Func(Dropdown.Value)
		end

		function Dropdown:SetValue(Val, Skip)
			if Dropdown.Multi then
				local nTable = {}

				local is_skip = (
					Idx == 'blocked_timings' or
					Idx == 'automation_usage_mantras' or
					Idx == 'mantra_slidecasting_mantras' or
					Idx == 'action_rolling_mantras' or
					Idx == 'backstab_movestacker_mantras'
				)
				for Value, _ in next, Val do
					if is_skip or table.find(Dropdown.Values, Value) then
						if is_skip and not table.find(Dropdown.Values, Value) then
							table.insert(Dropdown.Values, Value)
						end
						nTable[Value] = true
					end
				end

				Dropdown.Value = nTable
			else
				if not Val then
					Dropdown.Value = nil
				elseif table.find(Dropdown.Values, Val) then
					Dropdown.Value = Val
				end
			end

			Dropdown:Display()
			Library:SafeCallback(Dropdown.Callback, Dropdown.Value)
			Library:SafeCallback(Dropdown.Changed, Dropdown.Value)
		end

		DropdownOuter.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				if ListOpened then
					Dropdown:CloseDropdown()
				else
					Dropdown:OpenDropdown()
				end
			end
		end)

		if Info.Searchable then
			DropdownInnerSearch:GetPropertyChangedSignal('Text'):Connect(function()
				Dropdown:BuildDropdownList()
			end)
		end

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input)
			if not Library.Toggled or not ListOpened then
				return
			end

			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				local AbsPos, AbsSize = Overlay.AbsolutePosition, Overlay.AbsoluteSize
				if Mouse.X < AbsPos.X or Mouse.X > AbsPos.X + AbsSize.X
					or Mouse.Y < AbsPos.Y or Mouse.Y > AbsPos.Y + AbsSize.Y then
					Dropdown:CloseDropdown()
				end
			end
		end))

		local Defaults = {}

		if type(Info.Default) == 'string' then
			local defaultIndex = table.find(Dropdown.Values, Info.Default)
			if defaultIndex then
				table.insert(Defaults, defaultIndex)
			end
		elseif type(Info.Default) == 'table' then
			for _, Value in next, Info.Default do
				local defaultIndex = table.find(Dropdown.Values, Value)
				if defaultIndex then
					table.insert(Defaults, defaultIndex)
				end
			end
		elseif type(Info.Default) == 'number' and Dropdown.Values[Info.Default] ~= nil then
			table.insert(Defaults, Info.Default)
		end

		if next(Defaults) then
			for i = 1, #Defaults do
				local Index = Defaults[i]
				if Info.Multi then
					Dropdown.Value[Dropdown.Values[Index] ] = true
				else
					Dropdown.Value = Dropdown.Values[Index]
				end

				if not Info.Multi then
					break
				end
			end

			
			
		end

		Dropdown:BuildDropdownList()

		Groupbox:AddBlank(Info.BlankSize or 5)
		Groupbox:Resize()

		aztup_options[Idx] = Dropdown
		Library:UpdateDependencyBoxes()
		return Dropdown
	end

	return Component
end

end;

__modules["src/utility/librarys/components/hud"] = function()


return function(Library, context)
	local ScreenGui = context.ScreenGui or Library.ScreenGui
	local Mouse = context.Mouse
	local TweenService = context.TweenService or game:GetService('TweenService')

	local Component = {}

	local NotificationArea = Library:Create('Frame', {
		BackgroundTransparency = 1;
		BorderSizePixel = 0;
		Position = UDim2.new(0, 0, 0, 40);
		Size = UDim2.fromOffset(320, 0);
		ZIndex = 90;
		Parent = ScreenGui;
	})

	Library.NotificationArea = NotificationArea
	Library:AddUIScale(NotificationArea)

	Library:Create('UIListLayout', {
		Padding = UDim.new(0, 4);
		FillDirection = Enum.FillDirection.Vertical;
		SortOrder = Enum.SortOrder.LayoutOrder;
		Parent = NotificationArea;
	})

	local WatermarkOuter = Library:Create('Frame', {
		Position = UDim2.new(0, 24, 1, -48);
		Size = UDim2.new(0, 120, 0, 28);
		BackgroundColor3 = Library.AccentColor;
		BorderSizePixel = 1;
		ZIndex = 200;
		Visible = false;
		Parent = ScreenGui;
	})

	Library:AddUIScale(WatermarkOuter)

	WatermarkOuter.MouseEnter:Connect(function()
		Library.RequestingMouse = true
	end)

	WatermarkOuter.MouseLeave:Connect(function()
		Library.RequestingMouse = false
	end)

	Library:AddToRegistry(WatermarkOuter, {
		BackgroundColor3 = 'AccentColor';
	}, true)

	local WatermarkInner = Library:Create('Frame', {
		Size = UDim2.new(1, -2, 1, -2);
		Position = UDim2.new(0, 1, 0, 1);
		BackgroundColor3 = Library.MainColor;
		BorderSizePixel = 0;
		ZIndex = 201;
		Parent = WatermarkOuter;
	})

	Library:AddToRegistry(WatermarkInner, {
		BackgroundColor3 = 'MainColor';
	}, true)

	local WatermarkText = Library:Create('TextLabel', {
		Position = UDim2.new(0, 6, 0, 0);
		Size = UDim2.new(1, -10, 1, 0);
		BorderSizePixel = 0;
		BackgroundTransparency = 1;
		Text = '';
		TextColor3 = Library.FontColor;
		TextSize = 16;
		TextXAlignment = Enum.TextXAlignment.Left;
		TextStrokeTransparency = 1;
		AutoLocalize = false;
		RichText = true;
		ZIndex = 202;
		Parent = WatermarkInner;
	})

	task.spawn(function()
		WatermarkText.FontFace = lexend.regular;
	end);

	Library:ApplyTextStroke(WatermarkText)

	Library:AddToRegistry(WatermarkText, {
		TextColor3 = 'FontColor';
	}, true)

	Library.Watermark = WatermarkOuter
	Library.WatermarkText = WatermarkText
	Library:MakeDraggable(Library.Watermark)

	function Library:SetWatermarkVisibility(Bool)
		Library.Watermark.Visible = Bool
	end

	function Library:SetWatermark(Text, RText)
		if not Library.Watermark.Visible then
			return
		end

		
		local Scale = Library:GetUIScale()
		local X = Library:GetLexendTextBounds(RText, lexend.regular, 16 * Scale) / Scale
		Library.Watermark.Size = UDim2.new(0, X + 12, 0, 28)
		Library.WatermarkText.Text = Text
			
		local old_pos = Library.Watermark.Position;

		if old_pos.X.Scale > 0.4 and old_pos.X.Scale < 0.6 then
			Library.Watermark.Position = UDim2.new(old_pos.X.Scale, -((X + 12) / 2), old_pos.Y.Scale, old_pos.Y.Offset);
		end;

	end

	function Library:Notify(Text, Time)
		
		local Scale = Library:GetUIScale()
		local XSize, YSize = Library:GetLexendTextBounds(Text, lexend.regular, 14 * Scale)
		XSize, YSize = XSize / Scale, YSize / Scale + 6
		local TweenDuration = 0.4

		local NotifyOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			BackgroundTransparency = 1;
			Position = UDim2.new(0, 100, 0, 10);
			Size = UDim2.new(0, 0, 0, YSize);
			ClipsDescendants = true;
			ZIndex = 100;
			Parent = NotificationArea;
		})

		local NotifyInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BackgroundTransparency = 1;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 101;
			Parent = NotifyOuter;
		})

		Library:AddToRegistry(NotifyInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		}, true)

		local InnerFrame = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 1, 0, 1);
			Size = UDim2.new(1, -2, 1, -2);
			ZIndex = 102;
			Parent = NotifyInner;
		})

		Library:AddToRegistry(InnerFrame, {
			BackgroundColor3 = Library.MainColor
		})
		local NotifyLabel, NotifyStroke = Library:CreateLabel({
			Position = UDim2.new(0, 4, 0, 0);
			Size = UDim2.new(1, -4, 1, 0);
			Text = Text;
			TextTransparency = 1;
			TextXAlignment = Enum.TextXAlignment.Left;
			TextSize = 14;
			ZIndex = 103;
			Parent = InnerFrame;
		})

		task.spawn(function()
			NotifyLabel.FontFace = lexend.regular;
		end);

		local LeftColor = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, -1, 0, -1);
			Size = UDim2.new(0, 3, 1, 2);
			ZIndex = 104;
			Parent = NotifyOuter;
		})

		Library:AddToRegistry(LeftColor, {
			BackgroundColor3 = 'AccentColor';
		}, true)

		local destroyed = false

		local function destroyObject()
			if destroyed then
				return
			end

			destroyed = true
			pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, 0, 0, YSize), 'Out', 'Quad', TweenDuration, true)
			TweenService:Create(NotifyOuter, TweenInfo.new(TweenDuration), { BackgroundTransparency = 1 }):Play()
			TweenService:Create(NotifyInner, TweenInfo.new(TweenDuration), { BackgroundTransparency = 1 }):Play()
			TweenService:Create(InnerFrame, TweenInfo.new(TweenDuration), { BackgroundTransparency = 1 }):Play()
			TweenService:Create(NotifyLabel, TweenInfo.new(TweenDuration), { TextTransparency = 1 }):Play()
			TweenService:Create(LeftColor, TweenInfo.new(TweenDuration), { BackgroundTransparency = 1 }):Play()

			task.wait(TweenDuration)
			NotifyOuter:Destroy()
		end

		local function inputBegan()
			pcall(destroyObject)
		end

		InnerFrame.MouseEnter:Connect(destroyObject)
		InnerFrame.InputBegan:Connect(inputBegan)
		pcall(NotifyOuter.TweenSize, NotifyOuter, UDim2.new(0, XSize + 8 + 4, 0, YSize), 'Out', 'Quad', TweenDuration, true)

		TweenService:Create(NotifyOuter, TweenInfo.new(TweenDuration), { BackgroundTransparency = 0 }):Play()
		TweenService:Create(NotifyInner, TweenInfo.new(TweenDuration), { BackgroundTransparency = 0 }):Play()
		TweenService:Create(InnerFrame, TweenInfo.new(TweenDuration), { BackgroundTransparency = 0 }):Play()
		TweenService:Create(NotifyLabel, TweenInfo.new(TweenDuration), { TextTransparency = 0 }):Play()
		TweenService:Create(LeftColor, TweenInfo.new(TweenDuration), { BackgroundTransparency = 0 }):Play()
        TweenService:Create(NotifyStroke, TweenInfo.new(TweenDuration), { Transparency = 0 }):Play()


		task.spawn(function() 
			task.wait(Time or 5) 
			destroyObject()
		end) 
	end

	function Library:NotifyWithSound(Text, Time)
		if aztup and aztup_toggles and aztup_toggles.notification_sound and aztup_toggles.notification_sound.Value and not aztup.silent_mode then
			xpcall(function()
				local sound = Instance.new('Sound', game:GetService('CoreGui'))
				game:GetService('Debris'):AddItem(sound, 6)
				sound.Volume = aztup_options.NotificationVolume.Value
				sound.SoundId = getcustomasset('Frutiger/assets/notification.mp3')
				sound:Play()
			end, warn)
		end

		Library:Notify(Text, Time)
	end

	return Component
end

end;

