		['Mint']          = { 8, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"242424","AccentColor":"3db488","BackgroundColor":"1c1c1c","OutlineColor":"373737"}') },
		['Tokyo Night']   = { 9, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"191925","AccentColor":"6759b3","BackgroundColor":"16161f","OutlineColor":"323232"}') },
		['Ubuntu']        = { 10, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"3e3e3e","AccentColor":"e2581e","BackgroundColor":"323232","OutlineColor":"191919"}') },
		['Quartz']        = { 11, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"232330","AccentColor":"426e87","BackgroundColor":"1d1b26","OutlineColor":"27232f"}') },
		['Dracula']       = { 12, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"232533","AccentColor":"6271a5","BackgroundColor":"1b1c27","OutlineColor":"7c82a7"}') },
		["Scarlet Hook"]  = { 13, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"343446","AccentColor":"a23636","BackgroundColor":"211e2b","OutlineColor":"000000"}') },
		["maple.software"]= { 14, httpService:JSONDecode('{"MainColor":"292c3c","AccentColor":"f288b7","OutlineColor":"303446","BackgroundColor":"232634","FontColor":"c6d0f5"}')},

		["Nord"]          = { 15, httpService:JSONDecode('{"FontColor":"e5e9f0","MainColor":"2e3440","AccentColor":"88c0d0","BackgroundColor":"242933","OutlineColor":"3b4252"}') },
		["Midnight"]      = { 16, httpService:JSONDecode('{"FontColor":"f5f7ff","MainColor":"151826","AccentColor":"4f7dff","BackgroundColor":"10121b","OutlineColor":"272c3f"}') },
		["Forest"]        = { 19, httpService:JSONDecode('{"FontColor":"e8f5e9","MainColor":"1b3124","AccentColor":"66bb6a","BackgroundColor":"15261c","OutlineColor":"294334"}') },
		["Crimson Night"] = { 20, httpService:JSONDecode('{"FontColor":"ffffff","MainColor":"2a0f1f","AccentColor":"e53935","BackgroundColor":"1a0a13","OutlineColor":"4b1f33"}') },
		["Iceberg"]       = { 21, httpService:JSONDecode('{"FontColor":"e0f4ff","MainColor":"1f2933","AccentColor":"5bc0eb","BackgroundColor":"151a23","OutlineColor":"324154"}') },
		["Lavender"]      = { 23, httpService:JSONDecode('{"FontColor":"f5e9ff","MainColor":"2a233a","AccentColor":"c792ea","BackgroundColor":"211a33","OutlineColor":"3a3150"}') }
	}

	local count = 0;

	for name, catppuchin_macchiato_color in {
		["Rosewater"] = "f4dbd6",
		["Flamingo"] = "f0c6c6",
		["Yellow"] = "eed49f",
		["Maroon"] = "ee99a0",
		["Green"] = "a6da95",
		["Peach"] = "f5a97f",
		["Mauve"] = "c6a0f6",
		["Pink"] = "f5bde6",
		["Teal"] = "8bd5ca",
		["Blue"] = "8aadf4",
		["Red"] = "ed8796",
		["Sky"] = "91d7e3",
	} do
		count += 1;
		ThemeManager.BuiltInThemes[name] = { 	
			23 + count, 
			{
				MainColor = "24273a",
				AccentColor = catppuchin_macchiato_color,
				OutlineColor="363a4f",
				BackgroundColor="1e2030",
				FontColor="e9edfa"
			} 
		};
	end;

	function ThemeManager:ApplyTheme(theme)
		local customThemeData = self:GetCustomTheme(theme)
		local data = customThemeData or self.BuiltInThemes[theme]

		if not data then return end

		

		local scheme = data[2]
		for idx, col in next, customThemeData or scheme do
			self.Library[idx] = Color3.fromHex(col)
			
			if aztup_options[idx] then
				aztup_options[idx]:SetValueRGB(Color3.fromHex(col))
			end
		end

		self:ThemeUpdate()
	end

	function ThemeManager:ThemeUpdate()
		
		local aztup_options = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }
		for i, field in next, aztup_options do
			if aztup_options and aztup_options[field] then
				self.Library[field] = aztup_options[field].Value
			end
		end

		self.Library.AccentColorDark = self.Library:GetDarkerColor(self.Library.AccentColor);
		self.Library:UpdateColorsUsingRegistry()
	end

	function ThemeManager:LoadDefault()		
		local theme = 'PR'
		local content = isfile(self.Folder .. '/themes/default.txt') and readfile(self.Folder .. '/themes/default.txt')

		local isDefault = true
		if content then
			if self.BuiltInThemes[content] then
				theme = content
			elseif self:GetCustomTheme(content) then
				theme = content
				isDefault = false;
			end
		elseif self.BuiltInThemes[self.DefaultTheme] then
		 	theme = self.DefaultTheme
		end

		if isDefault then
			aztup_options.ThemeManager_ThemeList:SetValue(theme)
		else
			self:ApplyTheme(theme)
		end
	end

	function ThemeManager:SaveDefault(theme)
		writefile(self.Folder .. '/themes/default.txt', theme)
	end

	function ThemeManager:CreateThemeManager(groupbox)
		groupbox:AddLabel('Background color'):AddColorPicker('BackgroundColor', { Default = self.Library.BackgroundColor });
		groupbox:AddLabel('Main color')	:AddColorPicker('MainColor', { Default = self.Library.MainColor });
		groupbox:AddLabel('Accent color'):AddColorPicker('AccentColor', { Default = self.Library.AccentColor });
		groupbox:AddLabel('Outline color'):AddColorPicker('OutlineColor', { Default = self.Library.OutlineColor });
		groupbox:AddLabel('Font color')	:AddColorPicker('FontColor', { Default = self.Library.FontColor });

		local ThemesArray = {}
		for Name, Theme in next, self.BuiltInThemes do
			table.insert(ThemesArray, Name)
		end

		table.sort(ThemesArray, function(a, b) return self.BuiltInThemes[a][1] < self.BuiltInThemes[b][1] end)

		groupbox:AddDivider()
		groupbox:AddDropdown('ThemeManager_ThemeList', { Text = 'Theme list', Values = ThemesArray, Default = 1, Searchable = true })

		groupbox:AddButton('Set as default', function()
			self:SaveDefault(aztup_options.ThemeManager_ThemeList.Value)
			self.Library:NotifyWithSound(string.format('Set default theme to %q', aztup_options.ThemeManager_ThemeList.Value))
		end)

		aztup_options.ThemeManager_ThemeList:OnChanged(function()
			self:ApplyTheme(aztup_options.ThemeManager_ThemeList.Value)
		end)

		groupbox:AddDivider()
		groupbox:AddDropdown('ThemeManager_CustomThemeList', { Text = 'Custom themes', Values = self:ReloadCustomThemes(), AllowNull = true, Default = 1, Searchable = true })
		groupbox:AddInput('ThemeManager_CustomThemeName', { Text = 'Custom theme name' })

		groupbox:AddButton('Load custom theme', function() 
			self:ApplyTheme(aztup_options.ThemeManager_CustomThemeList.Value) 
		end)

		groupbox:AddButton('Save custom theme', function() 
			self:SaveCustomTheme(aztup_options.ThemeManager_CustomThemeName.Value)

			aztup_options.ThemeManager_CustomThemeList.Values = self:ReloadCustomThemes()
			aztup_options.ThemeManager_CustomThemeList:SetValues()
			aztup_options.ThemeManager_CustomThemeList:SetValue(nil)
		end)
		local refresh_list_theme = function()
			aztup_options.ThemeManager_CustomThemeList.Values = self:ReloadCustomThemes()
			aztup_options.ThemeManager_CustomThemeList:SetValues()
			aztup_options.ThemeManager_CustomThemeList:SetValue(nil)
		end
		
		groupbox:AddButton('Refresh list', refresh_list_theme)
		getgenv().refresh_list_theme = refresh_list_theme;
		groupbox:AddButton('Set as default', function()
			if aztup_options.ThemeManager_CustomThemeList.Value ~= nil and aztup_options.ThemeManager_CustomThemeList.Value ~= '' then
				self:SaveDefault(aztup_options.ThemeManager_CustomThemeList.Value)
				self.Library:NotifyWithSound(string.format('Set default theme to %q', aztup_options.ThemeManager_CustomThemeList.Value))
			end
		end)

		ThemeManager:LoadDefault()

		local function UpdateTheme()
			self.Library.BackgroundColor = aztup_options.BackgroundColor.Value
			self.Library.OutlineColor = aztup_options.OutlineColor.Value
			self.Library.AccentColor = aztup_options.AccentColor.Value
			self.Library.FontColor = aztup_options.FontColor.Value
			self.Library.MainColor = aztup_options.MainColor.Value
			self:ThemeUpdate()
		end

		aztup_options.BackgroundColor:OnChanged(UpdateTheme)
		aztup_options.MainColor:OnChanged(UpdateTheme)
		aztup_options.AccentColor:OnChanged(UpdateTheme)
		aztup_options.OutlineColor:OnChanged(UpdateTheme)
		aztup_options.FontColor:OnChanged(UpdateTheme)
	end

	function ThemeManager:GetCustomTheme(file)
		local path = self.Folder .. '/themes/' .. file
		if not isfile(path) then
			return nil
		end

		local data = readfile(path)
		local success, decoded = pcall(httpService.JSONDecode, httpService, data)
		
		if not success then
			return nil
		end

		return decoded
	end

	function ThemeManager:SaveCustomTheme(file)
		if file:gsub(' ', '') == '' then
			return self.Library:Notify('Invalid file name for theme (empty)', 3)
		end

		local theme = {}
		local fields = { "FontColor", "MainColor", "AccentColor", "BackgroundColor", "OutlineColor" }

		for _, field in next, fields do
			theme[field] = aztup_options[field].Value:ToHex()
		end

		writefile(self.Folder .. '/themes/' .. file .. '.json', httpService:JSONEncode(theme))
	end

	function ThemeManager:ReloadCustomThemes()
		local list = listfiles(self.Folder .. '/themes')

		local out = {}
		for i = 1, #list do
			local file = list[i]
			if file:sub(-5) == '.json' then
				

				local pos = file:find('.json', 1, true)
				local char = file:sub(pos, pos)

				while char ~= '/' and char ~= '\\' and char ~= '' do
					pos = pos - 1
					char = file:sub(pos, pos)
				end

				if char == '/' or char == '\\' then
					table.insert(out, file:sub(pos + 1))
				end
			end
		end

		return out
	end

	function ThemeManager:SetLibrary(lib)
		self.Library = lib
	end

	function ThemeManager:BuildFolderTree()
		local paths = {}

		
		

		local parts = self.Folder:split('/')
		for idx = 1, #parts do
			paths[#paths + 1] = table.concat(parts, '/', 1, idx)
		end

		table.insert(paths, self.Folder .. '/themes')
		table.insert(paths, self.Folder .. '/settings')

		for i = 1, #paths do
			local str = paths[i]
			if not isfolder(str) then
				makefolder(str)
			end
		end
	end

	function ThemeManager:SetFolder(folder)
		self.Folder = folder
		self:BuildFolderTree()
	end

	function ThemeManager:CreateGroupBox(tab)
		assert(self.Library, 'Must set ThemeManager.Library first!')
		return tab:AddLeftGroupbox('Themes')
	end

	function ThemeManager:ApplyToTab(tab)
		assert(self.Library, 'Must set ThemeManager.Library first!')
		local groupbox = self:CreateGroupBox(tab)
		self:CreateThemeManager(groupbox)
	end

	function ThemeManager:ApplyToGroupbox(groupbox)
		assert(self.Library, 'Must set ThemeManager.Library first!')
		self:CreateThemeManager(groupbox)
	end

	ThemeManager:BuildFolderTree()
end
return ThemeManager

end;

__modules["src/utility/librarys/ui"] = function()



local cloneref = cloneref or function(a) return a end;
local InputService =  cloneref(game:GetService('UserInputService'));
local TextService =   cloneref(game:GetService('TextService'));
local CoreGui =       cloneref(game:GetService("CoreGui"));
local Players =       cloneref(game:GetService('Players'));
local RunService =    cloneref(game:GetService('RunService'));
local TweenService =  cloneref(game:GetService('TweenService'));
local RenderStepped = RunService.RenderStepped;
local LocalPlayer =   cloneref(Players.LocalPlayer);
local Mouse =         cloneref(LocalPlayer:GetMouse());
local getgenv = getgenv or function() return {}end;
local uiOpen = false;

local ScreenGui = Instance.new('ScreenGui');
 
ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global;
ScreenGui.Parent = CoreGui;
ScreenGui.OnTopOfCoreBlur = true;

aztup_toggles = {};
aztup_options = {};
getgenv().aztup_toggles = aztup_toggles;
getgenv().aztup_options = aztup_options;

local Library = {
	OnToggledChanged = Instance.new("BindableEvent");
	Registry = {};
	RegistryMap = {};

	HudRegistry = {};

	FontColor = Color3.fromHex("d8dee9");
	MainColor = Color3.fromHex("1b2b34");
	BackgroundColor = Color3.fromHex("16232a");
	AccentColor = Color3.fromHex("6699cc");
	OutlineColor = Color3.fromHex("343d46");
	RiskColor = Color3.fromRGB(255, 50, 50),

	Black = Color3.new(0, 0, 0);
	Font = lexend.regular,

	OpenedFrames = {};
	DependencyBoxes = {};
	DependencyGroupboxes = {};

	Signals = {};
	ScreenGui = ScreenGui;
};

local function GetPlayersString()
	local PlayerList = Players:GetPlayers();

	for i = 1, #PlayerList do
		PlayerList[i] = PlayerList[i].Name;
	end;

	table.sort(PlayerList, function(str1, str2) return str1 < str2 end);

	return PlayerList
end;

function Library:SafeCallback(f, ...)
	if (not f) then
		return	
end;
	local success, event = pcall(f, ...);

	if not success then
		

		
		
		

		if aztup and aztup.silent_mode then return end
		return Library:Notify(event)	
end;
end;

function Library:AttemptSave()
	if Library.SaveManager then
		Library.SaveManager:Save();
	end;
end;

function Library:Create(Class, Properties)
	local _Instance = Class;

	if type(Class) == 'string' then
		_Instance = Instance.new(Class);
	end;

	
	for Property, Value in next, Properties do
		if Property ~= 'Parent' then
			_Instance[Property] = Value;
		end;
	end;

	if Properties.Parent ~= nil then
		_Instance.Parent = Properties.Parent;
	end;

	return _Instance
end;

Library.UIScale = 1;

Library.ScaledObjects = {};


function Library:AddUIScale(Inst)
	local Scale = Instance.new('UIScale');
	Scale.Scale = Library.UIScale;
	Scale.Parent = Inst;

	Library.ScaledObjects[Scale] = true;

	return Scale
end;

function Library:GetUIScale()
	return Library.UIScale
end;


function Library:GetInstanceScale(Inst)
	local Scale = Inst:FindFirstChildOfClass('UIScale');
	return Scale and Scale.Scale or 1
end;

function Library:SetUIScale(Value)
	Value = math.clamp(tonumber(Value) or 1, 0.25, 4);
	Library.UIScale = Value;

	for Scale in next, Library.ScaledObjects do
		if Scale.Parent then
			Scale.Scale = Value;
		else
			Library.ScaledObjects[Scale] = nil;
		end;
	end;
end;

function Library:ApplyTextStroke(Inst)
	Inst.TextStrokeTransparency = 1;

	-- The stroke is kept as an instance but made invisible.
	--
	-- It used to be Color3.new(0,0,0) at thickness 1, i.e. a black outline
	-- drawn around every label in the interface -- 1783 of them, measured. An
	-- outline on text reads as BOLD, which is exactly what it looked like, and
	-- it is not a font-weight problem: every text element already resolves to
	-- Enum.FontWeight.Regular.
	--
	-- Returned rather than removed because callers hold a reference to it and
	-- may restyle it later; setting Transparency keeps that reference valid
	-- while drawing nothing.
	return Library:Create('UIStroke', {
		Color = Color3.new(0, 0, 0);
		Thickness = 1;
		Transparency = 1;
		LineJoinMode = Enum.LineJoinMode.Miter;
		Parent = Inst;
	})
end;

function Library:CreateLabelNoStroke(Properties, IsHud, Font)
	local _Instance = Library:Create('TextLabel', {
		BackgroundTransparency = 1;
		FontFace = Font or Library.Font;
		TextColor3 = Library.FontColor;
		AutoLocalize = false;
		TextSize = 16;
		TextStrokeTransparency = 1;
	});

	Library:AddToRegistry(_Instance, {
		TextColor3 = 'FontColor';
	}, IsHud);

	return Library:Create(_Instance, Properties)
end;

function Library:CreateLabel(Properties, IsHud, Font)
	local _Instance = Library:Create('TextLabel', {
		BackgroundTransparency = 1;
		FontFace = Font or Library.Font;
		TextColor3 = Library.FontColor;
		AutoLocalize = false;
		TextSize = 16;
		TextStrokeTransparency = 1;
	});

	local Stroke = Library:ApplyTextStroke(_Instance);

	Library:AddToRegistry(_Instance, {
		TextColor3 = 'FontColor';
	}, IsHud);

	return Library:Create(_Instance, Properties), Stroke
end;

function Library:MakeUIDraggable(inst, Cutoff, Limit)
	
	
	

	local M = inst
	M.Active = true

	local X = Instance.new("Frame")
	X.BackgroundColor3 = Library.MainColor
	X.BackgroundTransparency = 0.3
	X.BorderSizePixel = 1
	X.BorderColor3 = Color3.fromRGB(0,0,0);
	X.ZIndex = 9999
	X.Visible = false
	X.Active = false
	X.Parent = ScreenGui

	local Stroke = Instance.new("UIStroke")
	Stroke.Color = Library.AccentColor
	Stroke.BorderStrokePosition = Enum.BorderStrokePosition.Inner;
	Stroke.Thickness = 1;
	Stroke.Parent = X;

	Library:AddToRegistry(X, {
		BackgroundColor3 = 'MainColor';
	});

	Library:AddToRegistry(Stroke, {
		Color = 'AccentColor';
	});

	
	
	
	
	
	

	M.InputBegan:Connect(function(Input)
		if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
			return
		end

		local clickPos = Vector2.new(
			Mouse.X - M.AbsolutePosition.X,
			Mouse.Y - M.AbsolutePosition.Y
		)

		if clickPos.Y > (Cutoff or 40) * Library:GetInstanceScale(M) then
			return
		end

		
		local absPos = inst.AbsolutePosition
		local absSize = inst.AbsoluteSize

		X.Size = UDim2.fromOffset(absSize.X - 2, absSize.Y - 1)
		X.Position = UDim2.fromOffset(absPos.X, absPos.Y)
		X.Visible = true

		
		inst.Visible = false

		
		while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
			RenderStepped:Wait()
			local newX = Mouse.X - clickPos.X
			local newY = Mouse.Y - clickPos.Y

			X.Position = UDim2.fromOffset(
				newX,
				newY
			)

		end

		

		local finalPosX = X.Position.X.Offset
		local finalPosY = X.Position.Y.Offset

		local anchor = inst.AnchorPoint
		local size   = inst.AbsoluteSize
		local parent = inst.Parent
		local parentPos = parent and parent.AbsolutePosition or Vector2.zero

		inst.Position = UDim2.fromOffset(
			(finalPosX - parentPos.X) + anchor.X * size.X,
			(finalPosY - parentPos.Y) + anchor.Y * size.Y
		)

		X.Visible = false
		if Library.Toggled then
			inst.Visible = true
		end
	end)
end

function Library:MakeDraggable(Instance, Cutoff, Limit)
	Instance.Active = true;

	Instance.InputBegan:Connect(function(Input)
		if Input.UserInputType == Enum.UserInputType.MouseButton1 then
			local ObjPos = Vector2.new(
				Mouse.X - Instance.AbsolutePosition.X,
				Mouse.Y - Instance.AbsolutePosition.Y
			);

			if ObjPos.Y > (Cutoff or 40) * Library:GetInstanceScale(Instance) then
				return			
end;

			while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
				Instance.Position = UDim2.new(
					0,
					Mouse.X - ObjPos.X + (Instance.AbsoluteSize.X * Instance.AnchorPoint.X),
					0,
					Mouse.Y - ObjPos.Y + (Instance.AbsoluteSize.Y * Instance.AnchorPoint.Y)
				);

				if Limit then
					task.wait(1/20);
				end;
				RenderStepped:Wait();
			end;
		end;
	end)
end;

function Library:MakeDraggableScale(Instance, Cutoff, O)
	Instance.Active = true

	Instance.InputBegan:Connect(function(Input)
		if Input.UserInputType == Enum.UserInputType.MouseButton1 then
			local absPos = Instance.AbsolutePosition
			local absSize = Instance.AbsoluteSize
			local viewportSize = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1920, 1080)

			local ObjPos = Vector2.new(
				Mouse.X - absPos.X,
				Mouse.Y - absPos.Y
			)

			if ObjPos.Y > (Cutoff or 40) * Library:GetInstanceScale(Instance) then
				return
			end

			while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
				local newX = (Mouse.X - ObjPos.X + (absSize.X * Instance.AnchorPoint.X)) / viewportSize.X
				local newY = (Mouse.Y - ObjPos.Y + (absSize.Y * Instance.AnchorPoint.Y))
				if O then
					newY -= Instance.Position.Y.Offset;
				end;

				newY /= viewportSize.Y;
				Instance.Position = UDim2.new(
					newX,
					O and Instance.Position.X.Offset or 0,
					newY,
					O and Instance.Position.Y.Offset or 0
				)

				RenderStepped:Wait()
			end
		end
	end)
end

function Library:AddToolTip(InfoStr, HoverInstance)
	local X, Y = Library:GetLexendTextBounds(InfoStr, Library.Font, 14);
	local Tooltip = Library:Create('Frame', {
		BackgroundColor3 = Library.MainColor,
		BorderColor3 = Library.OutlineColor,
		BackgroundTransparency = 1,

		Size = UDim2.fromOffset(X + 5, Y + 4),
		ZIndex = 100,
		Parent = Library.ScreenGui,

		Visible = false,
	})

	Library:AddUIScale(Tooltip);

	local Label, Stroke = Library:CreateLabel({
		Position = UDim2.fromOffset(3, 1),
		Size = UDim2.fromOffset(X, Y);
		TextSize = 14;
		Text = InfoStr,
		TextColor3 = Library.FontColor,
		TextXAlignment = Enum.TextXAlignment.Left;
		ZIndex = Tooltip.ZIndex + 1,

		Parent = Tooltip;
	});

	Tooltip.Visible = false
	Label.TextTransparency = 1
	Label.TextStrokeTransparency = 1 
	if Stroke then
		Stroke.Transparency = 1
	end

	Library:AddToRegistry(Tooltip, {
		BackgroundColor3 = 'MainColor';
		BorderColor3 = 'OutlineColor';
	});

	Library:AddToRegistry(Label, {
		TextColor3 = 'FontColor',
	});

	local IsHovering = false
	local HoverToken = 0
	local PositionTween
	local FadeTweens = {}

	local function CancelTween(Tween)
		if Tween then
			Tween:Cancel()
		end
	end

	local function TweenTooltipTransparency(TargetTransparency)
		CancelTween(FadeTweens.Background)
		CancelTween(FadeTweens.Text)
		CancelTween(FadeTweens.Stroke)

		local FadeInfo = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		FadeTweens.Background = TweenService:Create(Tooltip, FadeInfo, {
			BackgroundTransparency = TargetTransparency,
		})
		FadeTweens.Text = TweenService:Create(Label, FadeInfo, {
			TextTransparency = TargetTransparency,
			TextStrokeTransparency = TargetTransparency,
		})

		if Stroke then
			FadeTweens.Stroke = TweenService:Create(Stroke, FadeInfo, {
				Transparency = TargetTransparency,
			})
		end

		FadeTweens.Background:Play()
		FadeTweens.Text:Play()
		if FadeTweens.Stroke then
			FadeTweens.Stroke:Play()
		end
	end

	local function TweenTooltipPosition(TargetPosition)
		CancelTween(PositionTween)
		PositionTween = TweenService:Create(Tooltip, TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			Position = TargetPosition,
		})
		PositionTween:Play()
	end

	local me, ml;
	me = HoverInstance.MouseEnter:Connect(function()
		if Library:MouseIsOverOpenedFrame() then
			return
		end

		HoverToken += 1
		local CurrentToken = HoverToken
		IsHovering = true

		Tooltip.Position = UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12)
		Tooltip.Visible = true
		TweenTooltipTransparency(0)

		while IsHovering and uiOpen and HoverToken == CurrentToken do
			TweenTooltipPosition(UDim2.fromOffset(Mouse.X + 15, Mouse.Y + 12))
			task.wait(1 / 30)
		end
		IsHovering = false;
		TweenTooltipTransparency(1)
		task.delay(0.12, function()
			if HoverToken == CurrentToken and not IsHovering then
				Tooltip.Visible = false
			end
		end)
	end)

	ml = HoverInstance.MouseLeave:Connect(function()
		IsHovering = false
		HoverToken += 1
		TweenTooltipTransparency(1)
		task.delay(0.12, function()
			if not IsHovering then
				Tooltip.Visible = false
			end
		end)
	end)

	return {
		Destroy = function()
			Tooltip:Destroy();
			Label:Destroy();

			me:Disconnect();
			ml:Disconnect();
		end;
	}
end

function Library:OnHighlight(HighlightInstance, Instance, Properties, PropertiesDefault)
	HighlightInstance.MouseEnter:Connect(function()
		local Reg = Library.RegistryMap[Instance];

		for Property, ColorIdx in next, Properties do
			services.TweenService:Create(Instance, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				[Property] = Library[ColorIdx] or typeof(ColorIdx) == "function" and ColorIdx() or ColorIdx;
			}):Play();

			if Reg and Reg.Properties[Property] then
				Reg.Properties[Property] = ColorIdx;
			end;
		end;
	end)

	HighlightInstance.MouseLeave:Connect(function()
		local Reg = Library.RegistryMap[Instance];

		for Property, ColorIdx in next, PropertiesDefault do
			services.TweenService:Create(Instance, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				[Property] = Library[ColorIdx] or typeof(ColorIdx) == "function" and ColorIdx() or ColorIdx;
			}):Play(); 

			if Reg and Reg.Properties[Property] then
				Reg.Properties[Property] = ColorIdx;
			end;
		end;
	end)
end;

function Library:MouseIsOverOpenedFrame()
	for Frame, _ in next, Library.OpenedFrames do
		local AbsPos, AbsSize = Frame.AbsolutePosition, Frame.AbsoluteSize;

		if Mouse.X >= AbsPos.X and Mouse.X <= AbsPos.X + AbsSize.X
			and Mouse.Y >= AbsPos.Y and Mouse.Y <= AbsPos.Y + AbsSize.Y then

			return true		
end;
	end;
end;

function Library:CloseAllDropdowns()
	for _, Option in aztup_options do
		if Option.Type == "Dropdown" then
			Option:CloseDropdown();
		end;
	end;
end;

function Library:IsMouseOverFrame(Frame)
	local AbsPos, AbsSize = Frame.AbsolutePosition, Frame.AbsoluteSize;

	if Mouse.X >= AbsPos.X and Mouse.X <= AbsPos.X + AbsSize.X
		and Mouse.Y >= AbsPos.Y and Mouse.Y <= AbsPos.Y + AbsSize.Y then

		return true	
end;
end;

local function flush_dependency_boxes()
	for _, Depbox in next, Library.DependencyBoxes do
		Depbox:Update();
	end;
end;



local dependency_flush_queued = false;
function Library:UpdateDependencyBoxes()
	if dependency_flush_queued then return end;
	dependency_flush_queued = true;

	task.defer(function()
		dependency_flush_queued = false;
		flush_dependency_boxes();
	end);
end;

function Library:MapValue(Value, MinA, MaxA, MinB, MaxB)
	return (1 - ((Value - MinA) / (MaxA - MinA))) * MinB + ((Value - MinA) / (MaxA - MinA)) * MaxB
end;

function Library:GetTextBounds(Text, Font, Size, Resolution)
	local Bounds = TextService:GetTextSize(Text, Size, Font, Resolution or Vector2.new(1920, 1080))
	return Bounds.X, Bounds.Y
end;


function Library:GetLexendTextBounds(Text, Font, Size, Resolution)
	local params = Instance.new("GetTextBoundsParams")
	params.Text = Text
	params.Font = Font
	params.Size = Size
	local res = TextService:GetTextBoundsAsync(params);
	params:Destroy()
	return res.X, res.Y
end;

function Library:GetDarkerColor(Color)
	local H, S, V = Color3.toHSV(Color);
	return Color3.fromHSV(H, S, V / 1.5)
end;
Library.AccentColorDark = Library:GetDarkerColor(Library.AccentColor);

function Library:AddToRegistry(Instance, Properties, IsHud)
	local Idx = #Library.Registry + 1;
	local Data = {
		Instance = Instance;
		Properties = Properties;
		Idx = Idx;
	};

	table.insert(Library.Registry, Data);
	Library.RegistryMap[Instance] = Data;

	if IsHud then
		table.insert(Library.HudRegistry, Data);
	end;
end;

function Library:RegisterSearchEntry(Source, Data)
	local WindowRef = Source and (Source.Window or (Source.Tab and Source.Tab.Window))
	if not WindowRef or not Data or not Data.Text or Data.Text == '' then
		return
	end

	local TabOwner = Data.Tab
	if not TabOwner and Source then
		if Source.ShowTab or Source.Show then
			TabOwner = Source
		elseif Source.Tab and (Source.Tab.ShowTab or Source.Tab.Show) then
			TabOwner = Source.Tab
		end
	end

	if not TabOwner then
		return
	end

	while TabOwner and TabOwner.ParentTab do
		TabOwner = TabOwner.ParentTab
	end

	table.insert(WindowRef.SearchEntries, {
		Kind = Data.Kind or 'Feature';
		Text = Data.Text;
		Tab = TabOwner;
		Target = Data.Target;
		Focus = Data.Focus;
	})
end

function Library:RemoveFromRegistry(Instance)
	local Data = Library.RegistryMap[Instance];

	if Data then
		for Idx = #Library.Registry, 1, -1 do
			if Library.Registry[Idx] == Data then
				table.remove(Library.Registry, Idx);
			end;
		end;

		for Idx = #Library.HudRegistry, 1, -1 do
			if Library.HudRegistry[Idx] == Data then
				table.remove(Library.HudRegistry, Idx);
			end;
		end;

		Library.RegistryMap[Instance] = nil;
	end;
end;

function Library:UpdateColorsUsingRegistry()
	
	

	
	
	
	

	

	for Idx, Object in next, Library.Registry do
		for Property, ColorIdx in next, Object.Properties do
			if type(ColorIdx) == 'string' then
				Object.Instance[Property] = Library[ColorIdx];
			elseif type(ColorIdx) == 'function' then
				Object.Instance[Property] = ColorIdx()
			end
		end;
	end;
end;

function Library:GiveSignal(Signal)
	
	table.insert(Library.Signals, Signal)
end

function Library:Unload()
	
	for Idx = #Library.Signals, 1, -1 do
		local Connection = table.remove(Library.Signals, Idx)
		Connection:Disconnect()
	end

	
	if Library.OnUnload then
		Library.OnUnload()
	end

	ScreenGui:Destroy()
end

function Library:OnUnload(Callback)
	Library.OnUnload = Callback
end

Library:GiveSignal(ScreenGui.DescendantRemoving:Connect(function(Instance)
	if Library.RegistryMap[Instance] then
		Library:RemoveFromRegistry(Instance);
	end;
end))

