	local TransparencyCache = {};
	local Toggled = false;
	local Fading = false;

	function Library:Toggle()
		if Fading then
			return		
end;

		local FadeTime = Config.MenuFadeTime;
		Fading = true;
		Toggled = (not Toggled);
		uiOpen = Toggled;
		

		services.RunService:SetRobloxGuiFocused(false)
		if Toggled and aztup_toggles and aztup_toggles.BlurWhileOpen and aztup_toggles.BlurWhileOpen.Value then
			services.RunService:SetRobloxGuiFocused(true)
		end


		if FadeTime > 0 then
			for _, Desc in next, Outer:GetDescendants() do
				local Properties = {};

				if Desc:IsA('ImageLabel') then
					table.insert(Properties, 'ImageTransparency');
					table.insert(Properties, 'BackgroundTransparency');
				elseif Desc:IsA('TextLabel') or Desc:IsA('TextBox') then
					table.insert(Properties, 'TextTransparency');
				elseif Desc:IsA('Frame') or Desc:IsA('ScrollingFrame') then
					table.insert(Properties, 'BackgroundTransparency');
				elseif Desc:IsA('UIStroke') then
					table.insert(Properties, 'Transparency');
				end;

				local Cache = TransparencyCache[Desc];

				if (not Cache) then
					Cache = {};
					TransparencyCache[Desc] = Cache;
				end;

				for _, Prop in next, Properties do
					if not Cache[Prop] then
						Cache[Prop] = Desc[Prop];
					end;

					if Cache[Prop] == 1 then
						continue					
end;

					TweenService:Create(Desc, TweenInfo.new(FadeTime, Enum.EasingStyle.Linear), { [Prop] = Toggled and Cache[Prop] or 1 }):Play();
				end;
			end;
		end;

		if not Toggled then
			Library:CloseAllDropdowns();
		end;

		if FadeTime > 0 then
			task.wait(FadeTime);
		end;

		Outer.Visible = Toggled;
		Library.Toggled = Toggled;
		Library.OnToggledChanged:Fire(Toggled);

		Fading = false;
	end

	Library:GiveSignal(InputService.InputBegan:Connect(function(Input, Processed)
		if type(Library.ToggleKeybind) == 'table' and Library.ToggleKeybind.Type == 'KeyPicker' then
			if Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Library.ToggleKeybind.Value then
				task.spawn(Library.Toggle)
			end
		elseif Input.KeyCode == Enum.KeyCode.RightControl or (Input.KeyCode == Enum.KeyCode.RightShift and (not Processed)) then
			task.spawn(Library.Toggle)
		end
	end))

	if Config.AutoShow then task.spawn(Library.Toggle) end

	Window.Holder = Outer;

	return Window
end;

local function OnPlayerChange()
	local PlayerList = GetPlayersString();

	for _, Value in aztup_options do
		if Value.Type == 'Dropdown' and Value.SpecialType == 'Player' then
			Value:SetValues(PlayerList);
		end;
	end;
end;

function Library:SetInfoLoggerVisibility(Value)
	Library.InfoLoggerFrame.Visible = Value
end


function Library:UpdateInfoLoggerSize()
	if Library.InfoLoggerFrame.Visible then
		local YSize = 0
		local XSize = 0
		local items = 0;

		for _, Label in next, Library.InfoLoggerContainer:GetChildren() do
			if Label:IsA('TextLabel') and Label.Visible then
				YSize = YSize + 18;
				local LabelWidth = Label.TextBounds.X / Library:GetUIScale()
				if (LabelWidth > XSize) then
					XSize = LabelWidth
				end

				items += 1;
			end;
		end;
		
		local NewHeight = items == 0 and 24 or YSize + 32;
		local NewWidth = math.max(XSize + 34, 220);

		Library.InfoLoggerFrame.Size = UDim2.new(0, NewWidth, 0, NewHeight)
	end;
end


function Library:AddTextToInfoLogger(Text, CopyText, CopyFunc, Expiry)
	local InfoContainerLabel = Library:CreateLabel({
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new(1, 0, 0, 18),
		TextSize = 16,
		Visible = false,
		ZIndex = 110,
		Parent = Library.InfoLoggerContainer,
	}, true)

	task.spawn(function()
		InfoContainerLabel.FontFace = lexend.regular;
	end);

	if (#Library.InfoLoggerData.ContainerLabels + 1) > 15 then
		
		local FirstElement = Library.InfoLoggerData.ContainerLabels[1]
		if FirstElement then
			
			FirstElement:Destroy()

			
			table.remove(Library.InfoLoggerData.ContainerLabels, 1)
		end
	end

	InfoContainerLabel.Text = Text;

	if CopyText then
		InfoContainerLabel.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				Library:Notify("Set your clipboard to designated copyable text.");
				setclipboard(CopyText);
			end;
		end);   
	end;

	if CopyFunc then
		InfoContainerLabel.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				pcall(CopyFunc)
			end;
		end);   
	end;

	InfoContainerLabel.Visible = true
	InfoContainerLabel.TextColor3 = Library.FontColor

	Library.InfoLoggerData.ContainerLabels[#Library.InfoLoggerData.ContainerLabels + 1] = InfoContainerLabel
	Library.RegistryMap[InfoContainerLabel].Properties.TextColor3 = "FontColor"
	Library:UpdateInfoLoggerSize();

	if Expiry and type(Expiry) == "number" and Expiry > 0 then
		task.delay(Expiry, function()
			if not InfoContainerLabel or not InfoContainerLabel.Parent then
				return
			end

			local LabelIndex = table.find(Library.InfoLoggerData.ContainerLabels, InfoContainerLabel)
			if LabelIndex then
				table.remove(Library.InfoLoggerData.ContainerLabels, LabelIndex)
			end

			local FadeTime = 0.25
			local FadeTween = TweenService:Create(InfoContainerLabel, TweenInfo.new(FadeTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				TextTransparency = 1,
				TextStrokeTransparency = 1,
			})

			local TextStroke = InfoContainerLabel:FindFirstChildOfClass("UIStroke")
			if TextStroke then
				TweenService:Create(TextStroke, TweenInfo.new(FadeTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					Transparency = 1,
				}):Play()
			end

			FadeTween:Play()

			task.delay(FadeTime, function()
				if InfoContainerLabel and InfoContainerLabel.Parent then
					InfoContainerLabel:Destroy()
					Library:UpdateInfoLoggerSize()
				end
			end)
		end)
	end
end 


Players.PlayerAdded:Connect(OnPlayerChange);
Players.PlayerRemoving:Connect(OnPlayerChange);
getgenv().Library = Library;
return Library



end;

__modules["src/utility/logger"] = function()






local dev_file = getgenv().dev_file or string.format("Frutiger/logs/client-%s", tostring(tick()))

if not LPH_OBFUSCATED then
    if not isfolder("Frutiger/logs") then
        makefolder("Frutiger/logs");
    end;

    if not getgenv().dev_file then
        getgenv().dev_file = dev_file;
        writefile(dev_file, "");
    end;
end;

local Logger = {} do
    function Logger:short_notify(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end; 
        local message = table.concat(args, " ");
        Library:Notify(message, 2.5);
    end

    function Logger:notify(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:Notify(message, 5);
    end
    
    function Logger:notify_sound(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:NotifyWithSound(message, 5);
    end

    function Logger:long_notify_sound(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:Notify(message, 60);
    end

    function Logger:long_notify(...)
        if aztup and aztup.silent_mode then return end

        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        Library:Notify(message, 60);
    end

    function Logger.log_for_devs(...)
        if LPH_OBFUSCATED then return end
        
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        
        appendfile(dev_file, "\n[l] " .. message);
    end;

    function Logger.log(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        if Library then
            Library:AddTextToInfoLogger("[I]: " .. message, "[I]: " .. message, nil)
        elseif not (aztup and aztup.silent_mode) then
            print("[I]: " .. message)
        end;
    end

    function Logger.warn(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        if Library then
            Library:AddTextToInfoLogger("[W]: " .. message, "[W]: " .. message)
        elseif not (aztup and aztup.silent_mode) then
            warn("[W]: " .. message)
        end;
    end

    function Logger.error(...)
        local args = {...};
        for i, arg in args do
            args[i] = tostring(arg);
        end;
        local message = table.concat(args, " ");
        if Library then
            Library:AddTextToInfoLogger("[E]: " .. message, "[E]: " .. message)
        elseif not (aztup and aztup.silent_mode) then
            warn("[E]: " .. message)
        end;
    end
end

return Logger

end;

__modules["src/utility/loop"] = function()
return {
    run_for = function(time, callback)
        local task_conn;
        
        task_conn = services.RunService.PreSimulation:Connect(function(dt)
            if callback(dt) then
                task_conn:Disconnect();
            end;    
        end);
        
        task.delay(time, function()
            task_conn:Disconnect();
        end);
    end;
}

end;

__modules["src/utility/maid"] = function()





local maid = {}
maid.__type = "Maid"
	


function maid.new()
	return setmetatable({
		_tasks = {},
	}, maid)
end
	


function maid:__index(index)
	if maid[index] then
		return maid[index]
	else
		return self._tasks[index]
	end
end
	



function maid:__newindex(index, new_task)
	if maid[index] ~= nil then
		return error(("'%s' is reserved"):format(tostring(index)), 2)
	end
	local tasks = self._tasks
	local old_task = tasks[index]
	if old_task == new_task then
		return
	end
	tasks[index] = new_task
	if old_task then
		if type(old_task) == "function" then
			old_task()
		elseif typeof(old_task) == "RBXScriptConnection" then
			old_task:Disconnect()
		end
		pcall(function()
			if old_task.detach then
				old_task:detach()
			end
			if old_task.Destroy then
				old_task:Destroy()
			end
		end);
	end

	return
end
	



function maid:give_task(task)
	if not task then
		return error("task cannot be false or nil", 2)
	end
	local task_id = #self._tasks + 1
	self[task_id] = task
	return task_id
end
	

function maid:remove_task(task_id)
	local tasks = self._tasks
	tasks[task_id] = nil
end


function maid:clean_task(task_id)
	
	pcall(function()
		local task = self[task_id]
		pcall(function(...)  
			if typeof(task) == "RBXScriptConnection" then
				self[task_id] = nil
				task:Disconnect()
			end
			
			
			if type(task) == "function" then
				task()
			elseif typeof(task) == "RBXScriptConnection" then
				task:Disconnect()
			elseif typeof(task) == "table" and rawget(task, "do_cleaning") then
				task:do_cleaning();
			end;
		end)
		
		pcall(function()
			if task.detach then
				task:detach()
			end
			if task.Destroy then
				task:Destroy()
			end
		end);

		self[task_id] = nil
	end)
end


function maid:do_cleaning()
	local tasks = self._tasks
	
	
	for index, task in pairs(tasks) do
		if typeof(task) == "RBXScriptConnection" then
			tasks[index] = nil
			task:Disconnect()
		end
	end
	
	
	local index, task = next(tasks)
	while task ~= nil do
		tasks[index] = nil
		if type(task) == "function" then
			task()
		elseif typeof(task) == "RBXScriptConnection" then
			task:Disconnect()
		elseif typeof(task) == "table" and rawget(task, "do_cleaning") then
			task:do_cleaning();
		end;

		pcall(function()
			if task.detach then
				task:detach()
			end
			if task.Destroy then
				task:Destroy()
			end
		end);
		index, task = next(tasks)
	end
end


return maid

end;

__modules["src/utility/markedinstancecreator"] = function()
local MarkedInstanceCreator = {}





function MarkedInstanceCreator:new(markers, instance_type, settings)
	local instance = Instance.new(instance_type)
	for index, value in settings do
		instance[index] = value
	end

	Markers:mark(instance)

	return instance
end

return MarkedInstanceCreator

end;

__modules["src/utility/markers"] = function()



local Markers = {}
Markers.__index = Markers

function Markers.new()
	return setmetatable({
		_marked_instances = {},
	}, Markers)
end

function Markers:mark(instance)
	return table.insert(self._marked_instances, instance)
end

function Markers:get()
	return self._marked_instances
end

function Markers:clear()
	for i = #self._marked_instances, 1, -1 do
		local inst = self._marked_instances[i]
		if inst then
			pcall(function()
				inst:Destroy()
			end)
		end
		self._marked_instances[i] = nil
	end
end

return Markers

end;

__modules["src/utility/persistent_data"] = function()
local storage_service = identifyexecutor() == "Synapse Z" and services.MemStorageService or services.MemStorageService;

if identifyexecutor() == "Synapse Z" then
    local existing_data = storage_service:GetItem("persistent_data");
    if not existing_data or #existing_data <= 0 then
        storage_service:SetItem("persistent_data", "{}");
    end
elseif not storage_service:HasItem("persistent_data") then
    storage_service:SetItem("persistent_data", "{}");
end

local persistent_data = {} do
    persistent_data.__index = persistent_data;
    persistent_data.current = storage_service:GetItem("persistent_data") or "{}";

    function persistent_data:wipe()
        self.current = "{}";
        storage_service:SetItem("persistent_data", self.current);
    end

    -- Decode, garantendo SEMPRE una tabella.
    --
    -- JSONDecode restituisce nil quando il testo non e' JSON valido, e il
    -- salvataggio puo' corrompersi (scrittura interrotta, valore vuoto, dato
    -- di una versione precedente). Prima ogni funzione usava il risultato
    -- direttamente:
    --
    --     JSONDecode(self.current)[key]
    --
    -- quindi un salvataggio corrotto diventava "attempt to index nil with ..."
    -- a OGNI chiamata. E get viene chiamato di continuo dal ciclo
    -- dell'automazione, quindi un solo valore corrotto produceva errori su un
    -- percorso caldo -- osservato dal vivo:
    --     ":60513: attempt to index nil with 'auto_ferryman'"
    --
    -- Un salvataggio illeggibile adesso viene azzerato invece di rompere tutto.
    local function decode()
        local ok, decoded = pcall(services.HttpService.JSONDecode, services.HttpService, persistent_data.current);
        if ok and type(decoded) == "table" then
            return decoded;
        end;

        persistent_data.current = "{}";
        pcall(function() storage_service:SetItem("persistent_data", "{}") end);
        return {};
    end;

    function persistent_data:set(key, value)
        local decoded = decode();
        decoded[key] = value;
        
        self.current = services.HttpService:JSONEncode(decoded);
        storage_service:SetItem("persistent_data", self.current);
    end;

    function persistent_data:remove(key)
        local decoded = decode();
        decoded[key] = nil;
        self.current = services.HttpService:JSONEncode(decoded);
        storage_service:SetItem("persistent_data", self.current);
    end;

    function persistent_data:get(key, or_default)
        return decode()[key] or or_default
    end;
end;

return persistent_data

end;

