__modules["src/utility/player-data"] = function()

local signal = require("@src/utility/signal")
local maid = require("@src/utility/maid")

local player_data = {} do
    player_data.__index = player_data

    function player_data.new()
        local self = setmetatable({}, player_data)

        self.instance = services.Players.LocalPlayer
        task.spawn(pcall, function() 
            self.character = self.instance.Character or self.instance.CharacterAdded:Wait()
        end);
        self.character_added = signal.new()
        self.root_added = signal.new()
        self.hum_added = signal.new()
        self.data_maid = maid.new()
        self.tracker = require("@src/utility/deepwoken/action_tracker").new(self);

        self.player_gui = self.instance:FindFirstChild("PlayerGui");
        self.ui_items = {}; 
        aztup.maid:give_task(self.instance.ChildAdded:Connect(function(child)
            if child.Name == "PlayerGui" then
                self.player_gui = child;
                self.ui_items = {};
            end;
        end));

        
        aztup.maid:give_task(self.data_maid)

        
        local function bind_character(character)
            
            self.data_maid:do_cleaning()

            self.character = character
            self.root_part = nil
            self.humanoid = nil

            self.character_added:fire(character)

            
            self.data_maid:give_task(character.ChildAdded:Connect(function(part)
                if part.Name == "HumanoidRootPart" then
                    self.root_part = part
                    self.root_added:fire(part)
                elseif part.Name == "Humanoid" then
                    self.humanoid = part
                    self.hum_added:fire(part)
                end
            end))

            
            self.root_part = character:FindFirstChild("HumanoidRootPart")
            self.humanoid = character:FindFirstChild("Humanoid")

            if self.root_part then
                self.root_added:fire(self.root_part)
            end
            if self.humanoid then
                self.hum_added:fire(self.humanoid)
            end
        end

        
        aztup.maid:give_task(self.instance.CharacterAdded:Connect(bind_character))

        
        if self.character then
            bind_character(self.character)
        end

        return self
    end
end

return player_data.new()

end;

__modules["src/utility/profiler"] = function()

local profiler = {};

function profiler.wrap_no_xpcall(label, func): (...any)
    return function(...) 
        
        func(...);
        
    end
end

function profiler.wrap(label, func): (...any)
    return function(...) 
        
        xpcall(func, warn, ...);
        
    end
end

return profiler

end;

__modules["src/utility/queue"] = function()
local queue = {} do
    queue.__index = queue;

    function queue.new()
        local self = setmetatable({}, queue);

        self.tasks = {};

        return self    
end

    function queue:push(task)
        table.insert(self.tasks, task);
    end

    function queue:pop()
        return table.remove(self.tasks, 1)    
end

    function queue:empty()
        return #self.tasks == 0    
end
end

return queue

end;

__modules["src/utility/safety"] = function()

local Safety = {};

function Safety:MobsNear(part : BasePart | CFrame, distance): number
    if not distance then distance = 200; end

    local players_near = 0;
    for _, mob in workspace.Live:GetChildren() do
        if not mob:FindFirstChild("HumanoidRootPart") then continue end;
        
        local mob_distance = (part.Position - mob:GetPivot().Position).Magnitude;
        if mob_distance <= distance then
            players_near = players_near + 1;
        end;
    end;
    
    return players_near
end;

function Safety:PlayersNear(part : BasePart | CFrame, distance): number
    if not distance then distance = 200; end

    local players_near = 0;
    for _, player in services.Players:GetPlayers() do
        if player == local_player.instance then continue end;
        if not player.Character then continue end;
        
        local player_distance = (part.Position - player.Character:GetPivot().Position).Magnitude;
        if player_distance <= distance then
            players_near = players_near + 1;
        end;
    end;
    
    return players_near
end;

function Safety:PlayerNear(magnitude): boolean
    if not magnitude then magnitude = 300; end
    
    for _, player in services.Players:GetPlayers() do
        if player == local_player.instance then continue end
        if not player.Character then continue end
        
        local dist = (local_player.root_part.Position - player.Character:GetPivot().Position).Magnitude
        if dist <= magnitude then
            return true
        end
    end
    
    return false
end

function Safety:PlayerSafeTween(cf, speed, ylevel)
    local function serverhop()
        local slot = local_player.instance:GetAttribute("DataSlot");
        server_utility:hop(slot, 'any', true)
    end

    if not speed then speed = 250; end
    
    if self:PlayerNear() then
        serverhop()
        while task.wait() do end
    end
    
    if not ylevel then
        ylevel = math.random(8000, 10000)
    end
    
    local_player.root_part.CFrame = local_player.root_part.CFrame + Vector3.new(0, local_player.root_part.CFrame.Y + ylevel, 0)
    
    Tween.new(cf + Vector3.new(0, cf.Y + ylevel, 0), true, speed).wait()
    
    
    if self:PlayersNear(cf, 200) > 0 then
        serverhop()
        while task.wait() do end
    end
    
    
    local_player.root_part.CFrame = cf
end

function Safety:InDanger(): boolean
    return (local_player.humanoid:GetAttribute("DangerExpiration") and local_player.humanoid:GetAttribute("DangerExpiration") > 0)
end

return Safety

end;

__modules["src/utility/scheduler"] = function()

local scheduler = {};
local tasks = {};

function scheduler:add_task(every)
    local task = {
        event = Instance.new("BindableEvent"),
        every = every,
        last_run = 0
    };
    table.insert(tasks, task);

    return task.event.Event
end

function scheduler.run()
    local current_time = tick();
    for _, task in tasks do
        if current_time - task.last_run >= task.every then
            task.event:Fire();
            task.last_run = current_time;
        end
    end
end

aztup.maid:give_task(services.RunService.Heartbeat:Connect(scheduler.run))

return scheduler

end;

